/* ÇEVİRİ ko · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ko","olay",{
"KRONOLOJI_COK_ARABISTAN2:1538-01-01:0":{"b": ["하드라마우트가 오스만의 산자크가 됨 — 내부 통치는 카시리 부족장들에게 남음", "d80f8d20"], "d": ["하딤 쉴레이만 파샤의 인도 원정 중에 오스만 통치하에 들어간 하드라마우트는 예멘에 속한 산자크로 편성되었다. 그러나 하드라마우트 내부의 통치는 사실상 카시리 부족장들이 쥐고 있었으며, 오스만의 지배권은 해안과 조세 관계에 국한되었다.", "93dd8a13"]},
"KRONOLOJI_COK_ARABISTAN2:1659-01-01:0":{"b": ["자이드파 이맘 알무타와킬 알랄라가 하드라마우트를 침공 — 카시리 술탄국이 예멘 이맘국에 복속", "21ad9c85"], "d": ["1635년 오스만이 예멘에서 철수한 뒤 강성해진 자이드파 이맘국은 이맘 알무타와킬 알랄라 시대에 군대를 보내 하드라마우트를 침공했다. 이로써 하드라마우트 내륙의 카시리 지배는 반세기 가까이 예멘 이맘국에 종속된 채 남았다. 18세기 전반 이맘들과 카시리의 영향력이 약해지자 통치는 다시 현지 부족들에게 넘어갔다.", "e5a06ff4"]},
"KRONOLOJI_COK_ARABISTAN2:1835-01-01:0":{"b": ["압둘라 이븐 라시드가 이븐 알리 가문에게서 하일 아미르령을 장악 — 샴마르(라시드) 아미르국 수립", "357cc1a0"], "d": ["샴마르 부족의 가장 큰 지파인 아브다에 속한 압둘라 이븐 라시드는 동생 우바이드와 함께 하일을 다스리던 이븐 알리 가문에 맞서 시작한 투쟁에서 1835년 승리하여 아미르령을 장악했다. 하일은 메소포타미아-헤자즈 간 교역로 및 순례로상의 위치 덕분에 1921년까지 이어진 라시드 가문의 자발 샴마르 지배의 중심지가 되었다.", "dc0300b5"]},
"OLAYLAR:1299-01:0":{"b": ["오스만 베이국의 건국", "9f0b7c0a"], "d": ["카이 부족의 오스만 가지가 쇠위트-도마니치 일대에서 독자적으로 움직이기 시작한 것은 오스만 국가 건국의 관례적인 출발점으로 받아들여진다. 일부 역사가는 1302년 바페우스 전투의 승리를 진정한 전환점으로 본다. 베이국은 비잔티움 접경 지대라는 위치 덕분에 가자(성전) 원정을 통해 빠르게 세력을 키웠다. 셀주크의 유산이 해체되어 가던 이러한 환경에서 오스만 가지는 아히(상공업 형제단), 가지, 유목 투르크멘들을 주위에 모았다. 셰이흐 에데발리와 맺은 유대는 베이국의 정신적 정통성의 토대로 여겨진다. 같은 날짜에 편입된 다른 지역: 이네괼, 야르히사르.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["부르사 정복", "98c727fa"], "d": ["여러 해 동안 봉쇄되어 있던 부르사는 포위의 마지막 단계를 지휘한 오르한 가지에게 항복했으며, 이 도시는 베이국의 첫 번째 대규모 수도가 되었다. 정복 소식이 임종을 앞둔 오스만 가지에게 전해졌다는 이야기가 전하며, 오스만 가지는 유언에 따라 부르사에 안장되었다. 도시는 곧 모스크, 이마레트(빈민 급식소), 마드라사로 채워져 초기 오스만 도시 건설의 본보기가 되었다.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["이즈니크 정복", "a846a811"], "d": ["아나톨리아에서 비잔티움의 가장 중요한 중심지 가운데 하나였던 이즈니크(니케아)는 1329년 펠레카논 전투의 승리 이후 저항의 희망을 잃고 오르한 가지에게 항복했다. 최초의 오스만 마드라사가 이곳에 세워졌고 다부드 카이세리 같은 학자들이 강의를 시작했으며, 이 도시는 초기의 학문 중심지가 되었다. 아야 소피아 교회는 모스크로 바뀌어 정복 전통의 이른 사례를 보여 주었다.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["이즈미트 정복", "06a35035"], "d": ["이즈미트(니코메디아)가 함락되면서 아나톨리아 쪽에 남아 있던 비잔티움의 마지막 주요 요새도 오스만의 통치 아래 들어갔으며, 이스탄불 건너편 해안에 이르는 코자엘리 반도 전체가 오스만 영토가 되었다. 이로써 베이국은 마르마라해의 남쪽과 동쪽 해안 전체를 장악하여 루멜리아로 건너갈 기반을 마련했다.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["침페 요새 — 루멜리아 진출", "c2f0a07d"], "d": ["오르한 가지의 아들 쉴레이만 파샤는 비잔티움 내전 중에 넘겨받은 침페 요새를 1352년에 거점으로 삼았다. 1354년 3월 갈리폴리를 무너뜨린 대지진 이후 비게 된 요새들이 신속히 방비를 갖추면서 이 반도는 오스만의 영구적인 교두보로 바뀌었다. 아나톨리아에서 데려온 투르크멘 주민의 정착으로 뒷받침된 이 조치는 550년을 넘게 될 유럽 대륙에서의 오스만 존재의 시작이다.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["에디르네 정복", "2f54ebb0"], "d": ["트라키아의 요충 도시인 에디르네(아드리아노폴리스)의 점령은 발칸 정복의 주요 거점과 방향을 결정지었다. 정복 연대는 사료에 따라 1361년에서 1369년 사이로 논쟁이 있다. 이 도시는 얼마 지나지 않아 수도가 되어 국가의 무게 중심이 루멜리아로 옮겨 갔음을 선포했으며, 이스탄불 정복 때까지 약 90년 동안 왕도(파이타흐트)로 남았다.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["무라드 1세 즉위", "f8d48a26"], "d": ["오르한 가지의 죽음으로 즉위한 무라드 1세(휘다벤디갸르)는 27년의 치세 동안 국가를 접경 베이국에서 제국의 골격을 갖춘 나라로 끌어올렸다. 펜치크 제도를 통해 예니체리 군단의 기초가 놓였고, 티마르 제도가 확대되었으며, 루멜리아 베일레르베이령이 설치되고 재상직 제도가 강화되었다. 발칸 정복은 그의 시대에 체계적인 국가 정책이 되었다.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["제1차 코소보 전투 — 무라드 1세의 순교", "10b8ddc9"], "d": ["라자르 공이 이끈 발칸 동맹군은 코소보 평원에서 결정적으로 패배했고, 세르비아는 오스만의 종주권 아래 들어갔다. 전장을 둘러보던 무라드 1세는 세르비아 귀족 밀로시 오빌리치의 단검에 찔려 순교했는데, 그는 전장에서 목숨을 잃은 유일한 오스만 술탄이다. 진영에서 이을드름(번개왕) 바예지드가 그의 뒤를 이어 즉위했으며, 그의 동생 야쿠브 첼레비는 교살되었다. 이는 알려진 형제 살해 관행의 초기 사례 가운데 하나가 되었다.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["니코폴리스 전투의 승리", "75716e96"], "d": ["헝가리 왕 지기스문트의 호소로 모이고 프랑스-부르고뉴 기사들까지 참가한 대규모 십자군은 도나우강 변의 니코폴리스 앞에서 이을드름 바예지드에게 참패했다. 이 승리는 불가리아에 대한 오스만의 지배를 확정했으며, 유럽에서는 한 세대 동안 대규모 십자군 원정이 조직되지 못했다.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["앙카라 전투 — 공위 시대(페트레트기)의 시작", "b4a99d96"], "d": ["추부크 평원에서 티무르의 군대에 당한 대패에서 이을드름 바예지드는 포로가 되었고 몇 달 뒤 억류 중에 죽었다. 티무르는 아나톨리아의 베이국들을 부활시켰다. 오스만 영토는 바예지드의 아들들 사이에 분열되었고, 11년 동안 이어질 왕위 다툼(공위 시대, 페트레트기)이 시작되었다. 건국 이래 국가가 겪은 가장 심각한 위기였던 이 시기는 중앙집권 체제의 중요성을 오스만의 기억에 깊이 새겼다. 같은 날짜에 상실한 다른 정착지: 다트차, 마르마리스, 페티예(마크리), 쇠케, 퀴타히아, 아피온, 으스파르타, 마니사, 아이든, 데니즐리, 무을라, 안탈리아, 코니아, 카라만, 카이세리, 카스타모누, 바르튼, 사프란볼루, 삼순, 시바스, 말라티아, 베이셰히르, 시브리히사르, 크르셰히르, 초룸, 찬크르, 예니셰히르(부르사), 이네괼, 아이도스 요새, 게이베, 쾨프뤼히사르(예니셰히르), 마르마라즉, 아크히사르(파무코바), 메케제, 케스텔, 울루바트, 하르만카야, 아크야즈, 임랄르섬, 칸드라, 무다니아, 얄로바, 카라뮈르셀, 아르무틀루, 겜리크(키오스), 쇠위트, 빌레지크, 에스키셰히르, 부르사, 이즈니크, 이즈미트, 발르케시르, 차나칼레, 베르가마, 아마시아, 토카트, 초를루, 륄레부르가즈, 말카라, 케샨, 입살라, 킬리트바히르, 치르멘, 스타라 자고라(에스키 자으라), 타타르파자르즈으, 이흐티만, 큐스텐딜, 페트리치, 네브로코프(고체 델체프), 드라마, 갈리폴리, 침페, 에디르네, 디메토카, 크르클라렐리, 테키르다으, 필리베, 소피아, 니시, 비딘, 터르노보, 바르나, 슈멘, 실리스트라, 니코폴리스, 루세, 테살로니키, 세레스, 카발라, 스코페, 마나스트르, 오흐리드, 예니셰히르(라리사), 트르할라, 이즈딘(라미아), 플레벤, 귀뮐지네, 비가, 도마니치, 쿨라자히사르, 카라자히사르, 야르히사르, 딤보스, 키테(케테), 레프케(오스마넬리), 레블레비지히사르, 카라체퓌시, 카라티긴, 압수(힙수), 아드라노스(오르하넬리), 펠레카논(에스키히사르), 게브제, 헤레케, 사만드라, 키르마스티(M.케말파샤), 미할리치(카라자베이), 콘스탄차, 괼야즈(아폴로니아).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["첼레비 메흐메드의 통일 재건", "03413dfd"], "d": ["형제들 사이의 마지막 결전에서 차무를루에서 무사 첼레비를 꺾은 메흐메드 1세는 나라의 영토를 단일한 통치 아래 통합했으며, 이 때문에 '국가의 제2의 건국자'로 여겨진다. 그의 치세에 약해진 국가 체제가 복구되었고, 아나톨리아 베이국들과의 관계에 균형이 잡혔으며, 루멜리아에서는 신중한 평화 정책이 추진되었다. 같은 날짜에 지도에서 공위 시대의 과도기에서 오스만 행정으로 돌아온 다른 정착지: 압수(힙수), 아드라노스(오르하넬리), 아크히사르(파무코바).", "45315d2d"]},
"OLAYLAR:1416-05-01:0":{"b": ["셰이흐 베드레딘의 반란", "e0a072ca"], "d": ["공위 시대에 군법관(카자스케르)을 지낸 위대한 법학자이자 수피인 셰이흐 베드레딘을 중심으로 전개된 종교·사회 운동은, 카라부룬의 뵈르클뤼제 무스타파와 마니사의 토를라크 케말의 봉기와 동시에 터져 나왔다. 반란은 유혈 진압되었고, 베드레딘은 델리오르만에서 붙잡혀 세레스에서 처형되었다. 이 사건은 오스만 역사상 가장 이른 대규모 사회적·마흐디 신앙적 봉기로서 문학과 역사 서술에 깊은 흔적을 남겼다.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["바르나 전투의 승리", "f739eedc"], "d": ["세게드 조약을 깨고 남하한 헝가리-폴란드 십자군은, 퇴위했다가 다시 군대의 선두에 선 무라드 2세에게 바르나에서 섬멸당했으며, 젊은 국왕 브와디스와프 3세는 전장에서 죽었다. 이 승리로 발칸에서 오스만의 존재를 제거하려던 마지막 대규모 외부 개입의 기회가 사라졌고, 이스탄불 정복으로 가는 길이 확보되었다.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["제2차 코소보 전투", "ebe0b662"], "d": ["바르나의 복수를 하려던 후녀디 야노시의 군대는 사흘 동안 이어진 격전에서 무라드 2세에게 결정적으로 패배했다. 이는 십자군이 발칸에서 오스만을 상대로 벌인 마지막 대규모 회전이었으며, 이 승리로 도나우강 이남에서 오스만의 지배는 이제 되돌릴 수 없을 만큼 확고해졌다.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["이스탄불 정복", "583d5e3e"], "d": ["54일(1453년 4월 6일–5월 29일) 동안 계속된 포위 끝에 5월 29일 아침 성벽을 넘은 오스만군이 도시에 진입했다. 마지막 황제 콘스탄티노스 11세는 전투 중에 죽었고, 1100년 역사의 동로마 제국은 역사 속으로 사라졌다. 젊은 술탄은 '파티흐(정복자)' 칭호를 얻었고, 도시를 수도로 삼으며 아야 소피아를 모스크로 바꾸었다. 도시는 곧 이주 정착과 건설 사업으로 다시 활기를 찾았다. TDV에 따르면 실리브리와 비제는 1453년에야 비로소 확실하게 정복되었다. TDV 림노스 항목에 따르면 이 섬은 정복 직후 오스만의 통치 아래 들어갔고, 공납을 조건으로 가틸루시오 가문에 맡겨졌다. 지도에서 실리브리, 비제, 림노스는 이날부터 비잔티움에서 오스만으로 넘어간 것으로 기록되어 있다(림노스는 공납국). 거대한 대포의 주조, 육로를 통한 선박 이동, 성벽 앞의 포위 배치는 당대 군사 공학의 절정으로 평가된다. 이 정복은 유럽 역사 서술에서 중세의 종말을 상징하는 연대 가운데 하나로 꼽힌다.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["트라브존 정복", "15f52403"], "d": ["정복자 메흐메드가 육군과 함대를 동시에 움직인 험난한 흑해 원정 끝에 트레비존드 제국이 항복했다. 아나톨리아에 남은 비잔티움 세계의 이 마지막 잔재가 청산되면서 흑해 남안 전체가 오스만의 지배 아래 들어갔다. 콤네노스 왕조의 종말은 '두 바다와 두 대륙의 통치자'라는 정복자의 주장을 더욱 굳혔다. 같은 날짜에 편입된 다른 지역: 기레순, 리제.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["실리프케의 최종 정복 — 카라만 베이국의 마지막 저항 분쇄", "d988bee4"], "d": ["실리프케 요새는 1472년에 한 번 게디크 아흐메드 파샤에게 항복했으나, 같은 해 카라만 가문의 카슴 베이가 지중해의 십자군 함대의 도움을 받아 요새를 되찾았다. 오틀루크벨리 전투의 승리 이후 정복자는 자신의 아들과 게디크 아흐메드 파샤에게 이 지역을 확실히 장악하라는 임무를 맡겼다. 이전 오스만 포병들의 도움으로 화약고에 불이 붙어 요새는 빠르게 함락되었다. 이로써 타셸리-이첼 산지에서의 카라만 베이국의 마지막 저항이 분쇄되었으며, 베이국의 청산은 1474년에 마무리되었다.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["오틀루크벨리 전투", "42c7194e"], "d": ["동방의 강대 세력이 되어 베네치아와 동맹을 맺은 백양 왕조의 통치자 우준 하산은 오틀루크벨리에서 화기로 무장한 정복자의 군대에게 대패했다. 이 승리는 아나톨리아에서 오스만의 우위를 확정했으며, 고전적인 군대에 대해 대포와 총을 사용하는 중앙집권적 군대가 우월함을 보여 준 이른 증거이기도 했다. TDV 귀뮈슈하네 항목에 따르면 이 도시는 1467년 이래 백양 왕조의 지배 아래 있었으며, 이 지배는 오틀루크벨리의 패배로 끝나고 귀뮈슈하네는 확실하게 오스만의 지배로 넘어갔다.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["크림의 오스만 보호령 편입", "44e3f7c8"], "d": ["게디크 아흐메드 파샤가 지휘하는 함대는 제노바가 장악하고 있던 카파를 비롯한 크림 남해안의 도시들을 정복했으며, 이 해안 지대는 오스만 직할 산자크가 되었다. 크림 칸국은 멩글리 기라이와 함께 오스만의 종주권을 인정하는 특권적 속국이 되어 300년 동안 북방 정책의 초석이 되었으며, 흑해는 이제 사실상 오스만의 내해가 되었다. 같은 날짜에 편입된 다른 지역: 바흐치사라이, 케르치, 아조프.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["정복자의 죽음 — 젬 술탄 사건", "190ecf01"], "d": ["정복자 메흐메드가 원정길에서 갑자기 죽자 바예지드 2세가 즉위했다. 그의 동생 젬 술탄은 왕위를 주장하며 부르사에서 자신의 이름으로 후트바를 낭송하게 하고 화폐를 주조했다. 패배한 뒤 그는 먼저 맘루크 왕조에, 이어 로도스 기사단에 몸을 의탁했다. 기사단과 교황청의 수중에서 유럽 외교의 협상 카드가 된 젬은 1495년 나폴리에서 죽었다. 이 사건은 15년 동안 오스만의 대외 정책이 신중하게 움직이도록 강요했다.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["찰드란 전투의 승리", "fea64ebb"], "d": ["아나톨리아에서 사파비의 선전이 일으킨 위협을 뿌리부터 해결하려 한 야부즈 술탄 셀림은, 찰드란 평원에서 대포와 총의 우세를 바탕으로 샤 이스마일의 군대에 대패를 안겼다. 타브리즈에 입성했으며, 동부와 남동부 아나톨리아 및 모술-디야르바크르 선이 오스만의 통치에 편입되었다. 이드리스 비틀리시의 노력으로 쿠르드 베이들이 오스만에 귀속되면서 수백 년 동안 이어질 동쪽 국경의 틀이 세워졌다.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["마르지 다비크 전투의 승리", "07d254d3"], "d": ["맘루크군은 알레포 북쪽의 마르지 다비크에서 몇 시간 만에 궤멸되었고, 노령의 술탄 칸수 알가우리는 전투 중에 죽었다. 알레포와 다마스쿠스의 문을 활짝 연 이 승리로 시리아, 레바논, 팔레스타인이 오스만의 통치로 넘어갔으며, 맘루크 왕조의 종말을 가져올 이집트 원정의 길이 열렸다.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["리다니야 전투 — 이집트 정복과 칼리파 지위", "caf378d6"], "d": ["시나이 사막을 신속히 건넌 오스만군은 리다니야에서 투만바이의 방어선을 돌파하고 카이로에 입성했다. 저항을 계속하던 투만바이는 붙잡혀 처형되었고, 맘루크 왕조는 역사 속으로 사라졌다. 이집트, 히자즈, 성지의 도시들이 오스만의 통치 아래 들어갔으며, 압바스 칼리파와 성유물은 이스탄불로 옮겨졌다. 칼리파 지위가 오스만 왕조로 넘어가면서 술탄들은 이슬람 세계의 지도자라는 주장을 내세우게 되었고, 향신료 길의 통제는 제국에 막대한 수입을 안겨 주었다. 같은 날짜에 편입된 다른 지역: 아크레, 마안, 시돈, 카라크.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["카누니 술탄 쉴레이만 즉위", "f6512269"], "d": ["야부즈 셀림이 죽자 외아들로서 즉위한 쉴레이만 1세의 46년 치세는 제국의 정치적, 군사적, 법률적, 문화적 절정기로 평가된다. 관습법을 체계화한 법령집(카눈나메) 덕분에 그는 '카누니(입법자)'라는 칭호를 얻었고, 서방에서는 '대제(Magnificent)'로 불렸다. 건축가 시난의 작품, 디완 문학의 황금기, 지중해에서의 해군 우위가 이 시대의 상징이다.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["베오그라드 정복", "59ef5cec"], "d": ["정복자 메흐메드가 1456년에 함락하지 못했고 '중부 유럽의 자물쇠'로 여겨지던 베오그라드는, 카누니의 첫 원정에서 도나우강과 사바강의 합류점에서 벌어진 포위전으로 함락되었다. 헝가리의 남부 방어선은 무너졌으며, 이 정복은 5년 뒤의 모하치 전투와 20년 뒤의 부다 병합으로 이어지는 중부 유럽 작전의 문을 열었다.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["로도스 정복", "807bbb1e"], "d": ["동지중해의 항로와 순례길을 위협하던 성 요한 기사단의 거점 로도스는 여러 달에 걸친 유혈 포위 끝에 협정에 따라 항복했다. 기사단은 섬을 자유롭게 떠날 수 있도록 허락받았다(이후 몰타에 정착했다). 아나톨리아 해안의 안전이 확보되었고, 이스탄불-이집트 해상로는 중단 없는 오스만의 통제 아래 들어갔다.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["모하치 전투", "f3418b0d"], "d": ["헝가리군은 모하치 평원에서 약 두 시간 만에 포격과 기동의 우세로 괴멸되었고, 러요시 2세 왕은 도주하다가 늪에서 죽었다. 오스만 역사에서 가장 신속하게 승리한 대규모 회전 가운데 하나인 모하치 전투는 독립 헝가리 왕국을 사실상 끝내고 중부 유럽에서 오스만-합스부르크 경쟁의 시대를 열었다.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["제1차 빈 포위", "dc49ea4f"], "d": ["합스부르크가 헝가리 왕위에 손을 뻗은 데 맞서 일으킨 원정에서 오스만군은 빈을 포위했다. 중포를 도중에 두고 온 것, 일찍 닥친 겨울, 보급의 어려움 때문에 3주 만에 포위가 풀렸다. 도시를 함락하지는 못했으나 헝가리에 대한 오스만의 영향력은 유지되었다. 빈 앞은 중부 유럽에서 제국의 병참이 미칠 수 있는 한계를 보여 주었다.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["바그다드 정복 — 두 이라크 원정", "897092c3"], "d": ["'두 이라크'(아랍 이라크와 페르시아 이라크)를 향한 원정에서 먼저 타브리즈에, 이어 전투 없이 바그다드에 입성했다. 압바스 왕조의 옛 수도를 차지한 것은 오스만 통치자에게 이슬람 세계에서 큰 위신을 안겨 주었다. 이맘 아자므 아부 하니파의 영묘가 복원되었고, 바그다드와 바스라의 편입으로 오스만 영토는 페르시아만에 이르렀다. 같은 날짜에 편입된 다른 지역: 키르쿠크, 카르발라.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["프레베자 해전의 승리", "30dc0f97"], "d": ["교황의 주도로 결성된 십자군 함대는 수적으로 우세했음에도, 바람과 해안을 능숙하게 활용한 바르바로스의 전술에 프레베자 앞바다에서 흩어졌고, 안드레아 도리아는 전장을 이탈했다. 이 승리로 지중해에서 약 33년 동안 이어질 확고한 오스만의 제해권이 확립되었으며, 튀르키예 해양 전통에서 해군의 날을 상징하는 날짜이다. 같은 날짜에 편입된 다른 지역: 아덴, 벤데르.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["부다 병합 — 헝가리의 오스만 속주화", "db53b244"], "d": ["합스부르크가 부다를 포위하자 원정에 나선 카누니는 도시를 구한 뒤 중부 헝가리를 오스만 직할 통치 아래 두고 부다 베일레르베이령을 설치했으며, 트란실바니아는 오스만에 속한 자치 공국이 되었다. 헝가리가 셋으로 나뉜 이 체제는 약 150년 동안 이어졌고, 중부 유럽에서 오스만의 영속적인 통치 골격을 이루었다.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["아마시아 화약", "a5afe0d1"], "d": ["여러 해 동안 이어진 오스만-사파비 전쟁을 끝낸 최초의 공식 평화 조약이다. 바그다드와 이라크는 오스만에 남았고, 동부 아나톨리아 국경이 처음으로 상호 인정되었다. 사파비는 오스만 영토 내의 시아파 선전을 중단하기로 했고, 오스만은 이란 순례자들의 안전한 통행을 보장하기로 했다. 이 조약은 두 나라 관계의 법적 틀을 마련한 첫 사례가 되었다.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["시게트바르 — 카누니의 서거", "e2917ed2"], "d": ["72세의 카누니는 열세 번째 원정에서 포위하던 시게트바르 요새가 함락되기 몇 시간 전에 군막에서 서거했다. 소콜루 메흐메드 파샤는 군대가 흩어지지 않도록 그의 죽음을 여러 주 동안 숨겼다. 요새는 함락되었으나 국가는 가장 오래 재위하고 가장 찬란했던 술탄을 잃었다. 그의 아들 셀림 2세가 즉위했고, 국정에서 대재상들의 비중이 커지기 시작했다.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["키프로스 정복", "e364a2b3"], "d": ["베네치아가 통치하던 키프로스에 1570년 상륙이 이루어졌다. 니코시아는 빠르게 함락되었으나 파마구스타는 11개월의 포위 끝에 1571년 8월에야 항복했다. 동지중해의 교역로와 순례길의 안전에 결정적이던 이 섬은 베일레르베이령으로 편제되었고 아나톨리아에서 주민이 이주해 정착했다. 이 정복은 레판토 해전으로 이어질 대규모 십자군 동맹의 명분도 되었다.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["레판토(이네바흐트) 해전의 패배", "6a1d44a9"], "d": ["키프로스 정복에 맞서 결집한 십자군 함대는 레판토만에서 오스만 함대를 붙잡아 대부분을 파괴했다. 해군 총사령관(카푸단 파샤) 뮈에진자데 알리 파샤는 순교했고, 울루츠 알리의 함대만이 살아남았다. 이 참사 뒤에 대재상 소콜루 메흐메드 파샤는 울루츠 알리 파샤를 해군 총사령관으로 임명하여 흩어진 함대를 수습하게 했고, 이스탄불에서 알라니아에 이르는 모든 조선소에서 새 함대의 건조를 시작했다. 그러나 지중해에서의 절대적 우위는 심리적으로 흔들렸다.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["하초바(메죄케레스테시) 전투", "da308ec5"], "d": ["장기 전쟁(1593–1606)의 가장 큰 회전에서, 메흐메드 3세가 직접 지휘한 군대는 흩어지기 직전에 호자 사데딘 에펜디의 설득으로 전열을 가다듬어 합스부르크군을 격파했다. 이는 오스만이 승리한 마지막 대규모 고전적 회전으로 여겨진다. 그러나 전쟁의 전반적인 흐름을 바꾸지 못한 것은 군사 체제의 마모를 보여 주는 징표로도 받아들여졌다.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["지트버토로크 조약", "39c01142"], "d": ["13년에 걸친 소모전을 끝낸 이 조약으로 합스부르크 통치자는 처음으로 '로마 황제'라는 자격으로 술탄과 대등하게 인정되었고 연례 공납은 폐지되었다. 영토 상실은 거의 없었으나, 이러한 외교 언어의 변화는 유럽에 대한 오스만의 절대적 우위 주장이 끝났음을 상징하는 것으로 해석된다.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["카스르 쉬린 조약", "c1acf3af"], "d": ["무라드 4세가 바그다드를 되찾은(1638) 뒤 체결된 이 조약은 100년이 넘는 오스만-사파비 전쟁에 종지부를 찍었다. 바그다드와 이라크는 확정적으로 오스만에 남았고 레반(예레반)은 사파비에 넘겨졌다. 그어진 선은 약간의 변화를 거쳐 오늘날 튀르키예-이란 국경의 기초가 되었으며, 세계에서 가장 오래 지속된 국경 가운데 하나로 꼽힌다. 조약은 베드레, 제산, 멘델리, 데르텡, 데르네를 오스만에 남겼다. 국경의 젠지르 요새는 철거하고, 그 서쪽 마을들은 오스만에, 동쪽 마을들은 이란에 속하게 했다. 셰흐리조르 부근의 잘림 요새 일대와 크즐자 칼레는 오스만에, 아브로만과 미흐리반은 이란에 남았으며, 코투르, 마쿠, 마아즈베르드 요새는 양측이 모두 철거하기로 했다.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["크레타 정복 완료", "e0d85604"], "d": ["1645년에 시작된 크레타 전쟁의 마지막 막인 칸디아 포위전은 파즐 아흐메드 파샤의 3년에 걸친 단호한 작전으로 끝났고, 베네치아 지휘관 모로시니는 협정에 따라 도시를 넘겨주었다. 약 25년에 걸친 이 투쟁은 오스만 역사상 가장 긴 포위전으로 기록되었으며, 동지중해의 마지막 라틴 대요새도 오스만의 통치 아래 들어갔다. 섬 북쪽 해안의 작은 바위 요새 셋, 곧 수다, 스피날롱가, 그람부사는 아직 베네치아에 남았다. 이들은 별개의 작은 섬 위에 세워져 있어 지도에서 크레타의 나머지 부분과 따로 표시할 수 없다.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["부차치 조약 — 최대 판도", "b17b6e5a"], "d": ["폴란드 원정에서 카미야네치를 정복한 뒤 체결된 부차치 조약으로 포돌리아가 오스만에 편입되고 우크라이나의 일부가 보호 아래 들어갔다. 제국은 이로써 유럽에서 가장 넓은 국경에 도달했으며, 이 시점은 팽창 시대의 절정이자 마지막 고리로 여겨진다.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["제2차 빈 포위의 패주", "7d889252"], "d": ["메르지폰루 카라 무스타파 파샤가 두 달 동안 이어 간 빈 포위는, 폴란드 왕 얀 소비에스키가 칼렌베르크 언덕에서 가한 기습 타격으로 패주로 바뀌었다. 군대는 짐을 버리고 퇴각했으며, 메르지폰루는 베오그라드에서 처형되었다. 이후 결성된 신성 동맹과의 전쟁은 16년 동안 이어졌고, 이 패배는 오스만 역사에서 대후퇴가 시작된 순간으로 거론된다.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["그람부사 요새 정복 — 베네치아에 남아 있던 크레타의 바위 요새 가운데 하나", "3ddf9eeb"], "d": ["1669년 칸디아의 항복으로 크레타 정복은 대체로 완료된 것으로 여겨졌으나, 섬 북서쪽 끝의 바위섬 요새 그람부사는 23년 더 베네치아의 손에 남았다. 1692년에 이곳이 점령되면서 크레타에 남은 베네치아의 세 거점 가운데 하나가 정리되었다. 수다와 스피날롱가는 1715년 모레아 원정을 기다려야 했다.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["카를로비츠 조약 — 최초의 대규모 영토 상실", "8f7e2546"], "d": ["16년에 걸친 신성 동맹 전쟁을 끝낸 카를로비츠 조약으로 헝가리와 트란실바니아는 오스트리아에, 포돌리아는 폴란드에, 모레아와 달마티아 해안은 베네치아에 넘겨졌다. 오스만 역사상 처음으로 이 정도 규모의 영토가 협상 탁자에서 영구히 상실된 것이다. 이 조약은 제국이 유럽에 대해 수세로 돌아선 새 시대의 출발 문서로 여겨지며, 오스만 외교사의 전환점이기도 하다. 같은 날 지도에서 주인이 바뀐 정착지: 코스타이니차와 야세노바츠(오스만에서 합스부르크로. 조약문은 카스타노비츠를 황제의 수중에 남기며, 야세노바츠의 인도 날짜는 사료에 없어 조약 날짜를 적었다), 그리고 프레베자(베네치아에서 오스만으로. TDV karlofca: 1110년 라자브월 24일 / 1699년 1월 26일에 서명된 조항에 따라 레판토만 북쪽의 베네치아 점령지가 반환되었다). 지도는 또한 코스타이니차와 야세노바츠를 합스부르크 쪽에, 우크라이나 우안의 우만과 빈니차를 오스만에서 폴란드로(TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: 1672-99 튀르크 지배), 달마티아의 나딘을 베네치아로 기록한다(해당 정착지의 인도 날짜는 사료에 없어 조약 날짜를 적었다. 나딘의 시기 구간 양 끝은 사료로 검증되지 않았다 — 명시된 근사치). 레판토만 북쪽의 보니차도 베네치아에서 오스만으로 반환되며(TDV karlofca), 달마티아의 브라나(우라나)는 베네치아에 남은 곳에 속한다(시기 구간 끝은 미검증 — 명시).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["프루트 전투의 승리", "2583572f"], "d": ["폴타바에서 패한 뒤 오스만에 망명한 스웨덴 왕 문제로 일어난 전쟁에서, 차르 표트르 1세의 군대는 프루트강 변에서 포위되어 항복할 수밖에 없었다. 체결된 조약으로 아조프가 되찾아졌으며, 군대를 섬멸하지 않고 차르를 풀어 준 결정은 그날부터 오늘날까지 논란이 되는 결정으로 역사에 남았다.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["수다와 스피날롱가 요새 정복 — 크레타에서 베네치아의 마지막 흔적 제거", "7261f7ba"], "d": ["1692년 그람부사가 함락된 지 23년 뒤, 모레아 원정의 한 지류 작전으로 크레타에 남은 베네치아의 마지막 두 거점인 수다와 스피날롱가 요새도 정복되었다. 이로써 1645년에 시작된 크레타 정복은 46년 만에 섬의 마지막 한 치까지 완료되었다.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["파트로나 할릴의 반란", "100941a4"], "d": ["이란 전선의 실패, 세금, 궁정 주변의 사치에 대한 분노는 목욕탕 때밀이였던 파트로나 할릴이 이끄는 대규모 봉기로 번졌다. 대재상 이브라힘 파샤가 살해되고 아흐메드 3세가 폐위되었으며 튤립 시대는 끝났다. 반란자들이 몇 달 동안 도시를 지배한 것은 중앙 권력의 취약성을 극명하게 보여 주었다.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["베오그라드 조약 — 베오그라드, 스메데레보, 북부 세르비아의 탈환", "ba7f8e46"], "d": ["오스트리아와 러시아에 맞서 두 전선에서 벌인 전쟁(1736–1739)의 끝에 베오그라드와 북부 세르비아가 되찾아졌고, 러시아는 아조프를 비무장화하고 흑해에 함대를 두지 않기로 했다. 18세기 오스만 외교와 군대의 마지막 큰 성공으로 여겨지는 이 조약은 제국에 25년의 평화기를 안겨 주었다. 같은 날 지도에서 오스트리아에서 오스만으로 돌아온 다른 정착지: 히사르즈크(그로츠카)(베오그라드의 상위 중심지 연쇄; TDV belgrad), 크라이오바, 르므니쿠블체아, 투르누세베린(소왈라키아의 오스만 귀환, 왈라키아 속국 지위로). 사바강 지대의 보산스키 브로드와 보산스카 두비차는 지도상 1739년 9월 28일에 오스만으로 돌아온다(TDV bosna-hersek; TDV mahmud-i--osmanli: 1739년 9월 28일). 소왈라키아의 트르구지우도 같은 날 오스만으로 돌아온다.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["체슈메 습격", "840b30bd"], "d": ["영국의 지원을 받아 지중해로 나온 러시아 함대는 체슈메 항구에 피신한 오스만 함대를 화공선으로 급습하여 거의 전부를 불태웠다. 러시아는 처음으로 지중해의 대해군국으로 등장했다. 이 참사는 1774년 퀴취크 카이나르자 조약에 이르는 전쟁의 운명을 결정지은 타격 가운데 하나였으며, 해군의 근본적인 개혁이 필요함을 드러냈다.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["퀴취크 카이나르자 조약", "2776dcdb"], "d": ["1768–1774년 전쟁을 끝낸, 오스만 역사상 가장 가혹한 조약 가운데 하나로 꼽히는 퀴취크 카이나르자 조약으로 크림 칸국에 '독립'이 부여되었는데, 이는 사실상 러시아의 영향권이 만들어진 것이었다. 러시아는 흑해 연안에 자리 잡았고, 상선의 해협 통과권과 이스탄불 상주 대사관을 얻었으며, 정교도 신민에 대한 모호한 보호 조항은 다음 세기 간섭의 명분에 문을 열어 주었다. 처음으로 주민이 무슬림인 땅이 오스만의 지배에서 벗어나게 되었다.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["러시아의 크림 병합", "bdf6faa8"], "d": ["퀴취크 카이나르자 조약이 만들어 낸 '독립' 크림은 마지막 칸 샤힌 기라이 시기의 혼란을 구실로 예카테리나 2세의 선언에 의해 러시아에 병합되었다. 300년에 걸친 오스만-크림의 동반 관계는 끝났다. 북방 초원의 상실은 이스탄불의 전략적 종심을 없앴고, 수만 명의 크림 타타르인이 오스만 영토로 이주하는 첫 대규모 물결을 일으켰다. 이날 크림반도(알루슈타, 카파, 수다크, 얄타, 발라클라바, 인케르만, 망구프, 아라바트)는 러시아에 편입되었으며, 타만과 쿠반도 같은 병합으로 러시아에 넘어갔다(TDV 크림 항목: 율리우스력 1783년 4월 8일 = 그레고리력 4월 19일).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["셀림 3세와 니자므 제디드", "d53aec21"], "d": ["전쟁 한가운데에서 즉위한 셀림 3세는 패배가 구조적인 것임을 깨닫고 '니자므 제디드'(신질서)라는 이름으로 포괄적인 개혁 프로그램을 시작했다. 유럽식으로 훈련한 새 군대, 이를 재정적으로 뒷받침하는 별도의 국고(이라드 제디드), 공병 학교의 강화, 그리고 유럽 수도들에 둔 최초의 상주 대사관이 그것이다. 이 프로그램은 근대 튀르키예 개혁 전통의 시작으로 여겨진다. 그러나 군단들과 지방 유력자(아얀)의 저항으로 1807년에 무너지게 된다.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["몰타 기사단의 청산 — 프랑스 함대의 도중 기항지", "d62f901d"], "d": ["이집트로 향하던 프랑스 함대는 도중에 몰타에 기항했고, 성 요한(몰타) 기사단은 별다른 저항 없이 섬을 넘겨주었다. 이로써 1522년 로도스에서 쫓겨나 이곳에 정착했던 기사 수도회의 마지막 요새가 사라졌다. 몰타는 2년 뒤 영국의 손에 들어가게 되며, 나폴레옹은 이 섬에서 곧바로 알렉산드리아로 향했다.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["나폴레옹의 이집트 침공", "93fede5f"], "d": ["보나파르트 장군의 군대는 알렉산드리아에 상륙해 이집트를 점령했다. 영국의 인도 항로를 겨냥한 이 원정은 유럽 강국이 오스만의 중심 영토를 직접 공격한 최초의 사건이었다. 아부키르에서의 넬슨의 기습과 제자르 아흐메드 파샤의 아크레 방어가 프랑스의 진격을 꺾었다. 점령은 1801년에 끝났으나, 그것이 남긴 공백 속에서 카발라 출신의 메흐메드 알리 파샤의 부상과 '동방 문제'의 시대가 시작되었다.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["세네디 이티팍(동맹 협약)", "cce49ef5"], "d": ["마흐무드 2세를 즉위시킨 루스추크의 유력자 알렘다르 무스타파 파샤의 주도로, 궁정과 지방의 강력한 아얀 가문들 사이에 체결된 문서이다. 아얀들은 술탄에 대한 충성과 군사 지원을 약속했고, 국가는 그들의 존재와 권리를 인정했다. 술탄의 권위가 문서로 제한된 오스만 역사상 최초의 사례였기 때문에 일부 역사가는 이를 헌정 전통의 먼 시발점으로 본다. 그러나 사실상 몇 달 만에 효력을 잃었다.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["그리스 독립 봉기의 시작", "a7293715"], "d": ["필리키 에테리아 조직이 준비한 봉기는 먼저 왈라키아에서, 이어 주력이 모인 모레아에서 터져 나왔다. 테펠레니의 알리 파샤 사태에 몰두해 있던 국가는 초기 대응이 늦었다. 이 반란은 유럽 여론의 강한 친그리스 정서(필헬레니즘) 덕분에 곧 국제적 대의가 되었으며, 이렇게 오스만 영토에서 민족주의 시대의 첫 성공적인 독립 운동에 불이 붙었다. 같은 날짜에 상실한 다른 정착지: 아테네, 파트라(발랴바드라), 테베, 리바디아, 엘레우시스(아티카), 미솔롱기.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["모레아의 첫 무장 봉기", "77e6250f"], "d": ["프루트강을 건넌 뒤 반란은 모레아로 번졌다. 칼라브리타에서(율리우스력 3월 21일) 시작된 무장 행동에 이어 파트라, 칼라마타, 마니에서 움직임이 일어났다. 모레아는 곧 전면 봉기 상태가 되었고 오스만 행정부는 반도의 대부분을 상실했다. 같은 날짜에 상실한 다른 정착지: 아테네, 파트라(발랴바드라), 테베, 리바디아, 엘레우시스(아티카), 미솔롱기.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["바카이 하이리예(경사스러운 사건) — 예니체리 군단 폐지", "08c9372a"], "d": ["새로 창설된 에쉬킨지 군단의 훈련에 반발해 '솥을 뒤엎은'(반란을 일으킨) 예니체리들은, 마흐무드 2세가 미리 준비한 충성 부대의 포격으로 에트메이다느의 병영에서 섬멸되었다. 군단은 모든 하부 조직 및 연계된 벡타시 교단의 수도장과 함께 폐지되었다. '경사스러운 사건'이라는 뜻의 이름으로 역사에 남은 이 작전은 400년 된 제도를 청산함으로써 아사키리 만수레이 무함마디예 군대와 이후의 모든 중앙집권화 개혁의 길을 열었다.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["나바리노 해전(기습)", "ee579e7f"], "d": ["그리스 반란을 진압하던 오스만-이집트 함대는, 선전포고 없이 항구에 들어온 영국-프랑스-러시아 연합 함대에 의해 나바리노에서 불태워졌다. 60척에 가까운 배와 수천 명의 선원을 잃었다. 유럽 외교가에서 '불행한 사건'으로 얼버무려진 이 습격은 그리스의 독립을 사실상 보장했으며 1828–29년 러시아-튀르크 전쟁의 길을 열었다.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["탄지마트 칙령", "5042ce7b"], "d": ["귈하네에서 낭독된 황제 칙서(핫트 휘마윤)로, 종교의 구분 없이 모든 신민의 생명, 재산, 명예의 안전이 국가의 보장 아래 놓였으며, 조세의 공정, 병역 질서, 재판 없는 처벌 금지의 원칙이 선포되었다. 무스타파 레시드 파샤의 작품인 이 칙령은 오스만 근대화의 헌법적 성격을 띤 첫 주요 문서로 여겨지며, 개혁의 시대인 '탄지마트 시대'(1839–1876)라는 명칭의 유래가 되었다. 행정, 법, 교육, 재정의 근본적인 재편이 이 틀 안에서 진행되었다.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["크림 전쟁 발발", "3b9ca3c8"], "d": ["성지 문제와 정교도 신민에 대한 러시아의 보호권 주장에서 시작된 위기는 오스만의 선전포고로 공개적인 무력 충돌이 되었다. 시노프 습격 이후 영국과 프랑스(나중에는 피에몬테)가 오스만 편에서 참전했다. 연합군이 크림에 상륙해 세바스토폴을 점령함으로써 전쟁은 1856년 파리 조약으로 승리했다. 그러나 전쟁 기간에 처음 들여온 외채(1854)는 제국을 반세기 동안 이어질 재정 종속의 악순환에 빠뜨렸다.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["개혁 칙령(이슬라하트 칙령)", "78ff234d"], "d": ["파리 강화 회담에 앞서 선포된 이 칙령은 탄지마트의 원칙을 확대하여 비무슬림 신민에게 관직 임용, 병역, 학교 설립을 포함한 폭넓은 평등권을 부여했고, 종교 공동체의 조직도 재편했다. 이어 체결된 파리 조약으로 오스만 국가는 유럽 국제법 공동체에 공식적으로 받아들여졌고, 영토 보전은 열강의 공동 보장 아래 놓였다. 그러나 이 보장은 실제로는 간섭의 새로운 문이 되었다.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["카눈 에사시(기본법) — 제1차 입헌기", "0fe052c1"], "d": ["발칸 위기를 논의하기 위해 이스탄불에 모인 국제 회의가 개막한 날, 최초의 오스만 헌법이 예포와 함께 선포되었다. 미드하트 파샤가 이끈 '신오스만인' 운동의 산물인 카눈 에사시로 양원제 의회가 설치되었다. 하원(메즐리시 메부산)은 1877년 3월에 개원했으나, 압뒬하미드 2세는 93 전쟁을 구실로 1878년 2월에 의회를 무기한 정회했고, 헌법은 30년 동안 정지 상태로 남았다.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["93 전쟁(1877–78년 러시아-튀르크 전쟁)", "5bd96af7"], "d": ["루미력 1293년에 해당하여 '93 전쟁'으로 불리는 이 전쟁에서 러시아군은 두 전선에서 공격했다. 가지 오스만 파샤의 플레브나 방어전과 아흐메드 무흐타르 파샤의 캅카스 전투는 서사시가 되었으나, 전선은 붕괴했고 러시아군은 예실쾨이(산스테파노)까지 진격했다. 이 전쟁은 발칸과 캅카스에서 이스탄불로 향하는, 그 영향이 오늘날까지 이어지는 대규모 무슬림 이주의 물결을 일으켰으며, 제국의 인구와 재정 구조는 다시는 이전 상태로 돌아가지 못했다.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["베를린 조약", "47f76a49"], "d": ["산스테파노가 만든 '대불가리아'를 열강의 세력 균형이라는 명분으로 수정한 베를린 회의도 여전히 무거운 결과를 남겼다. 세르비아, 몬테네그로, 루마니아가 독립했고, 자치 불가리아 공국이 세워졌으며, 보스니아-헤르체고비나는 오스트리아의 점령에, 키프로스는 영국의 통치에, 카르스-아르다한-바툼은 러시아에 넘겨졌다. 루멜리아의 500년 오스만 질서는 대체로 해체되었고, '동방 문제'는 유럽 외교의 상시적인 의제가 되었다. 같은 날짜에 상실한 다른 정착지: 플로브디프, 비딘, 터르노보, 바르나, 슈멘, 실리스트라, 루세, 부쿠레슈티, 이아시, 콘스탄차. 루마니아는 베사라비아를 러시아에 넘기는 대신 툴체아와 도브루자를 얻었다. 북도브루자의 툴체아, 바바다그, 머친, 이삭체아, 허르쇼바, 망갈리아가 루마니아로 넘어갔다.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["튀니지 점령과 오스만 공채 관리청", "c7e25598"], "d": ["프랑스는 알제리 국경의 사건들을 구실로 튀니지를 점령하고 바르도 조약으로 보호령으로 삼았으며, 북아프리카에서 오스만의 존재는 트리폴리타니아로 줄어들었다. 같은 해 반포된 무하람 칙령으로 파산 상태의 외채를 관리하기 위해 채권자들이 대표로 참여하는 오스만 공채 관리청(뒤윤 우무미예)이 설립되었다. 소금, 담배, 비단 같은 기본 세입이 이 외국 기구에 직접 귀속되었고, 재정 주권은 심각하게 제한되었다. 같은 날짜에 상실한 다른 정착지: 카이르완, 가베스, 스팍스, 제르바.", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["영국의 이집트 점령", "f1269768"], "d": ["이집트에서 재정 파탄과 외국의 통제에 맞서 일어난 우라비 파샤 운동은, 알렉산드리아 포격 이후 상륙한 영국군의 텔 엘케비르 전투 승리로 분쇄되었고 카이로가 점령되었다. 이집트는 법적으로는 오스만에 계속 속해 있었으나 사실상 영국의 통치 아래 들어갔다. 수에즈 운하의 통제는 대영 제국 전략의 중심에 자리 잡았다.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["제2차 입헌기의 선포", "95ee2fd2"], "d": ["통일진보위원회에 속한 장교들이 마케도니아의 산으로 들어가면서 커진 운동 앞에서, 압뒬하미드 2세는 카눈 에사시를 다시 발효시켰다. '자유의 선포'는 열광 속에서 환영받았고 선거가 치러졌다. 그러나 안정은 오지 않았다. 3월 31일 사건(1909년 4월)이 진압된 뒤 압뒬하미드는 폐위되었다. 불가리아의 독립, 보스니아의 병합, 크레타의 그리스 지향도 이 격동의 몇 달 동안 일어났다.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["트리폴리타니아 전쟁", "ed441994"], "d": ["식민지를 찾던 이탈리아는 북아프리카에 남은 오스만의 마지막 영토인 트리폴리타니아에 선전포고하고 해안을 점령했다. 해군이 없는 국가가 정규군을 보낼 수 없게 되자, 무스타파 케말과 엔베르 베이 같은 젊은 장교들이 비밀리에 이 지역으로 건너가 사누시 부족들과 함께 효과적인 저항을 조직했다. 발칸 전쟁이 터지자 체결된 우시 조약(1912년 10월 18일)으로 리비아는 이탈리아에 넘겨졌고, 이탈리아는 로도스와 도데카네스 제도도 점령했다.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["런던 조약 — 루멜리아의 상실", "f3f976df"], "d": ["제1차 발칸 전쟁을 끝낸 런던 조약으로 미디예-에네즈 선 서쪽의 모든 영토와 에게해 섬들을 잃었고, 알바니아는 독립했다. 500년 넘게 제국의 인구, 경제, 문화의 무게 중심이던 루멜리아 가운데 남는 것은 동트라키아뿐이었다(에디르네는 제2차 발칸 전쟁에서 되찾았다). 이 상실은 통일파 정권의 전쟁 정책과 이주 정착 정책을 근본적으로 강경하게 만들었다. 미디예-에네즈 선 서쪽의 다음 지역들이 상실되었다: 스코페, 벨레스, 슈티프, 스트루미차, 도이란, 게브겔리야, 모나스티르, 오흐리드, 데바르(디브라), 프리즈렌, 프리슈티나, 페치, 노비파자르, 코소보폴례; 세레스, 드라마, 카발라, 페트리치, 네브로코프, 크산티, 코모티니, 데데아아치, 디디모티호, 치르멘, 페레스, 수플리, 오레스티아다(쿰치프틀리이), 프라비슈테(엘레프테루폴리), 스테르나, 타브리, 우무르 파키흐(파키아), 말락 데르벤트(랄코보); 크레타에서는 하니아, 칸디아, 레팀노, 시티아, 스파키아.", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["제1차 세계 대전 참전", "05a0252e"], "d": ["영국 해군을 피해 온 전함 괴벤과 브레슬라우를 구입한 것처럼 꾸며 해협 안으로 받아들인 일은 국가를 차츰 독일 편으로 끌어들였다. 수숑 제독이 지휘하는 함대가 러시아 항구들을 포격하면서(10월 29일) 전쟁은 사실상 시작되었고, 상호 선전포고는 11월 초에 이루어졌다. 대지하드(지하디 에크베르) 선포에도 기대한 효과는 나타나지 않았다. 제국은 4년 동안 캅카스에서 팔레스타인에 이르는 다섯 개의 전선에서 생존 전쟁에 뛰어들었다.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["차나칼레 전투의 승리", "95d888e8"], "d": ["이스탄불을 함락해 러시아에 닿으려던 연합 함대는 3월 18일 기뢰선과 포대의 화력에 막혀 해협에서 격퇴되었다. 기뢰 부설함 누스레트가 부설한 기뢰선이 전투의 운명을 결정지었다. 4월에 시작된 갈리폴리 지상 작전도 아나파르탈라르와 존크바이으르에서 저지되었고, 연합군은 1916년 1월 반도에서 완전히 철수했다. 무스타파 케말 중령의 이름은 이 전선에서 알려졌다. 약 25만 명의 전사자와 사상자를 대가로 거둔 이 승리는 민족 투쟁의 인재들과 그 정신이 태어난 곳으로 여겨진다.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["샤리프 후세인의 반란", "75f7c58c"], "d": ["메카의 아미르 샤리프 후세인은 영국과의 비밀 서신 교환 끝에 독립 아랍 왕국의 약속을 받고 봉기했으며, 히자즈 철도는 습격의 표적이 되었다. 휴전 이후까지 이어진 파흐레딘 파샤의 전설적인 메디나 방어는 저항의 상징으로 남았으나, 이 반란은 팔레스타인 전선의 영국군 진격과 맞물려 아랍 속주들에서 오스만 지배의 해체를 앞당겼다. 같은 날짜에 상실한 다른 정착지: 후르마, 투라바.", "f7c6b3e9"]},
"OLAYLAR:1918-10-30:0":{"b": ["무드로스 휴전 협정", "9e87c767"], "d": ["불가리아의 붕괴로 전선들이 서로 단절된 오스만 국가는 전함 아가멤논호에서 체결한 휴전 협정으로 전쟁에서 물러났다. 해협의 개방, 특히 안전이 위협받는 지역의 점령을 가능하게 한 제7조는 곧 사실상의 분할을 위한 법적 외피가 되었다. 모술, 이스켄데룬, 이어 이즈미르와 이스탄불이 점령되었다. 이 휴전 협정은 제국의 사실상 종말을 알리는 문서로 여겨진다. 같은 날짜에 상실한 다른 정착지: 하마, 다마스쿠스, 홈스.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["삼순에 도착한 무스타파 케말 — 민족 투쟁", "09a8f784"], "d": ["이즈미르 점령이 일으킨 격분의 분위기 속에서 제9군 감찰관 자격으로 삼순에 상륙한 무스타파 케말 파샤는 자신의 공식 임무를 아나톨리아의 저항을 조직하는 일로 바꾸었다. 아마시아 회람과 에르주룸 및 시바스 회의는 이 행보의 연장이다. '민족의 독립은 다시 민족의 의지와 결단이 구할 것이다'라는 원칙은 민족 투쟁의 정치 강령의 핵심이 되었다.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["튀르키예 대국민의회 개원과 세브르 조약", "2008feec"], "d": ["이스탄불이 공식 점령되고 하원이 해산되자 1920년 4월 23일 앙카라에서 대국민의회가 개원했다. 비상 권한을 한 손에 모은 의회는 국민의 의지에 기초한 새 국가의 핵심이 되었다. 8월에 이스탄불 정부가 서명한 세브르 조약은 아나톨리아를 분할하는 것이었다. 튀르키예 대국민의회는 조약에 서명한 이들을 조국의 반역자로 선언했고, 세브르 조약은 끝내 시행되지 못했다.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["사카리아 전투", "f2f970a6"], "d": ["앙카라에서 50킬로미터까지 다가온 그리스군의 공세는, 총사령관 권한을 맡은 무스타파 케말 파샤의 '방어선은 없다, 방어면이 있을 뿐이다'라는 명령 아래 치러진 22일 밤낮의 전투에서 꺾였다. 그리스군은 처음으로 전략적 수세로 돌아섰다. 이 승리는 무스타파 케말에게 가지 칭호와 원수(뮈시르) 계급을 안겨 주었고, 프랑스와의 앙카라 협정과 대외 승인의 문을 열었다.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["대공세와 이즈미르 해방", "172a50c4"], "d": ["8월 26일 아침 코자테페에서 시작된 공세는 8월 30일 둠루프나르에서의 총사령관 전투로 그리스군 주력의 섬멸에 이르렀다. '군대여, 제군의 첫 목표는 지중해다, 전진!'이라는 명령과 함께 이어진 추격으로 9월 9일 이즈미르가 해방되었다. 무다니아 휴전 협정(10월 11일)으로 동트라키아는 전투 없이 되찾아졌다. 이 군사적 승리는 로잔에서 수립될 새 국가가 협상 탁자에서 지닐 힘을 결정지었다.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["술탄제 폐지", "9f36a9f6"], "d": ["이스탄불 정부도 로잔 회담에 초청되자 튀르키예 대국민의회는 1922년 11월 1일 술탄제와 칼리파 지위를 분리하고 술탄제를 폐지했다. 623년에 걸친 오스만 왕조의 통치는 법적으로 종말을 맞았다. 메흐메드 6세 바히데딘은 11월 17일 영국 전함을 타고 나라를 떠났다. 대국민의회의 결정으로 압뒬메지드 에펜디가 칼리파 직에 올랐으며, 이 직위도 1924년 3월 3일에 폐지된다.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["로잔 조약", "38c27f7d"], "d": ["8개월에 걸친 힘겨운 협상 끝에 체결된 로잔 강화 조약으로 새 튀르키예 국가의 국경, 완전한 독립, 주권이 국제적으로 인정되었다. 불평등 특권(카피툴레이션)은 폐지되었고, 오스만 공채 관리청은 청산 절차에 들어갔으며, 주민 교환이 규정되었다. 세브르를 사실상 무효로 만든 로잔 조약은 민족 투쟁의 외교적 승리이자 공화국의 건국 대외 문서로 여겨진다.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["공화국 선포", "d5bfcdfb"], "d": ["튀르키예 대국민의회가 헌법 개정을 통해 '튀르키예 국가의 정부 형태는 공화국이다'라는 조항을 채택하면서 공화국이 선포되었고, 무스타파 케말 파샤가 초대 대통령으로 선출되었다. 1299년 접경 베이국으로 시작한 624년의 오스만 여정은 이렇게 막을 내렸으며, 주권이 조건 없이 국민에게 속하는 새 국가가 제국의 유산 위에 세워졌다.", "f5cabb8c"]},
"OLAYLAR_2S_0918:1284-01-01:0":{"b": ["헝가리 왕이 베오그라드와 마추바를 드라구틴에게 줌", "a4c2c535"], "d": ["1282년 퇴위한 세르비아 왕 스테판 드라구틴에게 헝가리 왕은 1284년 마추바와 베오그라드의 통치를 맡겼다. 베오그라드는 30년 넘게 드라구틴의 수중에 남았다(헝가리의 종주권 아래의 스렘 왕국).", "2fb699cd"]},
"OLAYLAR_2S_0918:1293-01-01:0":{"b": ["알라니아(알라이예)가 셀주크 이후 시기에 지방 베이국의 통제하에 들어감", "7b1489b3"], "d": ["1290년대에 아나톨리아 셀주크 국가가 사실상 해체되면서, 지중해 연안의 알라이예(알라니아) 항구는 중앙 권력에서 벗어나 이 지역 베이국들(이 시기에는 카라만 왕조의 영향권 안)의 통제하에 들어갔다. 정확한 날짜와 어느 베이국이 직접 지배했는지는 사료에서 분명하지 않다.", "78a4ff46"]},
"OLAYLAR_2S_0918:1319-01-01:0":{"b": ["헝가리가 밀루틴에게서 베오그라드를 되찾음", "16d254a2"], "d": ["1316년 드라구틴이 죽은 뒤 세르비아는 베오그라드를 계속 보유하려 했고, 헝가리는 반환을 요구했다. 1319년 헝가리군이 공격했고, 몇 달에 걸친 전투 끝에 세르비아군이 물러났으며, 폐허가 된 도시는 헝가리의 마추바 바나트에 편입되었다. 베오그라드는 1403-04년 스테판 라자레비치에게 넘겨질 때까지 헝가리의 통치하에 남았다.", "feb8ea91"]},
"OLAYLAR_2S_0918:1322-01-01:0":{"b": ["가지 첼레비가 시노프를 점령, 잔다르 왕조의 세력권에 들어감", "f107586a"], "d": ["일 칸국의 지배가 약해지면서 카스타모누와 시노프 지역에서 세력을 키운 잔다르(이스펜디야르) 베이국의 창업 가문 출신인 가지 첼레비는 1322년경 시노프를 점령하여 이 도시를 베이국의 항구 중심지로 만들었다.", "35c2fa9c"]},
"OLAYLAR_2S_0918:1322-03-01:0":{"b": ["슈비치 백작가와 베네치아 사이에 놓인 시베니크가 베네치아에 귀속", "99b341e0"], "d": ["크로아티아의 대영주인 브리비르의 슈비치 백작가와 베네치아 사이에 놓인 시베니크는 1322년 3월 1일 스스로 베네치아에 귀속했으며, 1357년까지 베네치아 통치하에 남았다.", "120581de"]},
"OLAYLAR_2S_0918:1322-04-17:0":{"b": ["트로기르가 브리비르의 크네즈들에 맞서 베네치아에 귀속", "4ccf9ce4"], "d": ["브리비르의 슈비치 백작가의 압박을 받던 트로기르는 자유를 지키기 위해 1322년 4월 17일 스스로 베네치아에 귀속했으며, 1357년까지 베네치아의 보호하에 남았다.", "e69237c1"]},
"OLAYLAR_2S_0918:1327-09-18:0":{"b": ["스플리트에서 헝가리 주권 종료 — 베네치아 통치 시작", "4b04ca1a"], "d": ["1133년부터 이어진 스플리트 코무네에 대한 헝가리의 주권은 1327년 9월 18일 끝났다. 도시는 베네치아 통치하에 들어가 1357년까지 그 상태로 있었다.", "75ef7dfc"]},
"OLAYLAR_2S_0918:1357-01-01:0":{"b": ["스플리트에서 베네치아 통치 종료 — 헝가리 지배 재개", "e99628fc"], "d": ["1327년에 시작된 스플리트의 베네치아 통치는 1357년 끝났다. 도시는 다시 헝가리의 직접 지배하에 들어갔다(1420년까지).", "84447172"]},
"OLAYLAR_2S_0918:1357-07-09:0":{"b": ["트로기르가 베네치아의 보호에서 벗어남 — 헝가리 지배 재개", "7f112aa8"], "d": ["트로기르는 1357년 7월 9일까지 베네치아의 보호와 통치하에 남았다. 앙주의 러요시가 달마티아를 베네치아에게서 떼어 내기 시작한 때에 이 보호에서 벗어나 크로아티아-헝가리 왕국의 주권으로 돌아갔다.", "6a7c7a44"]},
"OLAYLAR_2S_0918:1357-12-14:0":{"b": ["시베니크가 베네치아에서 이탈 — 헝가리의 지배로 넘어감", "adb9d6ca"], "d": ["앙주의 러요시가 달마티아를 베네치아에게서 떼어 내고 있던 때에, 시베니크는 1357년 12월 14일 베네치아에서 이탈하여 헝가리의 지배하에 들어갔다.", "7af69a3b"]},
"OLAYLAR_2S_0918:1358-02-18:0":{"b": ["자다르 조약 — 두브로브니크가 베네치아에서 헝가리의 보호하로 넘어감", "57fb81f9"], "d": ["1358년 2월 18일 체결된 자다르 조약은 150년에 걸친 베네치아의 달마티아 지배를 끝냈다. 이로써 두브로브니크(라구사)는 베네치아 통치에서 벗어나 헝가리 왕 러요시 1세의 보호를 받는 반자치 공화국의 지위를 얻었다.", "e207c893"]},
"OLAYLAR_2S_0918:1358-05-27:0":{"b": ["비셰그라드 특권 — 두브로브니크가 헝가리 왕 러요시 1세에게 귀속", "9d3d02a8"], "d": ["자다르 평화 조약(1358년 2월)으로 베네치아가 달마티아에 대한 권리를 포기하자, 두브로브니크는 러요시 1세 왕과 별도로 교섭했다. 1358년 5월 비셰그라드 특권으로 헝가리 왕관에 귀속되었다(보호의 대가로 충성, 연간 공납과 병력 제공).", "d37ccc8a"]},
"OLAYLAR_2S_0918:1390-06-01:0":{"b": ["트브르트코 1세가 달마티아 해안 도시들(시베니크 포함)의 지배권을 장악", "c53aad4d"], "d": ["보스니아 왕 트브르트코 1세는 1390년 자다르를 제외한 달마티아 해안 도시들의 지배권을 장악했다. 시베니크도 헝가리의 지배에서 벗어나 보스니아 왕의 종주권을 인정했다.", "dfb86467"]},
"OLAYLAR_2S_0918:1391-01-01:0":{"b": ["트브르트코 1세의 죽음; 시베니크는 헝가리의 지배로 복귀", "ef2d3b2f"], "d": ["1391년 보스니아 왕 트브르트코 1세가 죽으면서 시베니크에 대한 보스니아의 종주권은 끝났다. 도시는 헝가리 왕 지기스문트의 지배하에 들어갔다(1391-1402).", "0f8c4ab3"]},
"OLAYLAR_2S_0918:1408-01-01:0":{"b": ["흑양 왕조와 티무르 왕조의 쟁탈 속에 에르주룸·아슈칼레 지역의 주인이 바뀜", "ca64775a"], "d": ["1405년 티무르가 죽은 뒤 생긴 권력 공백 속에서, 흑양 왕조의 군주 카라 유수프는 1406-1408년에 동부 아나톨리아의 티무르 총독들을 상대로 행동에 나섰다. 에르주룸과 인근의 아슈칼레는 이 투쟁에서 티무르의 통제를 벗어나 흑양 왕조의 세력권에 들어갔다.", "10b1b07c"]},
"OLAYLAR_2S_0918:1409-07-31:0":{"b": ["자다르가 베네치아 통치하에 들어감 — 산타 인트라다", "820c9276"], "d": ["나폴리 왕 라디슬라스가 달마티아를 베네치아에 팔자, 자다르 주민들은 나폴리 병사들을 도시에서 몰아냈다. 1409년 7월 31일 베네치아의 프로베디토레들이 도시에 들어와 1797년까지 지속될 베네치아 통치를 세웠다.", "06e4d6fa"]},
"OLAYLAR_2S_0918:1420-06-22:0":{"b": ["트로기르가 베네치아 통치하에 들어감", "fbca501f"], "d": ["베네치아가 헝가리와 전쟁하던 중 총사령관 피에로 로레단의 함대가 도착하면서, 트로기르는 1420년 6월 22일 베네치아 통치로 넘어갔다. 달마티아 도시 가운데 마지막으로 베네치아에 합류한 이 도시는 1797년까지 베네치아 깃발 아래 남았다.", "8ebaf8eb"]},
"OLAYLAR_2S_0918:1462-01-01:0":{"b": ["백양 왕조의 우준 하산이 하산케이프의 아이유브 분가를 없앰", "2b464a1f"], "d": ["상부 티그리스에서, 하마의 분가와 함께 아이유브 왕조의 마지막 남은 두 분가 가운데 하나였던 하산케이프(히슨 카이파)와 시이르트는 1462년 백양 왕조의 군주 우준 하산에게 병합되었고, 아이유브의 지배는 끝났다.", "8bf494b3"]},
"OLAYLAR_2S_0918:1515-04-01:0":{"b": ["포르투갈, 호르무즈 해협 연안의 지배를 완성", "bef031f0"], "d": ["아폰수 드 알부케르크가 1507년에 시작한 페르시아만 원정은 1515년 호르무즈섬과 맞은편 해안의 키슘 및 부라이미까지 포괄하여 완료되었다. 이란에 종속되어 있던 호르무즈 왕국은 사실상 포르투갈의 보호하에 들어갔고, 포르투갈은 만의 교역을 장악했다.", "117a5c7e"]},
"OLAYLAR_2S_0918:1569-07-01:0":{"b": ["루블린 연합 — 우크라이나 땅이 리투아니아에서 폴란드로 넘어감", "1881ceff"], "d": ["1569년 7월 1일 체결된 루블린 연합은 리투아니아 대공국과 폴란드 왕국을 하나의 국가(제치포스폴리타)로 통합했다. 협정 조건에 따라 포돌리아, 볼히니아, 키예프 지역(바르, 베르디치우, 비아위스토크, 브라츨라프 포함)은 행정상 리투아니아에서 폴란드 왕국으로 직접 이관되었다.", "184b03dd"]},
"OLAYLAR_2S_0918:1776-02-14:0":{"b": ["피우메의 행정이 헝가리 왕관에 속한 크로아티아로 이관", "dfedccf8"], "d": ["마리아 테레지아 여제는 1776년 2월 14일 칙령으로 피우메의 행정을 자그레브 평의회를 통해 헝가리에 맡겼다. 1779년의 디플로마는 이 도시를 헝가리 왕관에 직접 속하는 별개의 단체(corpus separatum)로 만들었다.", "bbf160dd"]},
"OLAYLAR_2S_0918:1809-10-14:0":{"b": ["피우메가 쇤브룬 평화 조약으로 프랑스에 이양(일리리아주)", "16bf1fca"], "d": ["1809년 10월 14일의 쇤브룬 평화 조약으로 피우메는 오스트리아에서 프랑스로 넘어갔고, 1813년까지 나폴레옹의 일리리아주의 일부였다.", "417a8ae7"]},
"OLAYLAR_2S_0918:1813-01-01:0":{"b": ["피우메가 프랑스령 일리리아 통치에서 합스부르크로 복귀", "1b5b9954"], "d": ["1813년 나폴레옹이 러시아에서 패한 뒤, 피우메는 일리리아주에서 벗어나 오스트리아 제국으로 돌아갔다.", "5db16c92"]},
"OLAYLAR_2S_0918:1822-10-15:0":{"b": ["피우메가 헝가리 왕국에 반환됨", "aafdd0ee"], "d": ["프란츠 1세의 1822년 7월 5일 결정에 따라, 헝가리 정부를 대표하여 마일라트 죄르지 백작이 1822년 10월 15일 도시를 인수했다. 피우메는 헝가리 왕국으로 돌아갔다.", "e30af380"]},
"OLAYLAR_2S_0918:1841-10-01:0":{"b": ["이집트군이 아흐사(라흐사) 지역에서 철수", "5ea75c8d"], "d": ["메흐메트 알리 파샤의 이집트군은 1836년 나지드와 동부 아라비아(아흐사, 카티프, 우카이르, 주바일 포함)를 점령했다. 1840년 런던 해협 조약이 이집트에 아라비아반도의 정복지를 포기하게 하자, 군대는 1841년 이 지역에서 철수했고 통치는 다시 현지 세력(사우드/알칼리파의 영향력)에게 돌아갔다.", "99ff8f81"]},
"OLAYLAR_2S_0918:1853-07-28:0":{"b": ["아크메치트 요새가 러시아군에 점령 — 코칸트 칸국의 시르다리야 방어선 붕괴", "e9f9a9c7"], "d": ["바실리 페롭스키 장군이 이끄는 러시아군은 코칸트 칸국에 속한 시르다리야 강변의 아크메치트 요새를 긴 포위 끝에 1853년 7월 점령했다. 이 요새는 훗날 페롭스크라는 이름으로 러시아령 투르키스탄의 전초 기지가 되었다.", "9e64a219"]},
"OLAYLAR_2S_0918:1881-01-24:0":{"b": ["괵테페 전투 — 아할 테케 투르크멘이 러시아에 패배", "76c7a102"], "d": ["미하일 스코벨레프 장군이 이끄는 러시아군은 1881년 1월 24일 괵테페(게오크 테페) 요새를 함락시켜 아할 테케 투르크멘의 저항을 꺾었다. 데히스탄 평원, 아비바르드, 니사를 포함한 카스피해 너머의 투르크멘 지역은 러시아 제국에 편입되는 과정에 들어갔다(자카스피 주는 1881년에 설치되었다). 이 사건으로 크즐아르바트와 아시가바트(아할 투르크멘의 땅)는 러시아로 넘어갔다.", "f294fbe6"]},
"OLAYLAR_2S_0918:1881-03-26:0":{"b": ["루마니아 왕국 선포 — 공국이 왕국이 됨", "4d413f0c"], "d": ["1877-78년 오스만-러시아 전쟁 이후 베를린 회의에서 독립을 인정받은 루마니아 공국은 1881년 3월 26일(율리우스력 3월 14일) 카롤 1세 국왕의 대관과 함께 왕국으로 전환되었다. 바바다그, 비를라드, 부저우와 수도 부쿠레슈티를 비롯한 전 국토는 행정상 새 왕국의 일부가 되었다. 왕국 선포와 함께 루마니아 전체(이아시, 갈라치, 브러일라, 콘스탄차, 툴체아, 칼라파트 및 기타 도시)가 루마니아 왕국이 되었다.", "fbab3abf"]},
"OLAYLAR_2S_0918:1889-01-01:0":{"b": ["이탈리아, 아스마라와 케렌을 포함한 에리트레아 고원을 병합", "31308dc8"], "d": ["1889년 에티오피아 황제 요한네스 2세의 죽음으로 생긴 권력 공백을 이용하여 이탈리아는 우치알리(우찰레) 조약(1889년 5월 2일) 이후 아스마라와 케렌을 포함한 에리트레아 고원을 사실상 병합했고, 1890년 1월 1일 '에리트레아'라는 이름의 식민지를 공식 선포했다. 이 사건으로 케렌은 이탈리아 통치로 넘어갔다.", "b6bbb0a5"]},
"OLAYLAR_2S_0918:1895-07-01:0":{"b": ["케냐 북동부(가리사-마르사비트 선)가 영국령 동아프리카 보호령에 편입", "e45c6d43"], "d": ["1895년 대영제국 동아프리카 회사의 특허권이 왕실에 이관되면서 수립된 영국령 동아프리카 보호령은 가리사, 키투이, 마르사비트, 와지르 같은 북동부 지역까지 포함하도록 확장되었다. 이 내륙 지역들이 실질적 행정하에 놓이기까지는 1890년대 후반에 걸쳐 진행되었다.", "8cf3e473"]},
"OLAYLAR_2S_0918:1897-02-16:0":{"b": ["일로린 토후국이 왕립 나이저 회사의 군대에 점령됨", "b111cb7d"], "d": ["소코토 칼리파국에 종속된 일로린 토후국은 조지 골디 경이 이끄는 왕립 나이저 회사 군대의 1897년 2월 원정에서 점령되었다. 토후국의 군사력은 꺾였고 이 지역은 사실상 영국의 세력권에 들어갔다(공식 병합은 1900년 북나이지리아 보호령 수립으로 완료되었다).", "95f49872"]},
"OLAYLAR_2S_0918:1899-04-09:0":{"b": ["분요로의 왕 카발레가 생포, 왕국이 영국령 우간다 보호령에 편입", "62bc7c64"], "d": ["1894년부터 영국군에 저항해 온 분요로의 왕 카발레가는 1899년 4월 9일 랑고 지역(도콜로 인근)에서 붙잡혀 세이셸로 유배되었다. 수도 호이마와 마신디를 비롯한 왕국의 영토는 영국령 우간다 보호령에 편입되었다.", "87bc3dd6"]},
"OLAYLAR_2S_0918:1900-06-26:0":{"b": ["토로 협정 — 토로 왕국이 영국령 우간다 보호령의 자치 지역이 됨", "c55340a2"], "d": ["1899년 분요로가 몰락한 뒤, 이웃한 토로 왕국은 1896년부터 이어진 영국의 보호 관계를 1900년 우간다 협정의 틀 안에서 공식화했다. 수도 포트포털을 포함한 왕국은 영국령 우간다 보호령 안에서 자치 지방 행정의 지위를 얻었다.", "8459a73a"]},
"OLAYLAR_2S_0918:1901-09-02:0":{"b": ["아다마와 토후국이 독일과 영국 사이에 분할됨", "b9230d3d"], "d": ["소코토 칼리파국에 종속된 아다마와(폼비나) 토후국은 1899-1901년 독일과 영국 식민군의 원정 끝에 둘로 나뉘었다. 동부(가루아, 바뇨, 마루아, 응가운데레 포함)는 독일령 카메룬에, 서부(수도 욜라)는 영국령 북나이지리아에 편입되었고, 아미르 주바이르는 유배되었다. 이 사건으로 레이 부바(아다마와(독일 몫))는 독일령 카메룬의 통치로 넘어갔다.", "e3ebfafa"]},
"OLAYLAR_2S_0918:1902-05-07:0":{"b": ["티트 전투 — 아하가르 투아레그가 프랑스군에 패배", "831143d6"], "d": ["코트네스트 원정 중 1902년 5월 7일 티트 오아시스 인근에서 벌어진 전투에서 프랑스군은 켈 아하가르 투아레그를 결정적으로 격파했다. 아하가르의 중심지 아발레사와 이델레스를 비롯한 사하라의 이 내륙 지역은 프랑스령 알제리의 통제하에 들어갔다.", "5c1e86d4"]},
"OLAYLAR_2S_0918:1903-01-01:0":{"b": ["프랑스군이 우방기샤리 내륙(밤바리-브리아 선)을 점령", "0b9a9f72"], "d": ["1900년대 초 프랑스령 콩고의 북부 원정은 밤바리, 바탕가포, 보상고아, 브리아를 포함한 우방기샤리 내륙 지역을 실질적으로 장악했다. 이 지역은 1903년 12월 29일 공식적으로 우방기샤리 식민지로 편성되었다(프랑스령 적도 아프리카의 일부).", "ebbd38e7"]},
"OLAYLAR_2S_0918:1911-01-12:0":{"b": ["술탄 무함마드 알사누시의 다르 알쿠티 술탄국이 프랑스군에 의해 소멸", "644b2c3f"], "d": ["1897년 프랑스의 보호하에 들어간, 수도 은델레의 노예 무역에 기반한 다르 알쿠티 술탄국은 술탄 무함마드 알사누시가 프랑스의 권위에 계속 저항하자 1911년에 실시된 원정으로 사실상 소멸했다. 사누시는 전투에서 죽었고, 술탄국은 1912년 공식 폐지되었다.", "3f913340"]},
"OLAYLAR_2S_0919:1328-01-01:0":{"b": ["리보니아 기사단이 클라이페다(메멜) 영토를 튜턴 기사단의 프로이센 지부에 이양", "e61e5d50"], "d": ["리보니아 기사단은 네만강 어귀의 클라이페다(메멜) 성과 그 일대의 영토를 튜턴 기사단의 프로이센 지부에 넘겼다. 쿠를란트 주교도 자신의 몫을 1392년 같은 지부에 이양했다. 클라이페다는 1411년 토룬 평화 조약과 1422년 멜노 평화 조약에서도 기사단에 남았고, 1525년 프로이센 공국으로 넘어갔다.", "cad2853d"]},
"OLAYLAR_2S_0919:1329-01-01:0":{"b": ["우무르 베이가 제노바인에게서 이즈미르의 항구 요새를 빼앗음", "ab92d96e"], "d": ["아이든 왕조의 우무르 베이는 라틴인의 수중에 남아 있던 이즈미르의 항구 요새를 2년 반 동안 포위했다. 요새의 제노바인 통치자 마르티노 자카리아는 요새를 넘기고 키오스로 떠났다.", "1bec5de9"]},
"OLAYLAR_2S_0919:1343-01-01:0":{"b": ["수타이 가문의 이브라힘 샤가 디야르바크르를 장악", "179196cf"], "d": ["일 칸국이 해체된 뒤 잘라이르 왕조와 추판 왕조 사이의 투쟁 무대가 된 디야르바크르 지역을 수타이 가문의 이브라힘 샤가 장악했다. 그의 지배는 1353년까지 이어졌다.", "6143de93"]},
"OLAYLAR_2S_0919:1348-01-01:0":{"b": ["압드 알와드(자얀) 왕조가 틀렘센에서 마린 왕조의 지배를 벗어남", "a4aa9573"], "d": ["틀렘센의 압드 알와드 왕조는 우스만 2세와 그의 동생 아부 사비트의 지도 아래 마린 왕조의 지배에서 벗어났다. 이 독립은 오래가지 못했다.", "0afdf111"]},
"OLAYLAR_2S_0919:1351-01-01:0":{"b": ["바이람 호자의 독립 — 흑양 베이국의 탄생", "37964815"], "d": ["흑양 왕조의 초대 베이로 여겨지는 바이람 호자는 수타이 왕조의 군주 아크차사칼 휘세인 베이를 죽이고 독립을 얻었다. 그는 모술을 점령하고 그 통치를 동생 비르디 호자에게 맡겼다.", "892dced7"]},
"OLAYLAR_2S_0919:1353-01-01:0":{"b": ["이브라힘 샤가 죽으면서 디야르바크르가 잘라이르 왕조의 통치하에 들어감", "11c338ef"], "d": ["1343년부터 디야르바크르 지역을 지배해 온 수타이 가문의 이브라힘 샤가 죽자, 이 지역은 잘라이르 왕조의 통치하에 들어갔다.", "155719ec"]},
"OLAYLAR_2S_0919:1355-01-01:0":{"b": ["에네즈가 제노바인의 통치로 넘어감(가틸루시오 가문)", "5dc12940"], "d": ["비잔티움 시대에 중요한 항구 도시였던 에네즈는 1355년 제노바인의 통치로 넘어가 가틸루시오 가문이 다스렸다.", "33faefdd"]},
"OLAYLAR_2S_0919:1356-01-01:0":{"b": ["리투아니아 대공 알기르다스(올게르드)가 브랸스크를 점령", "3cad9caf"], "d": ["리투아니아 대공 알기르다스의 군대가 브랸스크를 점령했다. 이 도시는 1500년까지 리투아니아 대공국에 속했다.", "03107c6d"]},
"OLAYLAR_2S_0919:1368-01-01:0":{"b": ["이난치 가문이 게르미얀 왕조의 종주권을 인정", "0679db27"], "d": ["데니즐리 일대를 다스리던 이난치 베이국은 아마도 1368년에 게르미얀 왕조의 종주권을 인정했다.", "55ce9f1f"]},
"OLAYLAR_2S_0919:1371-11-01:0":{"b": ["테살로니키의 데스포트 마누엘이 세레스·드라마 지역을 비잔티움 통치하에 둠", "abb99c3e"], "d": ["치르멘(1371년 9월 26일)에서 부카신 왕과 세레스의 데스포트 우글레샤가 죽으면서 세레스 지역의 세르비아 통치는 끝났다. 테살로니키를 다스리던 비잔티움 황자 마누엘 2세 팔라이올로고스는 1371년 11월 세레스와 드라마를 포함한 지역을 비잔티움 통치하에 두었다. 이 지역은 1383년 9월 오스만에게 넘어갔다.", "b0802648"]},
"OLAYLAR_2S_0919:1378-01-01:0":{"b": ["피르 휘세인 베이가 죽으면서 에르진잔과 바이부르트가 무타하르텐에게 넘어감", "3269e55d"], "d": ["에르진잔의 아미르 피르 휘세인 베이가 죽자, 에르진잔과 바이부르트는 에레트나의 아미르 가운데 한 명인 무타하르텐의 손에 들어갔고, 무타하르텐은 에르진잔의 아미르가 되었다.", "4993bac9"]},
"OLAYLAR_2S_0919:1379-01-01:0":{"b": ["타제딘 베이가 닉사르에서 에레트나군을 격파하고 독자 행동을 함", "42982ea7"], "d": ["1379년 봄, 타제딘 베이는 닉사르를 공격한 카디 부르하네딘과 에레트나의 베이 알라에딘 알리의 군대를 격파했다. 그는 에레트나 베이국에 세금 바치기를 중단하고 781년(1379)부터 독자적으로 행동했다.", "5d809820"]},
"OLAYLAR_2S_0919:1379-01-01:1":{"b": ["티무르가 호라즘을 완전히 장악", "ef76d2c9"], "d": ["티무르는 1371년의 첫 호라즘 원정 이후 세 차례 더 원정을 실시했다. 1379년 원정에서 이 지역을 완전히 장악하고 약탈한 뒤 많은 전리품을 가지고 돌아갔다.", "f2ebd27a"]},
"OLAYLAR_2S_0919:1382-01-01:0":{"b": ["보스니아 왕 트브르트코 1세가 헤르체그노비를 건설", "1628221a"], "d": ["보스니아 왕 트브르트코 1세는 소금 무역에서 두브로브니크와 경쟁하기 위해 토플라만에 새 마을을 세웠다. 이 마을은 훗날 노비(헤르체그노비)라 불렸다.", "b970dc7f"]},
"OLAYLAR_2S_0919:1384-01-01:0":{"b": ["둘카디르 가문의 할릴 베이가 맘루크에게서 엘비스탄을 되찾음", "ee3da686"], "d": ["1381년 맘루크의 손에 넘어간 엘비스탄을 1384년 둘카디르 가문의 할릴 베이가 되찾았다.", "104e231d"]},
"OLAYLAR_2S_0919:1394-04-25:0":{"b": ["티무르가 디야르바크르(아미드)를 점령하고 약탈", "f8d200a8"], "d": ["티무르는 1394년 4월 25일 또는 26일에 디야르바크르를 점령하고 도시를 약탈했다.", "b1186b21"]},
"OLAYLAR_2S_0919:1399-02-13:0":{"b": ["게라르도 아피아니가 피사를 비스콘티에게 넘기고 피옴비노 영주국을 세움", "ac45a9dd"], "d": ["피사의 영주 게라르도 아피아니는 20만 플로린을 받고 도시를 밀라노의 지배자 잔 갈레아초 비스콘티에게 넘겼다. 그는 피옴비노, 수베레토, 스카를리노와 엘바, 피아노사, 몬테크리스토 섬들로 이루어진 피옴비노 영주국은 자신의 몫으로 남겼다.", "68084c1c"]},
"OLAYLAR_2S_0919:1401-01-01:0":{"b": ["디야르바크르가 카라윌뤼크 오스만 베이에게 주어짐 — 백양 왕조 지배의 시작", "38262401"], "d": ["티무르가 1394년에 점령한 디야르바크르는 1401년 카라윌뤼크 오스만 베이에게 주어졌고, 이로써 이 지역에서 백양 왕조의 지배가 시작되었다.", "de407b9c"]},
"OLAYLAR_2S_0919:1410-01-01:0":{"b": ["에르진잔이 흑양 왕조의 지배하에 들어감", "5729a50b"], "d": ["무타하르텐 이후 에르진잔은 흑양 왕조의 군주 카라 유수프의 손에 들어갔다. 카라 유수프는 먼저 신임하는 부하 가운데 한 명인 피르 오메르를 이 도시의 총독으로 임명했다.", "69ef181d"]},
"OLAYLAR_2S_0919:1500-01-01:0":{"b": ["샤이바니 칸이 부하라와 사마르칸트를 점령", "8f8f40eb"], "d": ["무함마드 샤이바니 칸은 티무르 왕조 내부의 혼란을 틈타 부하라와 사마르칸트를 점령하고 샤이바니(우즈베크) 왕조를 세웠다. 1500-1507년 사이에 그는 트란스옥시아나, 호라즘, 호라산의 거의 모든 도시를 장악했다.", "0e64ecae"]},
"OLAYLAR_2S_0919:1510-01-01:0":{"b": ["에스파냐가 베자이아를 점령", "8faa0133"], "d": ["배를 타고 온 8,000명의 에스파냐군이 베자이아를 점령했다. 도시 주민들은 공황에 빠져 고향을 버렸다.", "364b6234"]},
"OLAYLAR_2S_0919:1522-01-01:0":{"b": ["바기르미 술탄국 수립", "03829f94"], "d": ["켕가족은 비르니 베세의 지도 아래 차드호 동쪽의 마세냐를 중심으로 강력한 국가를 세웠다. 바기르미 왕조의 건립은 전통적으로 1522년으로 잡는다.", "2bd4497c"]},
"OLAYLAR_2S_0919:1535-11-01:0":{"b": ["마지막 스포르차 공작 사망, 밀라노가 카를 5세에게 넘어감", "53230b5c"], "d": ["밀라노 공작 프란체스코 2세 스포르차는 1535년 11월 1-2일 밤 자녀 없이 죽었다. 공국은 카를 5세 황제에게 넘어갔고, 에스파냐 총독에 의해 통치되기 시작했다.", "03b908c5"]},
"OLAYLAR_2S_0919:1544-01-01:0":{"b": ["제노바인이 타바르카섬에 정착", "0cb474f8"], "d": ["카를 5세가 튀니스의 지배자와 맺은, 해안에 요새를 쌓고 산호를 채취하는 것을 허용한 협정에 따라 페글리 출신의 제노바인 공동체가 타바르카섬에 정착하게 되었다. 이 섬은 로멜리니 가문이 운영하는 교역 거점이 되었다.", "74c7ab83"]},
"OLAYLAR_2S_0919:1558-01-01:0":{"b": ["러시아가 리보니아를 침공, 도르파트 함락", "dcb46a8a"], "d": ["이반 4세는 발트해 진출을 위해 리보니아를 침공하여 리보니아 전쟁을 시작했다. 나르바와 도르파트(타르투)를 점령하고 레발을 포위했다.", "37f1dd66"]},
"OLAYLAR_2S_0919:1579-07-13:0":{"b": ["카를로바츠 요새 건설", "9b28e6ad"], "d": ["크로아티아와 오스트리아 세습령을 오스만으로부터 지키기 위해 쿠파강과 코라나강 사이의 범람원에 카를로바츠 요새가 건설되었다. 이 요새는 크로아티아 군사 변경의 사령관인 대공 카를 2세가 짓게 했다.", "edc1a0fd"]},
"OLAYLAR_2S_0919:1580-04-10:0":{"b": ["자모시치의 건설(로카치오) 특허장", "e1157f3b"], "d": ["폴란드의 대법관 얀 자모이스키는 자모시치시의 건설(로카치오) 특허장을 발급했다.", "90df0b1c"]},
"OLAYLAR_2S_0919:1582-01-15:0":{"b": ["얌 자폴스키 휴전 — 리보니아와 도르파트가 폴란드로 넘어감", "7d02d8ad"], "d": ["폴란드-리투아니아와 러시아 사이에 얌 자폴스키 휴전이 체결되었다. 모스크바는 리보니아에 대한 주장을 포기하고 폴로츠크의 영토를 반환했다. 도르파트(타르투)는 1582년부터 폴란드의 수중에 남았다.", "3aa35e5c"]},
"OLAYLAR_2S_0919:1589-07-02:0":{"b": ["차리친 요새가 처음으로 문서에 언급됨", "ddf65b06"], "d": ["차르 표도르 이바노비치의 1589년 7월 2일자 칙령은 볼가강의 남쪽 국경을 지키기 위해 세운 차리친 요새를 언급한다. 이 날짜는 도시의 창건일로 여겨진다.", "fd3ba360"]},
"OLAYLAR_2S_0919:1590-07-12:0":{"b": ["사라토프 요새 건설", "a3ca702c"], "d": ["사라토프는 볼가 수로와 국가의 동쪽 국경을 유목민의 습격으로부터 지키기 위해 자세킨 공이 요새 초소로 건설했다.", "07dcdc66"]},
"OLAYLAR_2S_0919:1593-01-01:0":{"b": ["펠림 요새 건설", "baf3e7eb"], "d": ["보예보다 표트르 고르차코프는 타브다강 가에 펠림을 세웠다. 이 요새는 서시베리아에서 러시아 진출의 거점 가운데 하나가 되었다.", "7511aeab"]},
"OLAYLAR_2S_0919:1598-01-01:0":{"b": ["베르호투리예 요새 건설", "81be29bb"], "d": ["투라강 가의 옛 네롬카르 취락 자리에 베르호투리예 요새 거점이 세워졌다. 그 건설은 시베리아로 가는 더 짧은 길을 찾던 일과 관련이 있다.", "ac40c773"]},
"OLAYLAR_2S_0919:1600-01-01:0":{"b": ["투라강 변에 투린스크 요새 건설", "c1d8534e"], "d": ["1600년 오늘날의 투린스크 지역에 러시아의 카자크 야사크 요새(오스트로크) 투린스크가 세워졌다. 이 요새는 러시아의 서시베리아 진출 노선상에 놓인 방어 시설 가운데 하나이다.", "82075fd3"]},
"OLAYLAR_2S_0919:1611-01-01:0":{"b": ["샤 압바스 1세가 마잔다란에 파라하바드 도시를 건설", "cab4d0fe"], "d": ["사파비의 군주 압바스 1세는 마잔다란의 카스피해 연안에 가까운 곳에 파라하바드 도시를 세우게 하고, 나라 곳곳에서 백성을 이주시켰다. 공사는 1020/1611년에 시작되었다.", "cc05c705"]},
"OLAYLAR_2S_0919:1631-01-01:0":{"b": ["앙가라강 변에 러시아의 브라츠크 요새 건설", "e7b4be59"], "d": ["러시아가 동시베리아로 진출하던 중 앙가라강에 브라츠크 요새가 세워졌다.", "eb1a1abd"]},
"OLAYLAR_2S_0919:1658-03-08:0":{"b": ["로스킬레 조약 — 스코네, 할란드, 블레킹에, 보른홀름이 스웨덴으로 넘어감", "afcae41b"], "d": ["카를 10세 구스타프의 제1차 북방 전쟁을 끝낸 로스킬레 조약이 체결되었다. 덴마크-노르웨이는 스코네, 할란드, 블레킹에, 보른홀름을 스웨덴에 넘겼다.", "ac397fd6"]},
"OLAYLAR_2S_0919:1663-01-01:0":{"b": ["러시아가 수라강 변에 펜자 요새를 건설", "49e8d90b"], "d": ["펜자는 펜자강과 수라강이 합류하는 곳에 대규모 요새로 건설되었다. 1684년 이후에는 시즈란 방어선의 서쪽 끝을 이루었다.", "afba0eaa"]},
"OLAYLAR_2S_0919:1668-01-01:0":{"b": ["마르케트가 수세인트마리에 프랑스 선교소를 세움", "86612bcd"], "d": ["예수회 선교사 자크 마르케트는 슈피리어호와 휴런호 사이의 수세인트마리 급류 상류 어귀에 선교소를 세웠다.", "e90cdea2"]},
"OLAYLAR_2S_0919:1668-01-01:1":{"b": ["허드슨 베이 회사의 첫 교역소(와스카가니시) 건립", "07b32d57"], "d": ["제임스만의 루퍼트강 어귀에 메다르 슈아르 데 그로세예는 훗날 허드슨 베이 회사의 첫 교역소로 여겨지는 정착지를 세웠다.", "790b2f93"]},
"OLAYLAR_2S_0919:1700-01-01:0":{"b": ["에스파냐 식민 당국이 피틱(에르모시요)을 건설", "11e5cc04"], "d": ["에스파냐 식민 당국은 옛 원주민 취락 자리에 마을을 세웠다. 이 마을은 1828년 호세 마리아 곤살레스 데 에르모시요의 이름을 따게 되었다.", "4724e13c"]},
"OLAYLAR_2S_0919:1716-01-01:0":{"b": ["이르티시강과 옴강의 합류점에 러시아의 옴스크 요새 건설", "13dcce5e"], "d": ["옴스크는 토볼강과 이르티시강 사이의 이심 방어선 동쪽 끝에 요새로 건설되었으며, 1804년 도시가 되었다.", "45facb52"]},
"OLAYLAR_2S_0919:1717-11-30:0":{"b": ["준가르가 라싸를 습격 — 라장 칸 피살, 티베트가 준가르에 점령됨", "65beea29"], "d": ["체링 돈둡이 이끄는 준가르군은 호쇼트의 지배자 라장 칸이 지키던 라싸를 자정 이후 사방에서 공격했다. 내부의 호응을 얻은 준가르는 도시를 점령하여 약탈했고 포탈라궁도 털었다. 라장 칸은 달아나다가 살해되었으며, 준가르는 탁체파(sTag-rtse-pa)를 수반으로 하는 티베트 괴뢰 정부를 세웠다.", "b6dcede2"]},
"OLAYLAR_2S_0919:1720-09-24:0":{"b": ["청군의 라싸 입성 — 준가르 점령 종료, 청의 보호 시작", "083358c1"], "d": ["강희제가 티베트에 보낸 두 군대 가운데 갈비가 지휘하는 쓰촨 방면군은 힘든 행군 끝에 라싸에 도착하여 저항 없이 도시를 점령했다. 준가르는 북쪽에서 오는 코코노르 방면군에 대비해 모든 병력을 담(Dam)에 집결시키고 있었다. 준가르가 티베트에서 철수하자 청은 라싸에 지속적인 보호 체제를 세웠다.", "e5c9dcf8"]},
"OLAYLAR_2S_0919:1721-01-01:0":{"b": ["아구아요 원정대가 로스아다에스 프레시디오를 건설", "2031793a"], "d": ["아구아요 후작의 원정대는 로스아다에스에 프레시디오(군사 초소)를 세우고 선교소를 다시 정착시켰다. 이 초소는 프랑스령 루이지애나에 맞선 누에바에스파냐의 동부 텍사스 국경 거점이 되었다.", "6ccb0ff2"]},
"OLAYLAR_2S_0919:1722-01-01:0":{"b": ["바라바 초원에 러시아의 카인스크 초소 건설", "b14552a8"], "d": ["바라바 초원에 세워진 러시아의 세 상설 요새 초소(파스) 가운데 카인스크 초소는 옴강 중류의 카인카 개천이 합류하는 곳에 세워졌다.", "17a78ef2"]},
"OLAYLAR_2S_0919:1743-01-01:0":{"b": ["우이강 가에 러시아의 트로이츠크 요새 건설", "623d75f2"], "d": ["트로이츠크는 우이강에 우벨카강이 합류하는 곳에 요새로 건설되었으며, 1784년 도시 특허장을 받았다.", "49367d34"]},
"OLAYLAR_2S_0919:1749-12-15:0":{"b": ["옐리자베타의 칙령으로 돈강 어귀에 테메르니크 세관 설치(로스토프의 핵심)", "46519168"], "d": ["여제 옐리자베타 페트로브나는 돈강의 테메르니크강 어귀에 세관을 설치하라는 칙령을 내렸다. 테메르니크 세관은 로스토프나도누시의 초기 역사의 시작이다.", "51a82ea9"]},
"OLAYLAR_2S_0919:1750-01-01:0":{"b": ["프랑스인이 토론토의 험버강에 교역소를 세움", "18975f4c"], "d": ["프랑스인은 험버강에 두 번째 교역소를 세웠고, 이듬해 오늘날의 엑시비션 플레이스에 루이예 요새(Fort Rouillé)를 쌓았다.", "66aeb450"]},
"OLAYLAR_2S_0919:1750-01-01:1":{"b": ["카자르의 무함마드 하산 칸이 독립 선언; 마잔다란과 길란 점령", "42fc62e8"], "d": ["아프샤르의 술레이만 샤가 폐위되자, 아스타라바드의 카자르 수장 무함마드 하산 칸이 독립을 선언했다. 그는 아스타라바드와 고르간 외에 마잔다란과 길란도 자신의 통치하에 두었다.", "f5398386"]},
"OLAYLAR_2S_0919:1751-01-01:0":{"b": ["아흐마드 샤 두라니가 발흐를 영토에 편입", "12c6bbf1"], "d": ["아프간의 지배자 아흐마드 샤 두라니는 발흐를 자신의 지배 영역에 편입했다.", "e3ef9016"]},
"OLAYLAR_2S_0919:1751-01-01:1":{"b": ["카림 칸 잔드가 이스파한을 장악 — 이란의 아프샤르 지배가 잔드 통치로 바뀜", "73cdc1e8"], "d": ["나디르 샤가 죽은(1747) 뒤, 이스파한과 이라크 아자미는 아프샤르의 샤인 아딜 샤(1747년 7월 6일)와 이브라힘 샤(1748년 12월 8일)의 이름으로 통치되었다. 카림 칸 잔드는 1751년 1월 이스파한에 돌아와 정세를 장악했다. 호라산은 샤루흐의 통치 아래 아프샤르에 남았다.", "daab8159"]},
"OLAYLAR_2S_0919:1752-01-01:0":{"b": ["이심강 변에 러시아의 페트로파블롭스크 요새 건설", "5d16ef42"], "d": ["페트로파블롭스크는 러시아 요새로 건설되었으며, 곧 러시아와 중앙아시아 및 카자흐 초원 사이 교역의 중요한 중심지가 되었다.", "f0724528"]},
"OLAYLAR_2S_0919:1759-02-13:0":{"b": ["카자르의 무함마드 하산 칸이 카림 칸 잔드의 군대에 패해 살해됨; 아스타라바드, 마잔다란, 길란이 잔드 통치로 넘어감", "38f0a375"], "d": ["카림 칸의 군대는 카자르에게 큰 패배를 안겼다. 무함마드 하산 칸은 달아나다가 살해되었고, 아들 아가 무함마드는 시라즈로 끌려갔다. 카스피해 연안에 있던 카자르 세력의 영토는 잔드의 통치하에 들어갔다.", "aa7e4a1e"]},
"OLAYLAR_2S_0919:1806-01-01:0":{"b": ["우스만 단 포디오의 지하드 군대가 자리아를 점령", "41279ca7"], "d": ["우스만 단 포디오가 시작한 지하드 중에 고비르의 수도 알칼라와에 대한 첫 공격은 실패했으나, 1806년 자리아가 점령되었다.", "680cebf3"]},
"OLAYLAR_2S_0919:1808-01-01:0":{"b": ["술타나바드(아라크) 도시 건설", "674237a0"], "d": ["카자르 시대에 유수프 칸 구르지 장군이 오늘날의 아라크 도시를 세우고 술타나바드라는 이름을 붙였다.", "6ff3f6de"]},
"OLAYLAR_2S_0919:1818-01-01:0":{"b": ["보퍼트(보퍼트웨스트) 마을 건설", "c5cb1776"], "d": ["영국령 케이프 식민지에서 카루의 호이플라크테 농장 위에 보퍼트 마을이 세워졌다.", "70ea5620"]},
"OLAYLAR_2S_0919:1826-01-01:0":{"b": ["발흐가 부하라 아미르의 침공을 당함", "cd255a5d"], "d": ["두라니 아프간의 지배하에 있던 발흐는 1826년 부하라 아미르의 침공을 당했다. 이 도시는 1841년 아프간인에게 다시 점령되었다.", "a3ecb1be"]},
"OLAYLAR_2S_0919:1830-01-01:0":{"b": ["러시아가 이심강에 아크몰라 요새를 건설", "6c727ca9"], "d": ["러시아는 이심강 변의 카라우트쿨에 아크몰라 요새를 쌓아 이곳을 시베리아 키르기스(카자흐)인의 땅의 중심 마을로 삼았다.", "9e7d586f"]},
"OLAYLAR_2S_0919:1847-01-01:0":{"b": ["코팔 요새 건설 — 북부 세미레치예의 러시아 편입 시작", "8d4c24c6"], "d": ["러시아는 대주즈 카자흐인의 요청에 따라 제티수 알라타우 산기슭에 코팔 요새를 세웠다. 사료에 따르면 이는 일리강까지의 북부 세미레치예가 러시아에 편입되는 것을 수월하게 했다.", "ebe25fc6"]},
"OLAYLAR_2S_0919:1852-01-01:0":{"b": ["해안 상인들이 카제(타보라)에 정착", "173223b0"], "d": ["한 지방 지배자와 충돌한 뒤, 동아프리카 해안에서 온 상인들이 남쪽으로 이주했다. 우냐녬베의 추장 푼디키라는 그들에게 자신의 중심지 이테테미아 근처에 정착할 곳을 주었다. 이 정착지는 타보라 대상(隊商) 중심지의 핵심이 되었다.", "1261b92f"]},
"OLAYLAR_2S_0919:1880-06-13:0":{"b": ["브라자가 프랑스빌을 건설", "d28410d7"], "d": ["피에르 사보르냥 드 브라자는 음파사강이 내려다보이는 바위 돌출부 위에 프랑스의 이름으로 프랑스빌 초소를 세웠다.", "c23dd54e"]},
"OLAYLAR_2S_0919:1888-05-01:0":{"b": ["하드라마우트 해안(무칼라)이 영국의 보호하에 들어감", "dc824725"], "d": ["시흐르와 무칼라를 포함한 하드라마우트 해안을 지배하던 야피이 가문(쿠아이티 가문)과 영국 사이에 보호 조약이 체결되었다. 영국은 해안의 야피이 정권의 대외 관계를 전적으로 맡았다.", "98bd94ee"]},
"OLAYLAR_2S_0919:1890-01-01:0":{"b": ["프랑스가 졸로프 전체를 장악", "c6d28eaa"], "d": ["부족장들과 맺은 협정을 통해 이 지역을 식민지화한 프랑스는 1890년 졸로프 전체를 장악했다.", "15595659"]},
"OLAYLAR_2S_0919:1893-01-01:0":{"b": ["젠네가 프랑스에 점령됨", "b207bf62"], "d": ["하지 우마르가 세운 국가의 수중에 있던 젠네는 1893년 프랑스군에게 점령되어 프랑스령 수단에 편입되었다.", "5739cdc4"]},
"OLAYLAR_2S_0919:1894-01-01:0":{"b": ["그웨루가 군사 초소로 건설됨", "bd37b323"], "d": ["오늘날 짐바브웨 중부의 그웨루시는 군사 초소로 세워졌다. 이후 농업 중심지가 되었으며, 1914년 자치 도시의 지위를 얻었다.", "a8f323b9"]},
"OLAYLAR_2S_0919:1897-01-01:0":{"b": ["바기르미 술탄국이 프랑스의 보호하에 들어감", "59f20c32"], "d": ["라비흐의 위협에 직면한 바기르미의 지배자 가우랑은 프랑스와 어쩔 수 없이 보호 조약을 맺었다. 이에 반발한 라비흐가 바기르미 점령에 나서자 가우랑은 수도 마세냐를 자기 손으로 불태웠다.", "fcb0958f"]},
"OLAYLAR_2S_0919:1898-01-01:0":{"b": ["가오가 프랑스에 점령됨", "01eabb4c"], "d": ["니제르강 변의 옛 송가이 수도 가오는 1898년 프랑스에 점령되었다. 점령 후 도시는 다시 성장하여 지역의 중심지가 되었다.", "653ce49b"]},
"OLAYLAR_2S_0919:1903-07-27:0":{"b": ["부르미 전투 — 소코토 칼리파국의 정치적 지배 종식", "c7d87e2c"], "d": ["영국이 소코토를 점령한 뒤 달아난 칼리파 무함마드 타히르는 영국과의 새 전투에서 살해되었다. 약 한 세기 동안 이어진 소코토 칼리파국의 정치적 지배는 끝났다.", "b37ec3fb"]},
"OLAYLAR_2S_0919:1904-01-01:0":{"b": ["나쿠루가 공식적으로 읍으로 설립됨", "d82a2d76"], "d": ["우간다 철도상의 위치 덕분에 나쿠루는 공식적으로 읍으로 설립되었으며, 지역 농산물의 중심지가 되었다.", "bf30445b"]},
"OLAYLAR_2S_0919:1911-01-01:0":{"b": ["프랑스가 자네트를 점령", "f32997c8"], "d": ["가트에 속한 오스만의 나히예였던 자네트는 1911년 프랑스에 점령되었다. 나히예의 책임자 셰이크 아무드는 이 날짜까지 오스만 국가에서 봉급을 받았다.", "7075093e"]},
"OLAYLAR_2S_0919:1915-01-01:0":{"b": ["앵커리지가 알래스카 철도의 중심지로 건설됨", "f5014711"], "d": ["의회가 1914년 3월 12일 알래스카 철도법을 가결한 뒤, 1915년 봄 알래스카 기술 위원회는 십크리크에 철도 공사장을 세웠다. 해안에 천막촌이 생겨났고, 1915년 4월 우정 당국은 새 마을에 앵커리지라는 이름을 붙였다. 이 도시는 북쪽의 페어뱅크스까지 뻗은 알래스카 철도의 중심지가 되었다.", "ffe4cba5"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["사누시 교단의 사막 중심지 자그부브가 오스만 체제에 편입 — 압뒬메지드의 면세 칙령", "039fce6d"], "d": ["오랫동안 메카에 머문 무함마드 이븐 알리 앗사누시는 트리폴리로 돌아온 뒤 이집트 국경의 자그부브 오아시스에 정착하여, 주변을 내려다보는 암반 위에 큰 자위야(수도장)를 세우게 했다. 오두막 몇 채에 불과하던 곳은 곧 도시로 변했다. 1856년 술탄 압뒬메지드의 칙령으로 교단 구성원의 재산은 세금이 면제되었고 제자들에게는 자카트 징수 권한이 주어졌다. 이 칙령은 서아프리카와 수단을 카이로와 잇는 대상로 위의 오아시스를 오스만의 재정·행정 체제의 일부로 만들었고, 자그부브를 교역 중심지로 강화했다. 지역 주민의 칼리프에 대한 충성은 1884년과 1893년에 이곳을 방문한 대령 사디크 알무아야드의 여행기로도 확인된다.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["수에즈 운하 굴착의 시작과 포트사이드의 건설", "cef0be8d"], "d": ["바브알리가 1856년 1월 5일 승인한 레셉스 계획의 굴착 공사는 1859년 4월 25일에 시작되었으며, 운하는 10년 뒤인 1869년 11월 16일에 완공되게 된다. 굴착의 지중해 쪽 끝, 만잘라 호수와 바다 사이의 모래톱에 노동자를 위해 세운 다섯 채의 오두막 마을이 포트사이드의 핵심이 되었다. 1860년 운하 회사의 관계자들은 당시 이집트 총독 사이드 파샤에게 헌정하는 뜻으로 '사이드의 항구'라는 의미의 이 이름을 도시에 붙였다. 이로써 오스만 지도에는 이전에 어떤 정착지도 없던 해안 지대에 새 항구가 생겨났다.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["술탄 압뒬아지즈의 이집트 방문과 수에즈 지협의 이스마일리아 건설", "bcfacf38"], "d": ["술탄 압뒬아지즈는 대재상 유수프 캬밀 파샤의 권유로 1863년 4월 3일 이집트를 방문해 큰 환호 속에 맞이되었다. 목적은 카발랄르 메흐메드 알리 파샤의 반란 이래 사실상 별개의 국가가 되어 가던 이 주의 중앙에 대한 결속을 강화하는 것이었다. 같은 해 지협의 팀사흐 호숫가 틸랄 알지스르 언덕에 운하 회사의 행정 본부가 세워졌고, 먼저 기술자들을 위해 카리야 알팀사흐 마을이, 이어 노동자들을 위해 카리야 알아랍 마을이 자리 잡았다. 케디브 이스마일 파샤가 담수 운하에 깊은 관심을 기울여 이 언덕에 자신을 위한 별장을 지었기 때문에, 정착지는 그의 이름을 따 이스마일리아라고 불리게 되었다. 도시의 건설은 1863년으로 연대가 정해지며 정확한 날짜는 알려져 있지 않다.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["미드하트 파샤의 바그다드 총독 재임과 부족 정착 — 라마디와 나시리야의 건설", "0fa98f06"], "d": ["국가평의회 의장직에서 물러나 이스탄불에서 멀리 보내진 미드하트 파샤는 모술과 바스라까지 포함하는 바그다드 주를 1869-1872년에 제6군 사령관직도 겸하며 광범위한 권한으로 통치했다. 그는 토지법과 새 주 법령을 이곳에 적용하여 토지를 등기 증서로 분배했고, 유목 부족들을 정착 질서와 국가 권위에 묶었다. 이러한 정착 정책의 산물로 1869년 유프라테스 강가에는 둘라임 부족을 위한 라마디가, 남부에는 문타피크 현령 나시르 파샤 앗사아둔의 손으로 나시리야가 세워졌다. 두 곳 모두 그때까지 정착지가 없던 지점에서 생겨났으며 지도에는 이때 처음 나타났다.", "7babb36f"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["앙카라 패전 이후 왈라키아 보이보드 미르체아가 도브루자를 되찾다 — 실리스트라, 콘스탄차, 바바다그, 이삭체아", "5eaefc68"], "d": ["이을드름 바예지드가 앙카라에서 티무르에게 패하자 다뉴브 연안의 오스만 지배가 흔들렸다. 왈라키아 보이보드 미르체아는 이 공백을 틈타 도브루자에 다시 들어왔으며, 실리스트라, 콘스탄차, 바바다그 일대와 다뉴브 강변의 이삭체아는 공위 시대 내내 그의 손에 있었다. 미르체아는 첼레비 메흐메드에 맞서 무사 첼레비를 지원했다. 그는 1418년 죽을 때까지 실리스트라를 장악했다.", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["바바다그와 그 일대의 오스만 편입 — 미르체아와 아들 미하일의 패배", "bfda2c60"], "d": ["첼레비 메흐메드는 왈라키아 보이보드 미르체아와 아들 미하일을 격파한 뒤 북부 도브루자의 바바다그와 그 일대를 오스만의 지배 아래에 두었다. 바바다그는 살투크 바바의 이름을 딴, 13세기 투르크멘의 정착으로 세워진 읍이었다. 주변의 실리스트라, 콘스탄차와 다른 도브루자 요새들은 1419년까지 왈라키아에 남았다. 따라서 바바다그는 3년 동안 오스만 영토에서 떨어진 섬(월경지)으로 나타난다.", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["실리스트라와 도브루자의 수복 — 미르체아의 사망 이후", "73eb6ae9"], "d": ["1418년 왈라키아 보이보드 미르체아가 죽은 뒤 왈라키아에서 일어난 혼란은 첼레비 술탄 메흐메드에게 실리스트라와 도브루자를 되찾을 기회를 주었다. 1419년 봄 실리스트라, 콘스탄차와 도브루자의 대부분이 다시 오스만의 통치에 들어갔다. 에니살라(예니살레)와 이삭체아 요새는 수리되어 국경 요새(세르하트)가 되었으며, 도브루자는 이후 1878년까지 오스만에 남았다.", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["하류 다뉴브의 봉쇄 — 주르주, 투르누, 오르쇼바의 병합", "331a0b68"], "d": ["공위 시대가 끝난 뒤 다뉴브 전선을 정비하려던 첼레비 메흐메드의 움직임은 1420년에 결실을 맺었다. 왈라키아 보이보드 미르체아 대공이 자기 영토에, 소금 판매로 비용을 충당해 쌓은 주르주 요새가 이해에 오스만의 손에 들어갔고(도브루자는 1년 전인 1419년 봄에 되찾았다 — TDV 실리스트라 항목), 다뉴브 우안의 투르누(쿨레/홀로브니크)와 오르쇼바 — 뒷날의 이름은 페트홀이슬람 — 가 병합되었다. 이로써 강의 양안이 동시에 통제 아래에 놓였다. 주르주의 중요성은 지리에서 나온다. 다뉴브의 왼쪽, 즉 왈라키아 쪽 기슭에 세워진 오스만 요새이며 맞은편의 루세와 함께 같은 도하 지점의 양끝을 장악한다. 오스만 문서들은 이 이중성을 분명히 적고 있다. 루세를 '주르주의 이쪽 기슭', 주르주를 '주르주의 저쪽 기슭'이라 부른다. 요새는 1427년 왈라키아인들에게 탈환되었다가 1449년 다시 오스만의 통제에 들어가고, 주르주 카자는 니코폴리스 산자크에 속하여 보이보드령 안의 직할 섬이 된다. 지도에서 왈라키아의 다뉴브 연안이 왜 짙은 색인지에 대한 답은 여기서 시작된다.", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["토플리차 지역(쿠르슐룸리야, 프로쿠플례)의 오스만 지배 편입", "e22e690d"], "d": ["무라드 2세가 마라 브란코비치와 약혼할 무렵, 두보치차와 토플리차 지역(레스코바츠, 쿠르슐룸리야, 프로쿠플례 일대)이 오스만의 지배로 넘어갔을 가능성이 높다고 여겨진다. 1445-1447년의 토지 조사 대장은 이 지역이 오스만 시파히들에게 티마르로 지급되었음을 보여 준다. 지도에서 쿠르슐룸리야와 프로쿠플례는 이 해부터 오스만의 통치를 받는다.", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["사라예보 평야의 병합 — 보스니아 안의 오스만 변경 지대 수립", "be5c0f00"], "d": ["1428-1429년 보스니아 왕들이 공납 의무를 지게 된 뒤, 오스만은 왕국 내부에 영구적으로 자리 잡기 시작했다. 1428-1435년 사이에 호디디에드 읍이 점령되었고, 852년(1448년) 호디디에드 빌라예트는 사라예보 평야와 함께 완전히 오스만의 통치에 들어갔다. 이는 보스니아 정복 15년 전에 왕국 한가운데에 세워진 변경 지대이며, 보이보드 칭호를 가진 스코페 베이 이사 베이가 다스렸다. 주위에 여전히 오스만에 속한 보스니아 영주들이 있었기 때문에 이 지역은 이중의 통제를 받았다. 도시 자체도 이 시기에 생겨났다. 1462년 이전에 이스하크 베이 또는 그의 아들 이사 베이가 최초의 무슬림 마을을 세웠고, 862년(1458년) 파티흐의 이름으로 휜캬르(황제) 모스크가 지어졌으며, 브로데츠 마을의 경작지가 개발되어 사라이(사라예보) 읍이 생겨났다. 1463년의 정복은 보스니아 왕국을 없앴지만, 사라예보 평야는 그때 이미 15년 동안 오스만의 영토였다.", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["포드고리차의 오스만 영토 편입 — 제타 평야의 장악", "46e401c5"], "d": ["슈코더르 호수에서 북쪽으로 20킬로미터, 모라차강과 립니차강이 합류하는 평야에 자리한 이 읍은 사료에 1216년 립니차, 1326년 포드고리차라는 이름으로 처음 언급된다. 1457년 오스만 영토에 편입되었고, 이로써 제타 평야의 지배권은 발시치-츠르노예비치 가문의 손에서 벗어났다. 파티흐 술탄 메흐메드는 1474-1478년 두 강의 합류점에 있는 가파른 암반 위에 요새와 모스크를 짓게 했으며, 1479년 슈코더르 정복 후 이 지역은 새로 설치된 슈코더르 산자크에 속하게 되었다. 1485년 토지 조사에서 40가구의 기독교인 읍이던 포드고리차는 1529-30년에 인구 800명과 요새 안의 디즈다르(요새 지휘관) 휘하 32명의 수비대를 갖추었고, 1582년에는 322가구에 이르렀다. 에블리야 첼레비는 1662년 파티흐 요새에서 가옥 300채, 창고, 무기고, 수비병 700명을 헤아렸다. 이 기록들은 제타의 평야와 산지의 차이도 보여 준다. 평야는 호구 조사를 받고 세금이 부과되며 수비대가 있는 오스만의 카자였다. 그러나 18세기에 도시는 몬테네그로 산지 부족들의 습격을 막기 위해 보루 6개와 문 3개를 갖춘 성벽으로 요새화해야 했다. 포드고리차는 1876-1878년 전쟁 말기에 몬테네그로의 손에 넘어갔고 베를린 조약으로 그대로 남았다.", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["포차 점령 — 헤르체그 공국으로 들어가는 첫 관문 개방", "f098a9e6"], "d": ["1463년 보스니아 왕국이 사라진 뒤, 다음은 왕국에서 떨어져 나가 자신의 공국을 세운 스테판 부크치치-코사차의 영토였다. 드리나 계곡에서 이스탄불과 두브로브니크를 잇는 교역로의 교차점에 있는 포차는 1465년 오스만의 통치에 들어갔다. 도시의 중요성은 곧 인식되었다. 1470년 새로 편성된 헤르체고비나 산자크의 중심지가 되었다. 즉 헤르체고비나의 행정 핵심은 공국 자체가 무너지기도 전에 포차에 세워진 것이다. 공국 전체의 병합은 1483년까지 이어지게 된다. 이후 포차는 좋은 기후와 교통 요충지라는 위치 덕분에 상업과 행정의 중심지로 발전했다. 지도에서 이 날짜는 보스니아 정복 후 남쪽을 향한 두 번째 물결이 시작된 날이다.", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["리브노와 서부 보스니아의 확정적 병합 — 베네치아 국경의 수립", "c14d4283"], "d": ["리브노 평야를 내려다보는 고원 위의 요새는 1448-1454년 사이에 헤르체그 공국의 창건자 스테판 부크치치-코사차의 손에 있었다. 1463년 보스니아 원정에서 잠시 오스만군에게 점령되었으나 같은 해에 탈환되었다. 1466년 도시의 지배자는 이바니시 블라트코비치이다. TDV의 표현에 따르면 확정적인 오스만 지배는 거의 틀림없이 1468-1469년에 실현되었으며, 1485년 토지 조사는 리브노를 이제 오스만 영토로 기록한다. 이는 보스니아 정복의 서쪽 끝이 닫힌 것이다. 리브노는 평탄한 평야를 따라 불과 36킬로미터 떨어진 베네치아 영토에 인접한 위험한 국경 읍이 되었으며, 1521-1522년 보스니아 총독 가지 휘스레브 베이가 베네치아의 요새들을 점령할 때까지 이 위치를 유지했다.", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["샤바츠(뵈위르델렌)를 헝가리에 상실 — 사바 방어선의 첫 돌파구", "129fe8f2"], "d": ["파티흐 술탄 메흐메드 시대에 오스만의 손에 들어와 이전에는 자슬론이라 불리던 곳에, 1471년 나무와 흙으로 된 성채가 세워졌다. 베오그라드를 위협하는 지점에 있고 여기서 헝가리와 오스트리아 남부로 쉽게 습격할 수 있었기 때문에, 요새는 이름도 이 기능에서 얻었다. 뵈위르델렌은 '옆구리를 치는 보루'라는 뜻이다. 헝가리 왕 마차시 코르빈은 1475년 말 무렵 요새를 포위하여 1476년 2월에 점령했다. 이 포위를 이야기하는 헝가리 서사시 Szabács viadala는 15세기 헝가리 역사시 가운데 본문이 오늘날까지 전해지는 가장 긴 예 중 하나이다. 헝가리는 이 지역에 바나트령을 두고 요새를 돌로 다시 쌓아 국경 요새 사슬의 한 고리로 만들었다. 오스만은 1492년에 되찾으려 했으나 실패했으며, 요새는 45년 동안 헝가리의 손에 있었다.", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["이오니아 제도 정복 — 토코 공국의 종말: 레프카다, 케팔로니아, 자킨토스, 이타카", "07b27251"], "d": ["같은 해 1월 베네치아와 체결한 이스탄불 조약은 슈코더르와 알바니아 해안을 오스만에 남겼다. 그러나 이오니아 제도는 베네치아가 아니라 케팔로니아-자킨토스 백국을 보유한 토코 가문이 다스리고 있었으므로 별도의 작전으로 점령되었다. TDV의 레프카다 항목에 따르면, 마지막 공작 레오나르도 토코는 처음에는 파티흐의 친척인 밀리차 브란코비치와 결혼해 충성을 지켰으나, 1464년 아내가 죽은 뒤 1477년 나폴리 왕가의 프란체스카 마르차노와 결혼해 파디샤의 노여움을 샀다. 2년 뒤 블로러 베이 게디크 아흐메드 파샤가 지휘하는 함대는 레프카다를 남쪽의 케팔로니아와 함께 점령했고, 레오나르도와 프란체스카는 이탈리아로 도망쳤다. 게디크 아흐메드 파샤 항목은 같은 작전에서 자킨토스(잔테)도 점령되었다고 기록한다. 케팔로니아 백국에 속한 이타카도 이 이전과 함께 오스만의 통치에 들어갔다. 이로써 아드리아해 어귀에서 모레아로 이어지는 해로 전체가 통제 아래 놓였다. 제도 가운데 자킨토스는 3년 뒤 베네치아에 넘겨지고, 케팔로니아와 이타카는 1500년에 상실되며, 레프카다만이 200년 동안 오스만에 남게 된다.", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["츠르노예비치의 제타 신속(臣屬)과 체티네의 중심지화", "59d20267"], "d": ["1479년 슈코더르가 오스만에 남게 되자 그 뒷마당의 제타 산악 지역도 제국의 국경 안에 들게 되었다. 이 지역을 장악하던 츠르노예비치 가문은 파티흐가 죽은 뒤 즉위한 바예지드 2세의 종주권을 인정하고 공납을 바치기로 하여 내정의 자유를 유지했다. 이반 츠르노예비치는 중심지를 평야에서 옮겨 로브첸 산기슭의 체티네로 이전하고 도시를 세웠다. 2년 뒤 그가 이곳에 세운 수도원은 지역의 종교 중심지가 되었다. 이 때문에 몬테네그로는 지도에서 직접적인 오스만 영토가 아니라 옅은 색의 속령으로 나타난다. TDV의 몬테네그로 항목은 이 왕조와 체티네 주교구를 언급하고, 1514년 이 지배가 이스켄데르 베이(츠르노예비치 가문 출신으로 오스만 궁정에서 자란 인물)에 의해 별도의 산자크로 바뀌었다고 적는다. 그러나 1482년이라는 연도는 TDV에 없고 몬테네그로 역사 서술에서 제시하는 연도이다. 험준한 지형 때문에 이곳의 행정은 평야 지대처럼 긴밀하게 작동한 적이 없었다.", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["킬리아 요새 정복 — 다뉴브 하구의 열쇠", "ef4eca73"], "d": ["몰다비아는 1455년 9월부터 매년 금화 2000개를 공납하는 속국 보이보드령이었으나, 흑해로 열린 두 항구는 여전히 보이보드의 손에 있었고 다뉴브를 통해 오는 교역은 그곳을 지났다. 바예지드 2세는 즉위 후 첫 대원정을 이 두 항구에 대해 벌였다. 열흘 동안 밤낮으로 포격을 받은 킬리아 요새의 사령관은 항복할 수밖에 없었다. 요새는 직접 오스만 통치로 편입되어 산자크 베이령이 되었고, 16세기 후반에는 코사크의 위협 때문에 카자가 되어 루멜리아 베일레르베이령에 속한 아케르만 산자크에 편입되었다. 이후 몰다비아는 지도에서 2단계로 나타난다. 내륙에서는 보이보드령이 옅은 색의 속령으로 남고, 해안의 두 항구는 짙은 색의 직할 오스만 산자크이다. TDV의 몰다비아 항목은 이 두 곳을 '몰다비아의 열쇠이자 문'이라 부르며, 이 지역이 바예지드 2세 때 확실히 오스만에 귀속되었다고 적는다.", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["아케르만 정복 — 드네스트르 하구와 몰다비아의 흑해 관문의 폐쇄", "7cb20feb"], "d": ["킬리아의 항복 20일 뒤 군대는 드네스트르 하구의 아케르만 앞에 이르렀고, 요새는 8월 4일 점령되었다. 이 도시는 몰다비아에서 가장 활발한 항구였다. 파티흐 시대인 1455년 보이보드 표트르 3세가 오스만의 지배를 인정하자 아케르만 상인들에게 통상 허가가 주어졌는데, 이제 항구는 직접 국가의 것이 되었다. 정복 후 루멜리아 베일레르베이령에 속한 산자크가 된 아케르만은 1593년 새로 설치된 외지(오차코프) 주에 병합되었다. 이로써 북쪽의 호틴, 남쪽의 킬리아와 아케르만으로 둘러싸인 몰다비아의 바깥 껍질이 오스만의 직접 통제에 들어가기 시작했다. 보이보드령은 내정의 자유를 유지했으나 바다로 나가는 길은 남지 않았다. 지도에는 그 사이에 빈 지역이 없다. 짙은 색의 항구 산자크와 옅은 색의 보이보드령 영토가 서로 맞닿아 있으며, 그 사이의 부자크 초원은 1538년까지 여전히 보이보드령의 일부이다.", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["레판토의 항복 — 코린토스만 입구를 베네치아에게서 점령", "2cfe0777"], "d": ["레판토는 1407년부터 베네치아의 손에 있었으며 코린토스만의 입구를 장악하고 있었다. 만 안의 모든 해안이 이 요새의 사정권에 묶여 있었다. 1499년 원정에서 요새는 육상으로 포위되었고, 레판토 앞바다에서 베네치아 함대와 싸운 오스만 함대는 해상에서 포위군을 도왔다. 요새의 베네치아인들은 8월 26일 읍을 오스만에게 넘겨주었다. 이후 도시는 188년 동안 오스만령으로 남았고, 1687년 모레아 상실과 함께 다시 베네치아에 넘어갔다가 1715년에 탈환되었다. 같은 해 여름의 해전과 이 항복은 별개의 두 사건이다. 함대의 교전은 모레아 서쪽 끝의 사피엔차-존키오 해역에서 벌어졌고, 레판토는 코린토스만 입구에서 육상 포위로 함락되었다.", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["스레브레니크 바나트령 병합 — 북부 보스니아 헝가리 방어선의 첫 균열", "6d98c725"], "d": ["1463년 보스니아 왕국이 무너진 뒤 마차시 코르빈은 반격에 나서 왕국 북부에서 오스만의 진격을 멈추는 두 개의 바나트령을 세웠다. 서쪽의 야이체와 북동쪽의 스레브레니크였다. 이들은 보스니아에서 헝가리의 전방 방어선이었으며 사바강과 보스나강 사이의 회랑을 막고 있었다. 스레브레니크 바나트령은 1512년에 점령되었고, 이로써 방어선의 동쪽 날개가 무너져 즈보르니크 산자크는 북쪽으로 확대될 수 있었다. 서쪽 날개의 야이체는 16년을 더 버텼으며, 모하치 이후인 1528년에야 점령할 수 있었다.", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["샤바츠 정복 — 카누니가 점령한 첫 요새이자 베오그라드 결정이 내려진 곳", "85177a90"], "d": ["카누니 술탄 쉴레이만의 제1차 헝가리 원정에서 이 지역에 파견된 루멜리아 베일레르베이 아흐메드 파샤의 병력은 격렬한 포위 끝에 1521년 7월 7일 요새를 점령했다. 샤바츠는 카누니의 통치에서 정복된 첫 요새이다. 파디샤는 정복 후 직접 요새에 들어가 도시의 건설을 명령했으며, 베오그라드 정복에 관한 결정도 이곳에서 내려졌다. 즉 1521년 8월 29일 함락될 베오그라드의 계획은 샤바츠에서 세워진 것이다. 요새는 이후 200년 가까이 오스만의 손에 남았으며, 처음에는 루멜리아 주에, 1580년부터는 보스니아 주에 속했고, 이어 잠시 스메데레보 산자크에, 마지막으로 즈보르니크 산자크에 속했다. 지도에서 이날은 사바 방어선이 오스만에게 유리하게 닫힌 날이다.", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["세 공국의 반란 시작 — 트란실바니아가 신성 동맹에 가담, 친오스만 귀족들 체포", "68a33800"], "d": ["장기 전쟁의 두 번째 해에 중부 유럽의 오스만 속국 지대가 한꺼번에 무너졌다. 교황 클레멘스 8세의 후원으로 결성된 신성 동맹에 여름 말 몰다비아와 트란실바니아가 가담했다. 몰다비아 보이보드 아론 보더는 1594년 8월 16일 기독교 진영 합류를 문서로 공식화했고, 트란실바니아 공 지그몬드 바토리도 1594년 8월 28일 참전에 반대하던 친오스만 귀족들을 제거해 내부의 반대를 꺾었다. 왈라키아 보이보드 용감한 미하이는 같은 해 가을 동맹에 가담했다. 이로써 150년 동안 공납을 바치고 보이보드를 이스탄불의 승인으로 임명받던 다뉴브 북쪽의 오스만 속국 세 공국이 같은 가을에 한꺼번에 반대편으로 넘어갔다. 이 결정은 1595년 1월 28일 프라하에서 서명된 조약으로 공식화되었다. 이는 발칸 북부에서 오스만의 간접 통치 체제가 겪은 가장 심각한 동요였다. 반란은 진압되겠지만 세 공국의 충성은 1526-1593년 사이만큼 견고해지는 일이 다시는 없게 된다.", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["부쿠레슈티 봉기와 다뉴브 요새들에 대한 공격", "18971100"], "d": ["신성 동맹 가담 결정은 한 달 뒤 유혈로 실행되었다. 용감한 미하이는 부쿠레슈티에서 오스만 수비대와 도시의 레반트인 채권자들을 살육했다. 봉기는 같은 겨울 다뉴브 전선으로 번졌다. 왈라키아군은 주르주, 브러일라, 허르쇼바, 실리스트라를 공격했고, 몰다비아 쪽에서는 아론 보더가 벤데리의 오스만 수비대에 같은 기습을 가했다. 공격 대상의 선택은 우연이 아니었다. 이들은 모두 보이보드령의 영토가 아니라 다뉴브 연안에서 직접 오스만 통치에 속한 요새와 카자였다. 주르주 카자는 니코폴리스 산자크에, 브러일라는 1538년부터 국가에 직속으로, 벤데리도 1538년부터 부자크 산자크에 속해 있었다. 즉 반란은 속국인 내륙에서가 아니라 그 지역을 둘러싼 직할 오스만 껍질을 때린 것이다. 이 껍질이 뚫리지 않았다면 트란실바니아-왈라키아-몰다비아 삼각 지대는 합스부르크 전선에 연결될 수 없었다.", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["컬루거레니 전투 — 코자 시난 파샤의 왈라키아 원정", "201210a1"], "d": ["세 공국이 한꺼번에 이탈하자 대재상 코자 시난 파샤는 대군을 이끌고 다뉴브를 건너 왈라키아를 다시 복속시키기 위해 진군했다. 용감한 미하이는 정면 전투로는 맞설 수 없음을 알았기에 네아즐로브강의 늪지 통로인 컬루거레니에서 기다리다가 좁은 지형에 몰린 병력을 기습했다. 기습 뒤 수적으로 우세한 오스만군을 막아 내지 못한 그는 북쪽 산지로 물러났고, 시난 파샤는 부쿠레슈티와 트르고비슈테를 점령하고 왈라키아를 직접 통치에 편입하려 했다. 따라서 컬루거레니는 오스만에게 패배가 아니라 원정의 완수를 늦춘 기습이었다. 그러나 미하이가 군대를 보전할 수 있었기에 몇 주 뒤 트란실바니아에서 온 지원으로 반격에 나설 수 있었다.", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["왈라키아 철수와 주르주 기습 — 진압 원정의 무위", "118806e1"], "d": ["트란실바니아 공의 병력과 합류한 용감한 미하이의 반격으로 시난 파샤는 트르고비슈테와 부쿠레슈티를 비우고 다뉴브로 물러났다. 철수에서 가장 값비싼 순간은 나루터에서 벌어졌다. 1595년 10월 왈라키아에서 돌아오던 군대를 추격하여, 아큰즈(기습 기병)들이 주르주에서 미하이의 기습을 받았다. 이로써 원정은 왈라키아를 직접 통치에 편입하려던 목표를 이루지 못한 채 끝났고, 보이보드령은 사실상 이탈한 상태로 남았다. 이 삼각 지대에서 오스만의 권위는 여러 해에 걸쳐 조금씩만 회복될 수 있었다. 트란실바니아의 복속은 1604년의 보치카이 반란을, 전선의 완전한 종결은 1606년 지트바토로크 조약을 기다려야 했다.", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["호틴을 몰다비아에서 분리 — 보이보드령 한가운데의 직할 오스만 산자크", "947517cb"], "d": ["프루트 원정에서 몰다비아 보이보드 디미트리에 칸테미르가 러시아 편으로 넘어간 것은 보이보드령의 북쪽 국경을 더 이상 보이보드에게 맡길 수 없음을 보여 주었다. 그리하여 호틴은 1711년 이후 몰다비아에서 떼어 내어 직접 오스만 통치에 편입되었고, 처음에는 나히예(면)의, 이어 산자크의 지위가 부여되었다. 1713년의 일시적인 러시아 점령 뒤 요새는 이스탄불에서 파견된 오스만과 프랑스 기술 위원단의 감독 아래 다시 수리·확장되어 다뉴브 북쪽에서 가장 강력한 오스만 요새가 되었다. 이날 이후 지도에서 호틴이 속국 보이보드령의 색에서 벗어나 직할 오스만의 색으로 바뀌고, 속국 몰다비아 한가운데에 홀로 섬처럼 서 있는 것은 바로 이 행정적 분리에 해당하며 제도상의 오류가 아니다. 같은 구조는 부자크에서는 1538년부터, 킬리아와 아케르만에서는 1484년부터 이미 존재했다. 보이보드령은 내정이 자유롭고 국경 요새는 국가의 것이었다.", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["샤바츠의 두 번째 오스트리아 점령 — 사바 전선의 개방", "063b3ad0"], "d": ["1788년 2월 9일 오스트리아가 러시아 편으로 참전한 뒤 사바 방어선은 다시 전선이 되었고, 샤바츠는 1788년 4월 24일 오스트리아의 지배에 넘어갔다. 요새는 앞서 1717년 8월 17일 전투 없이 오스트리아에 내어졌고 베오그라드 조약(1739)까지 보유되었다. 그 시기에는 인구가 크게 줄어 도시에 기독교인 가옥 34채만 남았고 무슬림은 한 명도 남지 않았다. 1739-1788년의 오스만 시대에 인구는 다시 1500-2000명으로 늘었다. 두 번째 점령은 지슈토프(스비슈토프) 조약(1791년 8월 4일)으로 끝나고 요새는 오스만에 반환되게 된다.", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["샤바츠가 카라조르제에게 항복 — 제1차 세르비아 봉기의 첫 요새", "5c913eb4"], "d": ["1804년 베오그라드의 다이(예니체리 우두머리)와 야마크의 압제에 대한 반발로 시작되어 이후 민족주의적 성격을 띠게 된 첫 세르비아 혁명 중에, 샤바츠 요새는 1806년 1월 26일 카라조르제에게 넘겨졌다. 사바강 위의 이 요새는 봉기군이 장악한 첫 번째 큰 오스만 요새이며 베오그라드의 함락을 예고한다. 1813년 봉기가 진압되고 베오그라드가 탈환되자 요새도 오스만의 통치로 돌아왔다. 그러나 1830년 칙령의 수비대 조건에 따라 샤바츠는 베오그라드, 스메데레보, 페트홀이슬람(클라도보)과 함께 자치 세르비아 안에 오스만군이 남는 네 요새 중 하나로 규정되었고, 1867년 수비대가 철수할 때까지 이 지위를 유지했다.", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["라미아(이즈딘)가 그리스 국경 안에 남다 — 아르타-볼로스 선", "930f63b8"], "d": ["독립 그리스 국가의 북쪽 국경은 1832년 아르타만에서 볼로스만에 이르는 선으로 그어졌다. 오스만 시대(1424-1832)에 에우보이아 산자크에 속한 카자 중심지였던 라미아는 이 선의 남쪽에 있었기 때문에 그리스에 넘어갔으며, 테살리아의 나머지 지역(라리사, 트리칼라)은 1881년까지 오스만에 남았다.", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["러시아의 선전 포고 — 93년 전쟁의 시작", "ac548ab8"], "d": ["1876년 불가리아 봉기의 진압은 유럽 여론에 큰 분노를 일으켰고, 러시아는 이를 바브알리를 고립시키는 데 끝까지 활용했다. 불가리아를 두 자치 주로 나누자는 이스탄불(조선소) 회의의 제안과 이어 1877년 3월 31일자 런던 의정서를 오스만 국가가 거부하자, 러시아는 1877년 4월 24일 선전 포고했고, 러시아군은 자기 편으로 끌어들인 루마니아 공국의 영토에 들어갔다(지도는 이 시점부터 아드리아노폴리스(에디르네) 휴전까지 왈라키아-몰다비아를 러시아 진격의 빗금 덮개로 표시한다). 루미력 1293년에 해당하기 때문에 이 전쟁은 '93년 전쟁'이라는 이름으로 불린다. 작전은 다뉴브와 동아나톨리아의 두 전선에서 전개되었다. 다뉴브에서 18만 명의 오스만군은 강의 왼쪽 기슭을 제1방어선, 발칸 산맥을 제2방어선으로 삼았고, 동쪽에서는 아흐메드 무흐타르 파샤의 병력 5만 5000명이 아르다한과 도우베야즛 사이에 포진했다. 이 전쟁은 지도에서 오스만 루멜리아의 붕괴를 시작시킨 사건이다. 불가리아, 세르비아, 몬테네그로, 루마니아의 오늘날 국경은 모두 이 15개월의 산물이다.", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["루마니아의 독립 선언 — 왈라키아·몰다비아 속국 지위의 종말", "bdd164b3"], "d": ["93년 전쟁이 선포된 지 2주 뒤 루마니아 공국은 독립을 선언하고 러시아 편에서 참전했으며, 플레브나 포위에서 맡은 몫은 오스만의 패배에 결정적이었다. 400년이 넘는 왈라키아와 몰다비아의 속국 지위는 이렇게 사실상 끝났다. 독립은 베를린 회의(1878)에서 국제적 승인을 얻었다. 지도는 이날부터 루마니아를 속국이 아니라 고유의 색을 지닌 독립 국가로 표시한다. 독립 선언으로 왈라키아와 몰다비아 전역(이아시, 갈라치, 브러일라, 주르주, 칼라파트, 보토샤니 등)은 독립 루마니아가 되었다.", "9e037d13"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["러시아군의 다뉴브 도하 — 스비슈토프와 터르노보의 함락", "811367b1"], "d": ["전쟁이 시작되면서 루마니아 영토에 들어와 이 공국을 자기 편으로 끌어들인 러시아군은, 하나는 도브루자 방면, 하나는 부쿠레슈티 방면의 두 갈래로 진격했다. 다뉴브강은 루세와 니코폴리스 사이에서 건너졌고, 6월 27일 스비슈토프가, 7월 1일에는 옛 불가리아의 수도 터르노보가 점령되었다. 철수 명령이 내려졌는데도 이에 주의를 기울이지 않았기 때문에 니코폴리스도 한동안 저항한 뒤 항복했다. 제1방어선이 일주일 만에 돌파되자 이스탄불에는 큰 공황이 일었고, 술탄의 정부가 부르사로 옮겨진다는 소문까지 퍼졌으며, 전쟁 지휘는 수도에 설치된 군사 회의에 넘겨졌다.", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["시프카 고개의 철수 — 발칸 방어선의 돌파", "1f45e50a"], "d": ["발칸 산맥을 넘는 고개 가운데 전략적으로 가장 중요한 시프카의 오스만군은 러시아의 공격에 격렬히 맞섰으나, 패할 것이라고 판단하자 7월 19일 고개를 은밀히 철수했다. 이로써 제2방어선도 열렸고, 구르코 장군은 7월 22일 스타라 자고라를 점령했다. 몬테네그로 방면에서 달려온 쉴레이만 파샤는 구르코를 격파하고 발칸 남쪽의 점령지를 되찾았으나, 8월 21일부터 몇 달 동안 이어진 공세에도 시프카는 되찾지 못했다. 지도상에서 이는 발칸 산맥 북쪽과 남쪽 사이의 방어 일체성이 다시는 세워지지 못했음을 뜻하며, 다뉴브 전선의 싸움은 이후 플레브나에서 매듭지어지게 된다.", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["러시아군의 로베치 점령", "70e54611"], "d": ["93년 전쟁에서 로베치는 1877년 6월 5일 러시아에 점령되었고, 리파트 파샤가 지휘하는 오스만군이 6월 15일 러시아군을 격퇴했다. 도시는 8월 23일 오스만이 버려 다시 러시아의 점령에 들어갔다. 지도는 로베치를 이날부터 베를린 조약까지 러시아 점령(빗금)으로 표시하며, 법적으로는 오스만 영토로 계속 남는다.", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["카르스 함락 — 동부 전선의 붕괴와 아지지예 보루", "53fc3bf5"], "d": ["동아나톨리아에서 카르스, 도우베야즛, 아르다한을 향해 세 갈래로 진격한 러시아군은 4월 30일 도우베야즛을 점령하고 아르다한에 진입했으나, 에르주룸으로 진군하던 중 7월 15일 패하여 국경 밖으로 밀려났다. 아흐메드 무흐타르 파샤에게 '가지' 칭호를 안겨 준 이 성공은 8월 라자레프 장군이 다시 공세에 나서면서 뒤집혔고, 11월 18일 카르스가 함락되었다. 더 유리한 방어를 위해 에르주룸으로 물러난 오스만군은 아지지예 보루에서 네네 하툰이 주민들을 격려하는 가운데 큰 저항을 보였다. 카르스, 아르다한, 바투미는 8개월 뒤 베를린에서 전쟁 배상금 일부를 대신하여 러시아에 넘겨지게 된다.", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["제1차 발칸 전쟁의 발발 — 몬테네그로의 선전 포고", "c0c2697e"], "d": ["발칸 국가들은 통일진보위원회가 1911년 7월 3일자 법률로 교회 문제를 해결한 뒤 서로 간의 가장 큰 장애물이 사라지자, 러시아의 부추김 속에 1912년 내내 서로 동맹 조약을 맺었다(3월 13일 세르비아-불가리아, 5월 29일 불가리아-그리스, 8월 몬테네그로-불가리아, 10월 6일 몬테네그로-세르비아). 바브알리는 이를 눈치채지 못했으며, 심지어 러시아의 보장을 믿고 루멜리아의 훈련된 120개 대대를 제대시켰다. 네 나라는 10월 3일 공동 각서를 내어 마케도니아, 알바니아, 크레타의 자치를 요구했고, 답을 얻지 못하자 1912년 10월 8일 몬테네그로의 선전 포고로 작전이 시작되었다. 10월 13일 세르비아와 불가리아의 대사들에게 여권이 건네졌고, 이튿날 이 두 나라가, 이어 그리스가 선전 포고했다. 전쟁 중 군대 내부의 정치적 견해 차이가 패배에 큰 몫을 했다.", "33b60249"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["로도피에서 크르잘리 분견대가 패하고 크르잘리가 함락되다", "8cf59b7f"], "d": ["불가리아의 선전 포고 뒤 로도피에서 내려온 불가리아군은 메흐메드 야베르 파샤의 크르잘리 분견대를 격파하고 크르잘리에 진입했다. 패주한 분견대는 코모티니 방면으로 물러났으며, 로도피의 동부는 전쟁 첫 주에 상실되었다.", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["동부군의 참패와 차탈자 방어선으로의 후퇴 — 쿠마노보와 테살로니키의 상실", "cf95591a"], "d": ["오스만 동부군은 1912년 10월 23일 자기보다 세 배나 많은 불가리아군에게 패하여 이스탄불 서쪽 30킬로미터의 차탈자 방어선까지 후퇴했고, 수도는 전쟁 첫 달에 직접적인 위협을 받게 되었다. 같은 시기 서부군은 10월 23-24일 쿠마노보에서 세르비아군에게 패했으며, 타흐신 파샤는 3만 5000명의 군대와 함께 테살로니키에서 그리스군에게 항복했다. 이 참패들로 10월 29일 가지 아흐메드 무흐타르 파샤 내각이 사퇴했고, 테살로니키에서 유배 생활을 하던 압뒬하미드 2세는 11월 1일 이스탄불로 옮겨졌다. 차탈자 방어선은 전쟁이 끝날 때까지 지켜졌다. 500년에 걸친 루멜리아의 오스만 영토는 몇 주 만에 이 좁은 띠로 줄었다.", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["알렉산다르 왕자가 노비파자르 산자크의 중심지에 입성", "326d0616"], "d": ["세르비아군은 전쟁 첫 주에 노비파자르를 점령하고 서쪽에서 온 몬테네그로군과 합류했다. 백 년 동안 세르비아와 몬테네그로를 갈라놓았던 노비파자르 산자크는 이렇게 두 동맹국을 잇는 다리가 되었다.", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["크르클라렐리 전투 이후 크르클라렐리 상실", "eda4c759"], "d": ["동트라키아에서 동부군이 크르클라렐리 전투에서 패하자, 쾰레멘 압둘라 파샤가 지키던 이 도시는 불가리아군에 넘겨졌다. 도시는 아홉 달 동안의 점령에서 제2차 발칸 전쟁 때인 1913년 7월 21일에야 해방되었다.", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["코소보 주의 중심지 스코페가 저항 없이 내어지다", "455d9b71"], "d": ["쿠마노보 참패(10월 23-24일) 뒤 코소보 주의 중심지 스코페는 무방비 상태가 되었다. 주민들이 도시 주변에서 전투가 벌어지지 않기를 원하자, 영사들을 통해 초청된 알렉산다르 왕자 휘하의 세르비아군은 10월 26일 저녁 저항 없이 도시에 입성했다.", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["바르다르강 유역의 벨레스 상실", "73d20b7d"], "d": ["스코페 함락 이틀 뒤 바르다르강을 따라 남하한 세르비아군은 벨레스를 점령했다. 이로써 테살로니키로 열리는 바르다르 계곡의 관문이 세르비아의 손에 넘어갔다.", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["브레갈니차 유역: 스테파노비치 장군의 슈티프 입성", "70a84256"], "d": ["스테파노비치 장군 휘하의 세르비아 부대는 저항을 만나지 않고 슈티프를 점령했으며, 도시에는 먼저 비정규 무장단이 들어왔다. 쿠마노보에 이어 동마케도니아의 브레갈니차 유역이 세르비아의 통제에 들어갔다.", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["사란다포로 고개 이후 베리아가 그리스의 지배에 들어가다", "02a68e02"], "d": ["테살리아에서 북쪽으로 진격하던 그리스군은 사란다포로(크르크게치트) 고개를 넘은 뒤 베리아를 장악했다. 이때 도시의 무슬림 주민 일부가 이 지역을 떠났다.", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["테살로니키-비톨라 철도의 에데사 상실", "fc15b917"], "d": ["테살로니키-비톨라 철도에 있는 에데사는 그리스군의 손에 넘어갔다. 슬라브계와 튀르크계 주민이 강제로 떠나면서 도시 인구는 단기간에 크게 줄었다.", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["야니차 전투 — 야니차가 그리스에 넘어가다", "8f6cb76e"], "d": ["하산 타흐신 파샤의 제8 혼성 군단은 테살로니키 서쪽의 야니차에서 그리스군에게 패하고 테살로니키 지역으로 물러났다. 전투 중 읍의 대부분이 불탔고, 그리스군에게 테살로니키로 가는 길이 열렸다.", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["코소보 남서부의 프리즈렌 항복", "bae6b1b9"], "d": ["코소보 남서부의 프리즈렌은 세르비아군에게 항복했다. 도시에 들어온 부대가 무슬림 주민에게 보인 태도는 코소보에서 벌어진 이 전쟁의 가장 참혹한 대목 중 하나로 기록되었다.", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["미토프 대령이 스트루미차에 계엄 선포", "bcad75cc"], "d": ["불가리아의 미토프 대령은 스트루미차에 들어와 계엄을 선포했으며, 이튿날 떠나면서 읍을 불가리아인 군수(카이마캄)와 세르비아인 지휘관에게 맡겼다. 스트루미차는 전쟁 내내 동맹국들 사이에서 주인이 바뀌었고 1913년 불가리아에 귀속되었다.", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["하산 타흐신 파샤가 테살로니키를 그리스에 넘기다", "1738933c"], "d": ["야니차 패배 뒤 테살로니키로 물러난 하산 타흐신 파샤는 불가리아군이 북쪽에서 다가오자 도시를 그리스에 넘겼으며, 그리스군은 11월 8일 정오 무렵 도시에 입성했다. 이로써 오스만 루멜리아의 가장 큰 항구 도시이자 통일진보위원회의 발상지인 테살로니키가 상실되었다.", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["서트라키아의 중심지 코모티니가 불가리아에 열리다", "96eec25f"], "d": ["크르잘리에서 물러난 야베르 파샤 분견대가 페레스 방면으로 후퇴하자 코모티니는 불가리아군에게 항복했다. 서트라키아의 중심지는 전쟁이 끝날 때 불가리아에 넘겨질 영토 가운데 으뜸이었다.", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["엘바산에 도달한 세르비아군이 같은 날 데바르에 입성", "16720246"], "d": ["비톨라에서 서쪽으로 진격하던 세르비아군은 엘바산에 도달한 날 데바르에도 입성하고 아드리아해를 향해 내려갔다. 같은 날 블로러에서는 알바니아의 독립이 선포되고 있었다.", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["티무르의 두 번째 바그다드 점령 — 도시의 아바스 시대 구역 파괴", "04b68a24"], "d": ["티무르는 8년 간격으로 바그다드를 두 번 점령했다. 1393년의 첫 점령 때에는 도시가 큰 피해를 입지 않았다. 1401년의 두 번째 점령은 바그다드의 문화생활에 가해진 두 번째 큰 타격으로 여겨진다. 주민들은 살육당했고, 아바스 시대부터 남아 있던 구역과 건물 대부분이 파괴되었다. 잘라이르 왕조의 군주 아흐마드는 1405년 도시로 돌아와 무너진 성벽과 시장을 복구하려 했으나 시간이 없었다. 바그다드는 1410년 흑양 왕조의 투르크멘의 손에 넘어갔다. 이 두 차례의 점령은 앙카라 전투로 이어지는 길에서 티무르가 오스만과 맘루크의 국경에 얼마나 가까이 다가왔는지를 가장 구체적으로 보여 주는 걸음 중 하나이다.", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["주네이드 베이가 아이딘 지방의 수장으로 복귀 — 아이든 왕조의 재독립", "63281658"], "d": ["첼레비 메흐메드는 1414-15년 이즈미르를 점령하고 주네이드 베이를 니코폴리스 산자크 베이로 보내 아이딘 지방을 오스만의 통치에 편입했다. 주네이드는 첼레비 메흐메드가 죽은 뒤, 비잔티움이 왕위 요구자로 내세운 무스타파 첼레비의 편에 다시 등장했으며 그의 재상까지 지냈다. 무라드 2세는 옛 베이국을 돌려주겠다는 약속으로 그를 이 동맹에서 떼어 놓았다. 주네이드는 이즈미르로 돌아가 아야술루크를 장악하고 아이든 가문의 무스타파 베이를 죽이고 베이국의 수장이 되었다. 이로써 아이딘 지방은 가짜 무스타파 위기 속에서 오스만의 통치를 벗어난 상태로 생겨났다.", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["주네이드 베이와 그 일족의 처형 — 아이든 베이국의 종말", "efa684ba"], "d": ["다시 아이딘 지방의 지배자가 된 주네이드 베이가 아나톨리아의 베이들을 선동하고 베네치아와 접촉하려 하자, 무라드 2세는 아나톨리아 베일레르베이 함자 베이를 보냈다. 아들 쿠르드 하산이 아크히사르 근처에서 패해 포로가 되자 주네이드는 사모스 섬 맞은편의 입실리로 물러났다. 카라만의 군주에게 기대한 원조가 오지 않고, 오스만과 행동을 같이하던 제노바인들이 그를 해상에서 봉쇄하자 항복할 수밖에 없었으며, 그는 일족 전체와 함께 제거되었다. 이로써 아이든 왕조의 영토는 완전히 오스만의 통치에 들어갔다.", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["에르주룸과 반 호수 분지가 사파비에 넘어가다 — 백양 왕조의 북쪽 날개 붕괴", "b418875f"], "d": ["샤루르에서 엘반드 베이를 격파하고 1501년 여름 타브리즈에 입성한 샤 이스마일은 이듬해 북서쪽으로 진격해 에르주룸에서 반 호수 분지에 이르는 선을 지배 아래에 두었다. 백양 왕조는 우준 하산이 죽은 뒤 이미 왕위 다툼으로 둘로 나뉘어 있었다. 엘반드 베이는 아제르바이잔과 디야르바크르를, 그의 사촌 무라드는 이라크 아자미와 파르스를 장악하고 있었다. 이 분열은 사파비의 진격을 쉽게 했으며, 이 지역은 10개의 기록에 걸쳐 1년 안에 주인이 바뀌었다. 에르주룸은 이후 16년 동안 사파비의 손에 있었고 찰디란 전투 이후인 1518-19년에야 오스만의 지배에 들어갔다. 이해(1502년)에 아슈칼레와 파신레르(하산칼레)는 에르주룸 지역과 함께 백양 왕조에서 사파비에 넘어갔다(날짜 미확인).", "2f80b39d"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["무라드 베이의 하마단 패배: 이라크 아자미와 파르스가 사파비에 넘어가다", "8de07a31"], "d": ["백양 왕조 왕위의 두 번째 요구자 술탄 무라드는 하마단 근처에서 샤 이스마일과 벌인 전투에서 대패하고 바그다드로 도망쳤다. 이 한 번의 전투로 이라크 아자미, 파르스, 케르만 지역이 사파비의 통치에 들어갔으며, 지도에서 이 지역들은 동시에 주인이 바뀐다. 이는 백양 왕조 해체에서 가장 큰 한 걸음이다. 타브리즈의 상실이 왕조를 수도 없는 처지로 만들었다면, 하마단의 패배는 영토 없는 처지로 만들었다.", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["샤 이스마일의 야즈드 입성: 중부 이란에서 백양 왕조 잔존 세력의 마지막 요새 함락", "6f9835df"], "d": ["1503년 하마단 패배 후 이라크 아자미와 파르스가 사파비에 넘어갔음에도, 야즈드는 백양 왕조 가문의 바이은드르 무라드 베이의 손에 따로 남아 있었다. 도시는 한 달간의 포위 끝에 함락되었고, 중부 이란의 마지막 백양 왕조 섬이 닫혔다. TDV의 기록은 \"샤 이스마일은 910년 주마다 알아키라월 28일(1504년 12월 6일) 한 달간의 포위 끝에 도시에 입성했다.\"이다.", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["샤 이스마일의 디야르바크르 원정: 백양 왕조의 마지막 중심지 함락", "b6d8504e"], "d": ["아제르바이잔과 이란 고원을 장악한 샤 이스마일은 1507년 서쪽으로, 백양 왕조가 발원한 디야르바크르 지역으로 향했다. 아미드에서 마르딘, 우르파에서 하르푸트에 이르는 선이 두 차례의 작전으로 사파비의 통치에 들어갔고 백양 왕조는 사실상 사라졌다. 이 원정은 또한 사파비의 국경을 처음으로 오스만과 맘루크의 국경에 맞닿게 했으며, 찰디란에 이르는 긴장의 지리적 토대가 이렇게 형성되었다.", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["바그다드의 사파비 이관 — 아랍 이라크의 주인 교체", "39730186"], "d": ["하마단 패배 후 바그다드로 피신한 백양 왕조의 술탄 무라드에 이어, 샤 이스마일은 1508년 아랍 이라크에 들어가 바그다드를 점령했다. 카르발라와 나자프의 영묘가 사파비의 통치에 들어간 것은 이 운동의 종파적 주장이라는 면에서 타브리즈 점령만큼 중요했다. 지도에서 아랍 이라크는 같은 날 주인이 바뀌며, 이는 해체의 마지막이자 지리적으로 가장 넓은 단계이다. 바그다드는 1534년 카누니의 두 이라크 원정까지 사파비의 손에 있었다.", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["메르브 전투: 우즈베크의 대패, 메르브와 헤라트 점령", "f8e45aaf"], "d": ["서쪽에서 백양 왕조의 유산을 완전히 차지한 샤 이스마일은 동쪽의 호라산으로 진군해 메르브 앞에서 우즈베크를 크게 격파했으며, 샤이바니 칸은 전장에서 전사했다. 메르브와 헤라트는 사파비의 지배에 들어갔고, 사파비 왕조는 유프라테스에서 아무다리야에 이르는 국경을 얻었다. 이로써 1501년 여름 타브리즈 입성으로 시작된 과정은 9년 만에 완결되었다. 백양 왕조의 유산은 모두 사파비의 통치로 넘어갔고, 오스만 국가는 동쪽에서 자신과 비슷한 크기의 두 번째 국가를 이웃으로 두게 되었다.", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["자비드의 오스만 지배 확정", "ddd971c7"], "d": ["1538년 11월 5일 디우 포위를 푼 함대는 귀로에 예멘 해안에 들렀고, 자비드는 확정적으로 오스만의 통치에 편입되었다. 하딤 쉴레이만 파샤는 1539년 3월 10일 도시를 떠나 4월 1일 제다에 도착했다. 도시는 1517년부터 옛 맘루크 베이들의 손에서 오스만의 이름으로 다스려지고 있었으며, 이날로 직접 통치에 넘어갔다.", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["이베리아 연합: 포르투갈 왕관이 스페인 왕에게 넘어가다", "1cc6dfdc"], "d": ["추기경 왕 엔히크가 후계자 없이 죽으면서 시작된 왕위 계승 다툼은 알칸타라 전투(1580년 8월 25일)에서 스페인에 유리하게 끝났으며, 토마르에서 소집된 포르투갈 코르테스는 1581년 4월 16일 펠리페 2세를 포르투갈 왕으로 인정했다. 토마르 조건에 따르면 포르투갈은 자국의 제도, 화폐, 언어를 유지하고, 통치에는 포르투갈인만 임명하며, 마드리드에 별도의 포르투갈 평의회를 두기로 했다. 즉 통합은 병합이 아니라 동군연합이었다.", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["왕정 복고(Restauração): 포르투갈의 독립 회복", "64ec0738"], "d": ["카탈루냐 반란이 스페인을 붙들고 있던 시기에 리스본에서 일단의 귀족들이 궁전을 급습해 스페인의 통치를 무너뜨리고 브라간사 공작을 주앙 4세라는 이름의 왕으로 선포했다. 60년에 걸친 이베리아 연합은 이렇게 끝났으나, 세우타는 스페인에 남기를 택했고 이는 1668년 리스본 조약으로 승인되었다. 포르투갈이 합스부르크의 전쟁에 연결되었던 이 시기는 아시아에서의 손실의 틀이기도 하다. 호르무즈는 1622년, 말라카는 1641년, 콜롬보는 1656년에 상실되었으며, 탕헤르와 봄베이는 독립의 대가로 영국에 주어졌다. 출처: Britannica, History of Portugal — Restoration.", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["탕헤르의 영국 이양", "1f7cad6d"], "d": ["포르투갈의 독립 전쟁에서 영국의 지원을 확보하기 위해 체결된 혼인 조약(1661년 6월 23일) 제2조는 탕헤르를 브라간사의 캐서린의 지참금으로 영국에 넘기도록 했다. 샌드위치 백작의 함대는 1662년 1월 29일 정박했고, 이튿날 피터버러 백작의 의식으로 공식 이양이 이루어졌다. 영국인들은 1684년에 도시를 포기하게 된다.", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["나디르 샤의 암살 — 아프샤르 지배의 와해", "19c218c0"], "d": ["사파비 왕좌를 끝내고 1736년 자신의 이름으로 왕조를 선포했으며, 인도 원정으로 델리까지 갔고 오스만과 세 차례 전쟁을 치른 뒤 1746년 케르덴 조약으로 화해한 나디르 샤는 자신의 경호병들에게 천막 안에서 살해되었다. 이후 이란은 하나의 손으로 통치되지 못했다. 호라산의 아프샤르 잔존 세력, 남부의 잔드 왕조, 북부에서 부상하는 카자르가 49년 동안 나라를 나누어 가졌다. 오스만의 동쪽 국경은 이 분열 덕분에 오랫동안 평온했다. 나디르 샤는 1747년 6월 20일에 살해되었으며, TDV에 따르면 예레반 칸국은 같은 해(1747년)에 세워졌으나 날짜는 확인되지 않았다.", "75fd6ab9"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["카자르 왕조의 이란 장악", "744b48c5"], "d": ["카자르 부족의 수장 아가 무함마드 칸은 잔드 왕조의 지배를 무너뜨리고 호라산의 마지막 아프샤르 저항도 꺾어 이란을 다시 하나의 손에 모으고 테헤란을 수도로 삼았다. 49년간의 분열 시대는 이렇게 끝났으며, 이후 1923년까지 오스만의 동쪽 이웃은 카자르 왕조의 이란이 된다. TDV 이슬람 백과사전에 따르면 마슈하드에서는 1796년 아프샤르 군주 샤흐루흐가 아가 무함마드 샤를 맞이했고, 마슈하드는 카자르의 지배에 들어갔다(사료에 날짜 없음).", "755b544a"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["페르디난트의 부다 장악 — 서포여이가 수도에서 축출되다", "99f77c29"], "d": ["모하치 전투 이후 헝가리 왕위에는 두 명의 왕이 등장했다. 귀족 일부는 서포여이 야노시를, 일부는 합스부르크가의 페르디난트를 선출했다. 페르디난트는 1527년 부다를 장악하고 서포여이를 수도에서 몰아냈으며, 서포여이는 술탄 쉴레이만에게 도움을 청했다. 이것이 1529년 빈 원정의 첫 번째 목표가 부다였던 이유이다.", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["바르바로스의 에게해 도서 원정 — 낙소스 공국이 오스만의 통제하에 들어가다", "722b2fea"], "d": ["1207년부터 베네치아의 종주권 아래 라틴계 공작들이 다스리던 낙소스 공국은 바르바로스 하이레딘 파샤의 도서 원정으로 오스만의 통제하에 들어갔다. 섬의 지위는 건드리지 않아 공국은 오스만의 속국으로 존속했으며, 1540년 오스만-베네치아 조약으로 주권이 공식적으로 오스만에 이양되었다.", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["십자군 함대의 제르바 점령 — 투르구트 파샤의 근거지 상실", "f41b3f2a"], "d": ["스페인, 교황령, 몰타, 제노바, 피렌체의 선박으로 구성된 십자군 함대는 투르구트 레이스가 1551년부터 습격 기지로 사용해 온 제르바를 목표로 삼았다. 함대는 폭풍과 전염병 때문에 1560년 초에야 섬 앞바다에 도달할 수 있었고, 1560년 3월 12일 섬을 점령하고 요새를 쌓았다. 이 소식을 들은 피얄레 파샤는 3월 28일 갤리선 120척의 함대를 이끌고 이스탄불을 출항했다. 점령은 오래가지 못했다. 오스만 함대는 5월 제르바 앞바다에서 연합군을 격파했고, 요새도 7월 말에 탈환되었다. 이 원정은 프레베자 이후 지중해에서 오스만의 우위를 굳힌 두 번째 대규모 해상 작전의 시작이다.", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["제르바 요새의 함락 — 섬의 오스만 행정 편입", "f1efc0df"], "d": ["1560년 5월 14일 피얄레 파샤의 해전 승리 후 십자군 병력은 자신들이 섬에 쌓은 요새에 틀어박혔고, 트리폴리 베일레르베이 투르구트 파샤의 병력이 육지에서 이를 포위했다. 두 달간 이어진 포위전은 1560년 7월 30일 요새가 함락되면서 끝났고, 섬은 트리폴리 베일레르베이령에 편입되었다. 해전 승리와 요새 정복 사이에는 77일의 간격이 있으며, 섬은 5월 14일이 아니라 7월 30일에 실질적으로 주인이 바뀌었다.", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["단치히의 러시아-프로이센 이중 통치 종료 — 나폴레옹의 자유시가 프로이센으로 돌아가다", "1ccda4d2"], "d": ["틸지트 강화(1807년 7월 9일)로 프로이센에서 분리되어 프랑스의 보호를 받는 자유시가 된 단치히를 나폴레옹의 군대는 1813년의 포위전 이후 포기했다. 1814년 1월 2일부터 2월 4일까지 이 도시에서는 러시아-프로이센의 이중 통치가 이어졌으며, 차르 알렉산드르가 단치히와 비스와강 하구를 차지하려던 계획을 포기하면서 도시는 프로이센의 행정하에 들어갔다.", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["빈에서 크라쿠프를 자유·독립·중립 도시로 선포", "19eea839"], "d": ["빈 회의에서 러시아, 오스트리아, 프로이센은 크라쿠프시와 그 주변 지역을 세 나라의 보호를 받는 자유 국가로 만들었으며, 빈 회의 최종 의정서가 이 체제를 확인했다.", "21a6fe2b"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["보르누가 라비흐 이븐 주바이르의 지배하에 들어가다", "8be4ca96"], "d": ["바기르미와 와다이를 뒤흔든 수단 출신의 군벌 라비흐 이븐 주바이르가 보르누를 장악했다. 그는 1896년까지 나라 전체를 손에 넣고 디크와를 중심지로 삼았다.", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["라비흐 이븐 주바이르가 프랑스군에 패해 전사 — 보르누에서의 지배 붕괴", "fb5a3ace"], "d": ["프랑스 식민지 군대에 패한 라비흐는 죽임을 당했다. 그의 아들이 지배를 이어가려 했으나 버티지 못했고, 보르누는 1902년 프랑스, 영국, 독일 사이에 분할되었다.", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["귀뮐지네를 중심으로 한 서트라키아 임시정부 선포", "974b2e28"], "d": ["부쿠레슈티 조약(1913년 8월 10일)이 서트라키아를 불가리아에 넘기자, 이 지역의 튀르크계 주민은 귀뮐지네를 중심으로 한 임시정부를 선포했다. 데데아아치를 점령한 뒤 정부는 '서트라키아 독립정부'라는 이름으로 독립을 선언했다. 열강의 개입으로 오스만 정부는 이 정부를 지원하지 않았고, 1913년 9월 29일의 이스탄불 조약이 서트라키아를 불가리아에 넘기면서 이 정부는 1913년 10월 25일까지 겨우 57일간 존속했다.", "86d3bfee"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["오르한 가지의 서거 — 베이국에서 국가로 이행한 40년의 마감", "62c59cfd"], "d": ["1324년 오스만 가지가 죽자 베이국의 수장이 된 오르한 가지는 38년의 통치 동안 오스만을 변경의 베이국에서 마르마라해 양안에 자리 잡은 국가로 변모시켰다. 부르사(1326), 이즈니크(1331), 이즈미트(1337)를 점령하고 카레시 베이국을 병합했으며, 최초의 악체를 주조했고(1327), 이즈니크에 최초의 마드라사를 세웠으며(1331), 침페(1352)와 갈리폴리(1354)를 통한 루멜리아 진출을 영구적인 것으로 만들었다. 그는 루멜리아 정복을 이끌던 맏아들 쉴레이만 파샤를 1357년 사냥 중 사고로 잃었다. 오르한 자신은 1362년 3월 부르사에서 세상을 떠났고 아들 무라드 1세가 뒤를 이었다.", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["바레인 제도가 자브르 왕조의 수중에 넘어가다", "6a242b16"], "d": ["TDV의 바레인 항목은 이 섬이 \"차례로 우윤 왕조, 살구르 왕조, 타브 왕조, 자브르 왕조의 통치하에 있었으며, 자브르 왕조 시대에 다수파가 시아파에서 수니파로 바뀌었다\"고 기록하면서도 어느 것에도 연대를 제시하지 않는다. 일반 연구 문헌에 따르면 자브르 왕조는 15세기 초 카티프의 마지막 자르완 왕조 통치자를 무너뜨리고 세워졌으며, 전성기(아즈와드 이븐 자밀, 1496년 사망)에는 페르시아만의 아랍 해안 전체와 알하사, 카티프, 바레인 제도를 지배했다. 아즈와드 이후 아왈 제도는 무크린 이븐 자밀에게 넘어갔는데, 그가 바로 1521년 포르투갈인에게 패하게 되는 통치자이다.", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["포르투갈의 아르질라 점령 — 모로코 해안의 두 번째 교두보", "83444a11"], "d": ["아폰수 5세는 3만 명의 병력과 400척의 함대를 이끌고 몸소 모로코 해안에 상륙하여, 와타스 왕조가 다스리던 아르질라를 1471년 8월 24일 점령했다. 이 도시의 함락은 탕헤르의 저항 의지를 꺾었고, 탕헤르는 나흘 뒤인 8월 28일 싸우지 않고 항복했다. 이로써 포르투갈은 세우타(1415)와 크사르 에스세기르(1458)에 이어 모로코 대서양 연안에 세 번째와 네 번째 거점을 확보했다. 국왕은 이 원정 이후 자신의 칭호에 \"아프리카의 주군\"이라는 문구를 덧붙였다.", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["사피가 포르투갈의 영향권에 들어가다", "765e703e"], "d": ["대서양 연안에서 곡물과 어업이 가장 활발한 항구였던 사피는 1488년 포르투갈의 영향권에 들어갔다. 이 도시는 한동안 포르투갈의 보호 아래 현지 통치자들을 통해 다스려졌고, 1508년에 직접 점령되었다. 사료마다 이 두 단계에 두는 비중이 달라 시작 연도는 1488년과 1508년 사이에서 엇갈리지만, 둘 다 같은 과정의 양 끝이다. 사피는 53년간 포르투갈의 수중에 있었으며, 1541년 아가디르가 함락된 뒤 철수가 이루어졌다.", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["산타크루스 두 카부 드 게의 건설 — 아가디르의 포르투갈 요새", "cc22c433"], "d": ["수스 해안에서 그때까지 포르투갈의 손이 닿지 않았던 지점에 민간 사업으로 세워진 산타크루스 두 카부 드 게 요새는 1505년에 건설되었고 1513년 포르투갈 왕실에 이관되었다. 이 요새는 수스 계곡의 설탕과 금 교역을 통제하며 마라케시의 남서쪽 출구를 막았기 때문에 사드 왕조 운동의 첫 번째 주요 목표가 되었다. 1533년의 포위는 격퇴되었으나 1541년의 포위는 성공하여 모로코에서 포르투갈의 붕괴가 시작되었다.", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["아제무르 점령 — 움 에르 르비아강 하구의 장악", "232acd4b"], "d": ["브라간사 공작 자이므가 지휘하는 포르투갈군은 1513년 9월 3일 움 에르 르비아강 하구의 아제무르에 아무런 저항 없이 입성했다. 이 도시를 점령함으로써 강 하구와 내륙으로 통하는 곡물 수송로를 모두 장악하게 되었고, 이듬해 남서쪽 12km 지점에 마자간 요새를 세우는 길이 열렸다. 아제무르는 28년간 포르투갈의 수중에 있었다.", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["마자간 요새의 건설 — 모로코에서 가장 오래 유지될 포르투갈 거점", "786cdb40"], "d": ["아제무르를 점령한 이듬해인 1514년 여름, 해안에 마자간 성채가 건설되었다. 1541년의 전면적 붕괴 이후 포르투갈은 모로코의 모든 거점을 포기하면서도 마자간만은 버리지 않았다. 오히려 이탈리아식 능보를 갖춘 요새로 처음부터 다시 쌓았으며, 이 도시는 255년 동안 유지되었다. 1562년의 대규모 포위도 격퇴되었다. 마자간은 모로코의 마지막 포르투갈 거점으로서 1769년에 철수가 이루어지게 된다.", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["마르딘 요새의 항복 — 디야르베키르 남쪽에서 사파비 저항의 종결", "e6226de5"], "d": ["찰디란 전투 이후 디야르베키르 지방으로 진군한 브이으클르 메흐메드 파샤가 마르딘을 포위하자, 사파비 병력은 1515년 10월 요새 안으로 물러났다. 도시는 오스만의 손에 넘어갔으나 요새는 저항했다. 사파비 총독 카라 칸이 증원군을 얻어 감행한 반격은 1516년 5월의 코치히사르(크즐테페) 전투로 귀결되었다. 데데 가르큰 평원에서 하루 종일 이어진 전투에서 카라 칸은 참수되었고 그의 군대는 흩어졌다. 그러나 요새는 TDV의 표현에 따르면 \"9개월 뒤에야\" 항복했다.", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["포르투갈의 바레인 점령 — 자브르 왕조 지배의 종말", "315a435a"], "d": ["자브르 왕조의 통치자 무크린 이븐 자밀이 호르무즈에 공납 바치기를 거부하자, 포르투갈 함대와 포르투갈의 속국인 호르무즈 왕국의 병력이 섬에 상륙했다. 무크린은 전투에서 패했고 바레인은 1521년 포르투갈의 지배하에 들어갔다. 이후 80년간 이 섬은 호르무즈를 통해, 대개 수니파 이란인 총독들의 손으로 다스려졌다. 바레인의 진주와 전략적 위치는 이 섬을 페르시아만에서 벌어진 오스만-포르투갈 경쟁의 직접적인 목표로 만들게 된다.", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["아가디르 함락 — 사드 왕조가 모로코에서 포르투갈을 몰아내기 시작하다", "bb1568f6"], "d": ["사드 왕조의 술탄 무함마드 앗셰이흐는 1541년 2월 16일 산타크루스 요새를 포위하여 3월 12일 점령했다. 총독 구테르 드 몬로이를 포함하여 약 600명의 포르투갈인이 포로가 되었다.", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["사피와 아제무르에서의 철수 — 포르투갈이 대서양 연안에서 물러나다", "4cb6099a"], "d": ["1541년 3월 12일 아가디르가 함락되고 모로코 술탄과 기대하던 동맹을 맺지 못하자, 주앙 3세는 대서양 연안의 두 대거점에서 철수하라고 명령했다. 사피와 아제무르의 철수는 1541년 가을인 9~10월에 완료되었다. 이로써 단 한 해에 세 거점을 잃었고, 모로코 해안에서 50년간 이어진 포르투갈의 팽창은 역전되었다. 남은 곳은 세우타, 탕헤르, 아르질라, 크사르 에스세기르, 그리고 새로 요새를 보강한 마자간이었다.", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["아르질라 철수 — 포르투갈이 북부 해안의 영역을 줄이다", "b5d18373"], "d": ["재정 위기와 사드 왕조의 압박이 겹치자 주앙 3세는 1471년부터 보유해 온 아르질라에서 철수했다. 이로써 모로코에서 포르투갈의 세력은 세우타, 탕헤르, 마자간으로 줄었다. 아르질라는 1577년 잠시 다시 점령되었다가 1589년에 완전히 포기되었다.", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["오스만의 바레인 원정 — 페르시아만에서 포르투갈에 맞선 마지막 대공세", "14501df3"], "d": ["1546년 바스라를 병합하고 라흐사(알하사) 주를 설치하여 페르시아만의 아랍 해안에 자리 잡은 오스만 국가는 섬의 진주 교역과 포르투갈의 호르무즈 노선을 겨냥하여, 라흐사 베일레르베이 무스타파 파샤의 지휘 아래 바레인으로 진군했다. 원정의 결과는 사료마다 엇갈린다. TDV 이슬람 백과사전은 오스만이 \"1559년 바레인을 점령하고 그곳에 기지를\" 세웠으며 제도가 \"그 후 다시 포르투갈의 통치하에\" 넘어갔다고 쓴다. 반면 서구의 문헌은 포위가 실패했고, 호르무즈에서 해로로 온 포르투갈 증원군이 오스만 병력을 격퇴했으며, 양측 모두에 큰 타격을 준 페스트 유행 이후 오스만 측이 항복 조건을 요청했다고 기록한다. 두 서술은 결과 자체에서 갈라지지만, 바레인이 오스만의 수중에 영속적으로 남지 않았다는 점은 공통된다.", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["울루츠 알리 파샤의 튀니스 점령 — 하프스-스페인 체제의 종말", "d4498698"], "d": ["카를 5세는 1535년 튀니스를 점령했을 때 도시를 직접 다스리지 않고 하프스 왕조의 술탄 물라이 하산을 다시 왕위에 앉혔다. TDV의 표현에 따르면 튀니스시는 \"1569년 오스만의 두 번째 개입이 있기까지 스페인의 보호 아래, 그리고 물라이 아흐마드 3세의 통치 아래\" 있었다. 1568년 6월 27일 알제 베일레르베이령에 임명된 울루츠 알리는 육로로 튀니스를 향해 진군하여 베자에서 하프스 술탄을 격파하고 도시에 입성했다. 물라이 아흐마드는 스페인의 요새 거점(프레시디오)인 라굴레트(할쿨와디)로 피신했다. 이로써 만은 도시는 오스만, 항구 요새는 스페인의 둘로 나뉘었으며, 이 분할은 4년간 지속되었다.", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["돈 후안 데 아우스트리아의 튀니스 탈환 — 레판토 승리가 육지에서 거둔 유일한 결실", "a6f044ee"], "d": ["레판토 해전(1571) 이후 신성동맹이 해체되었는데도 스페인은 단독으로 북아프리카를 압박했다. TDV의 표현에 따르면 \"1573년 10월 10일 스페인인들은 튀니스의 지배권을 장악할 목적으로 새로운 작전에 착수했다. 그들은 튀니스를 점령하고 이곳에 8000명의 병사를 남겼다.\" 돈 후안 데 아우스트리아가 지휘한 이 작전은 레판토의 승리가 육지에서 결실을 거둔 유일한 곳이다. 그러나 이는 오래가지 못했고 도시는 11개월 뒤에 탈환되었다. 이 점령이 무너뜨린 것은 이미 확립되어 있던 오스만 행정이었다. 히즈라력 980년 둘 히자월 2일(1573년 4월 5일) 당시 튀니스의 사령관은 클르츠 알리 파샤, 카이마캄(대리관)은 라마잔 파샤, 베일레르베이는 하이다르 파샤였다.", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["사파비 왕조가 포르투갈로부터 바레인을 탈취하다", "c37d982c"], "d": ["샤 아바스 1세가 보낸 병력은 섬의 반란 세력과 합세하여 포르투갈 수비대를 요새에서 몰아냈다. TDV의 표현에 따르면 이 제도는 \"1602년 이란에 속한 병력에 의해\" 포르투갈인의 손에서 빼앗겼다. 이로써 바레인은 81년간의 포르투갈 통치에서 벗어나 사파비 왕조의 지배하에 들어갔고, 115년 동안 이란에 속했다. 이는 페르시아만에서 포르투갈 세력이 해체되는 첫 번째 고리이다. 20년 뒤에는 호르무즈 자체도 영국-이란 합동 작전으로 함락되게 된다.", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["오만의 바레인 침공 — 사파비 지배의 종말", "c9be5820"], "d": ["사파비 국가 말기의 해체 과정에서 야루브 왕조가 다스리던 오만의 함대가 섬을 침공했고, 사파비의 지배는 끝났다. 뒤이은 35년은 페르시아만에서 가장 혼란한 시기였다. 섬은 오만, 이란, 현지 아랍 세력 사이에서 여러 차례 주인이 바뀌었다.", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["바레인이 부셰르의 알 마즈쿠르 가문의 통치로 넘어가다", "610e2f9d"], "d": ["본래 오만에서 와서 부셰르에 정착했으며 후왈라족으로 간주되는 알 마즈쿠르 가문은 1753년 부셰르의 근거지에서 출발하여 바레인을 자신들의 통치 아래 두었다. 이 가문은 이란의 페르시아만 연안에 사는 아랍 공동체들을 이끌었고 이란의 이름으로 섬을 다스렸다. 마지막 대표자인 나스르 알 마즈쿠르는 잔드 정권에 의해 바레인 총독으로 임명되었다. 이는 알 칼리파 가문 이전 섬의 마지막 통치 체제이다.", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["마자간 철수 — 모로코의 마지막 포르투갈 거점 상실", "f9e9749d"], "d": ["알라위 왕조의 술탄 무함마드 3세 이븐 압달라가 1769년 초에 시작한 포위 앞에서 592명의 수비대는 버틸 수 없었다. 2월 1일 리스본을 출항한 철수 선단은 1769년 3월 11일 마지막 병사들을 승선시켰고, 총독 디니스 그레고리우가 가장 마지막으로 도시를 떠났다. 이로써 1415년 세우타 점령으로 시작된 모로코 내 포르투갈의 존재는 3세기 반 만에 끝났다. 마자간은 1541년의 전면적 붕괴 이후 유지된 대서양 연안의 유일한 거점이었으며, 255년이라는 기간으로 포르투갈이 모로코에서 가장 오래 보유한 곳이 되었다.", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["알 칼리파 가문의 바레인 정복 — 오늘날까지 이어지는 왕조의 성립", "8773b011"], "d": ["잔드 정권의 바레인 총독 나스르 알 마즈쿠르는 카타르반도의 주바라를 포위했다. 아흐마드 이븐 무함마드 이븐 칼리파가 지휘하는 우투브 병력은 포위를 깨뜨리고 반격에 나서 같은 해에 바레인을 점령했다. TDV의 기록은 짧다. \"바레인은 1783년 우투브 부족의 알 칼리파 가문의 지배하에 들어갔다.\" 아흐마드 이븐 무함마드는 이 승리 이후 \"알파티흐\"(정복자)라는 칭호로 불렸고, 그가 세운 왕조는 오늘날까지 섬을 통치해 왔다.", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["바레인과 영국의 조약 — 페르시아만의 보호령 체제 편입", "576796b2"], "d": ["TDV의 기록에 따르면 \"1861년 5월 21일 영국과, 바레인을 대표한 셰이크 무함마드의 동생 알리는 이 지역에서 노예무역과 해적 행위를 금지하는 협정에 서명했다.\" 영국 문서에서는 같은 조약(Perpetual Truce of Friendship and Peace, 우호와 평화의 영구 휴전 조약)의 날짜가 1861년 5월 31일로 되어 있다. 이 조약은 바레인의 대외 관계를 영국에 종속시킨 보호령 체제의 첫 번째 고리이며, 1871년 오스만이 라흐사와 카티프에 다시 자리 잡은 뒤에도 섬은 이 체제 밖에 남았다.", "ab2ad5ff"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["아히 에브란 — 아히 조직의 창시자이자 수호성인", "3392e100"], "d": ["아히 에브란은 아나톨리아 아히 조직의 창시자 가운데 한 사람이자 무두장이(가죽 장인)들의 수호성인(피르)으로 여겨진다. 크르셰히르에 있는 그의 자비예(수도원)는 오스만 시대에 장인·길드 조직의 정신적 중심지로서 20세기 초까지 이어졌으며, 국가는 1780년, 1782년, 1822~23년, 1842년에 이 지위를 공식적으로 확인했다.", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["셰이흐 에데발리 — 아히 조직과 오스만 왕가를 잇는 건국기의 유대", "c1186059"], "d": ["빌레지크에 자비예를 세웠고 아히 조직의 셰이흐이기도 했던 에데발리는 전승에 따르면 오스만 가지의 유명한 꿈을 해몽했으며, 그 뒤 오스만 가지는 에데발리의 딸 말훈 하툰과 혼인했다. 에데발리는 또한 오스만 최초의 카디이자 무프티로 여겨진다.", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["오르한 가지가 부르사 정복 후 지리드 경기를 위한 터를 와크프로 기증하다", "da1becbd"], "d": ["TDV의 지리드(말 타고 창 던지기) 항목에 따르면, 오르한 가지는 부르사를 정복한 뒤 인근의 한 터를 경마와 지리드 경기를 위한 와크프(기증 재산)로 내놓았다. 이는 오스만에서 지리드 경기가 제도화된 최초의 기록 사례 가운데 하나이다.", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["전승에 따른 크르크프나르 레슬링의 시작", "2d93fa65"], "d": ["전승에 따르면 크르크프나르 레슬링 전통은 루멜리아의 정복자 쉴레이만 파샤와 함께 바다를 건넌 40명의 가지(전사)들 사이에서 벌어진 레슬링 시합에서 시작되었다. TDV의 레슬링 항목과 크르크프나르 항목은 이 전승을 전하지만 확정적인 창설 연대는 제시하지 않는다.", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["예니체리 군단의 창설", "f4206dce"], "d": ["찬다를르 카라 할릴과 몰라 뤼스템의 건의에 따라, 펜치크 법에 의해 전쟁 포로 가운데서 뽑은 비무슬림 청년들을 훈련시키는 것으로 시작된 이 제도는 갈리폴리에 설치된 아제미 오자으(신병 양성 부대)를 거쳐 무라드 1세 시대에 제도적 형태를 갖추었다.", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["에디르네 에스키 모스크(울루 모스크)의 착공", "da7a22ac"], "d": ["민간에서 울루자미(자미이 아티크)라는 이름으로도 알려진 에스키자미의 건설은 에미르 쉴레이만 첼레비에 의해 1402~1403년에 시작되었다.", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["부르사 예실 모스크 복합 단지의 착공", "280b8a21"], "d": ["공위 시대 이후 왕위를 다시 통일한 메흐메드 1세는 1414년 이 복합 단지의 공사를 시작했으며, 부르사의 중심부에 할아버지와 아버지의 복합 단지와 구별되도록 자리를 잡았다. 수석 건축가는 하즈 이바즈 파샤였다.", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["부르사 예실 모스크 복합 단지의 완공", "bc82821f"], "d": ["타브리즈 출신 장인들도 기여한 타일 장식과 장식 프로그램으로 알려진 예실(녹색) 모스크 복합 단지는 1419년 12월에 완공되었다. 복합 단지는 모스크, 영묘(예실 튀르베, 녹색 영묘), 마드라사, 이마레트, 목욕장으로 이루어져 있으며, 초기 오스만 건축의 가장 풍부한 사례 가운데 하나이다.", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["데브시르메 제도가 실제로 시행되기 시작하다", "fa835172"], "d": ["이전의 이슬람 국가들에서는 보이지 않던 데브시르메 방식은 처음에는 펜치크 법에 따라 비무슬림 전쟁 포로 청년들을 활용하는 형태로 시작되었다. TDV에 따르면 \"첼레비 메흐메드 시대에 시행되었으나 그의 아들 무라드 2세 시대에 법제화된 것으로 이해된다.\"", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["셰이휠이슬람 직의 창설 — 몰라 페나리의 부르사 무프티 임명", "2a8ee2b9"], "d": ["오랫동안 부르사의 카디를 지낸 학자 몰라 페나리가 1425년 부르사 무프티로 임명된 것은 TDV의 표현으로 \"오스만에서 무프티 직과 셰이휠이슬람 직의 시작\"으로 인정된다. 그러나 TDV는 이것이 16세기에 일미예(울라마) 조직 전체를 대표하던, 완전히 제도화된 셰이휠이슬람 직과 동일한 것은 아니라고 밝힌다.", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["티마르 제도의 정착", "dc267780"], "d": ["문서에 근거한 최초의 티마르 언급은 오르한 베이 시대까지 거슬러 올라가지만, 체계적인 법제화는 무라드 2세 시대에 이루어졌다. 이 시기에 작성된 티마르 이즈말(요약) 대장은 제도의 모든 기본 원칙이 형태를 갖추었음을 보여 주며, 1432년 무렵의 문서들은 법령이 전면적으로 시행되고 있었음을 증명한다.", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["위치 셰레펠리 모스크와 복합 단지의 완공", "cde6993e"], "d": ["무라드 2세가 무슬리훗딘과 셰하벳딘이라는 장인들에게 10년(1437~1447)에 걸쳐 짓게 한 위치 셰레펠리 모스크는 오스만 건축에서 중앙 집중식 평면 모스크의 첫 사례로 인정되며, 고전기 이전 과도기 건축의 전환점 가운데 하나이다.", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["정복자의 법령에 의한 황실 평의회(디완 휘마윤)의 제도화", "e8443e77"], "d": ["디완은 무라드 2세 시대에 에디르네에서 정규 규정에 따라 운영되면서 \"디완 휘마윤\"의 성격을 띠기 시작했다. 진정한 전환은 정복자 술탄 메흐메드의 법령과 함께 이루어졌다. 가장 큰 변혁은 술탄의 디완 주재가 완전히 폐지되고 그 역할이 대재상에게 넘어간 것이었다.", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["정복자 술탄 메흐메드가 오크메이다느를 궁수들에게 할당하다", "342a9fd5"], "d": ["이스탄불 정복 당시 카슴파샤 언덕에 본영을 둔 정복자 술탄 메흐메드는 이곳을 궁수들의 훈련장으로도 사용했다. 도시를 점령한 뒤 그는 이 일대를 궁수들에게 영구히 할당했다. 이 할당은 오크메이다느(활의 광장)가 수백 년간 이어질 오스만 궁술 전통의 중심지가 되는 출발점이었다.", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["부르사가 이란 비단 교역에서 정점에 이르다", "f1324cdf"], "d": ["타브리즈에서 온 대상들은 길란, 아스타라바드, 사리의 비단을 부르사로 실어 날랐고, 이곳에서 제노바, 베네치아, 피렌체 상인들과 유대인 상인들이 경쟁하며 사들였다. 1479년 이란에서 수입한 비단의 가치는 베네치아 금화 150,000닢에 달했으며, 1502년 이 도시에서는 1000대가 넘는 베틀이 가동되고 있었다.", "0f47c417"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["바예지드 2세가 크르크프나르 레슬러들에게 큰 상을 내리다", "d745b882"], "d": ["TDV의 레슬링(귀레시) 항목에 따르면, 바예지드 2세는 1504년 레슬러들에게 3,000쿠루시와 1,500쿠루시의 상을 내렸다. 이는 오스만 궁정이 레슬링을 후원한 기록상의 이른 사례 가운데 하나이다.", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["바예지드 모스크와 복합 단지의 완공", "eb9ab65b"], "d": ["바예지드 2세를 위해 지어진 바예지드 모스크와 복합 단지의 공사는 한 기록 문서에 따르면 906년(1500)에 시작되어 911년 주마다 알울라월 14일(1505년 10월 13일)에 완료되었다. 건축가에 대해서는 논란이 있다. 아이반사라이의 기록을 근거로 오랫동안 건축가 하이렛딘의 작품으로 여겨졌고, 이후에는 건축가 케말렛딘의 것으로 보았으며, 일부에 따르면 두 사람이 함께 작업했다. 그러나 같은 문서는 장인이 술탄 샤의 아들 야쿠브 샤였음을 보여 준다. 이 모스크는 고전기 이전 오스만 건축에서 고전기로의 이행을 보여 주는 중요한 기념물 가운데 하나로 꼽힌다.", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["제국 조선창(테르사네이 아미레)의 이스탄불(카슴파샤/금각만) 이전", "f36e3675"], "d": ["야부즈 술탄 셀림 시대에 갈라타 성벽 서쪽의 만에 건설하기 시작한 새 조선창은 1515년 160개의 선대(괴즈)를 갖추고 완공되었다. 이로써 갈리폴리를 중심으로 하던 조선창 활동이 이스탄불로 옮겨졌다. 이 기관은 이후 바르바로스 하이레딘 파샤 시대에 공식적으로 \"테르사네이 아미레\"라는 이름을 갖게 되었다.", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["셰이흐 함둘라의 서거와 서예 유파의 유산", "f5ed4d09"], "d": ["아마시아 출신의 셰이흐 함둘라는 바예지드 2세의 서예 스승으로서 아클람 싯타(여섯 서체) 유파를 성숙기로 이끌었고, 이슬람 세계 전체를 지배하게 될 오스만 서체 양식의 창시자가 되었다. 1520년에 세상을 떠났을 때 그는 폭넓은 제자 집단을 남겼다.", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["피리 레이스가 『키타브 바흐리예』의 첫 판본을 완성하다", "fd6cc1ff"], "d": ["피리 레이스는 지중해의 해안, 항구, 항해 정보를 집대성한 『키타브 바흐리예』의 첫 번째(산문) 판본을 1521년에 완성했다. 이 첫 판본은 아직 술탄에게 바쳐지지 않은 것으로, 이후 몇 해에 걸쳐 증보될 초고의 성격을 띠었다.", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["피리 레이스가 『키타브 바흐리예』를 증보하여 카누니 술탄 쉴레이만에게 바치다", "d4abf0b7"], "d": ["피리 레이스는 『키타브 바흐리예』를 부분적으로 운문 형식을 취해 증보하여 1526년 카누니 술탄 쉴레이만에게 바쳤다. 이 형태의 저작은 오스만 해운의 가장 포괄적인 항해 안내서로 널리 퍼졌다.", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["마트라크츠 나수흐가 두 이라크 원정의 행로를 『베야느 메나질』에 그리다", "aa012278"], "d": ["카누니 술탄 쉴레이만이 1534년에 나선 첫 번째 이란(두 이라크) 원정에 참가한 마트라크츠 나수흐는 이스탄불에서 타브리즈로, 다시 바그다드로 이어진 군대의 행로에 있는 모든 숙영지를 세밀화 지도 기법으로 그렸다. 이 작업은 『베야느 메나질 세페리 이라카인』이라는 저작에 모아졌으며, 오스만의 멘질나메(역참 여정기) 장르에서 가장 독창적인 사례이다.", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["푸줄리가 바그다드 정복 후 카누니에게 카시다를 바치다", "1ef0653f"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["푸줄리가 마스나비 『레일라와 메즈눈』을 완성하다", "e3ef4085"], "d": ["고전 튀르크 문학에서 가장 아름다운 마스나비(장편 서사시) 가운데 하나로 꼽히는 『레일라와 메즈눈』은 1535년 카누니의 바그다드 원정에 참가한 이스탄불 시인들의 요청에 따라 푸줄리가 지어 완성했다.", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["미마르 시난의 황실 수석 건축가 임명", "7a753f0e"], "d": ["TDV 이슬람 백과사전의 시난 항목에 따르면, 1537년 황실 수석 건축가 아젬 알리시가 죽자, 몰다비아 원정 때 프루트강에 놓은 다리로 주목을 받은 시난이 대재상 뤼트피 파샤의 인정을 받아 이 직책에 올랐다. 이로써 50년 넘게 이어질 시난의 수석 건축가 시대가 시작되었다.", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["셰흐자데 모스크와 복합 단지의 착공", "1a70ddfd"], "d": ["카누니 술탄 쉴레이만은 1543년 페스트 유행으로 잃은 아들 셰흐자데(황자) 메흐메드의 이름으로 복합 단지를 짓도록 명했다. 공사는 1543년 6월에 시작되었으며, 먼저 영묘를 완성한 다음 모스크 건축에 들어갔다. 미마르 시난 자신의 표현에 따르면 이 건축물은 \"나의 도제 시절 작품\"이다.", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["위스퀴다르 이스켈레(미흐리마흐 술탄) 복합 단지의 완공", "3769007f"], "d": ["위스퀴다르 이스켈레(선착장) 광장의 복합 단지 공사는 1540년대 초에 시작되어 1547년에 완료되었다. 미흐리마흐 술탄이 미마르 시난에게 짓게 한 두 대형 모스크 가운데 연대순으로 첫 번째이며, 두 번째(에디르네카프)는 약 20년 뒤에 완공된다.", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["베네치아가 알레포에 영사관을 개설하다", "3aad8b9e"], "d": ["16세기에 유럽인들의 상업 중심은 다마스쿠스에서 알레포로 옮겨 갔다. 이 변화의 구체적 지표로서 베네치아는 1548년 알레포에 영사관을 열었고, 프랑스가 1557년에, 영국이 1586년에 그 뒤를 따랐다. 이 도시는 유럽의 모직물과 은이 인도 향신료, 그리고 세기말에는 이란 비단과 교환되는 주요 시장이 되었다.", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["셰흐자데 모스크의 예배 개시", "2bb3f4b2"], "d": ["약 5년에 걸친 공사 끝에 셰흐자데 모스크는 1548년 8월 예배를 위해 문을 열었다. 두 개의 미너렛과 중앙 돔을 갖춘 평면 구성은 미마르 시난의 이후 대작들을 예고하는 것으로 평가된다. 복합 단지는 모스크, 영묘, 마드라사, 이마레트(빈민 급식소), 타브하네(숙박소), 카라반사라이로 이루어져 있다.", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["크르크체시메 상수도 송수로의 착공", "14124b59"], "d": ["미마르 시난은 카누니의 명에 따라 베오그라드 숲에서 이스탄불로 물을 끌어오는 방안을 조사하여 가능하다고 보고했다. 대규모 수도 시설의 공사는 1554년에 시작되어 1563년 이전에 완료되었다. TDV는 이 구조물을 시난의 \"공학적으로 가장 중요하며 규모 면에서도 가장 큰 작품\"으로 규정한다.", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["이스탄불에 최초의 커피하우스가 문을 열다", "85c12f9f"], "d": ["커피가 오스만의 도시 생활에 들어온 것은 알레포 출신 상인 하켐과 다마스쿠스 출신의 셈스라는 사람이 타흐타칼레에 연 커피하우스들에서 시작되었다. 얼마 지나지 않아 사회 각계각층의 사람들이 모이는 새로운 공공 공간이 생겨났으며, 카누니 시대 말기에는 이스탄불에 커피하우스가 50곳 있었다.", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["에뷔수우드 에펜디가 게딕(장인 독점권) 문제를 법적으로 검토하다", "5d4e2930"], "d": ["장인 업종에서 일정한 수의 사람에게만 인정되는 독점·특권인 \"게딕\" 문제가 카누니 시대에 다시 의제로 떠올랐다. 셰이휠이슬람 에뷔수우드 에펜디는 1555~56년에 이 문제를 깊이 검토하고 이 관행의 정당성을 술탄에게 보고했다.", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["세이디 알리 레이스가 이스탄불에서 『미르아튈 메말리크』를 완성하다", "ee8640e1"], "d": ["세이디 알리 레이스는 바그다드에서 시작된 귀환 여정 내내 써 온 여행기 『미르아튈 메말리크』(여러 나라의 거울)를 1557년 1월 이스탄불에서 완성했다. 이 저작은 한 오스만 뱃사람이 인도양에서 중앙아시아를 거쳐 육로로 고국에 돌아온 과정을 전하는 일차 사료이다.", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["뤼스템 파샤 복합 단지(모스크)의 건립", "02e30725"], "d": ["카누니의 부마이자 대재상인 뤼스템 파샤가 미마르 시난에게 짓게 한 복합 단지는 1555년에서 1561년 사이에 건설되었다. 이 건물은 아래에 아치형 상점들이 있는 높은 기단 위에 세워진 독창적인 건축과 풍부한 이즈니크 타일로 알려져 있다.", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["모스타르 다리의 완공", "e7f434af"], "d": ["네레트바강에 놓인 유명한 모스타르 다리는 1566~67년경 건축가 하이렛딘이 건설했다. 1568년 자의 공식 문서에 다리가 언급된 것은 다리가 이미 완공되었음을 확인해 준다. 이 구조물은 단일 경간의 첨두아치를 지닌 고전 오스만 교량 건축의 가장 널리 알려진 사례 가운데 하나이다.", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["에디르네카프(미흐리마흐 술탄) 모스크의 완공", "f2d21a82"], "d": ["카누니의 딸 미흐리마흐 술탄을 위해 1563년에 확인된 건축 허가 이후 시작된 모스크 공사는 1566년에 완료되었다. 복합 단지의 와크프 문서는 1570~71년에 작성되었다. 이 건물은 이스탄불 성벽에 가장 가까운 미마르 시난의 대작 가운데 하나이다.", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["바키가 카누니 술탄 쉴레이만을 위한 애도시를 쓰다", "7aa6665f"], "d": ["시게트바르에서 카누니 술탄 쉴레이만의 부고가 전해지자, 당대의 \"시인들의 술탄\" 바키는 오스만 문학에서 가장 유명한 애도시 가운데 하나를 지었다.", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["바키가 셀림 2세에게 즉위 축시를 바치다", "6027f034"], "d": ["셀림 2세가 즉위한 직후 바키는 새 술탄에게 \"줄루시예\"(즉위 축시)를 바쳤다. TDV에 따르면 이는 카누니의 죽음에 부쳐 쓴 애도시 바로 뒤의 일이었다.", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["뷔위크체크메제 다리의 완공", "5f49b3c5"], "d": ["카누니 술탄 쉴레이만의 명으로 착공된 이 다리는 술탄이 시게트바르 원정 중에 서거하자 그의 아들 셀림 2세가 1567~68년에 완공하게 했다. 미마르 시난은 뷔위크체크메제 호수가 바다와 만나는 지점에 지은 이 다리에서 홍수로 손상된 구간도 직접 보수했다.", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["셀리미예 모스크(에디르네)의 착공", "07e18c9e"], "d": ["미마르 시난이 \"나의 장인 시절 걸작\"이라고 부른 셀리미예의 공사는 셀림 2세의 이름으로 1568년에 시작되어 6년 만인 1574년에 완료되었다(완공은 이미 연표에 기록되어 있다). 아라스타(부속 상가)의 서쪽 상점들과 초등학교는 셀림 2세가 죽은 뒤 무라드 3세 시대에 다부드 아가가 완성했다.", "a3d4551b"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["크날르자데 알리 첼레비의 서거 — 오스만 도덕철학의 고전 『아흘라키 알라이』의 저자", "dd921873"], "d": ["오스만 도덕철학의 가장 널리 알려진 고전인 『아흘라키 알라이』의 저자 크날르자데 알리 첼레비는 아나톨리아 카자스케르(군법관)로 재직하던 중 1572년 1월 22일에 세상을 떠났다. 이스탄불의 도서관들에는 그의 저작 필사본이 70종 넘게 남아 있다.", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["피얄레 파샤 복합 단지의 건립", "75411278"], "d": ["셀림 2세의 부마 가운데 한 사람인 카푸단 파샤(해군 총사령관) 피얄레 파샤는 1573년 복합 단지의 부지를 사들여 미마르 시난에게 짓게 했다. 복합 단지는 모스크, 마드라사, 테케(수도원), 영묘, 묘지, 초등학교, 샘터, 시장, 목욕장으로 이루어진 광대한 단지로 설계되었다.", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["드리나(소콜루 메흐메드 파샤) 다리의 완공", "1d668c73"], "d": ["대재상 소콜루 메흐메드 파샤의 후원으로 미마르 시난이 지은 이 다리는 비문에 새겨진 연대에 따르면 1577~78년에 완공되었다. 일부 연구자들은 공사가 1571~72년에 시작되었다고 주장한다. 이 다리는 소콜루가 자신이 태어난 비셰그라드에 품은 애착의 상징이다.", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["아자프카프(소콜루 메흐메드 파샤) 모스크의 건립", "f7b57feb"], "d": ["운카파느 다리의 시슈하네 쪽 교각 옆에 있는 이 모스크는 대재상 소콜루 메흐메드 파샤가 미마르 시난에게 짓게 한 것이다. 이 건물은 소콜루의 이름으로 세워진 시난의 모스크 두 곳 가운데 하나이다(다른 하나는 카드르가의 모스크).", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["무라드 3세가 『휘네르나메』 집필 칙령을 내리다", "b125710d"], "d": ["무라드 3세는 1578년 1월 2일 자 칙령으로 세이이드 로크만에게 오스만 가지부터 자신의 시대에 이르는 술탄들의 생애를 다루는 『휘네르나메』를 집필하라고 명했다. 이 저작의 세밀화는 나카시 오스만과 그의 팀이 제작했다.", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["잘 마흐무드 파샤 모스크의 완공", "732f75bc"], "d": ["1574년 잘 마흐무드 파샤와 샤 술탄의 혼인 이후 시작된 복합 단지 공사에서 모스크는 1580년에 완공되었다. 마드라사의 공사는 1582년까지, 샘터는 1590년까지 이어졌다. 이 복합 단지는 에윕 언덕에 자리하며, 대칭을 이루는 두 개의 미너렛을 갖춘 독창적인 평면으로 눈길을 끈다.", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["『휘네르나메』 제2권의 완성", "70a1e741"], "d": ["『휘네르나메』의 제2권은 1588년 1월에 완성되었다. 65점의 세밀화를 담은 이 책은 오스만 역사 서술에서 기록 자료로서 가장 가치 있는 저작 가운데 하나가 되었다. 두 권 모두 나카시 오스만의 공방에서 삽화가 그려졌다.", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["다부드 아가의 황실 수석 건축가 취임", "8cdc7f53"], "d": ["1588년 미마르 시난이 죽은 뒤 짧은 공백기를 거쳐, 다부드 아가는 1592년부터 공식 문서에서 황실 수석 건축가로 언급되기 시작했다. 셀리미예 복합 단지의 일부 부속 요소와 예니 모스크의 초기 공사를 맡은 다부드 아가는 그 시대의 가장 중요한 건축가 가운데 한 사람이다.", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["예니 모스크(에미뇌뉘)의 정초", "d3cddc01"], "d": ["메흐메드 3세의 어머니 사피예 술탄의 발원으로, 지반을 말뚝으로 다진 뒤 석재 블록으로 모스크의 기초를 놓았다. TDV의 두 항목은 이 사건에 서로 다른 날짜를 제시한다(예니자미 복합 단지 항목은 1598년 4월 9일, 다부드 아가 항목은 1597년 8월 23일). 여기서는 건물 자체를 다룬 전용 항목의 날짜를 기준으로 삼았다.", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["다부드 아가의 페스트 사망과 예니 모스크 공사의 중단", "81f2cd04"], "d": ["다부드 아가는 예니 모스크를 지면에서 겨우 1지라(약 한 완척) 높이까지 올렸을 때인 1598년 9월 페스트 유행 중에 죽었고, 달그츠 아흐메드 차우시가 후임 수석 건축가로 임명되었다. TDV는 역사 연대시(타리흐)에 근거한 다른 전승에서는 사망 연도가 1599~1600년으로도 나오며, 정확한 날짜는 확정할 수 없다고 밝힌다.", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["앙카라 모헤어 직물의 유럽 대량 수출", "3f37018d"], "d": ["앙카라에서 짠 소프(모헤어 직물)와 샬리는 이스탄불, 부르사, 다마스쿠스, 알레포 같은 국내 시장은 물론 베네치아, 폴란드, 영국, 프랑스로도 수출되었다. TDV가 드는 사례에 따르면 1599년에 상인 18명이 5,700,000악체 상당의 소프 162짐을 사들여 알레포와 베네치아로 보냈다.", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["메흐메드 3세의 서거로 예니 모스크 공사가 중단되다", "5acef053"], "d": ["발원자 사피예 술탄의 아들 메흐메드 3세가 1603년에 서거한 뒤 사피예 술탄은 구궁(에스키 사라이)으로 보내졌고 예니 모스크의 공사는 중단되었다. 건물은 이 상태로 약 60년 동안 완공되지 못한 채 남아 있었다.", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["카티브 첼레비가 『케슈퓌즈 주눈』을 위해 알레포에서 연구를 시작하다", "094e6870"], "d": ["카티브 첼레비는 훗날 자신의 서지학적 걸작이 될 『케슈퓌즈 주눈』의 자료를 1633년 알레포에서 모으기 시작했다. 20년에 걸친 이 작업 동안 그는 방문한 도시들의 도서관과 서점을 하나하나 샅샅이 뒤졌다.", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["네프이가 풍자시 때문에 처형되다", "5e459c60"], "d": ["풍자시로 이름난 디완 시인 네프이는 『시하미 카자』(운명의 화살)라는 풍자시집 때문에 1635년 무라드 4세의 명으로 처형되었다. 대재상 바이람 파샤가 그를 넘겨주었고, 네프이는 궁전의 장작 창고에서 교살된 뒤 시신이 바다에 던져졌다.", "e3b52153"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["포괄적 나르흐(공정 가격) 대장의 작성", "6c1e231b"], "d": ["나르흐(가격 상한제)의 시행은 오스만에서 매우 오래되었지만, 오늘날까지 전하는 가장 포괄적인 나르흐 대장은 1640년의 것이다. 식품, 의류, 용역, 품질 기준, 위생 조건을 망라한 이 대장은 TDV의 표현에 따르면 \"완전한 시장 규제법처럼 기능했다.\"", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["카티브 첼레비가 『지한뉘마』 집필을 처음 시작하다", "554c6734"], "d": ["카티브 첼레비는 서구의 지리상 발견에 직면하여 오스만 지리 지식의 공백을 메우고자 1648년 『지한뉘마』의 첫 저술에 착수했다. 이 첫 판본은 일부 유럽 국가들에 관한 충분한 자료를 구하지 못해 미완성으로 남았다.", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["일티잠(징세 청부) 제도가 군사 계층의 독점이 되며 성숙하다", "2c587934"], "d": ["일티잠 방식(대금을 받고 조세 징수를 개인에게 청부하는 제도)은 15세기 후반부터 시행되었으나 16세기 초부터 빠르게 확산되고 있었다. TDV에 따르면 이 부문이 완전히 군사 계층 구성원들의 독점에 들어가는 과정은 1650년에 완료되었다. 이로써 일티잠은 티마르 제도를 대체하는 주요 재정 방식이 되었다.", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["카티브 첼레비가 『지한뉘마』를 처음부터 다시 쓰기 시작하다", "e9c68110"], "d": ["첫 저술을 미완으로 남긴 카티브 첼레비는 1654년 말 『지한뉘마』를 처음부터 다시 쓰기 시작했다. 이 두 번째 판본도 완성되지 못했다. 서술이 반(Van)에 이르렀을 때 1657년 저자가 죽으면서 중단되었고, 1732년에야 이브라힘 뮈테페리카가 이 상태 그대로 간행했다.", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["예니 모스크의 완공과 예배 개시", "d6d86c82"], "d": ["60년 넘게 미완성으로 남아 있던 예니 모스크의 공사는 하티제 투르한 발리데 술탄(모후)이 1661년에 임명한 수석 건축가 메레메트치 무스타파 아가의 지휘 아래 완료되었고, 1665년 10월 30일 금요 예배와 함께 문을 열었다.", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["메흐메드 4세가 에디르네의 할례 축전에서 여러 날 지리드 경기를 열다", "3638a5b6"], "d": ["메흐메드 4세는 1675년 에디르네에서 연 황자들의 할례 축전에서 여러 날에 걸친 지리드 시합을 열었다. TDV의 지리드 항목은 이를 오스만 궁정이 지리드 경기를 지원한 가장 화려한 사례 가운데 하나로 특별히 언급한다.", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["하프즈 오스만이 독자적인 서체 양식을 발전시키다", "93081cb3"], "d": ["셰이흐 함둘라의 계보를 잇는 하프즈 오스만은 1679년 아클람 싯타에서 훗날 \"하프즈 오스만 유파\"로 불리게 될 독자적인 새 양식을 발전시켰다. 이 양식은 두 갈래로 나뉘어 오늘날까지 이어지고 있다.", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["하프즈 오스만이 무스타파 2세의 서예 스승으로 임명되다", "d976cda4"], "d": ["당대 최고의 서예가로 인정받던 하프즈 오스만은 1695년 갓 즉위한 무스타파 2세의 서예 스승으로 임명되었다. 그는 평생 약 50명의 서예가를 길러 냈고, 꾸란 25부를 필사했다.", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["으트리의 서거", "62750526"], "d": ["튀르크 음악의 가장 위대한 작곡가 가운데 한 사람인 부후리자데 무스타파 으트리 에펜디는 당대에 가까운 사료에 따르면 1711년에 세상을 떠났다. 그는 세가흐 타크비르와 라스트 나아트 같은 작품으로 모스크 음악과 수도원(테케) 음악의 걸작을 남겼다.", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["네딤이 튤립 시대 시문학의 선구자로 부상하다", "d3c40dbb"], "d": ["1718년에서 1730년에 이르는 튤립 시대 동안 네딤은 표현의 완성도, 간결함의 추구, 재치 있는 문체가 두드러지는 새로운 시 양식을 발전시켰다. 네브셰히르 출신의 다마트 이브라힘 파샤 주변에서 발전한 이 양식은 디완 시에서 토착화 흐름의 가장 큰 대표로 꼽힌다.", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["레브니가 『수르나메이 베흐비』의 삽화를 그리다", "8c127866"], "d": ["궁정 화가 레브니는 1720년 아흐메드 3세의 황자들의 할례 축전을 기록한 『수르나메이 베흐비』에 137점의 세밀화를 그렸다. 그는 이전 작품들과 달리 축전을 아트메이단(히포드롬)에만 가두지 않고 도시 곳곳에서 묘사함으로써 오스만 세밀화 예술에 새로운 이해를 열었다.", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["게딕 제도가 독점에 기초한 장인 체제로 공식 정착하다", "cd0f79a7"], "d": ["TDV에 따르면 게딕권이 \"독점, 특권, 일종의 특허\"라는 의미를 얻게 되는 체계적 전환은 1727년부터 확인된다. 장인 업종에서 일정한 수의 사람에게 영업권을 인정하는 이 체제는, 대부분 와크프 재산인 점포들에서 \"게딕권\"이라는 이름으로 정착했다.", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["파트로나 할릴 반란 중 사다바드의 파괴", "8a30f9a0"], "d": ["1730년 9월 25일에 일어난 파트로나 할릴 반란 중에 사다바드의 정자와 건물 수백 채가 파괴되었다. 튤립 시대의 상징이던 이 복합 시설은 다시는 옛 영화를 되찾지 못했다.", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["파트로나 할릴 반란 중 네딤의 죽음", "06bf909e"], "d": ["파트로나 할릴 반란이 일어났을 때 세크반 알리 파샤 마드라사의 교수였던 네딤은 반란에 뒤이은 며칠 사이에 죽었다. 사망일은 알려져 있지 않다. 다만 그의 유산에 관한 카삼(유산 분배 담당관)의 법정 문서가 1143년 라비 알아키르월 15일(1730년 10월 28일)에 작성되었으므로 그 이전에 죽은 것이다. 사인에 대해서는 여러 설이 전한다. 일부 사료는 그가 공포병(일레티 베히메)이나 술과 아편 때문에 걸린 떨림병으로 죽었다고 쓰며, 뮈스타킴자데는 그가 변란 중에 두려움에 못 이겨 자기 집 지붕에 올라갔다가 떨어져 죽었다고 쓴다. 그의 죽음과 함께 튤립 시대의 문화적 광채도 사실상 끝났다.", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["레브니의 서거", "dd48b56e"], "d": ["오스만 세밀화 예술의 마지막 거장으로 여겨지는 레브니는 1732년에 세상을 떠났다. 그의 작품 대부분은 오늘날 톱카프 궁전 박물관에 소장되어 있다.", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["누루오스마니예 모스크와 복합 단지의 정초", "397ec798"], "d": ["누루오스마니예 복합 단지의 기초는 1749년 1월 19일 마흐무드 1세에 의해 놓였다. 이 건축물은 오스만 건축에서 유럽 바로크 양식을 처음으로 대규모 적용한 사례로 인정되며, 고전적 복합 단지의 구성에서 뚜렷이 벗어난다.", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["누루오스마니예 모스크와 복합 단지의 개관", "15d83731"], "d": ["마흐무드 1세가 착공했으나 완공을 보지 못한 이 복합 단지의 개관식은 그의 동생 오스만 3세 시대인 1755년 12월 5일에 열렸다. 모스크는 개관식을 거행한 오스만 3세를 기려 \"오스만의 빛\"이라는 뜻의 이름을 얻었다.", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["제국 해군 공학교(뮈헨디스하네이 바흐리이 휘마윤)의 개교", "a2fab1cd"], "d": ["오스만 최초의 근대식 해군 공학교인 뮈헨디스하네이 바흐리이 휘마윤은 프랑스 문서고의 자료에 따르면 1775년 4월 29일, 압뒬하미드 1세 시대에 대재상 데르비시 메흐메드 파샤의 재임 중에 문을 열었다.", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["에샴(수익 지분) 제도의 창설", "eabd8ece"], "d": ["퀴치크 카이나르자 조약이 부과한 750만 쿠루시의 배상금 부담에 직면하여 1775년 에샴 제도가 창설되었다. 말리카네(종신 징세 청부)의 한계를 넘기 위해 고안된 이 방식에서는 무카타아(재정 수입원)의 수익이 지분으로 나뉘었고, 말리카네와 달리 여성, 비무슬림, 일반 서민도 지분을 가질 수 있었다.", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["함마미자데 이스마일 데데 에펜디의 출생", "c033f039"], "d": ["튀르크 음악에서 가장 다작한 작곡가 가운데 한 사람인 함마미자데 이스마일 데데 에펜디는 1778년 1월 9일 이스탄불의 셰흐자데바시 구역에서 태어났다. 그는 평생 500곡이 넘는 작품을 작곡했으며, 그 가운데 약 294곡이 오늘날까지 전한다.", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["제국 육군 공학교(뮈헨디스하네이 베리이 휘마윤)의 착공", "4f5d521a"], "d": ["셀림 3세의 니잠 제디드(신질서) 개혁에서 가장 중요한 기관 가운데 하나인 뮈헨디스하네이 베리이 휘마윤의 공사는 1793년 7월 14일에 시작되었다. 건물은 1795년 9월에 완공되어 교육을 시작했다. 이 기관은 유럽의 군사 학교를 본보기로 삼은 오스만의 두 번째 군사 공학교였다.", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["셀림 3세가 일부 장인 길드의 독점을 폐지하기 시작하다", "008f4a7d"], "d": ["TDV의 장인(에스나프) 항목에 따르면, 성립 때부터 아히 조직과 뒤얽혀 있던 오스만의 길드 체제에서는 \"아히 바바\"와 \"셰이흐\" 같은 직책자들이 19세기 초까지 길드의 지도자 역할을 했다. 18세기에 길드들이 독점을 이용해 가격을 나르흐(공정 가격) 이상으로 올려 경제적 압박이 생기자, 셀림 3세는 1794년부터 기초 식품 길드의 독점을 폐지하기 시작했다.", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["데데 에펜디가 무사히비 셰흐리야리로 궁정에 들어가다", "0cb99ac3"], "d": ["셀림 3세 시대에 부셀리크 선법의 작품으로 술탄의 주목을 받은 데데 에펜디는 1812년 마흐무드 2세에 의해 \"무사히비 셰흐리야리\"(술탄의 가까운 연회 동반자) 반열에 들었고, 곧이어 수석 무에진(예배 시각을 알리는 사람)의 자리에 올랐다.", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["오스만 최초의 정규 인구 조사 실시", "4f004c6c"], "d": ["마흐무드 2세는 징병 대상 인구를 파악하기 위해 1830년 말에 처음으로 정규 인구 조사를 실시하게 했다. 남성 인구만 기록되었으며, 아나톨리아와 루멜리아에서 약 750만 명이 파악되었다. 에르주룸과 반 같은 일부 지역에서는 1836년에야 조사를 마칠 수 있었다.", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["제국 페스 공장(페스하네이 아미레)의 설립", "971ab85a"], "d": ["1826년 예니체리 군단이 폐지된 뒤 창설된 아사키리 만수레이 무함마디예 군대의 페스(모자) 수요를 충당하기 위해, 150만 쿠루시의 자본으로 1833년 카드르가의 준디 광장에서 페스 생산이 시작되었다. 시설은 1839년 에윕의 하티제 술탄 궁전으로 옮겨졌으며, 페스하네는 오스만 섬유 산업의 토대를 이루었다.", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["의학교가 메크테비 티비예이 아들리예이 샤하네라는 명칭을 받다", "187d60f3"], "d": ["갈라타사라이의 엔데룬 아가 학교 건물로 옮긴 의학교는 1839년 5월 14일 마흐무드 2세의 방문과 함께 \"메크테비 티비예이 아들리예이 샤하네\"(황실 아들리예 의학교)라는 이름을 받았다. 이로써 이 기관은 군사·행정 학교라는 정체성을 공식적으로 인정받았다.", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["데데 에펜디가 성지 순례 중 미나에서 서거하다", "c3e613a2"], "d": ["핫즈(성지 순례)의 의무를 행하러 간 미나에서 콜레라에 걸린 함마미자데 이스마일 데데 에펜디는 1846년 11월 29일 세상을 떠났다. 1824년에서 1839년 사이에 일곱 편의 서로 다른 메블레비 아인(의식 음악)을 작곡한 이 예술가의 죽음으로 고전 오스만 음악의 한 시대가 막을 내렸다.", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["1850년 상법전의 채택", "8ac085fd"], "d": ["탄지마트 시대 법률 개혁의 틀 안에서 서구 국가들로부터 번역과 차용을 통해 새로운 법률들이 도입되었다. 형법은 1840년에, 상법은 1850년에, 토지법은 1857년에 시행되었다. 상법전은 오스만 상법의 첫 근대적 법전화였다.", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["크림 타타르인과 캅카스 민족들의 오스만 영토로의 대규모 이주 시작", "8832c06d"], "d": ["1859년 셰이흐 샤밀이 러시아군의 포로가 된 뒤, 크림 타타르인들과 함께 캅카스에서 수많은 체르케스인과 노가이인 이주민이 오스만 영토로 이주하기 시작했다. 이 이주 물결은 1877~78년 오스만-러시아 전쟁 이후까지 강도를 달리하며 이어졌다.", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["이주민 위원회(무하지린 위원회)의 설립", "9717e77e"], "d": ["캅카스에서 늘어나는 이주 물결에 대처하기 위해 오스만 정부는 1860년 1월 16일 이주민 위원회를 설립했다. 위원회는 아나톨리아, 발칸, 시리아의 정착 사업을 조정했으며 1875년까지 활동했다.", "404d989d"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["이슬람 교육 협회(제미예티 테드리시예이 이슬라미예)의 설립", "77ad553a"], "d": ["가난한 무슬림 도제들의 교육을 맡기 위해 1864년 3월 30일 이슬람 교육 협회가 설립되었다. 이 민간 결사의 시도는 자선 기관의 전통이 근대 학교 사업으로 전환된 선구적 사례이다. 협회는 9년 뒤 다뤼슈샤파카를 열게 된다.", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["1864년 주(州) 규정에 의한 무흐타르(촌장)와 장로회 제도의 정비", "1a2e8cf2"], "d": ["1864년 주(빌라예트) 규정으로 촌락 행정이 개편되었다. 무슬림과 비무슬림이 함께 사는 마을에서는 각 종교 공동체가 자체 무흐타르와 장로회를 선출하도록 했다. 이로써 장로회는 처음으로 마을·동네 행정에서 공식적인 지위를 얻었다.", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["체르케스인 대추방의 절정", "b2ab1874"], "d": ["러시아가 1858년에서 1878년 사이, 가장 집중적으로는 1861~1864년에 캅카스를 점령하면서 120만~150만 명의 체르케스인이 오스만 영토로 강제 이주당했다. TDV에 따르면 많은 연구자가 이 사건을 \"근대사 최초의 인종 청소 행위\"로 규정한다.", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["1869년 일반 교육 규정(마아리프 우무미예 니잠나메)의 공포", "787f6022"], "d": ["1869년 9월 1일 공포된 일반 교육 규정은 지방과 중앙의 보통 교육을 규율한 최초의 포괄적 문서였다. 이 규정에 의해 대교육 평의회(메즐리시 케비리 마아리프)가 설치되었다. 시비얀 학교(초등 종교 학교)를 순전히 종교 교육 단계에서 벗어나게 하여 읽기·쓰기 교육을 지향하도록 재편하는 작업도 이 조치와 함께 시작되었다.", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["다뤼슈샤파카 학교의 수업 개시", "525c457c"], "d": ["이슬람 교육 협회가 세운 다뤼슈샤파카는 1873년 6월 28일 고아와 가난한 무슬림 아이들을 무료 기숙 교육하기 위해 실제 수업을 시작했다. 입학 연령은 최대 열 살로 정해졌다.", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["1894년 이스탄불 지진", "7ae7f648"], "d": ["1894년 7월 10일 이즈미트만 앞바다에서 발생한 지진은 이스탄불을 심하게 강타했다. 이스탄불 성벽을 비롯해 많은 모스크와 역사적 건축물이 피해를 입었다. TDV의 지진 항목은 이 지진을 1509년, 1719년, 1766년의 지진과 함께 마르마라 지역에서 막대한 인명과 재산 피해를 낸 지진으로 꼽는다.", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["다륄아제제(구빈원)의 개원", "a30baf31"], "d": ["압뒬하미드 2세가 1890년부터 내린 명령에 따라 준비된 다륄아제제는 1896년 2월 2일 대재상 할릴 리파트 파샤가 개원했다. 의지할 곳 없는 아이들, 노인, 빈곤층을 수용한 이 기관은 200병상의 병원, 작업장, 그리고 모스크·교회·시너고그 같은 별도의 예배 시설을 갖춘, 당대 최대의 사회 구호 복합 시설이었다.", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["다륄퓌눈 샤하네가 상설 기관으로 다시 설립되다", "7d6d8fc4"], "d": ["다륄퓌눈(대학)은 앞선 두 차례의 실패한 시도(1863년과 1870년) 이후 1900년 8월 31일 다륄퓌눈 샤하네라는 이름의 상설 기관으로 다시 설립되었다. TDV는 이 날짜를 오늘날 튀르키예 대학 제도의 직접적인 토대로 평가한다.", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["사르바다르가 사브제바르를 점령 — 호라산 최초의 일 칸국 이후 국가", "af997fec"], "d": ["아부 사이드의 죽음(1335년 11월 30일)으로 일 칸국의 중앙 권력이 무너지자, 호라산에서 세리들에게 쌓여 온 반발이 바슈틴에서 폭발했다. 압둘 라자크는 1337년 3월 13일 봉기하여 1337년 9월 9일(738년 사파르월 12일) 사브제바르를 장악했다. \"사르바다르\"(\"교수대에 머리를 건 자\")라는 이름은 패배하면 교수형도 감수하겠다는 뜻을 그들 스스로 표현한 말이다.", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["마라시 사이이드 가문이 아몰을 점령 — 마잔다란의 사이이드 정권", "c0e03266"], "d": ["사이이드 키밤 알딘 마라시는 사르바다르가 호라산에서 연 길을 따라 760년(1359)에 아몰을 장악하고 카스피해 남쪽 연안에 사이이드 국가를 세웠다. 이 왕조는 사리, 바르푸루시와 그 주변으로 퍼졌으며, 티무르의 원정으로 흔들리다가 사파비 왕조의 샤 아바스 1세 시대에 해체되었다.", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["길란에서 카르키야 왕조의 성립 — 카스피해 연안의 마지막 독립 지배자들", "6e5f9db7"], "d": ["알리 키야는 가족과 함께 길란으로 돌아와 773년(1371~72)에 라히잔을 중심으로 카르키야 정권을 세웠다. 이 왕조는 카스피해 남서 연안을 200년 넘게 장악했으며, 1592년 사파비 왕조의 샤 아바스 1세가 이 지역을 병합할 때까지 존속했다.", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["다르푸르의 지배권이 다주족에서 툰주르족으로 넘어가다", "6eb22a2a"], "d": ["TDV 이슬람 백과사전의 다르푸르 항목에 따르면 이 지역에 처음 정착하여 최초의 국가를 세운 것은 다주족이다. 13세기와 14세기 내내 이곳을 지배한 다주족은 상업적 주도권을 툰주르족에게 빼앗겼으며, 15세기에는 특히 중부 지역의 상황이 완전히 툰주르족에게 유리하게 바뀌었다.", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["스페인의 바디스(페뇬 데 벨레스) 암초 요새 탈환", "0dc52728"], "d": ["TDV의 사드 왕조 항목은 스페인인들의 바디스 장악이 마그레브 해운에 큰 타격이었다고 기록한다(1564). 모로코 북부 해안의 이 바위섬 거점은 서지중해의 해적 활동과 오스만-스페인 대립의 발판이었다.", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["엘아라이시(라라시)의 스페인 할양", "7b8f6e27"], "d": ["사드 왕조가 분열한 내전기에 대서양 연안의 엘아라이시 항구는 스페인에 넘겨졌다. TDV의 사드 왕조 항목은 이 시기에 나라가 마라케시(남부)와 페스(북부) 두 에미르국으로 갈라졌고, 왕위 다툼의 당사자들이 외부의 도움을 구했다고 기록한다. 이 항구는 80년 가까이 스페인의 수중에 남게 되며, 1689년 물라이 이스마일이 되찾게 된다.", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["마모라(메흐디야)가 스페인인의 손에 넘어가다", "c8fd494e"], "d": ["세부강 하구의 마모라(마무라/메흐디야) 항구는 1614년 스페인인들에게 점령되었고 산 미겔 데 울트라마르라는 이름으로 요새화되었다. TDV의 물라이 이스마일 항목은 이 항구가 1092년(1681)에 기습으로 스페인인의 손에서 탈환되었다고 기록한다. 즉 스페인의 지배는 67년간 이어졌다.", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["사드 왕조의 종말 — 모로코에서 알라위(필랄리) 시대의 시작", "b1afa579"], "d": ["TDV 이슬람 백과사전은 사드 왕조를 \"모로코를 통치한 이슬람 왕조(1511~1659)\"로 정의한다. 1549년 와타스 왕조의 지배를 끝내고 모로코 전체를 통일했으며, 1578년 와디 알마카진에서 포르투갈군을 섬멸했고, 어느 시기에도 오스만에 예속되지 않은 이 왕조는 오랜 왕위 다툼 끝에 1659년에 종말을 맞았다. 그 자리는 타필랄트에서 온 알라위(필랄리) 샤리프들이 이어받았다. 물라이 라시드는 1666년 페스시에 입성하여 새 왕조를 공고히 했고, 그의 동생 물라이 이스마일은 대서양 연안의 유럽 거점들을 소탕했다.", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["스페인의 알우세마스(엘후세이마) 제도 점령", "954ca998"], "d": ["지중해 연안의 알우세마스 제도는 1673년 스페인 함대에 점령되었다. 바디스, 세우타와 더불어 스페인이 모로코 북부 해안에서 확보하여 오늘날까지 보유하고 있는 거점 가운데 하나이다. 같은 해에 물라이 이스마일의 형 물라이 라시드는 마라케시에 입성하여 주민의 충성 서약을 받았고, 필랄리 가문의 지배가 남부에서 공고해졌다. 해안에서의 이 상실은 내부 통합이 대외 전선에는 아직 반영되지 않았음을 보여 준다.", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["물라이 이스마일이 스페인인들로부터 엘아라이시를 되찾다", "a54bc6ee"], "d": ["TDV의 물라이 이스마일 항목은 분명하게 쓴다. \"1100년(1689)에 아라이시를 스페인인들에게서 되찾으며 대포 200문을 노획했고, 2년 뒤에는 아실라도 되찾았다.\" 이는 필랄리 술탄의 해안 소탕 연쇄의 한 고리이다. 탕헤르는 1678년 영국인에게서, 마모라는 1681년에, 엘아라이시는 1689년에, 아실라는 1691년에 되찾았다. 80년 전 사드 왕조의 내전 중에 포기된 항구는 이렇게 모로코로 돌아왔다.", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["다르푸르 술탄국의 건국 — 케이라 왕조와 술레이만 솔롱", "0fc1c112"], "d": ["TDV에 따르면 다르푸르 술탄국의 건국은 17세기 말 부무 알카시르가 이 지역을 침략한 뒤에 닥친 혼란 이후에 해당한다. 푸르족은 술레이만 솔롱을 수장으로 하는 키라(케이라) 가문의 지도 아래 다주족과 툰주르족의 손에서 지배권을 빼앗고 견고한 통치 체제를 세웠다. 술레이만 솔롱은 1695년부터 1715년까지 통치했다. 다르푸르의 술탄들은 이후 수 세기 동안 바브알리(오스만 정부)와 서신을 주고받았으며, 압뒬메지드와 압뒬아지즈는 그들의 통치권을 승인했다.", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["프랑스 제1공화국 선포 — 왕정의 종말", "d53d49b0"], "d": ["국민 공회의 첫 회기에서 왕정이 폐지되고 다음 날 제1공화국이 선포되었으며, 새 달력의 원년은 이날부터 시작되었다. 오스만의 입장에서 상대는 바뀌지 않았지만 상대의 성격은 바뀌었다. 셀림 3세의 니잠 제디드 시대에 프랑스는 이제 왕조가 아니라 하나의 정권이었고, 1798년 이집트에 상륙하게 될 것도 바로 그 정권의 군대였다.", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["대(大)카빌리아의 함락 — 랄라 파트마 은수메르의 생포", "0f61ff08"], "d": ["TDV의 알제리 항목은 산악 지대인 카빌리아(빌라드 알카바일) 지역이 1853년, 1854년, 1857년의 원정 끝에 점령됨으로써 프랑스의 알제리 점령 작업이 대부분 완료되었다고 기록한다. 1857년의 원정은 티지우주-아크부 전선을 무너뜨렸고, 저항의 상징 랄라 파트마 은수메르는 포로가 되었다. 1847년 아미르 압드 알카디르의 항복 이후 남아 있던 마지막 대규모 저항 거점이 이렇게 꺼졌다.", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["프랑스의 인살라(티디켈트) 점령", "1e28d1d0"], "d": ["사하라 한가운데 있는 티디켈트 오아시스군의 중심지 인살라는 1899년 12월 29일 프랑스군에 점령되었다. 이는 알제리 해안에서 남쪽으로 내려온 프랑스의 팽창이 사막으로 넘쳐 들어간 첫 번째 큰 걸음이다. 2년 안에 투아트와 구라라도 같은 길을 걷게 된다.", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["투아트·구라라·티디켈트 오아시스의 프랑스 병합", "d412838b"], "d": ["알제리 남서부의 투아트, 구라라, 티디켈트 오아시스 지대는 1901년 2월 21일 공식적으로 프랑스에 편입되었다. 모로코 술탄이 명목상 권리를 주장하던 이 대상로의 결절점은 아드라르, 티미문, 레간, 베니압베스를 포함하여 이로써 알제리에 합쳐졌다. 이것이 모로코와 프랑스령 알제리 사이 국경 분쟁의 시작이다.", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["베샤르(콜롱베샤르)에 프랑스 초소 설치", "4d44d252"], "d": ["모로코 국경의 베샤르 오아시스는 1903년 11월 11일 프랑스군에 점령되어 콜롱베샤르라는 이름의 전진 초소가 되었다. 투아트 지대 병합 2년 뒤에 이루어진 이 조치는 알제리에서 모로코를 향한 프랑스 진출의 마지막 고리들 가운데 하나로, 1912년 모로코가 보호령이 되는 길을 열었다.", "bd1a7ae2"]},
"OLAYLAR_EK16:1283-01-01:0":{"b": ["모스크바 공국의 성립 — 다닐 1세", "49549309"], "d": ["알렉산드르 넵스키의 막내아들 다닐이 모스크바를 독립 공국으로 다스리기 시작했다. 당시 모스크바는 블라디미르-수즈달 땅의 작고 보잘것없는 중심지였으며, 러시아 사학은 이 연대를 이후 부상의 출발점으로 간주한다.", "10cf92d1"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["카레시 베이국과 하미드 베이국의 건국", "3905da93"], "d": ["TDV의 카레시오울라르(카레시 가문) 항목에 따르면, 카레시 베이는 아버지 칼렘 베이의 죽음과 함께 해체된 셀주크 변경 조직에서 독립을 선언하고 696년(1296~97)부터 발르케시르를 중심지로 삼았으며, 얼마 지나지 않아 에르데크, 비가, 에드레미트, 베르가마를 포함한 미시아 전체를 비잔티움에게서 빼앗았다. 같은 해(1297)에 하미드 베이는 울루보를루를 정부 소재지로 삼아 하미드 베이국을 세웠으며, 해체된 셀주크 변경 지대에서 으스파르타, 부르두르, 에이르디르, 얄바치가 베이국의 첫 영토에 편입되었다. 두 베이국은 모두 서아나톨리아에서 일어난 같은 붕괴, 즉 셀주크 중앙 권력의 해체가 낳은 산물이다.", "7d297343"]},
"OLAYLAR_EK16:1301-01-01:0":{"b": ["모스크바 공 다닐이 콜롬나와 세르푸호프를 모스크바에 합병하다", "6d82dccd"], "d": ["다닐은 랴잔 공국에게서 콜롬나(포로가 된 랴잔 공이 풀려나기 위해 요새를 넘겨주었다)와 세르푸호프를 차지했다. 모스크바는 오카강에 이르렀으며, 이는 모스크바 공국의 첫 번째 영토 확장이었다.", "f6b7a96c"]},
"OLAYLAR_EK16:1304-01-01:0":{"b": ["모자이스크를 스몰렌스크 공국에게서 빼앗아 모스크바에 합병하다", "462055a0"], "d": ["모스크바 공국은 모스크바강 상류 유역의 모자이스크를 스몰렌스크에게서 빼앗아 서쪽 국경을 리투아니아에 가깝게 만들었다.", "3002aa5d"]},
"OLAYLAR_EK16:1307-01-01:0":{"b": ["폴로츠크 공국이 리투아니아 대공국으로 넘어가다", "04a26a6f"], "d": ["폴로츠크, 비테프스크와 그 주변은 1307년까지 루스 공 왕가 안에 남아 있었다. 게디미나스 이전 리투아니아의 동방 확장은 이 이행으로 뚜렷해졌다(지도 자료의 항목 연대는 1307년이며, 비테프스크가 실제로 넘어간 시점인 1320년경에는 논란이 있다).", "52bf8042"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["아이든 베이국의 건국 — 이즈미르, 아야술루크, 티레의 점령", "69a021ae"], "d": ["TDV의 아이든 가문 항목에 따르면, 무바리즈 알딘 가지 메흐메드 베이는 게르미얀 가문의 변경 영주 사사 베이에게서 이 지역을 빼앗아 1308년 아이든 지방의 지배자가 되었다. 그는 이즈미르의 무슬림 구역을 아야술루크(셀추크), 티레, 보데미아와 함께 정복했다. 아야술루크를 함대 기지로 삼고 획득한 땅을 다섯 아들에게 나누어 주었다. 이 베이국은 이후 수십 년 동안, 특히 아들 우무르 베이 시대에 에게해 해운의 결정적 세력이 된다.", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["아나톨리아 셀주크 국가의 사실상 종말 — 일 칸국의 직접 통치", "00f85ecb"], "d": ["TDV의 메수드 2세 항목에 따르면, 오랜 병환 끝에 708년(1308) 카이세리에서 죽은 기야스 알딘 메수드 2세는 일반적으로 받아들여지는 견해에 따르면 아나톨리아 셀주크 국가의 마지막 통치자이다. 그의 사후에 왕위에 올려진 후보들은 내부 당국의 인정도 일 칸국의 인정도 받지 못했다. 이 지역은 이미 메수드의 재위 내내 사실상 일 칸국 관리들이 다스리고 있었으며, 그의 죽음과 함께 이 직접 통치는 코니아, 니데, 악사라이 같은 중심지에서 형식적인 외피마저 벗게 되었다.", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["잔다르 베이국의 카스타모누-찬크르-바르튼-사프란볼루 확장", "64e39ad0"], "d": ["TDV의 잔다르 가문 항목에 따르면, 이 베이국은 일 칸국의 통치자 가이하투에게서 에플라니와 그 주변을 이크타(분봉지)로 받은 셈세딘 야만 잔다르가 14세기 초 카스타모누-시노프 일대에서 세웠으며, 사료가 부족하여 정확한 건국 연대는 알려져 있지 않다. 잔다르의 후계자 쉴레이만 베이는 초반 베이국을 대신한 통치자로 언급된다. 즉 카스타모누와 찬크르 일대는 초반 가문에게서, 바르튼-사프란볼루-에플라니 선은 일 칸국의 직접 통치에서 잔다르 가문으로 넘어간 것이다.", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["성 요한(구호) 기사단의 로도스와 도데카니사 제도 정복", "67885b4b"], "d": ["TDV의 로도스 항목은 섬이 1309년 성 요한 기사단(구호 기사단/이스비타리야)의 손에 넘어갔다고 기록한다. 구호 기사단에 관한 표준적 역사(J. Riley-Smith, The Knights Hospitaller 참조)는 포위가 1306년 여름에 시작되었고, 비잔티움의 증원을 받아 오래 저항한 로도스시는 기사단장 풀크 드 빌라레의 병력에 의해 1310년 8월 15일에야 함락되었다고 상세히 서술한다. 섬은 이때부터 1522년 오스만의 정복까지 기사단의 본거지가 되었으며, 주변의 도데카니사 제도도 같은 과정에서 비잔티움으로부터 구호 기사단의 지배로 넘어갔다.", "c1422e2c"]},
"OLAYLAR_EK16:1313-01-01:0":{"b": ["리보니아 기사단이 리투아니아로부터 뒤나부르크 요새를 되찾다", "92119516"], "d": ["리투아니아인들은 1281년 무렵 예르시카를 차지하고 이를 기사단의 뒤나부르크 요새와 맞바꾸었다. 이 요새는 1313년 다시 리보니아 기사들의 손에 들어왔고, 기사단의 지방 지휘관구(콤투어) 중심지로 남았다.", "0cdd86e0"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["성 요한 기사단의 코스(이스탄쾨이) 점령", "445666f7"], "d": ["TDV의 이스탄쾨이(코스) 항목에 따르면, 성 요한 기사단은 로도스에 정착한 뒤 코스도 점령하고(1315) 새 요새들을 지었다. 이로써 섬은 1523년까지 이어진 기사단의 지배에 들어갔다. 1310년 로도스시가 함락된 이후 코스가 어느 통치 아래 있었는지는 TDV에 상세히 서술되어 있지 않다.", "145d1bad"]},
"OLAYLAR_EK16:1325-01-01:0":{"b": ["수도대주교좌의 모스크바 이전", "d20099f8"], "d": ["러시아 정교회의 수장인 수도대주교 표트르는 종교의 중심지를 모스크바로 옮겼다. 이는 모스크바가 정치적 중심지일 뿐 아니라 종교적 중심지로도 부상하는 출발점이었고, 공국의 정통성을 강화했다.", "4e31c42f"]},
"OLAYLAR_EK16:1330-01-01:0":{"b": ["리보니아 기사단이 리가시의 종주가 되다", "21453047"], "d": ["리투아니아 대공 비테니스와 게디미나스의 지원을 받아 기사단에 맞서 싸우던 리가 대주교구와 리가시는 1330년에 패배했고, 리보니아 기사단이 도시의 종주가 되었다. 1452년의 살라스필스 조약으로 리가는 기사단과 대주교의 공동 종주권 아래 들어갔다.", "28788282"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["에레트나 베이국의 건국 — 일 칸국 이후의 중부 아나톨리아", "a67bacd9"], "d": ["TDV의 에레트나 가문 항목에 따르면, 위구르계 일 칸국 관리였던 알라웃딘 에레트나는 1335년 일 칸국의 통치자 아부 사이드 바하두르 칸이 죽은 뒤 아나톨리아의 일 칸국 총독직을 사실상의 독립 정권으로 바꾸었다. 처음에는 맘루크 술탄의 대리인을 자처했으나 1340년 후트바에서 맘루크의 이름을 삭제하고 1341년 무렵 완전한 독립을 선언했다. 처음에는 시바스를, 나중에는 카이세리를 중심으로 한 이 베이국은 그가 죽을 때(1352)까지 아마시아, 토카트, 초룸, 니데, 악사라이, 에르진잔을 아우르는 광대한 중부 아나톨리아 지배권을 확립했으며, 1381년 카디 부르하네딘에 의해 종말을 맞았다.", "04978a80"]},
"OLAYLAR_EK16:1335-05-01:0":{"b": ["합스부르크가의 카르니올라·카린티아(류블랴나) 장악", "039918d3"], "d": ["1335년 4월 2일 카린티아 공작이자 티롤 백작인 하인리히 6세가 티롤성에서 후계자 없이 죽자, 1330년 11월 23일 바이에른의 루트비히와 비밀리에 맺은 합의에 따라 합스부르크가의 형제 알브레히트 2세와 오토 4세는 황제의 봉토 수여 문서로 카린티아 공국과 그에 부속된 카르니올라(오늘날의 류블랴나가 포함된 지역)를 받았다. 반면 티롤은 하인리히의 딸을 통해 따로 남았다. 이는 합스부르크가의 알프스 지역 확장의 첫 번째 큰 걸음 가운데 하나였으며, 카르니올라는 (중단이 있었으나) 1918년까지 합스부르크/오스트리아의 수중에 남게 된다.", "4dbed85a"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["잘라이르 국가의 건국 — 일 칸국 이후의 아제르바이잔", "a13ada90"], "d": ["TDV의 잘라이르 왕조 항목에 따르면, 일 칸국의 아미르 노얀의 손자 하산 부주르그는 일 칸국 통치자 아부 사이드 바하두르 칸의 죽음과 함께 터진 왕위 다툼을 틈타 1340년 타브리즈를 중심으로 하는 독립 국가를 세웠다. 이로써 잘라이르 왕조는 아제르바이잔과 그 주변에서 일 칸국 이후의 공백을 메운 최초의 대왕조가 되었다. 후계자 우와이스 시대(1356~1374)에 영토는 모술과 디야르베키르까지 확장된다.", "224cbb81"]},
"OLAYLAR_EK16:1341-01-01:0":{"b": ["니즈니노브고로드-수즈달 대공국의 성립 — 칸이 콘스탄틴 바실리예비치에게 야를리크를 내리다", "c69f5198"], "d": ["금장 칸국의 칸 우즈베크(항목 표기상 우즈베크/자니베크)는 수즈달의 공 콘스탄틴 바실리예비치에게 니즈니노브고로드-고로데츠 공국을 주었다. 이 공국은 모스크바의 경쟁자가 되었으며, 1392년 바실리 1세에 의해 모스크바에 합병되었다.", "4b281b04"]},
"OLAYLAR_EK16:1346-01-01:0":{"b": ["덴마크가 에스토니아 북부(레발과 나르바)를 리보니아 기사단에 매각하다", "6861ba55"], "d": ["덴마크 왕국은 에스토니아 북부의 영토를 레발과 나르바와 함께 리보니아 기사단에 팔았다. 이 지역은 리보니아 전쟁 때까지 기사단의 수중에 남았다.", "0723514c"]},
"OLAYLAR_EK16:1348-01-01:0":{"b": ["볼로토보 조약 — 노브고로드가 프스코프의 독립을 인정하다", "08eca44d"], "d": ["노브고로드는 프스코프를 '아우'로 인정했다. 프스코프는 자체의 베체(민회)와 포사드니크(시장)를 둔 독립 도시 공화국으로서 1510년 모스크바에 합병될 때까지 존속했다.", "12f9ce2f"]},
"OLAYLAR_EK16:1392-01-01:0":{"b": ["바실리 1세가 니즈니노브고로드-수즈달 공국을 모스크바에 합병하다", "5ecf441b"], "d": ["바실리 1세는 토크타미시 칸에게서 받은 야를리크로 니즈니노브고로드, 고로데츠, 수즈달을 모스크바에 귀속시켰다. 이로써 모스크바가 볼가강과 오카강 유역으로 진출하기 시작했다.", "ac83ac55"]},
"OLAYLAR_EK16:1404-01-01:0":{"b": ["비타우타스의 스몰렌스크 점령 — 스몰렌스크 공국의 리투아니아 합병", "1a68300c"], "d": ["비타우타스는 스몰렌스크를 장악했다. 도시는 1514년 모스크바에 넘어갈 때까지 리투아니아 대공국에 남았다.", "3ed5ce14"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["바그다드가 흑양 왕조의 수중에 넘어가다 — 잘라이르 술탄 아흐마드의 패배", "a42ebe92"], "d": ["TDV의 흑양 왕조 항목에 따르면, 카라 유수프는 813년 라비 알아키르월 28일(1410년 8월 30일) 타브리즈 인근에서 잘라이르의 술탄 아흐마드에게 큰 패배를 안겼다. 술탄 아흐마드가 죽은 뒤 814년(1411)에 그는 아들 피르 부다크를 타브리즈에서 술탄으로 선포했고, 같은 해 맏아들 샤 메흐메드가 바그다드를 정복했다. 이로써 100년 가까이 잘라이르의 수도였던 바그다드는 주변의 바스라-모술-키르쿠크 선과 함께 흑양 왕조의 지배하에 들어갔다.", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["에르진잔과 케마흐가 백양 왕조로 넘어가다 — 카라윌뤼크 오스만 베이", "122460d4"], "d": ["카라 유수프가 죽은 뒤 에르진잔 주민의 요청으로 무타하르텐의 손자 야르 알리가 도시의 총독이 되어 있었다. 그의 시대에 백양 왕조의 베이 카라윌뤼크 오스만은 에르진잔을 점령하여 백양 왕조의 영토에 편입했다. 이때 이후 에르진잔은 때로는 백양 왕조와 흑양 왕조 사이에서, 때로는 백양 왕조 왕자들 사이에서 주인이 바뀌는 곳이 되었다.", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["카잔 칸국의 건국 — 울루그 무함마드 칸의 금장 칸국 이탈", "335a7408"], "d": ["TDV의 카잔 칸국 항목에 따르면, 금장 칸국의 수도 사라이에서 왕좌를 잃은 울루그 무함마드 칸은 가족과 약 3000명의 병사를 이끌고 먼저 벨레프로 물러나 1437~1438년에 러시아의 대공(크냐지) 바실리 2세와 싸웠고, 그 뒤 카잔시에 정착했다. 그는 현지 주민의 지지를 받아 이곳에 새 칸국의 기초를 놓았다. TDV는 건국 과정이 1437년에서 1445년 사이에 완료되었고 칸국은 1445년부터 완전한 독립 지위를 얻었다고 밝힌다. 지도는 이 과정의 출발점, 즉 울루그 무함마드가 카잔에 정착한 1438년을 기준으로 삼는다.", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["크림 칸국의 건국 — 하즈 기라이의 금장 칸국으로부터의 독립", "5728223e"], "d": ["TDV의 크림 항목에 따르면, 크림 칸국은 14세기 후반 금장 칸국이 왕위 다툼으로 분열한 결과로 등장했다. 칸국의 실질적 창건자인 하즈 기라이가 주조한 가장 오래된 화폐에는 845년(1441~42)이라는 연대가 새겨져 있으며, 이것이 칸국의 공식 건국 연대로 간주된다. 같은 해에 하즈 기라이는 모스크바와 우호 관계를 맺어 크림에서의 입지를 굳혔고, 시린 부족을 필두로 한 현지 베이 가문들이 그의 편에 가담했다.", "dbd052d0"]},
"OLAYLAR_EK16:1450-01-01:0":{"b": ["자한 샤가 에르진잔을 점령 — 흑양 왕조의 지배", "0c928cc4"], "d": ["흑양 왕조의 통치자 자한 샤는 854년(1450) 에르진잔에 군대를 보내 백양 왕조로부터 도시를 빼앗았다. 이 상실은 백양 왕조의 베이 자한기르 미르자와 그의 동생 하산 베이(우준 하산) 사이가 틀어지는 계기가 되었다.", "203c5c2e"]},
"OLAYLAR_EK16:1452-01-01:0":{"b": ["흑양 왕조의 자한 샤가 티무르 왕조의 이란(레이, 이스파한, 파르스, 케르만)을 장악하다", "c6fbb3f5"], "d": ["TDV의 흑양 왕조 항목에 따르면, 흑양 왕조의 통치자 자한 샤는 티무르 왕자들 사이의 왕위 다툼을 틈타 856~857년(1452~1453)에 레이, 이스파한, 파르스, 케르만 주를 자신의 통치하에 두었다. 이는 1447년 샤루흐 미르자가 죽은 뒤 시작되어 술타니야-카즈빈 병합으로 문을 연 확장 과정의 정점이다. 이로써 이란 중남부의 티무르 영토는 흑양 왕조로 넘어갔다. 자한 샤의 지배는 1466년 아제르바이잔, 아란, 페르시아 이라크, 아랍 이라크, 파르스, 케르만, 동아나톨리아를 아우르는 범위에 이르게 된다.", "3f6a6c37"]},
"OLAYLAR_EK16:1452-10-23:0":{"b": ["영국의 보르도 탈환 — 존 탤벗의 마지막 가스코뉴 원정", "01b2b7be"], "d": ["1451년 프랑스에 빼앗긴 보르도는 주민들이 프랑스 수비대에 맞서 봉기하여 성문을 열면서, 1452년 10월 22일에서 23일로 넘어가는 밤에 노장 존 탤벗이 이끄는 영국군에게 넘어갔다. 이는 백년 전쟁에서 영국이 가스코뉴에서 거둔 마지막이자 단명한 승리였다. 보르도는 1년 뒤 카스티용 전투 이후 영구히 프랑스로 돌아가게 된다.", "f6945d27"]},
"OLAYLAR_EK16:1453-10-19:0":{"b": ["보르도의 프랑스 영구 귀환 — 백년 전쟁의 사실상 종결", "b0a86f6c"], "d": ["1453년 7월 17일 카스티용 전투에서 존 탤벗이 전사하고 그의 군대가 괴멸하자 가스코뉴에서 영국의 저항은 무너졌다. 포위된 보르도는 1453년 10월 19일 프랑스군에게 항복했다. 이 항복은 116년간 이어진 백년 전쟁이 사실상 끝난 순간으로 간주되며(공식 평화 조약은 끝내 체결되지 않았다), 유럽 대륙에서 영국의 지배 영역을 칼레로 좁혔다.", "1c632d46"]},
"OLAYLAR_EK16:1457-01-01:0":{"b": ["우준 하산의 에르진잔 탈환 — 다시 백양 왕조의 지배", "550d010a"], "d": ["우준 하산은 흑양 왕조를 격파하고 에르진잔을 다시 백양 왕조의 지배하에 두었다. 도시는 1473년 오틀루크벨리 전투 이후에도 백양 왕조의 국경 안에 남았다.", "d778fa85"]},
"OLAYLAR_EK16:1466-10-19:0":{"b": ["제2차 토룬 조약 — 단치히(그단스크)와 서프로이센이 폴란드에 귀속", "e2152dae"], "d": ["1454년 프로이센 연맹이 독일 기사단(튜턴 기사단)의 통치에 맞서 일으킨 봉기로 시작된 13년 전쟁을 끝낸 제2차 토룬(Thorn) 조약은 1466년 10월 19일에 체결되었다. 기사단은 단치히(그단스크)를 포함한 동포메른, 엘빙(엘블롱크)을 포함한 비스와강 하구, 쿨름 지방을 폴란드 왕국에 넘겼으며, 이 땅은 '왕령 프로이센'이라 불리게 되었다. 동프로이센은 1525년까지 기사단에 남게 된다.", "831685a9"]},
"OLAYLAR_EK16:1474-01-01:0":{"b": ["이반 3세가 로스토프 공국의 남은 절반을 매입하다", "5203244f"], "d": ["로스토프 공들이 가지고 있던 절반이 모스크바에 양도되었다. 1332년 모스크바에 넘어간 나머지 절반과 합쳐 로스토프 땅은 완전히 모스크바에 귀속되었다.", "ab0eeae6"]},
"OLAYLAR_EK16:1485-09-12:0":{"b": ["트베리 대공국의 모스크바 합병 — 이반 3세가 도시를 차지하다", "fa3f924e"], "d": ["모스크바군이 포위하자 트베리의 마지막 대공 미하일 보리소비치는 리투아니아로 달아났고, 트베리는 이반 3세에게 항복했다. 이로써 모스크바의 가장 강력한 경쟁자가 사라졌다.", "b9942526"]},
"OLAYLAR_EK16:1489-02-26:0":{"b": ["카테리나 코르나로 여왕이 키프로스를 베네치아에 양도하다 — 십자군 국가의 종말", "e24d3f3a"], "d": ["1473년 남편 자크 2세 국왕이 죽은 뒤 섭정 왕비로서 키프로스를 다스리던 베네치아 출신의 카테리나 코르나로는 후계자가 없었기 때문에 베네치아 정부의 압력을 받아 1489년 2월 26일 퇴위하고 섬에 대한 통치권을 도제와 베네치아 공화국에 넘겼다. 그 대가로 그녀는 여왕 칭호를 유지했고 테라페르마(베네치아 본토 영토)의 아솔로 백작령을 받았다. 이 양도로 1192년부터 이어진 뤼지냥 왕조의 지배와 마지막 십자군 국가가 끝났으며, 섬은 1570~71년 오스만의 정복까지 베네치아의 통치 아래 남았다.", "7f769951"]},
"OLAYLAR_EK16:1492-01-02:0":{"b": ["그라나다의 함락 — 이베리아반도 마지막 이슬람 국가의 종말", "46e5201b"], "d": ["10년에 걸친 단계적 포위와 내분으로 약해진 그라나다 나스르 에미르국의 마지막 통치자 아부 압달라(보압딜)는 1491년 11월에 체결된 관대한 항복 조건(그라나다 항복 협정)에 따라 1492년 1월 2일 도시의 열쇠를 가톨릭 부부 왕 페르난도와 이사벨에게 넘겼다. 보압딜이 알람브라를 떠나면서 이베리아반도의 마지막 이슬람 국가는 막을 내렸고 레콩키스타가 완성되었다. 같은 해에 유대인 추방(3월)과 크리스토퍼 콜럼버스의 항해(8월)가 뒤따르게 된다.", "5dc28ef8"]},
"OLAYLAR_EK16:1500-07-14:0":{"b": ["베드로샤 전투 — 모스크바가 리투아니아군을 격파, 브랸스크와 세베르스크 땅이 모스크바에 남다", "d3f61400"], "d": ["1500~1503년 모스크바-리투아니아 전쟁에서 다닐 셰냐가 지휘한 모스크바군은 도로고부시 근처의 베드로샤강에서 헤트만 콘스탄티 오스트로그스키의 군대를 격파하고 헤트만을 포로로 잡았다. 같은 해 봄에 점령한 브랸스크와 세베르스크 지역의 도시들은 모스크바의 수중에 남았다. 전쟁이 끝났을 때 리투아니아 영토의 약 3분의 1이 모스크바로 넘어가 있었다.", "e5879803"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["샤이바니 칸이 티무르 왕조로부터 헤라트와 호라산을 빼앗다", "a81d8575"], "d": ["TDV의 샤이바니 칸 항목에 따르면, 우즈베크의 통치자 샤이바니 칸은 1503~1505년에 안디잔, 페르가나, 히사르, 쿤두즈, 발흐를 점령한 뒤 913년(1507)에 티무르 왕조의 수도 헤라트도 점령했다. 이란 백과사전(Encyclopaedia Iranica)의 호라산 항목은 이 정복의 정확한 날짜를 제시한다. 도시는 913년 무하람월 8일(1507년 5월 20일)에 함락되었고, 일주일 뒤인 무하람월 15일(5월 27일)에 후트바가 샤이바니 칸의 이름으로 낭독되어 정복이 공식화되었다. 마슈하드를 포함한 호라산 전체가 같은 해에 티무르 왕조에서 샤이바니 왕조로 넘어갔다. 이는 티무르 왕조가 트란스옥시아나에 이어 이란의 마지막 대거점마저 잃었음을 뜻했다.", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["오랑이 스페인에 함락되다 — 시스네로스 추기경의 북아프리카 원정", "86ed8ac1"], "d": ["서지중해 해상로를 장악하고 틀렘센의 항구였던 와흐란(오랑)은 1492년 그라나다에서 피신한 안달루시아의 무슬림과 유대인이 몸을 의탁하면서 성장했다. 16세기 초 마그레브 해안의 항구 도시들을 하나씩 점령해 가던 카스티야 왕국은 1509년 5월 17일 오랑을 점령했다. 주민 대부분이 학살되고 나머지는 포로가 되었으며, 도시에는 무슬림과 유대인 인구가 남지 않았다. 스페인인들은 성벽과 요새를 확장했고, 오랑은 1708년까지 스페인의 수중에 있었다.", "be7b3b1b"]},
"OLAYLAR_EK16:1514-08-01:0":{"b": ["스몰렌스크가 모스크바에 항복하다 — 바실리 3세의 입성", "46c61446"], "d": ["1512~1522년 모스크바-리투아니아 전쟁의 세 번째 포위에서 리투아니아 수비대는 7월 31일 항복했다. 모스크바군은 8월 1일 의식을 치르며 도시에 입성했고, 주민들은 바실리 3세에게 충성을 서약했다. 스몰렌스크는 서방에서 바실리가 거둔 가장 큰 성과이며, 몇 주 뒤 오르샤에서 당한 패배도 이 도시를 되찾게 하지는 못했다.", "803c9255"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["저지대 국가의 스페인 왕관 귀속 — 페르디난트의 죽음과 카를 5세의 즉위", "fbe0dbd2"], "d": ["1516년 1월 23일 아라곤 국왕 페르난도 2세가 죽자, 1506년부터 부르고뉴 공작의 자격으로 이미 저지대 국가(오늘날의 벨기에, 네덜란드, 룩셈부르크와 프랑스 북부의 일부)를 다스려 온 그의 손자 카를 5세가 카스티야와 아라곤 왕위의 상속자도 되었으며, 1516년 3월 14일 브뤼셀에서 스페인 국왕으로 선포되었다. 이로써 이 땅은 인적 결합을 통해 합스부르크가의 독일·오스트리아 계통이 아니라 직접 스페인 왕관에 속한 것으로 간주되기 시작했다. 1519년 카를 5세가 신성 로마 황제로 선출되면서 이 두 정체성(스페인 국왕과 신성 로마 황제)은 한 사람에게 합쳐졌고, 이 지역의 스페인 귀속은 1556년 카를 5세가 퇴위하며 유산을 아들 펠리페 2세에게 물려줄 때까지 이어진다.", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["데막 술탄국이 마자파힛을 무너뜨리고 자바 해안을 지배하다", "7da602b5"], "d": ["TDV의 데막 항목에 따르면, 자바 최초의 독립 이슬람 국가인 데막 술탄국은 15세기 마지막 4분기에 라덴 파타가 세웠다. 자바 사료에 따르면 쇠퇴하던 힌두-불교 마자파힛 왕국은 데막의 공격으로 사라졌다. 1527년 데막은 중국 사료가 11세기부터 마자파힛 통치자들의 중요한 항구로 언급해 온 투반을 정복했다. 이해는 마자파힛의 마지막 잔존 세력까지 데막에 복속된 해이며, 자바 대부분이 이슬람화하는 과정의 전환점이다.", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["노르웨이가 덴마크 왕관에 속한 지방으로 격하되다", "8e2f274e"], "d": ["덴마크 국왕 크리스티안 3세는 1536년의 즉위 헌장(håndfæstning)에서 노르웨이를 더 이상 별개의 왕국으로 간주하지 않고 덴마크의 한 지방으로 통치하며, 노르웨이 국가 평의회(riksråd)를 폐지한다고 선언했다. 이 결정은 1537년 덴마크 교회 법령이 노르웨이에도 적용되면서 실행에 옮겨졌고, 스코틀랜드계 노르웨이 주교 올라브 엥겔브릭트손의 저항은 꺾였다. 노르웨이는 실제로는 한동안 자체 법률과 제도를 유지했지만, 정치적 지위는 더 이상 독립 왕국이 아니라 덴마크 왕관에 속한 지방이었으며, 이 상태는 1814년까지 이어진다.", "a8c9dee7"]},
"OLAYLAR_EK16:1558-05-01:0":{"b": ["러시아군의 나르바 점령 — 리보니아 전쟁의 첫 번째 주요 도시", "c21130d7"], "d": ["이반 4세의 군대가 나르바를 점령하여 러시아는 발트해 연안에 이르렀다. 나르바는 1581년 스웨덴에 넘어갈 때까지 러시아의 수중에 남았다.", "8057148b"]},
"OLAYLAR_EK16:1558-07-01:0":{"b": ["러시아군의 도르파트(타르투) 점령", "f941a504"], "d": ["러시아군은 1558년 여름 원정에서 도르파트(타르투)와 주변 요새들을 점령했다. 도시는 1582년 얌 자폴스키 휴전까지 러시아의 통치 아래 남았다.", "35503ef9"]},
"OLAYLAR_EK16:1561-06-01:0":{"b": ["레발(탈린)이 스웨덴의 보호를 받다 — 에스토니아 북부가 스웨덴에 넘어가다", "3c183267"], "d": ["리보니아 연맹이 해체되는 가운데, 레발 시의회는 1561년 스웨덴 국왕 에리크 14세에게 충성을 바쳤다. 에스토니아 북부는 대북방 전쟁(1721)까지 스웨덴에 남았다.", "cb752659"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["빌뉴스 조약 — 리보니아 연맹 해체, 쿠를란트와 리보니아가 폴란드-리투아니아에 귀속(리가시 제외)", "d1ceaad5"], "d": ["리보니아 전쟁 중 러시아의 압박으로 해체되어 가던 리보니아 연맹의 마지막 총단장 고트하르트 케틀러는 1561년 11월 28일 빌뉴스에서 체결된 조약(Pacta Subiectionis)으로 리투아니아 대공이자 폴란드 국왕인 지그문트 2세 아우구스트의 보호 아래 들어갔다. 리가시를 제외한 리보니아의 대부분은 폴란드-리투아니아에 귀속되었고, 케틀러는 쿠를란트 공국의 초대 공작이 되었다. 이는 리보니아 기사단이 중세에서 근세로 넘어가는 과정의 마지막 장이었다.", "bcd4efe9"]},
"OLAYLAR_EK16:1581-01-01:0":{"b": ["스웨덴이 러시아에게서 나르바를 빼앗다", "5a7f7a6a"], "d": ["리보니아 전쟁 말기에 스웨덴군은 1558년부터 러시아의 수중에 있던 나르바를 점령했다. 도시는 1704년까지 스웨덴에 남았다.", "5fee4227"]},
"OLAYLAR_EK16:1581-01-01:1":{"b": ["자유시 리가가 폴란드-리투아니아에 귀속되다", "77dba329"], "d": ["리보니아 전쟁 내내 자유시로 남아 있던 리가는 1581년 폴란드-리투아니아 연방에 귀속되었다. 도시는 1621년 스웨덴에 넘어갈 때까지 연방에 남았다.", "ecdf652d"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["포기 선언(Plakkaat van Verlatinghe) — 네덜란드가 스페인으로부터 독립을 선언하다", "a632aaee"], "d": ["80년 전쟁이 계속되는 가운데, 위트레흐트 동맹에 속한 네덜란드 주들의 전국 의회(Staten-Generaal)는 1581년 7월 26일 채택한 포기 선언을 통해 스페인 국왕 펠리페 2세를 '폭군'으로 선언하고 그에 대한 충성을 거부했다. 이 문서는 사실상 독립한 연합주(네덜란드 공화국)의 건국 선언으로 간주된다. 스페인의 최종 승인은 1648년 베스트팔렌 조약을 기다려야 했지만, 실질적인 결별은 이날 이루어졌다.", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["스몰렌스크가 폴란드-리투아니아에 함락되다 — 20개월 포위전의 끝", "4e9678e3"], "d": ["동란 시대(스무타)에 폴란드 국왕 지그문트 3세의 군대는 1609년 9월부터 포위해 온 스몰렌스크의 성벽에 1611년 6월 13일 지하 폭약을 터뜨려 돌파구를 내고 도시를 점령했다. 이로써 20개월간의 저항이 끝났다. 스몰렌스크는 1654년까지 폴란드-리투아니아에 남았고, 이 함락은 7년 뒤 체결될 데울리노 휴전(1618)의 토대를 마련했다.", "25d6488d"]},
"OLAYLAR_EK16:1611-07-16:0":{"b": ["스웨덴군의 노브고로드 점령 — 동란 시대에 러시아 북서부가 스웨덴의 통제 아래 들어가다", "a8ab28bb"], "d": ["야코브 델라가르디가 이끄는 스웨덴군이 노브고로드를 점령했다. 이 도시는 1617년까지 스웨덴의 보호를 받는 '노브고로드 국가'의 수도가 되었고, 칼 필립이 차르 후보로 추대되었다.", "281592c2"]},
"OLAYLAR_EK16:1617-03-09:0":{"b": ["스톨보보 조약 — 러시아가 발트해 연안(잉그리아)을 스웨덴에 잃다", "175dc175"], "d": ["잉그리아 전쟁을 끝낸 스톨보보 조약은 1617년 2월 27일 라도가호 남쪽의 스톨보보 마을에서 체결되었다. 러시아는 노브고로드와 북부의 다른 영토를 되찾았으나, 스웨덴은 카렐리야와 잉그리아(에스토니아와 핀란드 사이 지역으로 이반고로드, 얌, 코포리예, 오레셰크 요새 포함)를 차지했고, 러시아의 발트해 직접 연안은 끊겼다. 이 단절은 1703년 표트르 대제가 같은 지역에 상트페테르부르크를 세울 때까지 이어진다.", "7e70e3e6"]},
"OLAYLAR_EK16:1617-03-09:1":{"b": ["스톨보보 조약 — 러시아가 잉게르만란트를 스웨덴에 넘기고 노브고로드를 돌려받다", "e0bcbc7a"], "d": ["러시아는 네바강 연안과 카렐리야의 일부(얌, 코포리예, 이반고로드, 오레셰크)를 스웨덴에 넘겨 발트해 연안에서 차단되었고, 스웨덴은 노브고로드를 반환했다. 이 상태는 표트르 1세의 대북방 전쟁 때까지 이어졌다.", "bf517525"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["데울리노 휴전 — 스몰렌스크, 체르니고프, 노브고로드세베르스키가 폴란드에 넘어가다", "6880d2c1"], "d": ["1609~1618년의 폴란드-러시아 전쟁을 끝낸 데울리노 휴전은 1618년 12월 11일에 체결되어 14년 6개월의 휴전을 보장했다. 러시아는 스몰렌스크(뱌지마 제외)와 체르니고프 및 노브고로드세베르스키 지역의 29개 도시를 폴란드-리투아니아 연방에 넘겨야 했다. 이는 동란 시대(스무타) 최대의 영토 상실이었다. 이 지역은 1667년 안드루소보 휴전까지 폴란드에 남게 된다.", "5c52de5a"]},
"OLAYLAR_EK16:1625-01-01:0":{"b": ["스웨덴이 폴란드에게서 타르투(도르파트)를 빼앗다 — 리보니아 원정의 제2단계", "46b7c86a"], "d": ["구스타브 2세 아돌프는 1625년 원정에서 에스토니아 남부와 리보니아 북부를 정복했다. 타르투는 1632년 구스타부스 아돌푸스 아카데미가 설립되는 스웨덴의 도시가 되었다.", "b58d9bd1"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["페레야슬라우 회의 — 자포로자 코사크가 러시아 차르에게 충성을 서약하다", "bcd8f8ef"], "d": ["1648년부터 폴란드-리투아니아에 맞서 봉기한 자포로자 코사크의 헤트만 보흐단 흐멜니츠키는 모스크바에서 바실리 부투를린이 이끌고 온 사절단이 참석한 1654년 1월 18일(율리우스력 1월 8일)의 페레야슬라우 회의에서 차르 알렉세이 1세 미하일로비치에게 충성을 서약했다. 이는 우크라이나 코사크 헤트만국이 러시아의 보호 아래 들어가는 출발점으로 간주되며, 체르니고프-세베르스키 지역의 실질적 지배를 폴란드에서 러시아로 옮겼다. 공식 국경은 1667년 안드루소보 휴전에서 그어지게 된다.", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["러시아의 스몰렌스크 탈환", "bf0eca92"], "d": ["1654년에 시작된 폴란드-러시아 전쟁에서 러시아군은 7월부터 포위해 온 스몰렌스크를 1654년 10월 3일 폴란드 수비대의 항복을 받아 되찾았다. 1611년 폴란드에 잃은 이 도시는 43년 만에 러시아로 돌아왔다. 이는 러시아가 동란 시대의 손실을 되돌리는 과정에서 가장 중요한 단계 가운데 하나였으며, 1667년 안드루소보 휴전으로 영구적인 것이 되었다.", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["안드루소보 휴전 — 키예프와 좌안 우크라이나가 러시아로 넘어가다", "799be067"], "d": ["1654~1667년의 폴란드-러시아 전쟁을 끝낸 안드루소보 휴전은 13년 6개월의 휴전을 보장했다. 러시아는 스몰렌스크, 체르니고프-세베르스키 지역, 드니프로강 좌안의 우크라이나, 그리고 — 처음에는 2년 기한이었으나 사실상 영구적으로 — 키예프시를 얻었다. 이 조약은 우크라이나 땅이 드니프로강을 따라 폴란드와 러시아 사이에 분할되는 것(그리고 키예프가 러시아에 남는 것)의 법적 기초를 놓았다.", "94445e3a"]},
"OLAYLAR_EK16:1702-10-22:0":{"b": ["러시아가 스웨덴에게서 뇌테보리(오레셰크)를 빼앗다 — 대북방 전쟁에서 첫 번째 네바강 요새", "28d180eb"], "d": ["표트르 1세의 군대는 라도가호의 출구에 있는 뇌테보리(러시아어 오레셰크)를 포위하여 점령하고 그 이름을 실리셀부르크('열쇠의 요새')로 바꾸었다. 이로써 네바강과 1703년 상트페테르부르크 건설로 가는 길이 열렸다.", "3017c2be"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["상트페테르부르크의 건설 — 서방으로 열린 러시아의 창", "ba196be0"], "d": ["대북방 전쟁 중 스웨덴에게서 막 되찾은 네바강 삼각주의 토끼섬에, 표트르 대제는 1703년 5월 16일(율리우스력)/27일에 페트로파블롭스크 요새(베드로 바울 요새)의 초석을 놓았다. 이날이 상트페테르부르크시의 창건일로 인정된다. 표트르는 습지 삼각주를 서방으로 열린 '창'으로 구상했으며, 이 도시는 1712년 러시아의 새 수도가 되었다. 이 지역은 1721년 뉘스타드 조약으로 공식적으로 러시아에 편입된다.", "24c24aaf"]},
"OLAYLAR_EK16:1708-09-29:0":{"b": ["영국-네덜란드군의 메노르카 점령", "3ca66a83"], "d": ["스페인 왕위 계승 전쟁 중 오스트리아 대공 카를 6세의 동맹군으로 행동한 영국-네덜란드 병력은 제임스 스탠호프 장군의 지휘 아래 1708년 9월 14일 섬에 상륙했고, 9월 28~29일에 스페인의 방어를 무너뜨려 메노르카를 장악했다(주 요새 세인트 필립 요새의 공식 항복은 11월 24일에야 이루어졌다). 메노르카의 전략 항구 마온은 이후 한 세기 동안 영국, 프랑스, 스페인 쟁탈전의 초점이 된다.", "9188937e"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["라슈타트 조약 — 스페인 왕위 계승 전쟁 종결, 스페인령 네덜란드와 밀라노가 오스트리아로 넘어가다", "3c0e086f"], "d": ["스페인 왕위 계승 전쟁에서 프랑스와 오스트리아 사이의 전쟁을 끝낸 라슈타트 조약은 1714년 3월 7일에 체결되었다(1713년의 위트레흐트 조약은 영국-프랑스 관계를 정리했다). 이 조약으로 오스트리아의 합스부르크가는 스페인령 네덜란드(오늘날의 벨기에)와 이탈리아의 나폴리, 밀라노, 사르데냐를 넘겨받았다. 이는 오스트리아 역사상 가장 큰 영토 확장이었으며, 중부 유럽에서 합스부르크 왕가가 지닌 비중에 서유럽과 남유럽의 새로운 전선을 더했다.", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["뉘스타드 조약 — 대북방 전쟁 종결, 발트해 연안이 러시아로 넘어가다", "068ffd06"], "d": ["21년간 이어진 대북방 전쟁을 끝낸 뉘스타드 조약은 1721년 9월 10일(율리우스력 8월 30일)에 핀란드에서 체결되었다. 스웨덴은 에스토니아, 리보니아(리가 포함), 잉그리아와 핀란드 남동부(카렐리야)의 일부를 러시아에 넘기는 대신 핀란드의 나머지를 돌려받았고, 보상금이 지급되었다. 이 조약은 스웨덴의 강대국 지위의 종말이자 러시아가 유럽의 제국으로 부상했음을 공식 확인한 것으로 간주된다. 표트르 1세는 이 승리 후 '황제'라는 칭호를 취했다.", "f0c4fc4a"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["폴란드 제2차 분할 — 러시아와 프로이센에 영토를 잃다", "31750484"], "d": ["1791년 헌법 개혁에 러시아와 프로이센이 불안해하자, 두 나라는 1793년 1월 23일 상트페테르부르크에서 서명한 조약으로 폴란드를 다시 분할했다. 러시아는 리투아니아-벨라루스의 대부분과 서부 우크라이나(카메네츠, 바르, 민스크 포함)를 차지했고, 프로이센은 그단스크와 포즈난을 포함한 대폴란드를 병합했다. 총 307,000km²였다. 압박을 받던 폴란드 세임(의회)은 같은 해에 조약을 비준할 수밖에 없었다. 이는 폴란드의 완전 병합을 2년 늦춘 단명한 분할이었다. 이날(1793년 1월 23일) 폴란드 제2차 분할로 베르디치우, 파스티우, 지토미르, 카니우, 콘스탄티누우, 우만, 체르카시를 포함한 우안 우크라이나가 러시아에 넘어갔다.", "656e71c2"]},
"OLAYLAR_EK16:1795-03-28:0":{"b": ["쿠를란트-젬갈레 공국의 러시아 합병 — 마지막 공작 페터 폰 비론의 퇴위", "8d0e410f"], "d": ["제3차 폴란드 분할 과정에서 쿠를란트 귀족들은 예카테리나에게 충성을 바쳤고, 공작 페터 폰 비론은 퇴위했다. 쿠를란트는 러시아의 한 현(구베르니야)이 되었다(사료에는 1795년 10월 24일이라는 날짜도 나온다).", "4682774b"]},
"OLAYLAR_EK16:1797-06-14:0":{"b": ["제노바 공화국의 종말 — 나폴레옹이 리구리아 공화국을 세우다", "3d3e59ee"], "d": ["이탈리아 원정 중이던 나폴레옹의 압력으로 1797년 6월 초 임시 정부에 넘겨진 제노바 공화국을 대신하여, 1797년 6월 14일 프랑스식 헌법을 갖춘 '리구리아 공화국'이 선포되었다. 수백 년 역사의 제노바 국가는 사실상 프랑스의 위성 국가 가운데 하나가 되었다. 이 공화국은 1805년 프랑스에 직접 병합되었고, 1815년 빈 회의에서 사르데냐-피에몬테 왕국에 넘겨지게 된다.", "38af1e4b"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["캄포포르미오 조약 — 베네치아가 오스트리아와 프랑스 사이에 분할되다", "9f29678c"], "d": ["1797년 10월 17일 나폴레옹 보나파르트와 오스트리아 대표 코벤츨 백작이 서명한 캄포포르미오 조약은 천 년 역사의 베네치아 공화국을 공식적으로 없애고 그 영토를 나누었다. 아디제강 동쪽 지역과 이스트리아, 달마티아 해안(스플리트, 자다르, 시베니크, 코토르 포함)은 오스트리아에 넘겨졌고, 이오니아 제도(코르푸, 케팔로니아, 자킨토스, 레프카다, 그리고 프레베자와 파르가를 포함한 알바니아-모레아 해안의 베네치아 거점들)는 프랑스에 넘어갔다. 오스트리아는 또한 저지대 국가(오늘날의 벨기에)의 영토를 프랑스에 할양했다.", "296ee82f"]},
"OLAYLAR_EK16:1800-09-05:0":{"b": ["몰타의 영국 항복 — 2년에 걸친 프랑스군 포위의 종결", "fedc2867"], "d": ["1798년 이집트 원정길에 나폴레옹이 점령한 몰타는 얼마 지나지 않아 섬 주민의 봉기가 일어나면서 영국 함대의 해상 봉쇄를 받게 되었다. 2년간의 포위와 기아 끝에 프랑스 사령관 보부아 장군은 1800년 9월 5일 영국의 피고트 장군에게 항복했다. 이로써 몰타는 프랑스 공화국에서 영국의 보호 아래로 넘어갔고, 1814년 파리 조약으로 공식적으로 영국 왕실에 귀속되어 지중해에서 가장 중요한 영국 해군 기지가 되었다.", "6f406ae3"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["아미앵 조약 — 메노르카가 스페인에 반환되다", "f341e4b8"], "d": ["프랑스, 스페인, 네덜란드, 영국 사이에 서명된 아미앵 조약(1802년 3월 25일)은 제2차 대프랑스 동맹 전쟁을 일시적으로 끝냈다. 영국은 전쟁 중 점령한 거의 모든 영토(실론과 트리니다드 제외)를 반환했는데, 1798년 스페인에게서 빼앗은 메노르카도 그중 하나였다. 평화는 1년밖에 지속되지 않아 1803년 5월 전쟁이 다시 터졌지만, 메노르카는 이 조약 이후 다시는 영국의 손에 넘어가지 않았다.", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["프레드릭스함(하미나) 조약 — 스웨덴이 핀란드를 러시아에 할양하다", "c0d407bc"], "d": ["1808~1809년 러시아-스웨덴 전쟁을 끝낸 프레드릭스함(오늘날의 하미나) 조약은 1809년 9월 17일에 체결되었으며, 스웨덴은 올란드 제도를 포함한 핀란드 전체를 러시아에 넘겼다. 핀란드는 러시아 제국에 속하면서 폭넓은 자치권을 지닌 대공국의 지위를 얻었고 루터교 신앙과 스웨덴 법을 유지했다. 이는 발트해에서 스웨덴의 강대국 지위가 사실상 끝났음을 뜻했다. 이 조약으로 핀란드의 6개 주와 토르네강까지의 베스테르보텐(코콜라, 요엔수, 사본린나, 토르니오, 로바니에미, 이나리 등)이 러시아에 속한 핀란드 대공국으로 넘어갔다.", "fb46c9a1"]},
"OLAYLAR_EK16:1810-03-04:0":{"b": ["이메레티 왕국의 병합 — 솔로몬 2세 국왕의 폐위", "5ad36bff"], "d": ["1804년 엘라즈나우리 협정으로 러시아의 종주권을 받아들여야 했던 서조지아 이메레티 왕국의 마지막 국왕 솔로몬 2세가 갈수록 커지는 러시아의 압력에 계속 저항하자, 러시아군은 1810년 2월 20일 수도 쿠타이시를 점령하고 솔로몬을 폐위했으며 현지 귀족들에게 차르 알렉산드르 1세에 대한 충성 서약을 강요했다. 이로써 이메레티 왕국은 사실상 끝났고 러시아의 직접 통치에 편입되었다. 솔로몬은 오스만 영토로 달아나 망명지에서 죽었다(1815).", "fdccc40f"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["킬 조약 — 덴마크가 노르웨이를 스웨덴에 할양하다", "59ab1601"], "d": ["나폴레옹이 라이프치히에서 패한 뒤 남쪽에서 덴마크를 공격한 스웨덴은 1814년 1월 14일 체결된 킬 조약으로 노르웨이(아이슬란드, 페로 제도, 그린란드 제외)를 넘겨받았다. 이로써 1380년부터 이어진 덴마크-노르웨이 연합은 공식적으로 끝났다. 그 대가로 스웨덴은 포메른의 영토를 덴마크에 넘겼고, 덴마크는 또 헬골란트를 영국에 이양했다. 노르웨이는 이 조약에 무력으로 저항하며 자체 헌법을 선포했고 스웨덴은 이를 인정할 수밖에 없었다. 그 결과는 1905년까지 이어지는 동군연합(real union)이었다. 스웨덴은 노르웨이를 실제로 넘겨받지 못했다. 조약은 노르웨이에서 받아들여지지 않았고 통치권은 크리스티안 프레데리크에게 남았으며, 스웨덴군은 1814년 7월 26일에야 노르웨이에 진입했다.", "223aed9a"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["빈 회의 최종 의정서 — 나폴레옹 이후의 유럽 지도가 다시 그려지다", "fca1c676"], "d": ["나폴레옹 전쟁을 끝낸 열강(오스트리아, 러시아, 프로이센, 영국, 프랑스) 사이에 서명된 빈 회의 최종 의정서는 1815년 6월 9일(워털루 전투 9일 전)에 채택되어 대륙의 지도를 일괄적으로 다시 그렸다. 옛 스페인·오스트리아령 네덜란드와 연합주는 '네덜란드 연합 왕국'으로 통합되었고, 제노바 공화국은 사르데냐-피에몬테 왕국에 합병되었으며, 바르샤바 공국의 대부분은 '회의 폴란드'라는 이름으로 러시아에 귀속되었고, 스웨덴령 포메른(슈트랄준트)은 프로이센으로 넘어갔다. 이 하루는 전후 유럽 세력 균형(유럽 협조 체제, Concert of Europe)의 공식적인 시작으로 간주된다. 이 의정서에 의해 우치, 쳉스토호바, 키엘체, 라돔, 루블린, 헤움, 자모시치(바르샤바 공국)는 러시아에 속한 폴란드 왕국으로, 포즈난(포젠 대공국)은 프로이센으로, 마스트리흐트와 루르몬트는 네덜란드 왕국으로 넘어갔다.", "b0c34466"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["일반 해양 조약 — 카와심과 다른 페르시아만 토후국들이 영국과 조약으로 묶이다", "fc499e19"], "d": ["영국은 1819년 라스알카이마를 포격하여 '해적'으로 부르던 카시미 함대를 흩어 버린 뒤, 1820년 1월 8일에 시작되어 지역의 토후국들과 하나씩 서명하며 3월에 마무리된 일반 해양 조약을 강요했다. 이 조약은 해적 행위와 노예제를 금지했고, 선박들이 영국 깃발과 비슷한 적백색 깃발을 달도록 의무화했다. 이 조약으로 '해적 해안'은 점차 '휴전 해안'(Trucial Coast)으로 바뀌었다. 1853년의 영구 해상 휴전과 1892년의 배타적 협정들로 심화된 영국의 패권은 1971년까지 이어지는 관계의 시작이었다.", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["가에타 포위전의 종결 — 양시칠리아 왕국의 붕괴", "121ae580"], "d": ["1860년 5월 가리발디의 시칠리아 상륙으로 시작된 붕괴 이후, 나폴리에서 달아난 부르봉 왕 프란체스코 2세는 1860년 11월 3일부터 마지막 요새 가에타에서 포위당했다. 1861년 1월 프랑스 함대가 이 해역에서 철수하자 이탈리아의 해상 봉쇄가 강화되었고, 1861년 2월 13일 가에타는 항복했다. 프란체스코 2세는 왕위를 버리고 망명길에 올랐으며, 양시칠리아 왕국의 마지막 저항 거점인 치비텔라 델 트론토는 1861년 3월 20일에야 함락된다. 왕국의 붕괴와 함께 시칠리아(팔레르모, 메시나, 시라쿠사, 트라파니, 미실메리)와 캄파니아(놀라 포함)의 땅은 더 이상 부르봉의 통치 아래 있지 않게 되었다.", "bb89dfd9"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["이탈리아 왕국의 선포 — 사르데냐, 토스카나, 남이탈리아의 통일", "12e52f70"], "d": ["1861년 3월 17일 토리노에서 열린 이탈리아 의회의 첫 회기에서 이탈리아 왕국이 공식 선포되었고, 사르데냐-피에몬테의 왕 비토리오 에마누엘레 2세가 통일 이탈리아의 첫 국왕이 되었다. 새 왕국은 전해의 국민투표로 합류한 토스카나, 에밀리아로마냐, 나폴리, 시칠리아(양시칠리아)의 영토를 사르데냐 왕국과 통합했다. 로마(교황령)와 베네치아(오스트리아령)는 아직 바깥에 남았으며, 각각 1870년과 1866년에 합류하게 된다.", "d044a9c0"]},
"OLAYLAR_EK16:1866-10-18:0":{"b": ["지자흐의 러시아 함락 — 시르다리야 전선에 있던 부하라 에미르국의 마지막 요새", "21205a6e"], "d": ["러시아의 중앙아시아 진출 과정에서 체르냐예프 장군의 1866년 2월 시도가 실패한 뒤, 후임으로 임명된 드미트리 로마놉스키 장군이 지휘하는 러시아군은 1866년 10월 7일간의 포위와 격렬한 공격 끝에 시르다리야 계곡에 있는 부하라 에미르국의 마지막 대요새 지자흐를 점령했다. 이 함락은 이 지역에서 부하라의 저항을 사실상 끝냈고 러시아군에게 사마르칸트로 가는 길을 열었다.", "b95ba993"]},
"OLAYLAR_EK16:1870-09-28:0":{"b": ["스트라스부르의 항복: 독일군이 도시를 점령하다", "ef3281f3"], "d": ["6주간의 포위와 포격 끝에 위리크 장군은 밤중에 쾨니히스호펜에서 항복 문서에 서명했다. 아침에 성문과 성채가 프로이센군과 바덴군에게 넘겨졌다. 도시는 프랑크푸르트 조약(1871년 5월 10일)까지 군사 점령 아래 남았다.", "38c8361d"]},
"OLAYLAR_EK16:1870-10-29:0":{"b": ["메스의 항복: 바젠의 군대가 무기를 내려놓고 독일군이 요새를 차지하다", "8dd66f58"], "d": ["포위된 라인군의 항복 의정서는 10월 27일 저녁에 서명되었다. 10월 29일 아침 보루에 프로이센 깃발이 게양되었고 프랑스군은 요새를 떠났다. 메스는 프랑크푸르트 조약(1871년 5월 10일)까지 군사 점령 아래 남았다.", "112e1a60"]},
"OLAYLAR_EK16:1882-03-10:0":{"b": ["아사브가 이탈리아 국가 소유로 넘어가다 — 이탈리아 최초 식민지의 기초", "15ab8732"], "d": ["홍해 연안의 아사브 항구는 1869년 이탈리아의 민간 해운 회사(루바티노)가 현지 아파르 지도자들에게서 사들였다. 영국의 승인을 받은 이탈리아 정부는 1882년 3월 10일 이 항구의 직접적인 국가 소유권을 인수했고, 7월에 제정한 법률로 아사브를 공식적으로 이탈리아 최초의 식민지로 선포했다. 이는 훗날 에리트레아 식민지(1890)로 발전하는 이탈리아의 홍해 연안 팽창의 출발점이었다.", "ba606490"]},
"OLAYLAR_EK16:1884-02-08:0":{"b": ["신카트 수비대의 전멸 — 신카트가 마흐디군에게 넘어가다", "e175a94e"], "d": ["몇 달 동안 오스만 디그나의 병력에게 포위당해 식량이 바닥난 신카트 수비대는 지휘관 타우피크 베이와 함께 포위를 뚫고 수아킨에 도달하려 했다. 1884년 2월 8일 요새 밖에서 전멸했고 신카트는 마흐디군의 손에 들어갔다. 이 소식은 2월 12일 수아킨에 전해졌다.", "abf8611c"]},
"OLAYLAR_EK16:1884-02-09:0":{"b": ["수아킨의 계엄령 — 도시가 영국 지휘 아래 들어가다", "801f6a81"], "d": ["토카르를 구원하러 간 베이커의 부대가 2월 4일 엘테브에서 참패한 뒤, 휴잇 제독은 2월 6일 수아킨에 해병대를 상륙시켰다. 1884년 2월 9일 도시에 계엄령이 선포되었고 영국 장교들에게 도시에 대한 군사·민정상의 전권이 부여되었다. 다음 날 도시의 책임은 공식적으로 베이커에게서 휴잇에게 넘겨졌다.", "92798eb8"]},
"OLAYLAR_EK16:1884-02-20:0":{"b": ["토카르가 마흐디군에게 항복하다", "0e21fd24"], "d": ["포위된 토카르 수비대는 1884년 2월 19일 마흐디군과 협상에 들어갔고, 다음 날인 2월 20일 도시를 넘겨주었다. 이 소식은 2월 24일 트링키타트에 있던 영국 부대에 전해졌다. 그레이엄의 구원 작전은 이미 늦었다.", "0ebad590"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["영국이 소말리아 북부 해안에 보호령을 설치하다 — 소말릴란드의 시작", "f301ea94"], "d": ["TDV의 소말리아 항목에 따르면, 제일라, 베르베라, 타주라는 1884년 영국인들에 의해 소말릴란드라는 이름으로 식민지화되었다. 표준 학술 자료에 따르면 이 과정은 이슬람력 1301년 라마단월 21일(1884년 7월 14일) 베르베라에서 하바르 아왈 부족과 맺은 조약으로 시작되었고, 1884~1886년에 가다부르시, 하바르 톨자알라, 하바르 가르하지스, 이사, 와르상갈리 부족과 비슷한 조약을 맺으면서 확대되었다. 영국은 그 대가로 군사적 보호를 약속했다. 이 일련의 조약은 1887년 공식적인 영국령 소말릴란드 보호령 선포의 토대가 되었다.", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["물라이다 전투 — 제2차 사우드 국가의 종말, 나지드가 라시드 가문에 넘어가다", "1cd3b213"], "d": ["자카트를 둘러싼 분쟁과 라시드 측 사절의 체포로 악화된 관계는 결국, 자발 샴마르의 아미르 무함마드 빈 라시드의 군대가 1891년 1월 21일 카심 지방의 물라이다에서 압둘라흐만 빈 파이살이 이끄는 사우드 병력과 그 동맹군에게 큰 패배를 안기는 것으로 끝났다. 이로써 제2차 사우드 국가는 사실상 종말을 맞았고, 알 사우드 가문은 쿠웨이트로 망명했으며, 나지드 전체가 라시드의 지배에 들어갔다. 남부의 딜람(하르즈), 하우타(하우타트 바니 타밈), 라일라(아플라즈) 지역도 여기에 포함되었다. 이 지배는 1902년 젊은 압둘아지즈 빈 사우드가 리야드를 되찾을 때까지(리야드 기습, 1902년 1월 16일) 이어진다.", "b77d8161"]},
"OLAYLAR_EK16:1891-02-19:0":{"b": ["영국-이집트군의 토카르 탈환 — 오스만 디그나의 철수", "80a2c26a"], "d": ["1884년부터 마흐디 운동의 현지 지휘관 오스만 디그나가 장악하고 있던 홍해 연안의 토카르는 1891년 2월 영국-이집트군의 작전으로 탈환되었고, 오스만 디그나는 산악 지대로 물러나야 했다. 이는 홍해 연안에서 마흐디 국가의 존재에 큰 타격이었으며, 이 지역은 영국-이집트 공동 통치 아래 들어갔다.", "07bd31cf"]},
"OLAYLAR_EK16:1891-03-03:0":{"b": ["그렌펠 부대의 신카트 통과 — 신카트가 마흐디 통치에서 벗어나 영국-이집트 통치로 돌아오다", "b7539a44"], "d": ["1891년 2월 토카르를 탈환한 뒤, 그렌펠이 지휘하는 영국-이집트 부대는 1891년 3월 3일 아파피트를 출발하여 신카트를 거쳐 3월 7일 수아킨에 도착했다. 부대는 1884년 이후 한 번도 들어가지 못했던 지역에서 적이 완전히 철수한 것을 확인했다. 3월 8일 수아킨에 모인 셰이크들에게 헤디브의 이름으로 대사면이 선포되었고, 신카트는 다시 영국-이집트 통치에 편입되었다.", "5e77e2d3"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["이탈리아령 소말릴란드의 국가 직접 통치 전환 — 베나디르 회사의 청산", "8c7d085b"], "d": ["TDV의 소말리아 항목에 따르면, 이탈리아는 1889~1891년에 잔지바르 술탄국 및 영국과 맺은 협정을 통해 남부 소말리아 해안(베나디르)에 대한 지배권을 확립했으며, 처음에는 그 통치를 특허 무역 회사(베나디르 회사)에 맡겼다. 표준 학술 자료에 따르면 이 회사의 특허는 1905년 1월 24일에 종료되었고, 이탈리아 국가는 베나디르 해안(모가디슈, 메르카, 바라웨 포함)의 직접 주권을 매입하여 공식 식민 행정을 수립했다. 식민지가 내륙(바르데라, 바이도아)으로 실제 확장하는 일은 1908년의 설립 법령과 그 이후 몇 해에 걸쳐 완료된다.", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["노르웨이-스웨덴 연합의 해체 — 스토르팅의 일방적 독립 선언", "aaba2935"], "d": ["노르웨이 정부의 별도 영사관 설치 요구를 국왕 오스카르 2세가 거부하고 새 정부를 구성할 수 없다고 밝히자, 노르웨이 스토르팅(의회)은 1905년 6월 7일 만장일치로 국왕이 더 이상 사실상 노르웨이 국왕의 직무를 수행하지 않으며 1814년 킬 조약 이래 이어진 연합은 해체되었다고 결의했다. 1905년 8월 13일의 국민투표에서는 거의 모든 유권자(반대 184표 대 찬성 371,000표)가 해체를 승인했으며, 스웨덴은 칼스타드 협상 이후 1905년 10월 26일 독립을 공식 인정했다.", "94eda38c"]},
"OLAYLAR_EK16:1915-05-08:0":{"b": ["리바우(리에파야)가 독일군에 점령되다 — 쿠를란트 점령의 시작", "fdb10548"], "d": ["1915년 하계 공세에서 독일군은 쿠를란트에 진입했다. 리바우는 발트해 연안의 러시아 해군 기지였다. 쿠를란트의 대부분은 (1918년 말까지) 오버 오스트(동부 총사령부)의 지휘 아래 들어갔다.", "98e7ef58"]},
"OLAYLAR_EK16:1915-08-01:0":{"b": ["미타우(옐가바)가 독일군에 점령되다", "eb491281"], "d": ["쿠를란트의 옛 공국 수도 미타우가 독일의 통제 아래 들어갔다. 리가 전선은 다우가바강 선에서 교착되어 1917년까지 고착되었다.", "05882415"]},
"OLAYLAR_EK16:1915-08-18:0":{"b": ["코브노(카우나스) 요새가 독일군에 점령되다 — 리투아니아가 점령 아래 들어가다", "9849405b"], "d": ["독일 제10군은 네만강에 있는 러시아 최대의 요새를 점령했다. 리투아니아 지역은 오버 오스트의 통치 아래 들어갔고, 1918년 타리바(리투아니아 평의회)는 이 점령 아래에서 독립을 선언했다.", "1f9a43bc"]},
"OLAYLAR_EK16:1915-09-18:0":{"b": ["빌나(빌뉴스)가 독일군에 점령되다", "2781858b"], "d": ["대퇴각 중에 빌나는 독일군에게 넘어가 오버 오스트의 리투아니아 지역에 편입되었다. 도시는 1919년까지 독일, 소련, 폴란드 병력 사이에서 주인이 바뀌었다.", "d9dddcbb"]},
"OLAYLAR_EK16:1916-11-03:0":{"b": ["영국-카타르 조약 — 카타르가 영국의 보호 아래 들어가다", "f61c4e49"], "d": ["제1차 세계 대전 중인 1916년 11월 3일, 페르시아만의 영국 정치 주재관 퍼시 콕스 소령과 카타르의 셰이크 압둘라 빈 자심 알 사니 사이에 서명된 조약으로 카타르는 대외 관계를 영국의 승인에 맡기기로 하는 대신, 해상 공격에 대한 영국의 보호를 보장받았다. 이 조약은 1971년까지 이어지는 카타르의 영국 보호 관계의 법적 기초가 되었으며, 1918년에 공식 비준되었다.", "abf30185"]},
"OLAYLAR_EK16:1917-09-03:0":{"b": ["리가가 독일 제8군에 점령되다", "df95df19"], "d": ["독일군은 다우가바강을 건너 리가를 점령했다. 도시는 1918년 11월까지 독일의 통제 아래 남았고, 라트비아의 독립은 이 점령 아래에서 선포되었다(1918년 11월 18일).", "e0339705"]},
"OLAYLAR_EK16:1918-11-18:0":{"b": ["라트비아 인민 평의회의 독립 선언", "fc72a7f7"], "d": ["리가의 국립 극장에 모인 라트비아 인민 평의회는 러시아 제국에서 독립한 라트비아 공화국을 선포했고, 카를리스 울마니스를 수반으로 하는 임시 정부가 구성되었다. 몇 주 뒤(1918년 12월) 소비에트 러시아가 공격해 오면서 독립 전쟁이 시작되었다. 이 선언으로 리가, 옐가바, 리에파야, 벤츠필스, 체시스, 다우가우필스, 레제크네는 라트비아 공화국의 영토로 간주되었다.", "615adeb0"]},
"OLAYLAR_EK16:1919-01-05:0":{"b": ["붉은 군대의 빌뉴스 진입 — 리투아니아 정부가 도시에서 철수하다", "889a97b3"], "d": ["붉은 군대가 다가오자 리투아니아 정부는 빌뉴스에서 철수했다. 소련군이 도시에 들어왔고, 1919년 2월 이곳에서 리투아니아-벨라루스 소비에트 공화국(리트벨)이 선포되었다. 도시는 1919년 4월 폴란드군에 점령된다.", "c3a0c216"]},
"OLAYLAR_EK16:1919-04-21:0":{"b": ["폴란드군이 소련군에게서 빌뉴스(빌노)를 빼앗다", "32d36c4a"], "d": ["유제프 피우수트스키의 부대는 1919년 4월 붉은 군대에게서 빌노를 빼앗았다. 리투아니아는 이 도시에 대한 권리를 계속 주장했고, 빌뉴스 문제는 전간기 리투아니아-폴란드 관계를 크게 악화시켰다.", "85e7c434"]},
"OLAYLAR_EK16:1922-02-28:0":{"b": ["영국이 이집트에 대한 보호령을 폐지하고 이집트의 독립을 선언하다", "f8faab66"], "d": ["영국은 1922년 2월 28일의 선언으로 1914년부터 이어진 보호령을 일방적으로 종료하고 이집트를 독립국으로 선언했다. 국방, 교통로, 수단 등의 문제는 영국에 유보되었다. 선언 2주 뒤(1922년 3월 15일) 술탄 아흐메드 푸아드는 국왕 칭호를 취했다. 지도에서 이집트 도시들의 영국 점령 레이어는 이날에 끝난다.", "8cde4005"]},
"OLAYLAR_EK16:1939-03-22:0":{"b": ["리투아니아가 독일의 최후통첩을 수락 — 메멜 지역이 독일에 넘어가다", "149fb0b2"], "d": ["리벤트로프의 최후통첩에 따라 리투아니아는 클라이페다(메멜) 지역을 독일에 넘겼고, 히틀러는 3월 23일 메멜에 들어갔다. 이 지역은 1945년 1월 28일 붉은 군대에 점령되었다.", "75afd979"]},
"OLAYLAR_EK16:1941-06-23:0":{"b": ["독일이 그로드노를 점령하다", "b7ca9378"], "d": ["동부 전선: 1941년 바르바로사 작전과 1944년 바그라티온 작전.", "c6101096"]},
"OLAYLAR_EK16:1941-06-23:1":{"b": ["독일이 브레스트-리토프스크를 점령하다", "25898c65"], "d": ["동부 전선: 1941년 바르바로사 작전과 1944년 바그라티온 작전.", "c6101096"]},
"OLAYLAR_EK16:1941-07-09:0":{"b": ["프스코프가 독일군에 점령되다 — 러시아 땅 점령의 시작", "d9822e30"], "d": ["바르바로사 작전 셋째 주에 독일 국방군은 프스코프에 진입했다. 도시는 1944년 7월 23일까지 독일 군정 아래 남았다. 출처: 프스코프시 연표, memorialmuseums.org «Memorials in Pskov» — 검색 요약 [요약].", "c875c7b2"]},
"OLAYLAR_EK16:1941-07-11:0":{"b": ["비테프스크가 독일군에 점령되다", "e1e4d7d0"], "d": ["중부 집단군은 바르바로사 작전의 첫 몇 주에 비테프스크를 점령했다. 도시는 1944년 6월까지 독일 군정 아래 남았고, 인구의 대부분이 목숨을 잃었다.", "aeb95ab0"]},
"OLAYLAR_EK16:1941-07-16:0":{"b": ["스몰렌스크가 독일군에 점령되다", "5a7f4e2a"], "d": ["중부 집단군이 스몰렌스크를 점령했다. 모스크바로 가는 길목에 있는 이 도시는 1943년 9월 25일까지 26개월 동안 점령 아래 있었고 큰 파괴를 겪었다.", "1cff2f04"]},
"OLAYLAR_EK16:1941-07-26:0":{"b": ["모길료프가 독일군에 점령되다", "4362b7a1"], "d": ["모길료프는 23일간의 방어전 끝에 독일 국방군의 손에 넘어갔다. 도시는 1944년 6월 28일까지 점령 아래 남았다.", "082ca73b"]},
"OLAYLAR_EK16:1941-07-28:0":{"b": ["오스틀란트 국가판무관부 설치 — 발트 국가들과 벨라루스가 독일 민정 아래 들어가다", "052d4c08"], "d": ["1941년 7월 17일 히틀러의 결정으로 동부의 점령지는 민정으로 이관되었다. 힌리히 로제가 이끄는 오스틀란트는 에스토니아, 라트비아, 리투아니아, 벨라루스를 포괄했다(소재지 리가). 에스토니아의 민정은 1941년 12월 5일에 수립되었고, 벨라루스 동부는 군정 아래 남았다.", "83f60be8"]},
"OLAYLAR_EK16:1941-08-17:0":{"b": ["나르바가 독일-에스토니아군에 점령되다", "60fc2b6a"], "d": ["여름 전쟁에서 에스토니아 의용병과 독일 국방군이 나르바를 점령했다. 도시는 오스틀란트에 편입되어 1944년 7월 26일까지 독일의 통치 아래 남았다.", "0f32445c"]},
"OLAYLAR_EK16:1941-08-19:0":{"b": ["노브고로드가 독일군에 점령되다", "4f599b62"], "d": ["북부 집단군이 노브고로드를 점령했다. 러시아에서 가장 오래된 도시 가운데 하나인 이곳은 1944년 1월까지 점령 아래 있었고 대부분 파괴되었다.", "ac0d4ff0"]},
"OLAYLAR_EK16:1941-08-19:1":{"b": ["고멜이 독일군에 점령되다", "9d78eb92"], "d": ["독일 국방군이 고멜을 공격한 지 사흘 뒤 붉은 군대는 도시에서 완전히 철수했다. 도시는 1943년 11월 26일까지 점령 아래 남았다.", "56a11e36"]},
"OLAYLAR_EK16:1941-08-28:0":{"b": ["탈린이 독일 제18군에 점령되다", "a855ad0d"], "d": ["소련 발트 함대가 크론시타트로 유혈 철수를 하는 가운데 탈린이 함락되었다. 에스토니아는 오스틀란트 안의 에스토니아 총지구(Generalbezirk Estland)가 되었다(1941년 12월 5일 민정 실시).", "859cfaf1"]},
"OLAYLAR_EK16:1941-10-03:0":{"b": ["오룔이 독일군에 점령되다", "3127f454"], "d": ["브랸스크-뱌지마 작전에서 독일 제2기갑군이 오룔을 점령했다. 도시는 1943년 8월 5일까지 점령 아래 남았다.", "f5465227"]},
"OLAYLAR_EK16:1941-10-06:0":{"b": ["브랸스크가 독일군에 점령되다", "20fa93f8"], "d": ["브랸스크 전투 끝에 독일군이 도시에 진입했다. 도시는 1943년 9월 17일까지 점령 아래 남았다.", "f4a24f91"]},
"OLAYLAR_EK16:1941-11-03:0":{"b": ["쿠르스크가 독일군에 점령되다", "a723a00a"], "d": ["소련 사령부의 명령으로 쿠르스크는 비워졌고 독일 제2군이 도시에 진입했다. 도시는 1943년 2월 8일까지 점령 아래 남았다.", "0d07184e"]},
"OLAYLAR_EK16:1943-02-08:0":{"b": ["붉은 군대의 쿠르스크 해방", "1ac03fba"], "d": ["소련의 동계 공세(보로네시-카스토르노예 작전에 이은 쿠르스크-하리코프 방면) 끝에 쿠르스크가 탈환되었다. 같은 해 7월, 이 도시의 이름은 쿠르스크 전투에 붙여졌다.", "68d51be4"]},
"OLAYLAR_EK16:1943-08-05:0":{"b": ["붉은 군대의 오룔 탈환 — 쿠르스크 이후 첫 소련의 승전 예포", "80bfc68d"], "d": ["오룔 돌출부가 점령되었고, 벨고로드와 함께 모스크바에서 처음으로 승전 포 예포가 발사되었다.", "5714054b"]},
"OLAYLAR_EK16:1943-09-17:0":{"b": ["붉은 군대의 브랸스크 탈환", "d0f2a35f"], "d": ["브랸스크 작전으로 도시는 1943년 9월 17일에 탈환되었다.", "e6b7799d"]},
"OLAYLAR_EK16:1943-09-25:0":{"b": ["붉은 군대의 스몰렌스크 해방", "6516d85a"], "d": ["1943년 8월 7일~10월 2일의 스몰렌스크 작전이 절정에 이르렀을 때 도시가 탈환되었다. 스몰렌스크는 1985년 '영웅 도시' 칭호를 받았다.", "e355d898"]},
"OLAYLAR_EK16:1943-11-26:0":{"b": ["붉은 군대의 고멜 해방", "280268c2"], "d": ["벨라루스 전선군은 고멜-레치차 작전에서 도시를 탈환했다. 이는 벨라루스에서 처음으로 이루어진 주요 도시 해방 가운데 하나이다.", "3402c1b4"]},
"OLAYLAR_EK16:1944-01-20:0":{"b": ["붉은 군대의 노브고로드 해방", "52962012"], "d": ["레닌그라드-노브고로드 작전 중에 벨리키 노브고로드는 1944년 1월 20일에 탈환되었다.", "75ea1a61"]},
"OLAYLAR_EK16:1944-06-26:0":{"b": ["붉은 군대의 비테프스크 해방 — 바그라티온 작전", "b06be69c"], "d": ["제1발트 전선군과 제3벨라루스 전선군은 비테프스크를 포위하여 점령했다. 이는 바그라티온 작전에서 처음으로 이루어진 주요 도시의 해방이었다.", "9b4d6042"]},
"OLAYLAR_EK16:1944-06-28:0":{"b": ["붉은 군대의 모길료프 해방 — 바그라티온 작전", "52fa985d"], "d": ["제2벨라루스 전선군은 모길료프를 점령하고 드니프로강 방어선을 넘었다.", "22c05c20"]},
"OLAYLAR_EK16:1944-07-03:0":{"b": ["붉은 군대의 민스크 탈환 — 바그라티온 작전", "87dc1fb5"], "d": ["6월 22일에 시작된 바그라티온 작전에서 벨라루스 전선군들은 중부 집단군을 돌파하여 민스크를 포위했다. 도시는 7월 3일에 탈환되었고, 동쪽에는 5만 명에 가까운 독일군 병사가 포위된 채 남았다. 벨라루스의 독일 민정(바이스루테니아 총지구, Generalbezirk Weißruthenien)은 붕괴했다.", "1c35549f"]},
"OLAYLAR_EK16:1944-07-13:0":{"b": ["붉은 군대의 빌뉴스 점령", "0172450e"], "d": ["7월 5~13일의 빌뉴스 작전에서 제3벨라루스 전선군은 독일 수비대를 포위하고 도시를 점령했다(폴란드 국내군의 «오스트라 브라마» 작전이 동시에 진행되었다). 빌뉴스는 리투아니아 SSR의 수도가 되었다.", "aaf124b7"]},
"OLAYLAR_EK16:1944-07-16:0":{"b": ["붉은 군대가 그로드노를 독일의 점령에서 해방하다", "1d134151"], "d": ["동부 전선: 1941년 바르바로사 작전과 1944년 바그라티온 작전.", "c6101096"]},
"OLAYLAR_EK16:1944-07-23:0":{"b": ["붉은 군대의 프스코프 탈환", "f18103aa"], "d": ["3년이 넘는 독일의 점령 끝에 프스코프는 붉은 군대에 의해 탈환되었다.", "b6fb3c84"]},
"OLAYLAR_EK16:1944-07-26:0":{"b": ["붉은 군대의 나르바 점령", "64854ae3"], "d": ["1944년 2월부터 전선에서 폐허가 된 채 있던 나르바는 1944년 7월의 나르바 작전에서 소련군에 점령되었다. 에스토니아 북동부는 독일 민정(에스토니아 총지구, Generalbezirk Estland)의 손에서 벗어났다.", "74009a05"]},
"OLAYLAR_EK16:1944-07-27:0":{"b": ["붉은 군대의 레제크네 점령 — 라트비아 동부의 해방", "e9efd12d"], "d": ["제2발트 전선군이 레제크네를 점령했고, 라트비아의 라트갈레 지방은 독일의 통치에서 벗어났다.", "eac95aa6"]},
"OLAYLAR_EK16:1944-07-27:1":{"b": ["붉은 군대의 다우가우필스 해방", "b4ee6622"], "d": ["제2발트 전선군의 제360소총사단이 다우가우필스(뒤나부르크)를 점령했고, 라트갈레의 제2의 도시가 독일의 통치에서 벗어났다.", "b8a7bd0d"]},
"OLAYLAR_EK16:1944-07-27:2":{"b": ["붉은 군대의 샤울랴이 점령 — 샤울랴이 작전", "ccb20729"], "d": ["제1발트 전선군이 리투아니아 북부의 철도 교차점 샤울랴이를 점령했다. 작전은 1944년 7월 5일부터 8월 29일까지 이어졌으며 리가만에 도달했다.", "444f3101"]},
"OLAYLAR_EK16:1944-07-28:0":{"b": ["붉은 군대가 브레스트-리토프스크를 독일의 점령에서 해방하다", "6d5a837a"], "d": ["동부 전선: 1941년 바르바로사 작전과 1944년 바그라티온 작전.", "c6101096"]},
"OLAYLAR_EK16:1944-08-01:0":{"b": ["붉은 군대의 카우나스 점령 — 리투아니아 임시 수도가 독일 통치에서 벗어나다", "5c2b2c16"], "d": ["제3벨라루스 전선군이 카우나스를 점령했고, 스탈린의 8월 1일 자 일일 명령이 그 점령을 알렸다. 이 도시는 1919~1939년에 리투아니아의 임시 수도였다.", "795fab27"]},
"OLAYLAR_EK16:1944-08-25:0":{"b": ["붉은 군대의 타르투 점령 — 타르투 작전", "cc8069ab"], "d": ["제3발트 전선군은 독일 제18군의 방어를 무너뜨리고 타르투를 점령했다. 도시는 몇 주 동안 전선에 놓여 있었고, 타르투 작전은 1944년 9월 6일에 끝났다.", "3e9ef2ba"]},
"OLAYLAR_EK16:1944-09-22:0":{"b": ["붉은 군대의 탈린 진입 — 독일군의 도시 포기", "41ae1ec5"], "d": ["탈린 작전 중에 독일군은 도시를 버렸다. 9월 18일 정부 청사를 접수한 에스토니아 국민 위원회의 정부는 붉은 군대가 들어오자 통치를 지키지 못했다. 에스토니아는 다시 소련의 통치 아래 들어갔다.", "a229e09c"]},
"OLAYLAR_EK16:1945-01-28:0":{"b": ["붉은 군대의 메멜(클라이페다) 점령", "d01ad3dc"], "d": ["동프로이센과 발트해 연안을 향한 소련군의 작전에서 메멜(클라이페다) 항구는 독일에게서 빼앗겨 리투아니아 SSR에 편입되었다. 1939년 독일에 넘겨졌던 이 지역은 이로써 독일의 통치에서 벗어났다.", "65cf6a00"]},
"OLAYLAR_EK16:1945-05-08:0":{"b": ["쿠를란트 포위망의 항복 — 쿠를란트 집단군이 고보로프에게 항복 문서에 서명하다", "3c88889b"], "d": ["1944년 10월부터 리에파야-벤츠필스 일대에 포위되어 있던 독일 쿠를란트 집단군이 항복했고, 라트비아 서부는 소련의 통제 아래 들어갔다.", "a7bfcc52"]},
"OLAYLAR_EK17:1485-01-01:0":{"b": ["타슈켄트가 모굴리스탄의 칸 유누스 칸의 통치하에 들어감", "a37ee010"], "d": ["티무르 왕조 왕자들 간의 왕위 다툼 중에 타슈켄트와 그 일대는 동차가타이(모굴리스탄)의 칸 유누스 칸의 손에 들어갔다. 2년 뒤 유누스 칸이 죽자 아들 마흐무드 칸이 뒤를 이었고, 이 도시는 1503년 샤이바니 칸의 우즈베크인들이 점령할 때까지 모굴 칸들의 수중에 남았다.", "07459832"]},
"OLAYLAR_EK17:1504-01-01:0":{"b": ["바부르, 페르가나를 우즈베크인에게 넘기고 카불로 감", "69df593c"], "d": ["우마르 샤이흐 미르자의 아들인 티무르 왕조의 바부르는 1494년부터 다스려 온 페르가나를 무함마드 샤이바니 칸과의 전쟁 끝에 우즈베크인에게 넘기고, 힌두쿠시를 넘어 카불에 자리 잡았다.", "21d1ed8c"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["카르스 일대의 통합: 쉬레겔, 아르파차이, 디고르가 오스만 통치하에 들어감", "10f16b5c"], "d": ["두 이라크 원정 중에 파신, 쉬레겔, 올투의 요새들이 오스만의 손에 들어갔다. 카르스 요새 역시 이때 병력에 의해 편입되었을 가능성이 매우 높다. 카르스 북쪽과 동쪽의 아르파차이와 디고르 지역도 같은 작전으로 오스만의 통제하에 들어갔다.", "f8a4288a"]},
"OLAYLAR_EK17:1538-10-01:0":{"b": ["시르반샤 왕조의 종말: 알카스 미르자가 샤루흐를 사로잡고, 시르반은 사파비의 속주가 됨", "e6d64114"], "d": ["샤 타흐마스프가 파견한 알카스 미르자는 시르반을 약탈하고 바이쿠르드 요새를 점령했으며, 열다섯 살의 시르반샤 샤루흐를 포로로 잡아 타브리즈로 데려갔다. 이로써 이 지역에서 오랫동안 지배권을 유지해 온 시르반샤 왕조의 통치는 끝났고, 시르반은 사파비 국가의 한 속주가 되었다.", "47532c27"]},
"OLAYLAR_EK17:1686-08-30:0":{"b": ["아나볼루(나우플리온)를 베네치아에 상실 — 모레아 전쟁의 전환점", "9d400557"], "d": ["TDV의 아나볼루 항목에 따르면 포위 중에 도시의 무슬림 주민 가운데 살아남은 이들은 인근 섬들과 아나톨리아로 달아났다(1686). 표준 학술 문헌(Setton, Venice, Austria, and the Turks in the Seventeenth Century)에 따르면 쾨니히스마르크의 군대는 2주 동안 오스만 구원군의 공격을 물리쳤다. 8월 29일 이스마일 파샤의 공격이 참패로 끝나자 요새는 며칠 안에 항복했다. 아나볼루는 1540년 조약으로 넘겨받은 오스만 영토였으며, 이곳을 잃으면서 모레아 반도가 베네치아로 넘어가는 과정이 빨라졌다.", "592908a0"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["문카치(무카체베) 요새, 3년간의 포위 끝에 오스트리아에 항복", "ca2efc3d"], "d": ["1685년 말 황제군에게 포위된 문카치 요새는 퇴쾨이 임레의 아내 즈리니 일로나의 지휘 아래 3년 동안 저항했다. 간행된 많은 참고 문헌에 따르면 요새는 1688년 1월 17일 안토니오 카라파 장군에게 항복했다. 이는 오스만-합스부르크 전선에서 헝가리의 친오스만 저항 세력이 지닌 마지막 대요새 가운데 하나의 함락이었다.", "d72ac109"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["스메데레보를 합스부르크(헝가리 왕국 왕관령)의 손에서 탈환 — 1737-39년 전쟁", "63dcf604"], "d": ["TDV의 스메데레보 항목에 따르면, 1717년 파사로비츠 조약으로 오스트리아에 넘겨진 이 요새는 1737년에 시작된 오스만-오스트리아 전쟁 중 도나우-사바 전선에서의 오스만군 진격으로 탈환되었다. 합스부르크(헝가리 왕국 왕관령) 군대는 이 지역에서 1738년 8월까지 버틸 수 있었으며, 그 뒤 스메데레보는 다시 오스만 통치하에 들어갔다. 1년 뒤 체결된 베오그라드 조약(1739-09-18)은 이 성과를 — 베오그라드 및 북부 세르비아와 함께 — 확정하게 된다.", "9ca857ec"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["모라바 계곡의 오스만 통치 복귀 — 야고디나, 크라구예바츠, 차차크", "b219d3c9"], "d": ["1738년 8월 스메데레보가 탈환되면서, 스메데레보와 오스만 본토 사이에 남아 있던 모라바 계곡도 오스만 통치로 돌아왔다. 야고디나, 크라구예바츠, 차차크는 이 날짜부터 오스만령으로 간주된다. 사료는 이 세 곳의 복귀를 따로 날짜를 붙여 언급하지 않으며, 지도는 스메데레보의 날짜를 따른다. 베오그라드 조약(1739-09-18)이 이 상황을 확정했다.", "4b38fa55"]},
"OLAYLAR_EK17:1799-01-03:0":{"b": ["오스만-러시아 방위 동맹 — 프랑스에 맞선 공동 방위", "c87079d1"], "d": ["나폴레옹의 이집트 점령에 대응하여 셀림 3세와 러시아 차르 파벨 1세는 14개조로 된 8년 기한의 방위 동맹을 맺었다. 양측은 친구와 적을 공동으로 삼고, 서로 원조하며, 단독 강화를 하지 않을 것을 약속했다.", "41183e81"]},
"OLAYLAR_EK17:1799-01-21:0":{"b": ["오스만-양시칠리아(나폴리) 방위 동맹 — 프랑스에 맞선 공동의 대의", "1d2be816"], "d": ["프랑스가 이탈리아, 몰타, 이집트를 점령하자 오스만 국가와 양시칠리아 왕국은 9개조로 된 방위 동맹을 맺었다. 양측은 전쟁을 공동으로 수행하고, 단독 강화를 하지 않으며, 서로 육해군 원조를 제공할 것을 약속했다.", "5a755b31"]},
"OLAYLAR_EK17:1800-04-02:0":{"b": ["칠도 공화국 수립 — 러시아-오스만 보호하의 이오니아 제도", "08839694"], "d": ["1799년 러시아-오스만 연합 함대는 프랑스군을 이오니아 제도에서 몰아냈다(코르푸 요새는 1799년 3월 5일에 함락되었다). 1800년 3월 21일자 12개조 협약으로 이 제도는 내정은 자치이고 외교는 오스만에 종속된 '제자이리 세바이 뮈즈테미아 줌후루'(칠도 공화국)로 수립되었다. 1799-03-05부터 이날까지는 공동 점령기이다.", "a9d3379e"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["틸지트 — 칠도 공화국에 대한 러시아의 권리가 프랑스로 양도됨", "98a78beb"], "d": ["틸지트에서 러시아와 프랑스 사이에 이루어진 합의로 러시아는 칠도에 대한 권리를 프랑스에 넘겼다. 프랑스군은 1807년 여름 섬들에 주둔했고 칠도 공화국은 소멸했다.", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["아야마브라(산타 마우라)와 이오니아 제도가 영국 보호하로 — 나폴레옹 이후의 질서", "0af821dc"], "d": ["1797년 프랑스에 넘어갔던 아야마브라와 다른 이오니아 제도의 섬들은 나폴레옹의 결정적 패배 이후, 1815년 11월 5일 파리에서 영국, 러시아, 오스트리아, 프로이센 사이에 체결된 특별 조약에 따라 '칠도 합중국'이라는 이름으로 영국의 보호하에 놓였다 — 이는 1815년 11월 20일의 일반 파리 조약과는 별개의 문서이다. 이 보호는 1864년까지 지속되며, 그 후 섬들은 그리스에 양도되게 된다.", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["프리즈렌 정복 — 코소보의 오스만 산자크 중심지", "f84c220f"], "d": ["859년 라자브월 4일(1455년 6월 20일), 정복자 술탄 메흐메드가 이끄는 오스만군은 세르비아의 데스포트 주라지 브란코비치 — 오스만 사료의 블코을루 — 와 전쟁을 치른 뒤 프리즈렌을 점령했다. 이 도시는 13세기 중엽 비잔티움에서 세르비아 왕국으로 넘어갔으며, 밀루틴 왕, 두샨 차르, 우로시 왕 시대에는 왕의 거처였다. 두샨이 죽은 뒤에는 중요성이 줄어들었다. 정복 후 한 산자크의 중심지가 되어 1912년까지 4세기 반 동안 그 지위를 유지했다. 프리즈렌은 유고슬라비아가 해체되기 전 발칸에서 세 언어 — 알바니아어, 튀르키예어, 세르비아어 — 가 함께 쓰이던 유일한 도시였다.", "82ab4141"]},
"OLAYLAR_EK19:1789-07-14:0":{"b": ["바스티유 함락 — 프랑스 혁명의 시작", "96e931f1"], "d": ["국왕 루이 16세가 재무 장관 네케르를 해임하자(1789년 7월 11일) 일어난 분노와 경제 위기 속에서, 파리 시민들은 무기와 화약을 요구하며 바스티유 요새로 행진했다. 오후에 시작된 충돌에서 3천 명이 넘는 봉기자에 맞서 수비병이 100명가량뿐이던 요새는 17:00경 항복했다. 요새 사령관 베르나르르네 드 로네를 비롯한 몇몇 관리가 살해되었고 수감자 7명이 풀려났다. 거의 비어 있었고 이미 철거가 계획되어 있던 이 요새는 왕권 폭정의 상징이었다. 함락 소식은 루이 16세에게 '아닙니다, 폐하, 이것은 반란이 아니라 혁명입니다'라고 전해졌다. 7월 14일은 오늘날 프랑스의 국경일이며, 이 사건은 곧 전국으로 퍼진 민중 운동과 프랑스 혁명(1789-1799)의 상징적 시작으로 여겨진다. 혁명은 이후 10년 동안 절대 왕정을 무너뜨리고 유럽의 정치 지도와 오스만을 포함한 국제 균형을 영구히 바꾸게 된다.", "ecc8db63"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["맘루크군의 말라티아 입성 — 도시가 일 칸국에서 맘루크 통치로 넘어감", "2540363d"], "d": ["맘루크는 다마스쿠스 총독 사이프 앗딘 텡기즈가 지휘하는 군대를 말라티아로 보냈다. 군대는 715년 무하람월 22일(1315년 4월 28일) 도시에 들어갔다. 말라티아는 그때까지 일 칸국의 지배하에 있었으며, 유프라테스강 서쪽에서 일 칸국과 맘루크의 세력권이 맞닿는 선의 요충지였다. 이 도시의 주인이 바뀐 것은 두 국가 간의 오랜 경쟁에서 맘루크가 상부 유프라테스 방향으로 진출한 것을 보여 준다. 말라티아는 이 날짜 이후 한동안 에레트나 가문의 통치를 받게 되며, 1338년부터 다시 맘루크의 지배로 돌아간다.", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["에슈레프 베이국의 종말 — 베이셰히르와 세이디셰히르가 하미드 왕조로 넘어감", "e4e70846"], "d": ["일 칸국의 아나톨리아 총독인 아미르 추판의 아들 데미르타시는 독립을 선언한 튀르크멘 베이국들을 상대로 행동에 나섰으며, 베이셰히르에 들어가 일찍이 자신을 고발했던 에슈레프오을루 쉴레이만 샤를 처형시켰다(1326년 10월 9일). 이로써 13세기 말 베이셰히르와 세이디셰히르 일대에 세워진 에슈레프 베이국은 끝났다. TDV의 하미드 왕조 항목은 그 뒤의 일을 전한다. 데미르타시가 없앤 에슈레프 가문의 베이셰히르, 세이디셰히르, 악셰히르, 도안히사르는 하미드 베이국의 영토에 편입되었다. 같은 해 하미드 가문의 뒨다르 베이도 데미르타시에게 넘겨져 살해되었다. 이 땅은 1381년 금화 8만 닢을 대가로 무라드 1세에게 팔려 오스만 통치하에 들어가게 된다.", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["말라티아가 다시 맘루크 지배하에 들어감 — 에레트나 가문 통치의 종말", "08b80aa2"], "d": ["1315년 맘루크 통치하에 들어간 말라티아는 일 칸국이 해체되던 시기에 한동안 에레트나 가문의 손에 넘어가 있었다. TDV의 말라티아 항목은 복귀를 한 문장으로 전한다. 1338년부터 맘루크가 다시 도시를 지배했다. 이는 아나톨리아 남동부에서 일 칸국 이후의 공백이 맘루크와 에레트나 사이에서 나뉘던 시기의 한 단면이다.", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["이즈미르 항구를 십자군 함대에 상실 — 아이든 왕조의 해군력이 꺾임", "775c65fe"], "d": ["교황 클레멘스 6세의 독려로 베네치아, 제노바, 키프로스 왕국, 로도스 기사단, 낙소스 공의 선박들로 이루어진 십자군 함대가 이즈미르 항구를 아이든 왕조의 손에서 빼앗았다(1344년 10월 28일). 이 항구는 우무르 베이의 아버지 메흐메드 베이가 1328-1329년에 제노바인 마르티노 자카리아에게서 빼앗은 것으로, 에게해에서 아이든 왕조 해군력의 기지였다. 1334년 9월 같은 목적으로 온 십자군 함대는 철수할 수밖에 없었으나, 이번 두 번째 원정은 성공했다. 우무르 베이는 저항을 이어 갔고 다른 튀르크 베이국들과 연합하여 1345년 1월 17일 십자군 함대를 격파했지만, 항구는 되찾지 못했다.", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["카라만 가문의 알라에딘 베이, 코니아, 악사라이, 니데를 카라만 영토에 편입", "2b8b0f70"], "d": ["맘루크 술탄국이 아르메니아 왕국을 멸망시키고 추쿠로바 전체를 자국 영토에 편입한 일과 중부 아나톨리아의 에레트나 국가에서 일어난 혼란을 틈타고자 한 카라만 가문의 알라에딘 베이는, 무엇보다 코니아(1366-1367)를 비롯해 니데 카라히사르(예실히사르), 악사라이, 악셰히르, 일근, 이스하클르, 카이세리를 카라만 영토에 편입했다. 코니아는 셀주크의 수도로서 지닌 무게 때문에 카라만 왕조에게 단순한 도시가 아니라 정통성의 주장이었다.", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["우준 하산, 흑양 왕조를 멸망시킴 — 반호 유역이 백양 왕조로 넘어감", "d8d6c2e8"], "d": ["백양 왕조의 군주 우준 하산은 1467년 자신을 향해 진군해 오던 불구대천의 적, 흑양 왕조의 군주 자한 샤를 기습하여 흑양 왕조를 멸망시켰다. 1438년부터 통치해 온 자한 샤가 제거되면서 반호 유역 — 반, 비틀리스, 바르기리(무라디예), 호샤프, 코투르 — 은 흑양 왕조에서 백양 왕조의 통치로 넘어갔다. 이 승리는 백양 왕조를 동부 아나톨리아와 이란의 유일한 강대 세력으로 만들었고, 우준 하산을 한 세대 뒤 오스만과 맞서게 할 길로 이끌었다.", "4d0ea428"]},
"OLAYLAR_EK20:1489-03-04:0":{"b": ["젬 술탄이 로마로 옮겨짐 — 인질 외교와 연 4만 두카트", "1c6715a8"], "d": ["교황 인노켄티우스 8세는 로도스 기사단장 피에르 도뷔송과 합의하여 젬 술탄을 로마로 데려오게 했다(1489년 3월 4일). 젬은 1482년 7월 29일 로도스로 피신했고, 거기서 사보이아의 영지로, 마침내 교황의 감시하에 옮겨졌다. 바예지드 2세는 동생을 억류해 두는 대가로 기사단에 연 4만 두카트를 지급하고 오스만 영토에서의 자유 무역권을 인정하기로 했다. 이 지급금은 공납이 아니라 왕위의 정당한 경쟁자를 유럽에 묶어 두는 값이었다. 젬이 자유로웠다면 아나톨리아에서 군대를 모을 수 있었고, 게다가 십자군의 정통성 근거가 될 수도 있었다. 이렇게 한 왕가의 문제가 30년 동안 오스만 대외 정책의 주된 제약이 되었다. 바예지드가 서방에서 신중하게 처신한 이유가 이것이다. 1495년 젬이 죽으면서 이 제약은 사라졌다.", "60ca67f8"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["조지아 왕국이 셋으로 분열 — 카르틀리, 카헤티, 그리고 쿠타이시를 중심으로 한 이메레티", "f9c5f798"], "d": ["바그라티온 왕조가 다스리던 통일 조지아 왕국은 긴 내분 끝에 공식적으로 세 왕국으로 나뉘었다. 동쪽의 트빌리시를 중심으로 한 카르틀리, 북동쪽의 카헤티, 서쪽의 쿠타이시를 중심으로 한 이메레티이다. TDV의 조지아 항목은 이 분열을 확인해 준다 — '조지아는 세 왕국(카르틀리, 카헤티, 이메레티)과 다섯 공국으로 나뉘었다'. 이 분열은 다음 세기의 오스만-사파비 대립에서 결정적인 요소가 되었다. 1555년 아마시아 조약에 따라 이메레티, 다디아니, 구리아, 다벨리는 오스만에, 카르틀리, 카헤티, 모수크는 사파비에 남겨졌다. 즉 아틀라스가 서부와 동부 조지아를 서로 다른 지배자에게 연결하는 것은 이 분열에서 비롯한다. 야부즈 술탄 셀림은 아직 트라브존 총독이던 1508년에 이메레티(아츠크바시) 왕국을 복속시키고 공납을 바치게 했다.", "6b0aaa55"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["에스파냐의 트리폴리(타라불루스 알가르브) 점령 — 하프스 왕조 지배의 종말", "de319d23"], "d": ["암마르 가문 이후 트리폴리에서 하프스 왕조의 지배는 1510년까지 이어졌다. 그해 도시는 올리베토 백작 돈 페드로 나바로가 이끄는 에스파냐군에게 점령되었고, 학살에서 살아남은 무슬림들은 도시를 떠났다. 이 점령은 멜리야에서 트리폴리까지 뻗은 에스파냐의 북아프리카 해안 요새 사슬의 동쪽 끝이었다. 트리폴리 주민은 925년(1519) 이스탄불에 사절단을 보내 에스파냐의 침략에 맞서 오스만에 도움을 요청하게 되며, 도시는 1551년 투르구트 레이스와 시난 파샤가 점령하여 오스만 통치하에 들어가게 된다.", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["몰타와 트리폴리가 성 요한 기사단에게 주어짐 — 로도스에서 쫓겨난 기사단의 새 기지", "2595729e"], "d": ["카누니 술탄 쉴레이만이 928년(1522)에 로도스에서 몰아낸 성 요한(구호) 기사단은 8년 동안 근거지 없이 지낸 뒤, 에스파냐-독일의 왕 카를 5세에 의해 몰타에 자리 잡게 되었다. 같은 하사로 트리폴리의 방어도 기사단에 맡겨졌다. 몰타는 이상적인 항구들을 갖추고 있어 해상에서 활약하던 기사들에게 유리한 기지가 되었다. 그들은 먼저 비르구에 정착하여 산탄젤로 요새를 보강하고, 셍글레아 끝에 생 미셸 요새를 쌓았다. 이 정착은 지중해 한가운데에 오스만의 해로를 끊는 항구적인 적 기지를 낳았다. 947년(1540) 투르구트 레이스의 고조섬 습격으로 시작된 충돌은 1565년 몰타 공방전까지 이어지게 된다.", "3992bdbc"]},
"OLAYLAR_EK20:1648-10-24:0":{"b": ["베스트팔렌 평화 — 30년 전쟁의 종결, 신성 로마의 통일성 해체", "d7719f05"], "d": ["30년 전쟁(1618-1648)을 끝낸 조약들은 뮌스터와 오스나브뤼크에서 같은 날 체결되었다(1648년 10월 24일). 신성 로마 제국의 약 300개 제후국은 독자적인 대외 정책을 펼 권리를 얻었고, 제국은 국가이기를 그치고 하나의 지붕으로 바뀌었다. 스웨덴은 서포메라니아와 슈테틴을 얻었고, 브란덴부르크는 동포메라니아와 마그데부르크 대주교령에 대한 계승 기대권을 얻었다. 호엔촐레른 가문이 1701년 왕국으로 나아가게 할 영토의 축적이 여기서 시작된다. 네덜란드와 스위스의 독립은 공식 승인되었다. 오스만의 관점에서 그 중요성은 간접적이지만 크다. 합스부르크가 서부 전선에서 물러나면서 중부 유럽에 다시 동쪽으로 향할 수 있는 힘이 생겨났다.", "21478661"]},
"OLAYLAR_EK20:1701-01-18:0":{"b": ["프로이센 왕국 선포 — 프리드리히 1세가 쾨니히스베르크에서 즉위", "337a9f74"], "d": ["브란덴부르크 선제후 프리드리히 3세는 황제 레오폴트 1세의 승인을 받아 쾨니히스베르크에서 대관식을 올리고 «프로이센에서의 왕» 칭호를 취했다(1701년 1월 18일). 이 칭호는 동프로이센에서 따온 것인데, 그곳이 신성 로마 제국 밖에 있었고, 황제에게 속한 선제후는 제국 국경 밖에서만 왕이 될 수 있었기 때문이다. 호엔촐레른 가문의 흩어진 영토는 이때부터 하나의 국명으로 불리기 시작했다.", "203ac1b3"]},
"OLAYLAR_EK20:1720-09-02:0":{"b": ["사르데냐가 에스파냐에서 사보이아 가문으로 넘어감 — 사르데냐 왕국의 탄생", "adf778b7"], "d": ["에스파냐 왕위 계승 전쟁을 마무리한 조치들의 마지막 단계에서 사르데냐섬은 에스파냐에서 떼어져 사보이아 가문에 주어졌다. 사보이아 공은 그 대가로 시칠리아를 내놓고 사르데냐 왕의 칭호를 얻었다. 이로써 칼리아리와 사사리는 2세기에 걸친 에스파냐 통치에서 벗어났다. 이렇게 탄생한 사르데냐 왕국은 한 세기 반 뒤 이탈리아 통일을 이룰 국가의 핵심이다. 즉 1870년 로마에 들어간 이탈리아 왕국의 뿌리는 여기까지 거슬러 올라간다.", "a73abd0e"]},
"OLAYLAR_EK20:1768-05-15:0":{"b": ["코르시카가 제노바에서 프랑스로 매각됨 — 베르사유 조약", "770343df"], "d": ["제노바 공화국은 수세기 동안 보유해 왔으나 반란 때문에 사실상 통제하지 못하던 코르시카를 프랑스에 양도했다. TDV의 코르시카 항목은 이 사건을 한 문장으로 전한다. 제노바는 제대로 장악하지 못하던 이 섬을 1768년 프랑스에 팔았다. 이 양도는 제노바가 지중해에서 마지막으로 보유한 대영토에서 물러났음을 나타낸다. 섬은 1796년 한동안 영국의 손에 넘어갔다가 다시 프랑스에 반환되게 된다. 섬이 프랑스 영토가 되면서, 1년 뒤 아작시오에서 태어날 나폴레옹 보나파르트는 프랑스 신민이 되었다. 이해(1768)에 바스티아를 포함한 코르시카는 제노바에서 프랑스로 매각되었다(TDV 코르시카; 날짜 미확인).", "c6214397"]},
"OLAYLAR_EK20:1807-07-09:0":{"b": ["틸지트 조약 — 프로이센이 영토의 절반을 잃고 바르샤바 공국이 수립됨", "d30bb2cc"], "d": ["예나-아우어슈테트의 참패 이후 프로이센은 틸지트에서 나폴레옹과 가혹한 강화를 받아들여야 했다(1807년 7월 9일). 엘베강 서쪽의 모든 영토와 1793년 및 1795년 분할에서 얻은 폴란드 영토를 포기했다. 후자로부터 바르샤바 공국이 수립되었고, 비아위스토크 일대는 러시아에 주어졌다. 프로이센은 인구와 영토의 약 절반을 잃었고 군대는 42,000명으로 제한되었다. 아틀라스에서 포즈난과 토룬은 이날부터 바르샤바 공국으로, 비아위스토크는 러시아로 넘어간다. 이 조약으로 우치와 쳉스토호바(1772년 이후 프로이센에 넘어간 폴란드 지방들)는 바르샤바 공국으로 넘어갔고, 그단스크(단치히)는 독립 자유시가 되었다.", "e484982c"]},
"OLAYLAR_EK20:1870-09-20:0":{"b": ["이탈리아군의 로마 입성 — 교황령의 종말과 이탈리아 통일의 완성", "a3689f2e"], "d": ["프랑스-프로이센 전쟁에서 나폴레옹 3세가 실각하자 로마를 지키던 프랑스 수비대가 철수했고, 이에 이탈리아군이 도시에 들어왔으며 교황은 바티칸으로 물러났다. 이로써 천 년 넘게 존속한 교황령은 끝났고, 로마까지 통일에 포함시킨 이탈리아 왕국은 정치 세력으로서 유럽과 세계 무대에 등장했다. 이는 아틀라스의 마지막 반세기에 직접적인 결과를 낳는 사건이다. 통일된 이탈리아는 1911년에 트리폴리타니아와 도데카네스 제도를 오스만에게서 빼앗게 될 국가이다.", "6d9c3e10"]},
"OLAYLAR_EK20:1887-01-07:0":{"b": ["첼렝코 전투 — 하라르 토후국의 종말과 아비시니아의 점령", "5671a0d9"], "d": ["다우드가 아우사의 이맘이 되자, 오로모인이 지배하는 땅 한가운데에 남게 된 하라르는 다시 독립 토후국이 되었고, 1887년 아비시니아에 점령될 때까지 이 상태를 유지했다. 지하드를 선포한 아미르 압둘라는 1887년 1월 7일 5,000명을 이끌고 셸레네코(첼렝코)에서 아비시니아군과 맞섰으나, 패배할 것을 깨닫고 남부 하라르의 오가덴 지역으로 달아났다. 이 전투는 화기로 무장한 아비시니아군과 토후국 병력 사이의 불균형을 드러냈으며, 홍해 너머의 마지막 독립 무슬림 토후국 가운데 하나를 없앴다. 이로써 하라르, 지지가, 다가부르는 아비시니아에 편입되었다.", "73175130"]},
"OLAYLAR_EK21:1509-01-01:0":{"b": ["샤 이스마일의 데르벤트 점령 — 사파비 지배가 캅카스의 관문에 도달", "305542c4"], "d": ["1500년 시르반샤 파루흐 야사르가 패하여 살해되면서 바쿠와 셰마하는 사파비의 손에 넘어갔으나, 데르벤트는 한동안 별개로 남았다. 샤 이스마일은 1509년 도시를 점령하고 루믈루 부족의 한 갈래를 이곳에 정착시켰다. 이로써 사파비의 지배는 캅카스의 북쪽 관문, 카스피해와 산맥 사이의 이 좁은 통로에 이르렀다. 1538년 시르반이 사파비의 직접 통치하에 들어가면서 이 연결은 영구화되었다. 데르벤트는 1578년 원정에서 오스만의 손에 넘어가 1607년까지 7개 산자크로 된 베일레르베이령의 중심지가 되게 된다. TDV의 기록은 다음과 같다. \"사파비 국가의 수립과 발전은 데르벤트에서 새로운 시대의 시작이 되었다. 샤 이스마일은 1509년 도시를 점령하고 루믈루 부족의 한 갈래를 이곳에 정착시켰다. 1538년 시르반이 사파비의 직접 지배하에 들어가자...\"", "e301b4f1"]},
"OLAYLAR_EK21:1537-01-01:0":{"b": ["카르스의 오스만 영토 최종 편입 — 동부 변경의 쐐기", "6235c85a"], "d": ["백양 왕조가 사파비에게 무너진 뒤, 카르스는 한동안 아프샤르 튀르크멘의 세뷘뒤크 칸 쿠르치바시의 손에 남아 있었다. 카누니의 두 이라크 원정 중(940/1534) 파신, 쉬레겔, 올투의 요새가 점령될 때 카르스 요새도 오스만에 편입되었을 가능성이 매우 높다. 그러나 도시의 최종 편입은 3년 뒤의 일이다. TDV의 기록은 다음과 같다. \"카르스는 오스만에 출사한 둘카디르의 메흐메드 칸에 의해 944년(1537)에 오스만 영토에 최종적으로 편입되었다.\" 긴 투쟁으로 도시와 요새가 크게 황폐해졌기 때문에 신속한 보수가 시작되었다. 955년(1548) 요새를 보수하던 중 사파비가 도시를 공격하여 요새를 다시 파괴했다. 카르스는 그 후 340년 동안 오스만 북동 변경의 자물쇠로 남으며, 1877-78년 전쟁 이후 러시아에 넘겨지게 된다.", "dff46f96"]},
"OLAYLAR_EK21:1811-04-01:0":{"b": ["니코폴리스 탈환 — 6개월에 걸친 러시아 점령 종료", "7fb299d7"], "d": ["1806-1812년 오스만-러시아 전쟁에서 도나우강 남안으로 건너온 러시아군은 1810년 10월 쿠투조프 장군의 지휘 아래 니코폴리스를 점령했다. 6개월 뒤 도나우 전선을 지킬 수 없음을 깨닫고 도시를 비웠으며, 떠나기 전에 요새의 상당 부분을 폭파했다. TDV의 기록은 다음과 같다. \"1810년 10월(1808-1812년 튀르크-러시아 전쟁기)에 니코폴리스는 유명한 러시아 장군 미하일 쿠투조프의 군대에 점령되었다. 러시아군은 도시를 떠나기 전인 1811년 4월에 요새의 상당 부분을 폭파하여 도시에 큰 피해를 입혔다.\" 러시아군이 철수한 뒤 오스만은 요새를 다시 쌓게 했다. 1813-1814년의 비문이 이 보수의 기록이다.", "7237449c"]},
"OLAYLAR_EK21:1811-05-01:0":{"b": ["실리스트라 철수 — 도나우 중류의 요새가 성벽이 파괴된 채 버려짐", "561628bb"], "d": ["도나우강의 가장 강력한 오스만 요새 가운데 하나인 실리스트라는 1810년 러시아 포병의 포격을 받았고, 한 무기고의 폭발로 요새와 외곽 시가지가 큰 피해를 입었다. 러시아군은 도시를 점령한 뒤 이곳을 지키는 대신 방어 시설을 파괴하는 쪽을 택했다. 쿠투조프 장군은 성벽 철거를 명령했고, 1811년 5월 차르에게 실리스트라 성벽이 폭파되었다고 보고했다. TDV의 기록은 다음과 같다. \"1810년 도시는 러시아군의 포격을 받았다… 러시아군이 도시를 점령한 뒤 철수하기 전에 쿠투조프 장군은 실리스트라를 파괴하라고 명령했다. 1811년 5월 차르에게 실리스트라 성벽이 폭파되었다고 알렸다.\" 이 요새는 1827-1828년 전쟁에서 러시아에 다시 점령되며, 그 포위전은 헬무트 폰 몰트케가 상세히 서술하게 된다.", "d18dd90e"]},
"OLAYLAR_EK22:1794-01-01:0":{"b": ["잔드 왕조의 종말 — 이란의 카자르 지배", "5dda30a4"], "d": ["잔드 왕조의 마지막 군주 루트프 알리 칸이 패배하면서 1751년에 세워진 왕조는 끝났고, 이란 전체가 아가 무함마드 칸의 손에 들어갔다. 카자르 국가의 공식 건국은 2년 뒤, 아가 무함마드 칸이 테헤란에서 샤한샤의 왕관을 쓴 때(1796)로 잡는다. 그러나 실질적 지배권은 1794년에 넘어갔다.", "793d45c6"]},
"OLAYLAR_EK22:1923-07-24:0":{"b": ["로잔-세브르의 차이: 강요된 평화에서 대등한 평화로", "4b578583"], "d": ["세브르(1920년 8월 10일)는 이스탄불 정부에 강요되었으며 한 번도 발효되지 않은 문서였다. 반면 로잔(1923년 7월 24일)은 앙카라가 대등한 당사자로서 서명하고 튀르키예 대국민의회가 1923년 8월 23일에 비준한 평화 조약이다(로잔 제1, 143조). 국경에서 세브르는 튀르키예의 유럽 국경을 차탈자 선까지 후퇴시키고, 에디르네를 포함한 동트라키아와 임브로스 및 보즈자아다를 그리스에 준다(세브르 제27, 84조). 이즈미르와 그 일대는 명목상 튀르크 주권에 남되 행정은 그리스에 맡겨지며, 5년 뒤 지방 의회가 병합을 요청할 수 있다(제65-83조). 로잔은 마리차-아르다 선을 긋고, 에디르네와 카라아아치는 튀르키예에 남으며, 임브로스와 보즈자아다는 튀르크 영토가 된다(로잔 제2, 12, 14조; 카라아아치 의정서). 해협에 관해 세브르는 모든 수역에 미치며 튀르크 위원이 단 1표만 갖는 국제 위원회를 설치한다. 방어 시설은 철거되고 해협 지대는 연합국의 사용에 개방된다(세브르 제36-61, 178-180조). 로잔은 자유 통항 원칙을 유지하되 튀르크인이 의장을 맡는 위원회, 비무장 지대, 이스탄불의 12,000명 주둔군을 남긴다(로잔 제23조; 해협 협약). 아르메니아의 승인과 미국 대통령의 국경 중재, 쿠르드 자치 계획(세브르 제62-64, 88-93조)은 로잔에 없다. 아랍 영토, 이집트, 수단, 키프로스에 관해 세브르는 상세한 이양 규정을 둔다(세브르 제94-97조 위임통치, 제98-100조 헤자즈, 제101-122조 이집트, 수단, 키프로스, 모로코, 튀니지, 리비아의 포기; TDV의 조항 범위도 이와 같다). 로잔은 권리 포기를 더 간략하게 적고, 도데카네스 제도는 이탈리아에, 키프로스는 영국에 남으며, 모술 국경은 연기된다(로잔 제3, 15-21조). 세브르는 카피툴레이션을 부활·확대하고, 재정 위원회를 통해 튀르키예의 예산과 차입을 감독하며, 무장 병력(헌병대 및 증원 요소)은 50,000명을 넘을 수 없고, 군사 항공과 해군 항공은 금지한다(세브르 제155, 164, 191-195, 231-264, 261-263조). 로잔은 카피툴레이션을 폐지하고 부채를 분담시키며 별도의 군대 제한을 두지 않는다(로잔 제28, 46-63조; 제113조는 외국 우체국도 폐지한다). 소수민족 조항은 세브르에서는 더 광범위하고 연합국의 개입에 열려 있는 반면, 로잔에서는 국제연맹이 보장하며 상호적이다(세브르 제140-151조; 로잔 제37-45조).\n\n항목별 비교:\n• 동트라키아, 에디르네, 차탈자 — 세브르: 차탈자 선이 국경; 동트라키아와 에디르네는 그리스로(제27, 84-85조) | 로잔: 마리차강과 아르다강을 따른 국경; 에디르네와 카라아아치는 튀르키예에(제2조; 카라아아치 의정서)\n• 이즈미르 지역 — 세브르: 주권은 튀르크, 행정과 군대는 그리스, 5년 뒤 병합 신청(제65-83조) | 로잔: 이즈미르에 대한 특별 지위 조항 없음; 아나톨리아는 튀르키예 국경 안에 있다(제2-3조 일반 국경; 이즈미르에 특정된 조항 근거 없음)\n• 해협과 이스탄불 — 세브르: 국제 해협 위원회, 튀르크 1표; 방어 시설 철거, 해협 지대는 연합국이 사용; 이스탄불은 튀르크 수중에 두되 소수민족 조건에 구속(제36-61, 178-180조) | 로잔: 자유 통항 원칙; 튀르크인이 의장인 위원회, 비무장 지대, 이스탄불의 12,000명 주둔군(제23조; 해협 협약)\n• 아르메니아와 쿠르디스탄 — 세브르: 아르메니아 승인, 국경은 미국 대통령이 결정; 쿠르드 자치, 1년 뒤 독립 신청(제62-64, 88-93조) | 로잔: 관련 규정 없음(제1-143조 요약에 나오지 않음)\n• 에게해 섬들, 도데카네스 제도 — 세브르: 임브로스, 보즈자아다, 에게해 섬들은 그리스로; 도데카네스 제도와 카스텔로리조는 이탈리아로(제84, 122조) | 로잔: 임브로스와 보즈자아다는 튀르키예에, 동에게해 섬들은 그리스령, 도데카네스 제도와 카스텔로리조는 이탈리아령(제12-15조)\n• 키프로스, 이집트, 수단, 아랍 영토 — 세브르: 시리아/메소포타미아와 팔레스타인 위임통치, 헤자즈 독립; 이집트 보호령, 수단, 키프로스 병합 승인(제94-98, 101-117조) | 로잔: 시리아 국경은 1921년 프랑스-튀르크 협정에, 이라크 국경은 후일로; 이집트, 수단, 키프로스에 대한 권리 포기(제3, 16-20조)\n• 카피툴레이션 — 세브르: 부활·확대; 사법 개혁안은 연합국 위원회에서(제136, 261-263, 308-309조) | 로잔: 완전 폐지; 외국 우체국과 고등 위생 평의회 폐지(제28, 113-114조)\n• 재정 통제와 부채 — 세브르: 연합국 재정 위원회가 예산과 차입을 감독, 오스만 공채 관리청 확대, 재원은 담보(제231-264조) | 로잔: 오스만 공채는 각국의 몫으로 분할; 전쟁 피해는 상호 포기(제46-63, 58조)\n• 군사 제한 — 세브르: 병력 50,000명, 공군과 전차 금지, 연합국 통제 위원회(제152-207조) | 로잔: 전반적 제한 없음; 그리스 섬들과 해협-트라키아 지역에서만 비무장화(제13조; 해협 및 트라키아 협약)\n• 소수민족 — 세브르: 연합국의 보장과 개입권, '유기 재산'법 무효화, 반환(제140-151, 86, 142-144조) | 로잔: 비무슬림 소수민족에게 국제연맹이 보장하는 권리, 그리스 내 무슬림의 상호적 권리; 그리스인-튀르크인 주민 교환(제37-45조; 주민 교환 협약)\n• 법적 지위 — 세브르: 이스탄불 정부가 서명, 앙카라가 거부, 발효되지 않음(TDV) | 로잔: 대등한 당사자; 튀르키예 대국민의회 비준 1923년 8월 2일, 찬성 213 반대 14(TDV; 제1, 143조)", "95c8b4ce"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["최초의 오스만 아크체 주조", "38d2d638"], "d": ["오르한 가지의 이름으로 주조된 최초의 은화 아크체는 베이국의 독립 주권을 화폐로 선포한 것이었다. 아크체는 5세기 동안 기본 화폐 단위로 남았다.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["루멜리아 베일레르베이령 설치", "ffa16089"], "d": ["유럽 쪽의 정복지가 하나의 군사·행정 체계 아래 모였으며, 베일레르베이 제도는 제국 지방 조직의 근간이 되었다.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["이을드름 바예지드와 데스피나 하툰의 혼인", "4b10dc6c"], "d": ["코소보 이후 세르비아 전제공국과 맺은 속국 관계는 라자르의 딸 올리베라와 바예지드의 혼인으로 굳어졌다. 초기 혼인 외교의 전형적인 사례이다.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["아나톨리아 베일레르베이령 설치", "5ef8d3a7"], "d": ["병합한 베이국 영토를 다스리기 위해 아나톨리아 베일레르베이령이 조직되었고, 루멜리아와 아나톨리아의 두 날개를 갖춘 행정 체제가 완성되었다.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["부르사 울루 자미(대모스크) 완공", "27bcc4a5"], "d": ["니코폴리스의 전리품으로 지은 스무 개의 돔을 가진 대모스크는 초기 오스만 건축의 기념비적 사례이자 서예의 야외 박물관이다.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["찬다를르 할릴 파샤의 파면과 처형", "5e19438f"], "d": ["정복 이후, 포위전에 거리를 두었던 유서 깊은 찬다를르 가문 출신의 대재상이 처형되었다. 대재상이 술탄의 명령으로 처형된 것은 처음이었으며, 데브시르메 출신 재상들의 시대가 열리고 있었다.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["몰다비아의 공납국화", "25bd3693"], "d": ["몰다비아 총독령은 공납을 바치기로 했으며, 왈라키아, 트란실바니아와 함께 도나우강 북쪽의 세 속국 지대가 제국의 북방 완충 지대가 되었다. 같은 날짜에 편입된 다른 지역: 이아시.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["두브로브니크(라구사)의 공납", "d127c78a"], "d": ["상인 공화국 라구사는 공납의 대가로 자치와 통상 특권을 보장받았으며, 아드리아해에서 오스만의 창구로서 번영했다. 공화국의 영토인 믈레트섬도 같은 지위를 누렸다.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["왈라키아 원정: 꿰뚫는 자 블라드(카즈클르 보이보다)", "fd4530bb"], "d": ["공납을 거부하고 사절을 살해한 블라드 체페슈에 대한 원정으로 왈라키아는 속국 지위로 되돌려졌다. 야간 기습과 꼬챙이에 꿴 공포의 광경은 유럽에서 전설이 되었다. 같은 날짜에 편입된 다른 지역: 부쿠레슈티.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["파티흐 복합 단지 개관", "a150ea55"], "d": ["여덟 개의 마드라사(사흔 이 세만)를 갖춘 이 복합 단지는 이스탄불을 이슬람 세계의 학문 중심지로 바꾸려는 계획의 첫 번째 큰 걸음이었다.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["이스탄불의 알리 쿠슈추", "8508229d"], "d": ["사마르칸트 천문대의 마지막 위대한 대표자인 알리 쿠슈추는 정복자의 초청으로 아야 소피아 마드라사의 교수(뮈데리스)가 되었으며, 이스탄불에 수학·천문학의 전통을 세웠다.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["정복자의 법령집(파티흐 카눈나메)", "b08944c9"], "d": ["국가 조직, 의전, 형벌을 집성한 최초의 포괄적 관습법 법령집이다. '세계 질서(니자므 알렘)를 위해' 형제 살해를 허용한 유명한 조항으로 오랫동안 논쟁의 대상이 되어 왔다.", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["최초의 오스만 금화(술타니) 주조", "2fd5c0dd"], "d": ["베네치아 두카트에 상당하는 최초의 오스만 금화가 주조되었으며, 제국의 재정은 국제 화폐 질서에 합류했다.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["톱카프 궁전으로 이전", "b9cd6a5e"], "d": ["신궁(톱카프)이 완공되면서 국정의 중심이 이곳으로 옮겨졌으며, 궁전은 4세기 동안 제국의 두뇌로 남았다.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["피렌체 공화국의 공국 전환 — 알레산드로 데 메디치", "c08764e1"], "d": ["교황 클레멘스 7세의 압력으로 피렌체의 통치 위원회(발리아)는 새 헌법을 채택했다. 500년 동안 이어진 공화정은 폐지되고 알레산드로 데 메디치가 세습 공작으로 선포되었으며, 그는 5월 1일에 실제로 권좌에 올랐다. 이로써 피렌체는 독립 도시 공화국에서 메디치 가문의 세습 공국으로 바뀌었다.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["카누니와 휘렘 술탄의 혼인 계약", "abc05f26"], "d": ["카누니가 휘렘과 정식 혼인 계약을 맺은 것은 궁정 전통을 근본적으로 바꾸었다. '하세키 술탄' 제도가 생겨났고 왕조 정치에서 여성의 시대가 열렸다.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["프랑스에 대한 최초의 포괄적 카피툴레이션", "e2264e48"], "d": ["합스부르크의 포위에 맞선 프랑스 동맹의 일환으로 장 드 라 포레와 마크불 이브라힘 파샤 사이에 통상 특권이 체결되었다. 그날에는 외교 수단이던 카피툴레이션은 수세기를 거치며 재정 종속의 문으로 변하게 된다.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["인도양 원정: 디우 포위", "fcd1217a"], "d": ["수에즈에서 출항한 함대는 홍해를 건너 구자라트의 디우를 포위했다. 요새는 함락하지 못했으나 오스만의 힘이 처음으로 인도양에 이르렀고 포르투갈의 독점이 흔들렸다.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["세이디 알리 레이스의 인도 여행", "e5da3b2c"], "d": ["바스라의 함대를 이집트로 데려오는 임무를 맡은 세이디 알리 레이스는 폭풍에 밀려 인도에 표류했다. 그가 귀환의 모험을 서술한 『미르아튈 메말리크』는 초기 오스만 여행기 가운데 하나이다.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["피리 레이스의 처형", "63026444"], "d": ["호르무즈 원정에서 함대를 바스라에 남겨 두고 돌아온 위대한 항해가이자 지도 제작자는 84세에 처형되었다. 이는 우리 과학사에서 가장 논란이 많은 결정 가운데 하나이다.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["쉴레이마니예 복합 단지 개관", "1c6458b2"], "d": ["건축가 시난이 '나의 숙련공 시절 작품'이라 부른 이 복합 단지는 마드라사, 병원(다뤼쉬시파), 도서관을 갖춘 고전기 최대의 교육·자선 복합 시설이 되었다.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["몰타 포위", "f57f6a85"], "d": ["지중해의 자물쇠인 몰타가 넉 달 동안 포위되었다. 투르구트 레이스가 전사(순교)했고 포위는 풀렸다. 이는 카누니 시대 해양 활동의 첫 번째 큰 후퇴였다.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["셀리미예 모스크 완공", "3b0484e1"], "d": ["시난이 '나의 장인 시절 작품'이라 부른, 하나의 돔이 공간을 지배하는 셀리미예는 오스만 고전 건축의 절정으로 평가된다(유네스코 세계 유산).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["이스탄불 천문대 설립", "169bdf5d"], "d": ["당대에 가장 잘 갖춰진 천문대 가운데 하나였던 타키윗딘의 천문대는 1577년 혜성 이후 일어난 논쟁 끝에 1580년에 철거되었으며, 제도적 천문학은 3세기 늦어졌다.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["츨드르 전투의 승리 — 동방 전쟁의 시작", "13125a54"], "d": ["사파비군이 츨드르에서 패하면서 캅카스의 문이 열렸으며, 트빌리시가 점령되고 조지아가 오스만의 지배 아래 들어갔다.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["횃불 전투 — 시르반의 확정적 오스만 귀속", "3bbc23bc"], "d": ["밤에도 횃불 아래에서 계속되어 이 이름으로 불리는 전투에서 사파비는 결정적으로 패배했으며, 시르반과 바쿠에서의 오스만 지배가 확고해졌다.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["대규모 화폐 개악 — 아크체 위기", "9205c3d4"], "d": ["장기 전쟁과 아메리카 은의 압력으로 아크체의 은 함량이 절반으로 줄었다. 물가 혁명은 시파히 체제의 해체와 젤랄리 반란의 혼란을 키웠다.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["타브리즈 정복", "6506bdb9"], "d": ["총사령관(세르다르) 외즈데미르오을루 오스만 파샤가 타브리즈에 입성했으며, 사파비의 옛 수도가 오스만의 통치 아래 들어갔다. 오스만 파샤는 몇 주 뒤 진영에서 서거했다.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["페르하드 파샤 조약 — 동방에서의 최대 판도", "c429972f"], "d": ["샤 압바스의 사절 하이다르 미르자가 이스탄불에 도착한(1590년 1월 18일) 뒤, 정복지를 오스만에 남긴다는 조건으로 맺어져 12년 전쟁을 끝낸 이 조약으로 타브리즈, 카라바흐, 시르반, 조지아, 로레스탄이 오스만에 남았으며, 제국은 동방에서 역사상 가장 넓은 국경에 도달했다.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["오스만-사파비 전쟁(1603-1612) 발발 — 샤 압바스의 반격과 타브리즈 상실", "abf27dd8"], "d": ["군대를 재편한 샤 압바스는 젤랄리 반란의 혼란을 틈타 공세에 나섰다. 타브리즈가 함락되었고, 캅카스에서 얻은 성과는 몇 년 안에 상실되었다. 같은 원정과 그 이후에 상실한 다른 정착지: 나흐츠반, 호이, 마란드, 살마스. 카라자다으(아하르)와 무크리의 영주들도 사파비 편으로 돌아섰다.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["에블리야 첼레비 탄생", "2b6051ff"], "d": ["50년이 넘는 여행을 10권의 『세야하트나메(여행기)』에 담은 에블리야 첼레비는 17세기 오스만 세계의 비길 데 없는 파노라마를 남겼다.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["나수흐 파샤 조약", "bb69e388"], "d": ["1603년부터 이어진 전쟁을 끝낸 이 조약으로 1590년의 획득을 포기하고 1555년 아마시아 국경으로 돌아갔으며, 동부 전선의 균형이 다시 확립되었다.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["술탄 아흐메드 모스크 개관", "e39dfd43"], "d": ["여섯 개의 첨탑과 푸른 이즈니크 타일을 가진 '블루 모스크'는 고전기의 마지막 대규모 술탄 복합 단지이다.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["술탄 이브라힘의 처형", "bc4eb452"], "d": ["낭비와 국정의 위기를 이유로 군단과 울레마의 동맹이 이브라힘을 폐위했으며, 열흘 뒤 파트와(법적 견해)에 따라 교살되었다. 일곱 살의 메흐메드 4세가 즉위했고, 권력은 사실상 대왕대비 쾨셈 술탄의 손에 넘어갔다.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["캬티브 첼레비의 죽음", "e167e89d"], "d": ["서지 『케슈퓌쥬누눈』과 지리서 『지한뉘마』로 오스만 학술사의 정점에 선 이름이며, 유럽 자료를 활용한 선구적인 접근으로 알려져 있다.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["에디르네 사건 — 무스타파 2세의 폐위", "0291c1cd"], "d": ["술탄이 에디르네에 머무는 것과 페이줄라 에펜디의 세력에 대한 분노는 군인과 상공인의 대규모 봉기로 번졌다. 셰이흘이슬람은 군중에게 살해되고 술탄은 폐위되었으며, 궁정은 이스탄불로 돌아왔다.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["파리 주재 대사: 이르미세키즈 메흐메드 첼레비", "26312a3f"], "d": ["프랑스에 파견된 대사절단은 서구를 현지에서 살펴본 최초의 체계적인 관찰이었으며, 그의 『세파레트나메(사행록)』는 튤립 시대의 쇄신에 영감을 주었다.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["최초의 오스만 인쇄소 설립", "4943f7e5"], "d": ["튀르크어 서적의 인쇄 허가가 내려졌고, 첫 작품인 반쿨루 사전이 1729년에 인쇄되었다. 인쇄소는 튤립 시대 쇄신의 가장 영속적인 유산이다.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["카피툴레이션의 항구화", "d044a79e"], "d": ["프랑스에 부여된 특권은 해당 술탄의 치세에 한정되지 않고 영구 조약으로 묶였다. 일방적으로 폐기할 수 없게 된 카피툴레이션 체제는 로잔에서야 폐지될 수 있었다.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["황립 해군 공병 학교(뮈헨디스하네이 바흐리이 휘마윤) 설립", "9bf3f439"], "d": ["체슈메의 참사 이후 근대적 해군 장교를 양성하기 위해 설립된 이 공병 학교는 서구식 기술 교육의 최초의 영구적 기관이다. 육군 공병 학교는 1795년에 뒤따랐다.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["런던에 최초의 상주 대사관 설치", "6b5630eb"], "d": ["니자므 제디드 프로그램의 일환으로 유럽 수도들에 상주 대사관이 개설되었으며, 오스만 외교는 상호주의 원칙으로 옮겨 갔다.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["알렘다르 무스타파 파샤의 죽음", "4426534e"], "d": ["1808년 11월 15일 밤에 시작된 예니체리 봉기에서, 바브알리(대재상부)에 포위된 개혁파 대재상은 기다리던 원군이 오지 않자 이튿날 화약고에 불을 질러 수백 명의 공격자와 함께 죽었다. 세네디 이티팍 체제와 첫 개혁 시도는 그와 함께 묻혔다.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["최초의 관보: 타크비미 베카이", "c637f623"], "d": ["국가의 관보가 발행되기 시작했다. 이는 근대적 여론과 공식 공지 전통의 시작이다.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["발타 리마느 통상 조약", "e790b383"], "d": ["영국은 국내 상업에서조차 가장 특혜적인 지위를 인정받았고 전매 제도(예드 이 바히드)는 폐지되었다. 국내 생산이 보호받지 못하게 된 가운데, 이 조약은 오스만 시장이 자유 무역에 전면 개방되었음을 보여 주는 문서가 되었다.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["레바논 에미르령의 종말 — 바시르 시하브 3세의 해임", "f85ae454"], "d": ["기독교도와 드루즈의 갈등 및 슈프 지방의 내부 균형을 통제하지 못한 에미르 바시르 2세(3세)는 1842년 1월에 해임되었다. 1516년부터 (마안 가문과 이어 시하브 가문을 통해) 이어진 현지 에미르령 체제는 끝났으며, 이 지역은 오스만의 직접 통치로, 이어 이중 카임마캄 제도로 넘어갔다.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["화폐 정비: 메지디예 체제", "c77be809"], "d": ["화폐 개혁으로 순도가 떨어진 주화들이 회수되었고, 금 리라(메지디예)를 기준으로 하는 안정적인 금은 복본위제가 수립되었다.", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["바알베크 하르푸시 가문의 지방 지배 종식", "8438f4ae"], "d": ["1521년(잔비르디 가잘리의 반란 이후)부터 바알베크에서 작은 지방 왕조로 군림하던 하르푸시 가문의 세력은 오스만 정부의 새로운 행정 개편으로 끝났으며, 도시는 다마스쿠스주에 속한 평범한 카자(군) 중심지가 되었다.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["시르케티 하이리예 설립", "462830e7"], "d": ["보스포루스에서 증기선을 운항하기 위해 설립된 이 회사는 최초의 오스만 주식회사로 여겨진다. 증기선 선착장은 도시 생활에 뚜렷한 자취를 남겼다.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["최초의 외채 계약", "9017c579"], "d": ["크림 전쟁의 자금을 마련하기 위해 런던 시장에서 최초의 외채를 들여왔다. 21년 동안 15차례의 차입 끝에 도달한 지점은 1875년의 지불 유예와 오스만 공채 관리청이었다.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["이스탄불의 전신선", "d320f39f"], "d": ["크림 전쟁의 필요에 따라 가설된 최초의 전신선이 운영을 시작했으며, 제국은 수십 년 만에 세계에서 가장 넓은 전신망 가운데 하나를 갖게 되었다.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["토지법(아라지 카눈나메)", "6bae243a"], "d": ["토지법을 근대화한 이 법령은 국유지(미리)에서의 사실상의 점유를 토지 등기(타푸)와 연결했으며, 오늘날 중동의 소유 질서의 기본 문서 가운데 하나이다.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["다륄퓌눈의 첫 강의", "08f74066"], "d": ["대학 수준의 교육을 담당할 다륄퓌눈이 공개 강의로 활동을 시작했다. 중단을 거듭하며 이어진 이 기관은 1900년에 영구적으로 개교했으며 이스탄불 대학교의 핵심이 되었다.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["주(빌라예트) 규정", "ad20853b"], "d": ["에얄레트 제도를 대신하여 프랑스 모델의 빌라예트 조직이 수립되었으며, 미드하트 파샤의 도나우주 시행 사례를 본보기로 전국에 확대되었다.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["압뒬아지즈의 유럽 순방", "9ff0fa1e"], "d": ["오스만 술탄의 평화 목적 유럽 방문으로는 최초였다. 파리 박람회와 런던 방문은 외교와 근대화를 동시에 보여 주는 진열장 구실을 했다.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["갈라타사라이 황립 고등학교(메크테비 술타니) 개교", "f9688524"], "d": ["프랑스어로 교육한 이 고등학교는 종교와 민족 공동체(밀레트)를 가리지 않는 학생 구성으로 교육 평등이라는 탄지마트 이상의 상징이 되었다.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["메젤레 제1권 시행", "6475461c"], "d": ["이슬람법의 채권·물권 분야를 근대적 입법 기술로 집성한 메젤레는 최초의 이슬람 민법전으로 여겨진다. 제브데트 파샤가 이끈 위원회는 1876년에 16권을 완성했다.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["압뒬아지즈의 폐위", "eb7397ea"], "d": ["입헌파 정치가들과 군 수뇌부는 조용한 쿠데타로 압뒬아지즈를 끌어내렸다. 닷새 뒤의 의문스러운 죽음과 이어진 츠라안 사건들은 여러 해 동안 이어질 청산 다툼을 낳았다.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["츠라안 습격 (알리 수아비 사건)", "d2a9ac87"], "d": ["언론인 알리 수아비는 무라드 5세를 다시 왕위에 앉히기 위해 츠라안 궁을 습격했다. 습격은 유혈 진압되었고, 압뒬하미드 정권은 경비망을 영구적으로 강화했다.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["레지 관리국 설립 (담배 전매)", "bad9b030"], "d": ["담배 세입은 오스만 공채 관리청 산하의 외국 자본 회사인 레지에 이양되었다. 농민과 감시원(콜주) 사이의 '레지 밀수' 충돌은 수십 년 동안 이어졌다. 같은 날짜에 상실한 다른 정착지: 제일라.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["빌헬름 2세 황제의 이스탄불·예루살렘 방문", "2988cd06"], "d": ["독일 황제의 두 번째 방문은 오스만-독일의 접근을 확고히 했다. 바그다드 철도 이권의 길이 열렸고, 다마스쿠스에서는 '3억 무슬림의 친구'라는 연설이 이루어졌다.", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["메디나에 닿은 히자즈 철도", "95009b9c"], "d": ["오직 무슬림의 기부금과 자국의 기술로 건설된 1464km의 노선이 메디나에 닿았으며, 성지 순례 여정은 몇 주에서 며칠로 줄었다. 압뒬하미드 2세 시대의 가장 큰 기반 시설 사업이다.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["3월 31일 사건", "1d7c2bb2"], "d": ["입헌 체제에 반대하는 대규모 봉기가 이스탄불을 장악했다. 테살로니키에서 온 행동군이 반란을 진압했고 압뒬하미드 2세는 폐위되었다.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["에디르네 포위 시작", "234d9b28"], "d": ["쉬크뤼 파샤의 다섯 달에 걸친 방어는 발칸의 참사 속에서 저항의 서사시가 되었다. 도시는 기아로 함락되었으며 1913년 7월에 되찾았다.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["바브알리(대재상부) 습격", "b304d02d"], "d": ["에디르네를 넘겨줄 준비를 하던 정부는 통일파의 무장 습격으로 무너졌고, 육군 장관 나즘 파샤는 살해되었다. 통일진보위원회의 전면 집권기가 시작되었다.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["레바논산 무타사르리프령 폐지", "b5639051"], "d": ["1861년 기본 규정(Règlement Organique)으로 설립되어 1864년에 갱신된 국제 의정서에 기초한 자치 무타사르리프 체제는 제1차 세계 대전 중에 오스만 국가에 의해 일방적으로 폐지되었으며, 내무부는 이 지역에 무슬림 무타사르리프(지사)를 직접 임명하기 시작했다. 1861년부터 1915년까지 8명의 무타사르리프가 재임한 자치 시기는 이렇게 막을 내렸다.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["왕자들 사이의 국토 분할", "82f26bfb"], "d": ["앙카라의 패전 이후 쉴레이만 첼레비는 루멜리아로 건너가 에디르네에서 술탄을 선언했다. 이사 첼레비는 부르사를, 첼레비 메흐메드는 아마시아-토카트-시바스 지역을 장악했다. 지도에서는 이 세 몫이 각각 다른 색으로 표시된다.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["갈리폴리 조약: 메셈브리아까지의 흑해 연안을 비잔티움에 이양", "a4164eca"], "d": ["앙카라의 패전 이후 루멜리아에서 자리를 지키려던 에미르 쉴레이만은 갈리폴리에서 비잔티움 황제 마누엘과 조약을 맺었다. 그는 카르탈, 펜디크, 게브제와 일부 섬들, 루멜리아의 테살로니키와 테살리아, 그리고 흑해에서는 메셈브리아까지 이어지는 해안 지대를 비잔티움에 넘겨주었으며, 비잔티움이 오스만에게 바치던 세금도 폐지되었다. 이로써 이스트란자 해안의 아흐토폴, 이으네아다, 레조보는 21년 동안 비잔티움의 통치 아래 남았으며, 무라드 2세는 1424년의 평화 협정으로 이곳들 대부분을 되찾았다.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["억류 중 이을드름 바예지드의 죽음", "7e968d83"], "d": ["티무르에게 포로로 잡혀 있던 술탄은 악셰히르에서 서거했으며, 그의 유해는 부르사로 옮겨져 안장되었다. 그의 죽음은 왕자들 사이의 왕위 다툼을 돌이킬 수 없게 만들었다.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["갈리폴리 조약 — 비잔티움에 대한 양보", "dfacbd00"], "d": ["루멜리아에서의 지위를 확보하려던 쉴레이만 첼레비는 비잔티움 및 라틴 국가들과 합의하여 테살로니키, 마르마라 연안, 일부 섬들을 반환했으며, 심지어 공납을 바치는 것까지 받아들였다.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["울루바트 전투 — 이사 첼레비의 패배", "500c5d24"], "d": ["부르사를 장악하고 있던 이사 첼레비는 울루바트에서 동생 메흐메드에게 패했으며, 몇 차례의 재기 시도도 성과 없이 끝났다.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["이사 첼레비의 소멸", "0effa11e"], "d": ["쉴레이만 첼레비의 지원을 받아 몇 차례 아나톨리아로 돌아왔던 이사 첼레비는 마지막 패배 이후 자취를 감추었다. 그의 몫은 첼레비 메흐메드에게 넘어갔으며, 지도에서 메흐메드의 영역은 서쪽으로 넓어졌다.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["무사 첼레비의 왈라키아행", "8441267a"], "d": ["쉴레이만 첼레비에게 부르사와 앙카라를 잃고 토카트-아마시아로 물러난 첼레비 메흐메드는 동생 무사에게 루멜리아로 가도록 부추겼다. 무사는 왈라키아 총독 미르체아의 초청을 받아들여 해로로 왈라키아에 도착했으며, 이곳에서 쉴레이만을 두 전선 사이에 놓이게 할 투쟁에 나서게 된다.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["첼레비 메흐메드의 부르사·앙카라 탈환 — 아나톨리아 몫이 쉴레이만 첼레비에게서 벗어남", "bfb69f12"], "d": ["무사 첼레비가 루멜리아에서 거둔 성공(얌볼, 1410년 2월 13일)에 대응하여, 아나톨리아에 있던 에미르 쉴레이만 첼레비는 루멜리아로 건너갔다. 쉴레이만이 아나톨리아를 떠난 뒤 메흐메드 첼레비는 앙카라를 포함한 부르사 일대를 다시 장악했으며, 즉위의 표시로 813년 연호가 새겨진 화폐를 주조하게 했다. 지도에서 마르마라의 아나톨리아 쪽은 에미르 쉴레이만의 몫에서 첼레비 메흐메드의 색으로 바뀐다.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["코스미디온 전투", "0efc2caa"], "d": ["비잔티움의 지원을 받아 이스탄불 성벽 앞에서 벌어진 전투에서 쉴레이만 첼레비는 동생 무사를 격파했으나, 루멜리아에서 그의 지지 기반은 빠르게 녹아내리기 시작하고 있었다. 같은 날짜에 상실한 다른 정착지: 엘라소나, 아이토스, 볼라이으르(지도상 루멜리아에서 무사에게서 쉴레이만에게 넘어간 곳).", "0498cbda"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["무사 첼레비의 이스탄불 포위", "4932f586"], "d": ["쉴레이만을 지원한 비잔티움을 응징하려던 무사 첼레비는 이스탄불을 포위했으며, 이 포위는 비잔티움을 첼레비 메흐메드와의 동맹으로 몰아갔다.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["에미르 쉴레이만의 죽음 — 루멜리아를 장악한 무사", "325c1549"], "d": ["에디르네에서 도주하다 붙잡힌 쉴레이만 첼레비는 살해되었으며, 루멜리아 전체가 무사 첼레비의 손에 넘어갔다. 지도에서 루멜리아는 파란색에서 보라색으로 바뀐다.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["차무를루 전투 — 통일의 회복", "0b23173e"], "d": ["비잔티움, 세르비아 전제공국, 루멜리아 영주들의 지원을 얻은 첼레비 메흐메드는 차무를루에서 동생 무사에게 결정적인 패배를 안겼고, 무사는 도주 중에 살해되었다. 무사가 장악하던 루멜리아는 에디르네와 함께 메흐메드에게 넘어갔으며, 메흐메드 첼레비는 에디르네에서 자신이 오스만 국가의 유일한 통치자임을 선포했다. 11년에 걸친 공위 시대가 끝났고, 지도상의 왕자들의 몫은 하나의 몸체로 합쳐졌다.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["빈 원정 결정 — 바슈바르 평화는 갱신되지 않고 목표는 죄르에서 빈으로 바뀌다", "1bf278f2"], "d": ["황제 레오폴트 1세는 아직 만료되지 않은 바슈바르 조약의 갱신을 원했고, 메흐메드 4세도 평화 쪽으로 기운 듯 보였다. 그러나 대재상 메르지폰루 카라 무스타파 파샤는 자신이 중부 헝가리의 왕으로 선포하게 한 퇴쾨이 임레의 불만을 근거로 평화를 갱신하지 못하게 했으며, 바니 메흐메드 에펜디를 필두로 한 설교자들을 동원해 술탄이 전쟁을 결심하도록 설득했다. 협의에서 술탄은 베오그라드에 남고 총사령관(세르다르 에크렘)은 죄르를 점령하러 전진하기로 결정되었다. 그러나 세케슈페헤르바르(이스톨니 벨그라드)에서 열린 협의에서는 크림 칸 무라드 기라이와 부다 총독 우준 이브라힘 파샤의 반대에도 불구하고 목표가 빈 포위로 바뀌었다.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["제2차 빈 포위 시작 — 빈 앞에 이른 군대", "bb542e49"], "d": ["대재상 카라 무스타파 파샤가 지휘하는 오스만군은 1683년 7월 14일 빈 앞에 도착했다. 황제 레오폴트 1세는 도시의 방어를 슈타르헴베르크에게 맡기고 오스트리아 내륙으로 물러났다. 첫 번째와 달리 처음부터 빈을 목표로 준비된 이 두 번째 포위는 9월 12일까지 이어진다.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["파르카니의 패주와 에스테르곰 상실", "a7366740"], "d": ["빈에서 퇴각하던 군대는 파르카니에서 두 번째로 패주했으며, 이어 헝가리의 요충 요새 가운데 하나인 에스테르곰이 함락되었다. 퇴각은 붕괴로 바뀌기 시작했다.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["메르지폰루 카라 무스타파 파샤의 처형", "ce8b10ac"], "d": ["빈 패전의 책임자로 지목된 대재상은 베오그라드에서 교살되었다. 그러나 그의 처형은 전선을 바로잡지도, 흔들린 국가의 위신을 되돌리지도 못했다.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["신성 동맹 결성", "060280d0"], "d": ["교황청의 주도로 오스트리아, 폴란드, 베네치아 사이에 오스만에 맞선 신성 동맹이 결성되었고, 1686년에는 러시아도 가담했다. 이로써 제국은 16년 동안 이어질 다전선 전쟁에 들어섰다.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["제1차 부다 방어전", "ccc43630"], "d": ["신성 동맹군의 첫 번째 부다 포위는 넉 달 동안 이어진 요새의 완강한 방어로 격퇴되었다. 그러나 헝가리의 요새들은 계속해서 하나씩 함락되고 있었다.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["우이바르 상실", "689ab78c"], "d": ["22년 동안 오스만의 수중에 있었고 유럽에서 속담이 되었던 우이바르(노베잠키) 요새가 함락되었으며, 상부 헝가리에서의 오스만의 존재가 와해되었다.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["바라드에서의 퇴쾨이 체포 — 중부 헝가리 왕국의 해체와 상부 헝가리 요새들의 항복", "1741aaaf"], "d": ["빈 패전 이후 오스만은 퇴쾨이도 전쟁과 패배를 초래한 자들 가운데 하나로 보기 시작했다. 1685년 10월 15일 총사령관(세르다르) 멜레크 이브라힘 파샤의 명령으로 바라드 베일레르베이 아흐메드 파샤는 원군으로 온 퇴쾨이를 붙잡게 했는데, 그를 합스부르크에 넘겨 더 나은 강화 조건을 얻어 내려는 기대가 있었다. 체포 소식이 퍼지자 그의 아내 즈리니 일로너가 지키던 문카치를 제외한 중부 헝가리 왕국의 모든 요새와 도시가 합스부르크에 항복했고, 쿠루츠 병사의 대부분은 합스부르크군에 넘어갔다. 퇴쾨이가 1686년 1월 2일 베오그라드에서 풀려났을 때 왕국은 이미 사라진 뒤였다.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["부다 상실 — 145년간의 헝가리 수도", "70800e2b"], "d": ["78일 동안 이어진 포위 끝에 부다가 함락되었으며, 마지막 베일레르베이 압두라흐만 압디 파샤는 성벽에서 순교했다. 1541년부터 오스만의 통치 아래 있던 이 도시의 상실은 헝가리 상실의 상징으로 여겨진다. 같은 날짜에 상실한 다른 정착지: 페슈트.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["제2차 모하치(허르샨) 패전 — 트란실바니아와 모하치의 상실", "a7922681"], "d": ["1526년에 대승을 거두었던 평원에서 이번에는 대패를 당했다. 군대는 흩어졌고, 반란을 일으킨 병사들은 대재상을 파면시켰다. 이 패배는 트란실바니아의 상실로도 이어졌다.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["아테네 상실과 파르테논 폭발", "b6691730"], "d": ["베네치아 포병이 쏜 포탄이 오스만이 화약고로 쓰던 파르테논을 폭파했으며, 2천 년 된 신전은 폐허가 되었다. 도시는 베네치아의 손에 넘어갔다(1688년에 되찾는다).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["메흐메드 4세의 폐위와 쉴레이만 2세의 즉위", "9f53037c"], "d": ["전선의 참사와 군대의 반란에 이어, 39년의 치세 끝에 메흐메드 4세가 폐위되고, 40년 동안 '새장(카페스)'에 갇혀 지낸 동생 쉴레이만 2세가 옹립되었다.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["베오그라드의 첫 상실 — 신성 동맹의 포위", "c6b9b19a"], "d": ["1521년 이래 오스만의 수중에 있던 베오그라드가 신성 동맹군에 항복했다. 세르비아의 문이 적에게 열렸고 위험은 니시-소피아 선까지 닥쳤다. 지도상 같은 날짜에 오스만에서 합스부르크로 넘어간 다른 정착지: 히사르즈크(그로츠카) — 베오그라드의 상위 중심지 연쇄를 따른다(TDV belgrad; 명시된 근사치).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["바덴, 포자레바츠 앞에서 모라바강 도하 — 포자레바츠가 오스트리아에 함락", "bcf3fc59"], "d": ["바덴 변경백 루트비히는 1689년 8월 포자레바츠에서 모라바강을 건너 니시 방면으로 진격했으며, 이 도시는 1690년 여름까지 오스트리아의 수중에 남았다(TDV suleyman-ii는 1690년에 포자레바츠를 되찾았다고 말한다). 날짜와 뢰더의 해독은 재검증되지 않았다.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["니시 상실 — 합스부르크(헝가리 왕관)의 진격, 가장 위태로운 해", "c5e27b3f"], "d": ["합스부르크(헝가리 왕국 왕관)의 진격은 니시마저 오스만의 통치에서 빼앗았으며, 습격은 스코페와 프리슈티나까지 이르렀다. 비딘은 그 뒤인 1689년 10월에 함락되었다(별도 항목). 전쟁의 가장 어두운 해에 국가는 수도마저 위협받고 있다고 느꼈다.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["오르쇼바와 페튈이슬람에 오스트리아 수비대 주둔", "ee8dd875"], "d": ["비딘이 전투 없이 점령된(1689년 10월, TDV vidin) 뒤, 바덴은 1689년 10월 25일 오르쇼바와 페튈이슬람을 보수하고 수비대를 두었으며, 오르쇼바는 1690년 가을까지 오스트리아에 남았다. 날짜는 Bánlaky/Röder에 근거하며 재검증되지 않았다.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["니시가 다시 오스만의 손에", "0c4f44eb"], "d": ["파즐 무스타파 파샤는 1690년 7월에 원정에 나섰다. 셰히르쾨이(피로트), 포자레바츠, 귀베르진리크를 점령한 뒤 포위한 니시는 1690년 9월 27일 오스만의 손에 들어왔다(TDV semendire). 같은 시기에 비딘도 되찾아졌다. 지도상 같은 날짜에 합스부르크에서 오스만으로 돌아온 다른 정착지: 야고디나와 위르퀴프(프로쿠플레) — 지점 단위의 날짜를 찾지 못해 니시의 날짜를 취했다(TDV semendire; 명시된 근사치. 뢰더 1842는 재상이 9월 8-24일에 야고디나를 지났다고 적고 있으며, 이 모순은 해결되지 않았다).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["스메데레보에서 오스트리아 부대 항복", "90da20c4"], "d": ["1690년 9월 27일 니시를 점령한 뒤, 나흘간의 포위로 스메데레보의 오스트리아 부대가 항복했다(TDV semendire). Bánlaky/Röder는 9월 24일이라고 한다. 사료가 서로 어긋나며 TDV를 기준으로 삼았다.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["베오그라드 탈환", "ab435838"], "d": ["대재상 쾨프륄뤼자데 파즐 무스타파 파샤는 1690년 10월 8일 오스트리아에게서 베오그라드를 되찾았으며, 1688년에 잃은 도시는 이렇게 오스만에 돌아왔다(TDV suleyman-ii). 지도상 같은 날짜에 합스부르크에서 오스만으로 돌아온 다른 정착지: 히사르즈크(그로츠카) — 베오그라드의 상위 중심지 연쇄를 따른다(TDV suleyman-ii; 명시된 근사치).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["슬란카멘의 패주 — 파즐 무스타파 파샤 순교", "10d626f1"], "d": ["세기의 가장 참혹한 회전 가운데 하나에서 대재상은 이마에 총을 맞고 순교했으며, 군대는 흩어졌다. 재기의 희망은 이 전투와 함께 꺼졌다.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["키오스섬 상실", "07c084f8"], "d": ["베네치아 함대가 키오스를 점령했으며, 에게해에서의 오스만 지배가 위협받게 되었다. 섬은 이듬해에 되찾아진다.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["무스타파 2세의 친정 결정", "61c3ba9c"], "d": ["새 술탄은 선조들의 길을 따라 군대의 선두에 서서 원정에 나서겠다고 선언했다. 이 결정은 군대의 사기를 높였고 2년 동안 이어질 술탄 친정의 시기를 열었다.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["키오스 탈환", "6b496fca"], "d": ["오이누세스 제도(코윤 아달라르) 해전에서 베네치아 함대를 격파한 메조모르토 휘세인 파샤가 키오스를 되찾았다. 이는 오스만 해양 활동의 짧은 부활을 알리는 신호였다.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["루고지 전투의 승리 — 무스타파 2세의 제1차 오스트리아 원정", "d5ee9b34"], "d": ["술탄이 직접 참가한 첫 원정에서 리포바를 되찾았고 루고지에서 오스트리아군을 격파했다. 여러 해 이어진 패배의 사슬에서 처음으로 단절이 일어났다. 지도는 카란세베슈도 이 원정에서 합스부르크에서 오스만으로 돌아온 것으로 본다. 사료는 1695년 9월만 제시하며(TDV mustafa-ii), 지도의 날짜는 루고지 기록에서 취했다(명시된 근사치).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["아조프 요새 상실", "2b78b5cd"], "d": ["흑해로 나아가려던 표트르 1세는 두 번째 포위에서 아조프를 점령했다. 러시아는 처음으로 오스만의 요새에 영구적으로 자리 잡았으며 해군국으로 가는 첫걸음을 내디뎠다.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["울라슈(올라신) 전투의 승리", "02ac9ca8"], "d": ["술탄의 두 번째 원정에서 도나우강 변에서 거둔 승리는 테메슈바르를 점령하려던 오스트리아의 계획을 무산시켰다. 그러나 전쟁의 전반적인 균형은 바꾸지 못했다.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["젠타의 패주 — 전쟁의 운명이 결정되다", "475c4a7b"], "d": ["군대는 티서강을 건너던 중 오이겐 공의 기습을 받았다. 강의 양안에 갈라진 병력은 몇 시간 만에 섬멸되었으며, 대재상 엘마스 메흐메드 파샤를 비롯한 수천 명의 병사와 관료가 죽었다. 오스만 역사상 가장 참혹한 패배 가운데 하나인 젠타 전투는 강화 협상을 피할 수 없게 만들었다.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["카를로비츠 강화 회담 시작", "1f395cf3"], "d": ["영국과 네덜란드의 중재로 시작된 회담에서 오스만 대표단은 처음으로 '우티 포시데티스'(현재 점유하고 있는 것을 그대로 보유한다) 원칙을 받아들여야 했다. 72차례의 회기에 걸친 협상은 근대 오스만 외교의 탄생으로 여겨진다.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["카발랄르 메흐메드 알리의 이집트 상륙", "514c943f"], "d": ["프랑스 점령하의 이집트를 되찾기 위해 파견된 오스만군에는 카발라에서 모집한 의용 부대도 있었다. 30대의 메흐메드 알리는 이 부대의 부지휘관이었으며, 총독이 아닌 중대 장교로서 이집트에 발을 디뎠다.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["알바니아 병사들이 이집트 총독을 축출", "c76a0ec2"], "d": ["급료(울루페)를 받지 못한 알바니아 부대가 반란을 일으켜 총독 휘스레브 파샤를 성채에서 달아나게 했다. 프랑스군의 철수로 생긴 공백 속에서 맘루크 베이들, 알바니아 군단, 바브알리가 임명한 총독들이 삼각 투쟁에 들어갔고, 메흐메트 알리는 이 삼각 구도에서 균형을 만들어 내며 두각을 나타냈다. 같은 날짜에 상실한 다른 정착지: 타이프.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["카이로의 울레마가 메흐메트 알리를 총독으로 선포", "a16752f2"], "d": ["과중한 세금에 시달리던 카이로의 상인·수공업자와 울레마는 나키브 알아슈라프 우마르 마크람의 지도 아래 봉기하여 총독 후르시드 파샤를 인정하지 않겠다고 선언하고, 메흐메트 알리를 총독 자리에 앉혔다. 총독이 백성에 의해 선출된 것은 오스만 역사에서 보기 드문 사건이다.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["바브알리가 기정사실을 수용: 이집트 총독 임명 칙령", "b86736a3"], "d": ["이집트에서 자기 후보를 지켜 낼 힘이 없던 바브알리는 메흐메트 알리에게 베지르 직위와 함께 이집트 총독 임명 칙령을 보냈다. 지도에서 이집트는 이 날짜부터 종속(옅은 색조) 층으로 넘어간다. 법적으로는 오스만 영토이지만 사실상 카발라 가문의 나라이다. 같은 날짜에 종속 층으로 넘어간 다른 정착지: 카이로, 알렉산드리아, 다미에타, 아시우트, 아스완, 이브림, 수에즈, 라시드(로제타).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["영국의 프레이저 원정대가 알렉산드리아에 상륙", "4d6c31be"], "d": ["오스만 제국이 프랑스에 접근하자 영국은 이에 대응해 이집트에 상륙 부대를 보냈다. 메흐메트 알리는 당시 상이집트에서 맘루크와 싸우고 있었으나, 급히 돌아와 방어를 조직했다.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["라시드(로제타)의 패주 — 영국군 격퇴", "3636004c"], "d": ["라시드 읍에 진입한 영국군 종대는 시가전에서 큰 손실을 입었고, 9월에 병력은 이집트에서 완전히 철수했다. 이 승리는 이집트와 이스탄불 양쪽에서 메흐메트 알리의 위신을 확고히 했다.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["성채 사건: 맘루크 베이들의 숙청", "84030b97"], "d": ["헤자즈 원정을 위해 마련된 의식 행렬에 초청된 맘루크 베이들은 카이로 성채의 좁은 통로에 갇혀 제거되었다. 이로써 5세기에 걸친 맘루크의 세력은 끝났고, 이집트에서 메흐메트 알리에게는 더 이상 경쟁자가 남지 않았다.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["헤자즈 원정 개시 — 군대가 수에즈에서 해로로, 순례길을 따라 육로로 얀부를 향해 진군", "1c05c159"], "d": ["1803년부터 사우드-와하브 세력의 지배를 받던 두 성지(하라마인)를 되찾는 것은 마흐무드 2세의 가장 큰 정통성 문제였다. 바브알리의 힘으로는 부족했기에 이 임무는 이집트 총독에게 맡겨졌다. 메흐메트 알리는 열여섯 살 아들 투순을 군대의 선두에 세워 보냈다.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["얀부 접수 — 헤자즈 원정의 첫 해안 거점", "179bc78d"], "d": ["새로 건조한 배를 타고 수에즈를 출발한 알바니아 보병 약 2천 명이 1811년 10월 얀부 부근에 상륙했고, 읍은 이틀간의 미약한 저항 끝에 항복했다. 투순이 지휘하는 기병은 육로로 순례길을 따라 아카바와 알와즈를 거쳐 2주 뒤에야 얀부에 도착했다. 얀부는 메디나와 메카로 진군할 이집트군의 헤자즈 내 첫 거점이 되었다.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["사프라-자디다 협곡에서의 첫 패주", "99ef804d"], "d": ["좁은 산길에서 매복을 당한 이집트 선봉대는 흩어졌다. 이 패배는 원정의 전술적 교훈이 되었다. 베두인 부족들의 지원 없이는 헤자즈에서 진군할 수 없다는 것이 분명해졌다.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["메디나 탈환", "6f6a5d55"], "d": ["긴 포위 끝에 메디나가 항복했다. 예언자의 도시를 되찾은 일은 이스탄불에서 축포 행사로 기념되었고, 메흐메트 알리에게는 포상으로 제다 총독직도 주어졌다.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["메카 탈환 — 순례길이 열리다", "3d6d66a0"], "d": ["메카에 입성한 이집트군은 카바에서 다시 오스만 술탄의 이름으로 후트바를 낭독하게 했다. 10년 동안 끊겼던 순례 대상이 다시 길을 떠날 수 있게 되었다. 지도에서 헤자즈는 오스만의 지배로 돌아가지만, 그 통치가 카이로에 있으므로 종속 색조로 표시된다. 같은 날짜에 종속 통치로 넘어간 다른 곳: 제다.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["타이프 탈환 — 헤자즈 원정의 완료", "6315fb31"], "d": ["메디나(1812년 12월)와 메카(1813년 1월)에 이어, 투순 파샤가 지휘하는 이집트군은 마지막으로 타이프를 와하브파로부터 되찾았다. 10년에 걸친 사우드의 지배가 끝났고, 헤자즈의 세 성스러운 중심지는 모두 다시 오스만-이집트의 통제 아래 들어왔다.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["메흐메트 알리가 직접 헤자즈로 건너감", "fda0ea2d"], "d": ["원정이 지지부진하게 진행되는 것을 본 총독은 지휘를 직접 장악했고, 부족장들과 협상하여 사우드 전선을 내부에서 무너뜨리려 했다. 이 원정을 통해 홍해 무역에서 이집트의 몫도 커졌다.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["비살 전투: 사우드군의 패주", "9c9ab91f"], "d": ["회전에서 큰 패배를 당한 사우드군은 내륙으로 물러났다. 이때 맺은 휴전은 오래가지 못했고, 2년 뒤 작전은 나지드의 심장부로 옮겨지게 된다. 본 아틀라스는 이 승리 이후 타이프 동쪽의 투라바와 후르마가 사우드의 손에서 벗어난 것으로 간주한다(사건의 출처는 로리머의 『지명사전(Gazetteer)』이며, 각 정착지에 특정된 증거와 1월 13일이라는 날짜는 명시해 둔 근사치이다).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["이브라힘 파샤가 나지드 원정에 나섬", "d5ed80d1"], "d": ["동생 투순이 죽자 지휘권을 넘겨받은 이브라힘 파샤는 사막에서 2년에 걸친 고된 행군에 들어갔다. 우물에서 우물로 전진한 군대는 부족들을 하나씩 제압하며 사우드의 수도에 육박했다.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["디리야 함락 — 제1차 사우드 왕국의 종말", "aa96206d"], "d": ["6개월에 걸친 포위 끝에 디리야는 항복했고 파괴되었다. 아미르 압둘라 이븐 사우드는 이스탄불로 압송되어 처형되었다. 오스만의 깃발이 아라비아 내륙 이처럼 깊숙한 곳까지 이른 것은 처음이었으며, 나지드 수비대는 1824년까지 주둔했다. 같은 날짜에 편입된 다른 곳: 디리야(나지드).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["수단 원정 개시", "b1fc6905"], "d": ["메흐메트 알리의 목적은 세 가지였다. 자신의 군대에 병사를 모으고, 센나르의 금을 손에 넣으며, 도망친 맘루크 잔당을 없애는 것이었다. 그의 아들 이스마일 파샤가 지휘하는 부대는 나일강을 따라 남쪽으로 내려갔다.", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["동골라가 무력 충돌 없이 이집트군에게 넘어감(맘루크는 1820년 6월에 이미 떠났다)", "bc5942c0"], "d": ["나일강의 큰 굽이에 있는 동골라는 맘루크가 1820년 6월에 버리고 떠난 뒤, 무력 충돌 없이 이스마일 파샤의 이집트군 손에 넘어갔다. 지도에서 수단은 이 날짜부터 종속 층에 나타난다. 정복한 것도 카이로이고 다스리게 될 것도 카이로이다.", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["자발 알다이카 전투 — 샤이키야 연맹이 이집트군에게 결정적으로 패배", "befc9539"], "d": ["무함마드 알리 파샤의 아들 이스마일 파샤의 군대는 쿠르티에서의 첫 교전 한 달 뒤, 자발 알다이카 부근에서 벌어진 두 번째이자 결정적인 전투에서 샤이키야를 격파했다. 샤이키야의 수장 마크 수바이르는 항복했고, 마크 샤위시는 저항을 계속했다. 이후 나일강 굽이에 대한 이집트의 지배는 확고해졌다.", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["센나르(푼지) 술탄국의 항복", "3cac7dd2"], "d": ["300년 역사의 푼지 왕조는 싸우지 않고 항복했다. 같은 해 나일강의 두 지류가 합류하는 지점에 세워진 진영은 곧 수단의 행정 중심지 하르툼으로 바뀌었다. 같은 날짜에 편입된 다른 곳: 센나르.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["코르도판 점령", "06440602"], "d": ["서쪽으로 파견된 제2종대는 바라(Bâra)에서 다르푸르군을 격파하고 누후드 일대와 함께 코르도판을 차지했다. 이로써 수단에 대한 이집트의 지배는 나일 계곡에서 서쪽 초원 지대까지 확대되었다.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["이집트군이 크레타에 상륙", "835aee90"], "d": ["그리스인의 반란이 크레타로 번지자 바브알리는 섬에 이집트군을 보내 달라고 요청했다. 섬에서 메흐메트 알리의 영향력은 이 개입으로 시작되었고, 8년 뒤 그에게 크레타 총독직이 주어지는 것으로 귀결되었다.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["셴디에서 이스마일 파샤 피살", "223860c9"], "d": ["과중한 세금과 병력 요구에 격분한 현지 아미르 니므르는 이스마일 파샤가 묵던 집에 불을 질러 그와 수행원들을 불태워 죽였다. 보복 원정은 이 지역을 피바다로 만들었고, 이후 수단의 통치는 강압 위에 세워졌다.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["마흐무드 2세가 모레아 문제로 메흐메트 알리에게 지원을 요청", "03594a42"], "d": ["예니체리 군대로는 3년이 지나도 진압하지 못한 모레아 반란 때문에, 술탄은 유럽식으로 훈련된 이집트군에 도움을 청했다. 그 대가로 모레아 총독직과 크레타가 약속되었다. 이 요청은 제국이 자기 속주에 의존하게 되었다는 최초의 공개적인 시인이었다.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["이브라힘 파샤가 모돈에 상륙", "9c993dba"], "d": ["이집트 함대의 엄호를 받은 상륙 부대가 모레아의 남서쪽 끝에 발을 디뎠다. 니자미 정규 보병과 야전 포병을 갖춘 이 군대는 반란 무장대를 상대로 단기간에 우위를 차지했다.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["트리폴리차 탈환 — 모레아의 중심지 함락", "8a478c11"], "d": ["반란의 행정 중심지였던 트리폴리차가 함락되면서 모레아의 대부분이 다시 통제 아래 들어왔다. 지도에서 이 반도는 이집트군의 수중에 있으므로 종속 색조로 나타난다.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["미솔롱기(메솔롱기) 함락", "07257f87"], "d": ["1년에 걸친 포위 끝에 도시가 점령되었다. 그러나 이 방어전이 유럽 언론에 불러일으킨 반향은 그리스의 대의에 대한 동정을 절정에 이르게 했고, 열강이 개입할 토대를 마련했다.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["아테네 아크로폴리스 접수", "3b19f946"], "d": ["아크로폴리스가 함락되면서 그리스 반란은 군사적으로 거의 끝난 상태였다. 바로 이 시점에 문제는 국내 반란을 넘어 유럽 외교의 의제가 되었다.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["런던 조약: 세 열강이 그리스의 자치를 강요", "7ce46fd8"], "d": ["영국, 프랑스, 러시아는 오스만과 그리스인에게 휴전과 자치 조건을 받아들이게 하기 위해 공동 행동을 결정했고, 거부할 경우 자국 함대가 개입할 것이라고 통고했다. 바브알리는 이 제안을 거절했다.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["알렉산드리아 협정: 이집트의 모레아 철수 결정", "cc978f37"], "d": ["나바리노에서 함대를 잃은 메흐메트 알리는 이스탄불과 상의하지 않고 영국 제독과 직접 합의하여 모레아에서 병력을 철수하기로 했다. 총독이 열강과 독자적으로 협정을 맺은 것은 다가올 위기의 전조였다.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["이집트군의 모레아 철수", "8fb742dd"], "d": ["마지막 부대가 배에 올랐다. 반도는 사실상 상실되었고, 1830년 런던 의정서와 함께 독립 그리스의 핵심 지역이 되었다. 한편 메흐메트 알리는 약속받은 모레아 총독직을 얻지 못했을 뿐 아니라 그 대가로 대규모의 함대와 군대를 잃었다. 같은 날짜에 상실한 다른 정착지: 모돈, 코론.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["크레타의 통치가 메흐메트 알리에게 맡겨짐", "7f76396d"], "d": ["모레아 상실에 대한 보상으로 크레타 총독직이 메흐메트 알리에게 주어졌다. 섬은 10년 동안 카이로에서 통치되었고, 지도에서는 이 기간 내내 종속 색조로 보인다. 같은 날짜에 편입된 다른 곳: 칸디아(크레타).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["이브라힘 파샤가 시리아에 진입 — 제1차 위기 시작", "1a5cc386"], "d": ["구실은 이집트에서 도망친 펠라(농민)들을 돌려보내지 않은 아크레 총독이었고, 진짜 이유는 시리아의 목재, 항구, 인력에 대한 메흐메트 알리의 필요였다. 군대는 시나이를 건너 팔레스타인 해안을 신속히 장악했다.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["아크레 포위전 개시", "b211d96d"], "d": ["1799년 나폴레옹을 저지했던 이 요새는 6개월 동안 버텼다. 이 포위전은 이집트군의 근대식 포병이 맞은 첫 번째 큰 시험이었다.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["아크레 함락", "0f47917b"], "d": ["성벽을 두드리던 포대가 돌파구를 열자 요새가 점령되었다. 시리아로 가는 문이 열린 것이다. 같은 시기에 바브알리는 메흐메트 알리를 반역자로 선포하고 그의 총독직을 박탈했다.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["다마스쿠스 항복", "48da3b62"], "d": ["도시는 싸우지 않고 항복했다. 이브라힘 파샤는 조세 제도와 비무슬림에게 부여하는 평등을 선포하여 현지의 지지를 얻으려 했다. 그러나 바로 이 정책들이 몇 년 뒤 그에 대한 반란의 원인이 된다. 같은 시기에 편입된 다른 곳: 베이루트, 시리아의 트리폴리, 시돈.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["홈스 전투", "867810ee"], "d": ["시리아를 구하기 위해 파견된 오스만군은 평지에서 패주했다. 예니체리가 폐지된 지 6년 뒤에 창설된 신식 군대가 아직 준비되지 않았음이 드러났다.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["알레포 점령", "9c0ead76"], "d": ["북부 시리아의 상업과 행정의 중심지도 함락되었다. 이로써 이집트군은 토로스산맥 기슭에 이르렀고 아나톨리아의 관문에 있는 고갯길들로 향했다.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["벨렌(베일란) 고개의 패주 — 추쿠로바가 열리다", "4bae872b"], "d": ["아마누스산맥의 좁은 고개에서 방어선이 돌파되었다. 안타키아, 아다나, 타르수스가 이집트군에게 넘어갔으며(TDV에 따르면 마라시 점령은 1833년이며, 별도 항목이다), 지도에서 추쿠로바는 종속 색조로 바뀐다. 아나톨리아 내륙으로 가는 길은 이제 무방비 상태였다.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["귈레크 협곡 함락 — 이첼 해안(메르신, 실리프케)이 이집트의 통제 아래 들어감", "d9049b5b"], "d": ["토로스산맥에서 추쿠로바로 통하는 관문인 귈레크 협곡이 이집트군의 손에 들어갔다. 이브라힘 파샤는 이첼 산자크에 자신의 뮈테셀림(대리 행정관)을 임명했고, 해안의 모든 부두가 이집트의 통제 아래 들어갔다. 지도에서 메르신과 실리프케는 이날부터(하한이며, 임명 날짜는 출처에 없다) 이집트에 속한 것으로 표시된다. 퀴타히아 결정에서 이양된 것은 아다나의 무하스륵(징세관직)뿐이었으므로, 이 통제는 아나톨리아 철수와 함께 끝난다.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["코니아의 에렐리가 이집트 점령하에 — 코니아–아다나 도로의 토로스 어귀", "fb908900"], "d": ["귈레크 협곡을 넘은 이집트군이 코니아로 가는 길목에 있던 에렐리는 1832년 이브라힘 파샤에게 점령되었고, 1833년 퀴타히아 합의에 따라 비워지면서 다시 카라만 주에 속하게 되었다. 지도에서 이곳은 아다나와 코니아 사이 점령선의, 출처가 있는 중간 지점이다. 울루크슐라와 카라프나르에 대해서는 도시 차원의 증거를 찾지 못했다.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["이집트군의 코니아 입성", "13952a2d"], "d": ["토로스산맥을 넘은 군대는 중부 아나톨리아에 이르렀다. 오스만 총독의 병력이 제국의 핵심 영토에서 진격한 것은 처음이었다. 같은 날짜에 편입된 다른 곳: 카라만.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["코니아 회전: 대재상이 포로가 됨", "ec82cc9a"], "d": ["안개 낀 날씨 속에 흩어진 오스만군은 큰 패배를 당했고, 대재상 레시드 메흐메드 파샤는 포로가 되었다. 국가의 중앙군은 더 이상 존재하지 않았고, 이스탄불과 이집트군 사이를 가로막을 힘은 남아 있지 않았다.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["마라시가 이집트에 점령됨", "f558e383"], "d": ["TDV에 따르면 마라시는 1833년에 카발라 가문의 이브라힘 파샤에게 점령되어 19개월 가까이 그의 통치 아래 있었다. 마라시는 퀴타히아 합의가 정한 주(州) 경계 밖에 남았으므로, 이 통치는 법적인 것이 아니라 사실상의 것이다.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["카라히사르 이 사히브(아피온)가 이집트에 점령됨 — 코니아–퀴타히아 도로", "ae0c2c78"], "d": ["코니아 회전 이후 퀴타히아로 진격하던 이집트군의 경로에 있던 카라히사르 이 사히브는 1833년 한동안 이브라힘 파샤의 수중에 있었다. 지도에서 이곳은 코니아와 퀴타히아 사이 점령선의, 출처가 있는 중간 지점이다. 아크셰히르, 으르근, 이스하클르에 대해서는 도시 차원의 증거를 찾지 못했으므로 이들은 오스만의 색으로 표시된다.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["이집트군이 퀴타히아에 도달", "214f8df6"], "d": ["이브라힘 파샤는 이스탄불에서 사흘 행정(行程) 거리에 있는 퀴타히아에서 멈췄다. 더 전진하지 않은 것은 군사적 이유가 아니라 정치적 이유 때문이었다. 러시아의 개입과 유럽의 반응을 계산에 넣었던 것이다.", "0f1c5f03"]}
});
